(function(){
  var R = String.raw;
  var D = {};
  D["mzt_s1"] = {id:"mzt_s1",ch:"毛中特讲义 · 导论 马克思主义中国化的历史进程和理论成果",title:"导论 马克思主义中国化的历史进程和理论成果",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 4 页</div><div class=\"sidebox\" style=\"left:504px;top:613px;width:195px;height:394px\"></div><span class=\"bl\" style=\"left:458px;top:64px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:344px;top:114px;font-size:27.8px;max-width:66px\">导论</span><span class=\"bl\" style=\"left:211px;top:166px;font-size:18.4px;max-width:334px\">马克思主义中国化的历史进程和理论成果</span><span class=\"bl\" style=\"left:53px;top:216px;font-size:18.4px;max-width:102px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:349px;top:259px;font-size:15.0px;max-width:172px\">考点1马克思主义中国化的内涵</span><span class=\"bl\" style=\"left:183px;top:265px;font-size:15.6px;max-width:114px\">马克思主义中国化的</span><span class=\"bl\" style=\"left:182px;top:286px;font-size:15.6px;max-width:115px\">历史进程和理论成果</span><span class=\"bl b hl\" style=\"left:350px;top:293px;font-size:13.9px;max-width:231px\">考点2马克思主义中国化理论成果及其进程</span><span class=\"bl b acc\" style=\"left:53px;top:344px;font-size:18.4px;max-width:102px\">考点考情分析</span><span class=\"bl\" style=\"left:77px;top:372px;font-size:17.8px;max-width:622px\">本章为本学科的导论部分，主要是总论马克思主义中国化的两大理论成果一毛泽东思想和中国特色社会主义理论体</span><span class=\"bl\" style=\"left:56px;top:392px;font-size:17.2px;max-width:614px\">系。本章内容是本门科目中考频一般的部分，考试形式一般为选择题。考生在复习过程中对本导论内容有所了解即可。</span><span class=\"bl b hl\" style=\"left:65px;top:447px;font-size:19.5px;max-width:361px\">考点1马克思主义中国化的内涵☆☆★（低频选择题）</span><span class=\"bl\" style=\"left:659px;top:450px;font-size:15.0px;max-width:40px\">记笔记</span><span class=\"bl\" style=\"left:66px;top:466px;font-size:15.6px;max-width:122px\">（2010.21,2011.21）</span><span class=\"bl\" style=\"left:214px;top:484px;font-size:40.6px;max-width:266px\">众号：</span><span class=\"bl b\" style=\"left:53px;top:501px;font-size:17.2px;max-width:166px\">1.1马克思主义中国化的内涵</span><span class=\"bl\" style=\"left:77px;top:522px;font-size:17.2px;max-width:423px\">坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结</span><span class=\"bl\" style=\"left:55px;top:543px;font-size:17.8px;max-width:446px\">合，运用马克思主义的立场、观点、方法研究和解决中国革命、建设、改革中的实际</span><span class=\"bl\" style=\"left:54px;top:564px;font-size:17.2px;max-width:447px\">问题；就是总结和提炼中国革命、建设、改革的实践经验，从而认识和掌握客观规</span><span class=\"bl\" style=\"left:55px;top:585px;font-size:15.6px;max-width:445px\">律，为马克思主义理论宝库增添新的内容；就是运用中国人民喜闻乐见的民族语言来</span><span class=\"bl\" style=\"left:55px;top:605px;font-size:17.8px;max-width:446px\">阐述马克思主义理论，使之成为具有中国特色、中国风格、中国气派的马克思主义。</span><span class=\"bl\" style=\"left:519px;top:619px;font-size:14.5px;max-width:94px\">火星姐姐背景补充1</span><span class=\"bl\" style=\"left:451px;top:629px;font-size:15.0px;max-width:49px\">&gt;补充1</span><span class=\"bl\" style=\"left:511px;top:641px;font-size:13.9px;max-width:189px\">马克思主义作为科学真理，具有普遍的指</span><span class=\"bl b\" style=\"left:53px;top:654px;font-size:17.8px;max-width:221px\">1.2“马克思主义中国化”的命题的提出</span><span class=\"bl\" style=\"left:511px;top:659px;font-size:15.0px;max-width:190px\">导意义，但它的具体运用却要根据各国的</span><span class=\"bl\" style=\"left:78px;top:675px;font-size:17.8px;max-width:423px\">1938年，毛泽东在党的六届六中全会上作的题为《论新阶段》的政治报告中，</span><span class=\"bl\" style=\"left:511px;top:678px;font-size:14.5px;max-width:191px\">具体情况。中国共产党从成立之日起，就</span><span class=\"bl\" style=\"left:55px;top:697px;font-size:15.0px;max-width:224px\">最先提出了“马克思主义中国化”的命题。</span><span class=\"bl\" style=\"left:511px;top:696px;font-size:14.5px;max-width:189px\">面临一个如何把马克思主义基本原理与中</span><span class=\"bl\" style=\"left:451px;top:719px;font-size:15.0px;max-width:48px\">&gt;补充2</span><span class=\"bl\" style=\"left:511px;top:714px;font-size:13.9px;max-width:189px\">国具体实际相结合的问题，即如何实现马</span><span class=\"bl\" style=\"left:511px;top:733px;font-size:13.9px;max-width:111px\">克思主义中国化的问题。</span><span class=\"bl b\" style=\"left:53px;top:745px;font-size:16.7px;max-width:178px\">1.3马克思主义中国化的必要性</span><span class=\"bl\" style=\"left:78px;top:768px;font-size:13.9px;max-width:421px\">理论创造是为了服务于现实，是为了解决和回应现实问题。马克思主义中国化既</span><span class=\"bl\" style=\"left:512px;top:766px;font-size:15.6px;max-width:102px\">火星姐姐背景补充2</span><span class=\"bl\" style=\"left:55px;top:787px;font-size:16.7px;max-width:445px\">是解决中国实际问题的客观需要，又是马克思主义理论本身发展的内在要求。马克思</span><span class=\"bl\" style=\"left:511px;top:790px;font-size:13.9px;max-width:190px\">十月革命一声炮响，给中国送来了马克思</span><span class=\"bl\" style=\"left:54px;top:808px;font-size:16.7px;max-width:445px\">主义只有实现中国化，解决中国的实际问题，才能体现其科学性和生命力，彰显其强</span><span class=\"bl\" style=\"left:511px;top:809px;font-size:12.2px;max-width:188px\">列宁主义，给苦苦探寻救亡图存出路的</span><span class=\"bl\" style=\"left:53px;top:829px;font-size:16.7px;max-width:446px\">大力量。实践证明，中国共产党为什么能，中国特色社会主义为什么好，归根到底是</span><span class=\"bl\" style=\"left:512px;top:826px;font-size:13.9px;max-width:188px\">中国人民指明了前进方向、提供了全新选</span><span class=\"bl\" style=\"left:510px;top:845px;font-size:12.2px;max-width:189px\">择。在马克思列宁主义同中国工人运动的</span><span class=\"bl\" style=\"left:55px;top:851px;font-size:13.9px;max-width:107px\">因为马克思主义行！</span><span class=\"bl\" style=\"left:511px;top:862px;font-size:13.9px;max-width:189px\">紧密结合中，中国共产党在1921年应运而</span><span class=\"bl\" style=\"left:511px;top:880px;font-size:13.9px;max-width:190px\">生。为了实现中华民族伟大复兴，中国共</span><span class=\"bl b hl\" style=\"left:65px;top:891px;font-size:17.8px;max-width:428px\">考点2马克思主义中国化理论成果及其历史进程☆☆（低频选择</span><span class=\"bl\" style=\"left:511px;top:898px;font-size:13.9px;max-width:189px\">产党努力探索马克思主义同中国革命实际</span><span class=\"bl\" style=\"left:66px;top:909px;font-size:16.7px;max-width:95px\">题）（2011.21）</span><span class=\"bl\" style=\"left:511px;top:916px;font-size:13.9px;max-width:189px\">的结合。以毛泽东同志为主要代表的中国</span><span class=\"bl\" style=\"left:511px;top:934px;font-size:13.9px;max-width:189px\">共产党人逐渐认识到，面对中国的特殊国</span><span class=\"bl b\" style=\"left:55px;top:944px;font-size:13.9px;max-width:188px\">2.1马克思主义中国化的理论成果</span><span class=\"bl\" style=\"left:511px;top:953px;font-size:12.2px;max-width:189px\">情，不能教条式地对待马克思列宁主义，</span><span class=\"bl\" style=\"left:77px;top:965px;font-size:13.9px;max-width:423px\">1.百年来，中国共产党推进马克思主义中国化始终围绕着一个主题：实现中华</span><span class=\"bl\" style=\"left:511px;top:970px;font-size:15.0px;max-width:188px\">必须从中国实际出发，实现马克思主义中</span><span class=\"bl\" style=\"left:55px;top:986px;font-size:14.5px;max-width:84px\">民族伟大复兴。</span><span class=\"bl\" style=\"left:510px;top:988px;font-size:15.0px;max-width:34px\">国化。</span><span class=\"bl b\" style=\"left:77px;top:1007px;font-size:13.9px;max-width:388px\">2.马克思主义中国的理论成果：毛泽东思想、中国特色社会主义理论体系。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 5 页</div><span class=\"bl b\" style=\"left:66px;top:111px;font-size:12.2px;max-width:175px\">2.2马克思主义中国化理论进程</span><span class=\"bl\" style=\"left:87px;top:131px;font-size:15.0px;max-width:423px\">1.新民主主义革命时期，党面临的主要任务是，反对帝国主义、封建主义、官</span><span class=\"bl\" style=\"left:65px;top:152px;font-size:15.0px;max-width:446px\">僚资本主义，争取民族独立、人民解放，为实现中华民族伟大复兴创造根本社会条</span><span class=\"bl\" style=\"left:65px;top:172px;font-size:15.0px;max-width:446px\">件。在革命斗争中，以毛泽东同志为主要代表的中国共产党人，把马克思列宁主义</span><span class=\"bl\" style=\"left:65px;top:194px;font-size:15.0px;max-width:446px\">基本原理同中国具体实际相结合，开辟了农村包围城市、武装夺取政权的正确革命道</span><span class=\"bl\" style=\"left:64px;top:215px;font-size:15.0px;max-width:368px\">路，创立了毛泽东思想，为夺取新民主主义革命胜利指明了正确方向。</span><span class=\"bl\" style=\"left:87px;top:236px;font-size:15.0px;max-width:423px\">2.社会主义革命和建设时期，党面临的主要任务是，实现从新民主主义到社会</span><span class=\"bl\" style=\"left:65px;top:256px;font-size:14.5px;max-width:445px\">主义的转变，进行社会主义革命，推进社会主义建设，为实现中华民族伟大复兴奠定</span><span class=\"bl\" style=\"left:66px;top:279px;font-size:12.2px;max-width:444px\">根本政治前提和制度基础。在这个时期，毛泽东提出把马克思列宁主义基本原理同中</span><span class=\"bl\" style=\"left:65px;top:299px;font-size:14.5px;max-width:446px\">国具体实际进行“第二次结合”。毛泽东思想是马克思列宁主义在中国的创造性运用</span><span class=\"bl\" style=\"left:66px;top:321px;font-size:12.2px;max-width:443px\">和发展，是被实践证明了的关于中国革命和建设的正确的理论原则和经验总结，是马</span><span class=\"bl\" style=\"left:66px;top:341px;font-size:12.2px;max-width:199px\">克思主义中国化的第一次历史性飞跃。</span><span class=\"bl\" style=\"left:89px;top:362px;font-size:12.2px;max-width:422px\">3.改革开放和社会主义现代化建设新时期，党面临的主要任务是，继续探索中</span><span class=\"bl\" style=\"left:66px;top:384px;font-size:12.2px;max-width:445px\">国建设社会主义的正确道路，解放和发展社会生产力，使人民摆脱贫困、尽快富裕起</span><span class=\"bl\" style=\"left:66px;top:405px;font-size:12.2px;max-width:436px\">来，为实现中华民族伟大复兴提供充满新的活力的体制保证和快速发展的物质条件。</span><span class=\"bl\" style=\"left:89px;top:424px;font-size:14.5px;max-width:422px\">①党的十一届三中全会以后，以邓小平同志为主要代表的中国共产党人，团结带</span><span class=\"bl\" style=\"left:66px;top:446px;font-size:12.2px;max-width:444px\">领全党全国各族人民，深刻总结新中国成立以来正反两方面经验，围绕什么是社会主</span><span class=\"bl\" style=\"left:67px;top:467px;font-size:12.2px;max-width:443px\">义、怎样建设社会主义这一根本问题，借鉴世界社会主义历史经验，创立了邓小平理</span><span class=\"bl\" style=\"left:65px;top:487px;font-size:17.3px;max-width:59px\">论。二Ⅱ</span><span class=\"bl\" style=\"left:73px;top:506px;font-size:17.3px;max-width:438px\">②党的十三届四中全会以后，以江泽民同志为主要代表的中国共产党人，团结带</span><span class=\"bl\" style=\"left:66px;top:529px;font-size:13.9px;max-width:445px\">领全党全国各族人民，坚持党的基本理论、基本路线，加深了对什么是社会主义、怎</span><span class=\"bl\" style=\"left:65px;top:550px;font-size:13.9px;max-width:446px\">样建设社会主义和建设什么样的党、怎样建设党的认识，形成了“三个代表”重要</span><span class=\"bl\" style=\"left:65px;top:570px;font-size:14.5px;max-width:38px\">思想。</span><span class=\"bl\" style=\"left:89px;top:591px;font-size:14.5px;max-width:422px\">③党的十六大以后，以胡锦涛同志为主要代表的中国共产党人，团结带领全党全</span><span class=\"bl\" style=\"left:65px;top:612px;font-size:14.5px;max-width:447px\">国各族人民，在全面建设小康社会进程中推进实践创新、理论创新、制度创新，深刻</span><span class=\"bl\" style=\"left:65px;top:633px;font-size:14.5px;max-width:441px\">认识和回答了新形势下实现什么样的发展、怎样发展等重大问题，形成了科学发展观。</span><span class=\"bl\" style=\"left:87px;top:654px;font-size:14.5px;max-width:424px\">4.党的十八大以来，中国特色社会主义进入新时代。党面临的主要任务是，实</span><span class=\"bl\" style=\"left:66px;top:676px;font-size:12.2px;max-width:445px\">现第一个百年奋斗自标，开启实现第二个百年奋斗自标新征程，朝着实现中华民族伟</span><span class=\"bl\" style=\"left:65px;top:695px;font-size:14.5px;max-width:446px\">大复兴的宏伟目标继续前进。以习近平同志为主要代表的中国共产党人，坚持把马克</span><span class=\"bl\" style=\"left:65px;top:717px;font-size:14.5px;max-width:445px\">思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持毛泽东思</span><span class=\"bl\" style=\"left:65px;top:738px;font-size:14.5px;max-width:446px\">想、邓小平理论、“三个代表”重要思想、科学发展观，深刻总结并充分运用党成立</span><span class=\"bl\" style=\"left:66px;top:759px;font-size:12.2px;max-width:443px\">以来的历史经验，从新的实际出发，创立了习近平新时代中国特色社会主义思想。习</span><span class=\"bl\" style=\"left:66px;top:780px;font-size:12.2px;max-width:444px\">近平新时代中国特色社会主义思想是当代中国马克思主义、21世纪马克思主义，是</span><span class=\"bl\" style=\"left:66px;top:801px;font-size:12.2px;max-width:366px\">中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。</span><span class=\"bl\" style=\"left:89px;top:822px;font-size:12.2px;max-width:422px\">5.马克思主义中国化的飞跃是一脉相承而又与时俱进的。新民主主义革命时期、</span><span class=\"bl\" style=\"left:66px;top:843px;font-size:12.2px;max-width:445px\">社会主义革命和建设时期创立并不断发展的毛泽东思想是马克思列宁主义在中国的创</span><span class=\"bl\" style=\"left:66px;top:864px;font-size:12.2px;max-width:443px\">造性运用和发展，是被实践证明了的关于中国革命和建设的正确的理论原则和经验总</span><span class=\"bl\" style=\"left:64px;top:883px;font-size:14.5px;max-width:447px\">结，是马克思主义中国化的第一次历史性飞跃；改革开放和现代化建设新时期，在改</span><span class=\"bl\" style=\"left:66px;top:905px;font-size:12.2px;max-width:445px\">革开放实践中创立了邓小平理论、形成了“三个代表”重要思想和科学发展观，形成</span><span class=\"bl\" style=\"left:66px;top:924px;font-size:14.5px;max-width:445px\">了中国特色社会主义理论体系，实现了马克思主义中国化新的飞跃；党的十八大以</span><span class=\"bl\" style=\"left:65px;top:945px;font-size:14.5px;max-width:446px\">来，党提出一系列原创性的治国理政新理念新思想新战略，创立了习近平新时代中国</span><span class=\"bl\" style=\"left:65px;top:966px;font-size:13.4px;max-width:295px\">特色社会主义思想，实现了马克思主义中国化新的飞跃。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 6 页</div><span class=\"bl\" style=\"left:457px;top:61px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:105px;font-size:18.3px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:55px;top:133px;font-size:13.9px;max-width:445px\">1.【2010.21】中国革命、建设和改革的实践证明，要运用马克思主义指导实践，必</span><span class=\"bl\" style=\"left:71px;top:153px;font-size:15.6px;max-width:362px\">须实现马克思主义中国化，马克思主义之所以能够中国化的原因在于</span><span class=\"bl\" style=\"left:70px;top:176px;font-size:13.9px;max-width:164px\">A.马克思主义理论的内在要求</span><span class=\"bl\" style=\"left:71px;top:196px;font-size:13.9px;max-width:245px\">B.马克思主义与中华民族优秀文化具有相融性</span><span class=\"bl\" style=\"left:70px;top:216px;font-size:16.1px;max-width:281px\">C.中国革命、建设和改革的实践需要马克思主义指导</span><span class=\"bl\" style=\"left:70px;top:237px;font-size:15.0px;max-width:328px\">D.马克思主义为中国革命、建设和改革提供了现实的发展模式</span><span class=\"bl\" style=\"left:55px;top:273px;font-size:13.9px;max-width:445px\">2.【2011.21】在马克思主义中国化的过程中，产生了毛泽东思想和中国特色社会主</span><span class=\"bl\" style=\"left:71px;top:293px;font-size:15.0px;max-width:399px\">义理论体系，这两大理论成果的一脉相承性主要体现在，二者具有共同的</span><span class=\"bl\" style=\"left:71px;top:316px;font-size:13.9px;max-width:140px\">A.马克思主义的理论基础</span><span class=\"bl\" style=\"left:71px;top:336px;font-size:13.9px;max-width:138px\">B.革命和建设的根本任务</span><span class=\"bl\" style=\"left:71px;top:357px;font-size:15.6px;max-width:128px\">C.实事求是的理论精髓</span><span class=\"bl\" style=\"left:71px;top:378px;font-size:13.9px;max-width:139px\">D.和平与发展的时代背景</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1090px\"><div class=\"bxnum\">第 7 页</div><div class=\"sidebox\" style=\"left:515px;top:512px;width:195px;height:461px\"></div><span class=\"bl b acc\" style=\"left:357px;top:110px;font-size:25.5px;max-width:66px\">第一章</span><span class=\"bl\" style=\"left:287px;top:160px;font-size:20.0px;max-width:207px\">毛泽东思想及其历史地位</span><span class=\"bl\" style=\"left:68px;top:211px;font-size:16.1px;max-width:99px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:379px;top:252px;font-size:15.5px;max-width:174px\">考点3毛泽东思想的形成和发展</span><span class=\"bl b hl\" style=\"left:379px;top:272px;font-size:17.2px;max-width:162px\">考点4毛泽东思想的主要内容</span><span class=\"bl\" style=\"left:190px;top:283px;font-size:15.5px;max-width:138px\">毛泽东思想及其历史地位</span><span class=\"bl b hl\" style=\"left:379px;top:293px;font-size:17.2px;max-width:151px\">考点5毛泽东思想活的灵魂</span><span class=\"bl b hl\" style=\"left:378px;top:314px;font-size:16.1px;max-width:162px\">考点6毛泽东思想的历史地位</span><span class=\"bl\" style=\"left:65px;top:364px;font-size:19.4px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:91px;top:392px;font-size:17.2px;max-width:621px\">本章主要介绍了毛泽东思想的形成与发展、主要内容与活的灵魂、历史地位等内容。本章是本门科目中考频一般的章</span><span class=\"bl\" style=\"left:68px;top:413px;font-size:16.1px;max-width:644px\">节，考试形式一般为选择题。考生在复习过程中，要重点掌握毛泽东思想的的代表作及其意义、毛泽东思想活的灵魂、毛泽</span><span class=\"bl\" style=\"left:66px;top:433px;font-size:17.2px;max-width:144px\">东思想的历史地位等内容。</span><span class=\"bl b hl\" style=\"left:77px;top:515px;font-size:18.9px;max-width:267px\">考点3毛泽东思想的形成和发展☆☆☆</span><span class=\"bl\" style=\"left:671px;top:518px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:65px;top:550px;font-size:17.8px;max-width:283px\">3.1毛泽东思想形成发展的历史条件（中频选择题）</span><span class=\"bl\" style=\"left:532px;top:546px;font-size:15.5px;max-width:91px\">火星姐姐考点提示1</span><span class=\"bl b\" style=\"left:89px;top:571px;font-size:17.8px;max-width:422px\">1.毛泽东思想：是马克思列宁主义在中国的运用和发展，是被实践证明了的关</span><span class=\"bl\" style=\"left:523px;top:569px;font-size:15.5px;max-width:112px\">毛泽东思想围绕的主题：</span><span class=\"bl\" style=\"left:67px;top:591px;font-size:18.3px;max-width:425px\">于中国革命和建设的正确的理论原则和经验总结，是中国共产党集体智慧的结晶。</span><span class=\"bl\" style=\"left:523px;top:587px;font-size:13.9px;max-width:82px\">中国革命和建设。</span><span class=\"bl\" style=\"left:522px;top:605px;font-size:15.5px;max-width:112px\">邓小平理论围绕的主题：</span><span class=\"bl b\" style=\"left:89px;top:614px;font-size:15.0px;max-width:422px\">2.毛泽东思想形成发展的实践基础：中国共产党领导人民进行的革命和建设的</span><span class=\"bl\" style=\"left:523px;top:624px;font-size:13.9px;max-width:82px\">中国建设和改革。</span><span class=\"bl\" style=\"left:66px;top:635px;font-size:16.1px;max-width:63px\">成功实践。</span><span class=\"bl\" style=\"left:464px;top:636px;font-size:14.4px;max-width:46px\">&gt;提示1</span><span class=\"bl b\" style=\"left:88px;top:654px;font-size:17.8px;max-width:423px\">3.毛泽东思想形成发展的时代背景/主题：帝国主义战争与无产阶级革命的时代</span><span class=\"bl\" style=\"left:533px;top:659px;font-size:15.0px;max-width:90px\">火星姐姐考点补充1</span><span class=\"bl\" style=\"left:66px;top:677px;font-size:15.0px;max-width:37px\">主题。</span><span class=\"bl\" style=\"left:463px;top:678px;font-size:15.0px;max-width:48px\">&gt;补充1</span><span class=\"bl\" style=\"left:522px;top:682px;font-size:13.9px;max-width:188px\">19世纪末20世纪初，世界进入帝国主义</span><span class=\"bl b\" style=\"left:65px;top:703px;font-size:17.2px;max-width:333px\">3.2毛泽东思想形成和发展的过程（中频选择题）（2017-11）</span><span class=\"bl\" style=\"left:521px;top:700px;font-size:15.0px;max-width:190px\">和无产阶级革命时代。1917年俄国十月革</span><span class=\"bl\" style=\"left:522px;top:718px;font-size:13.9px;max-width:189px\">命的胜利开辟了世界无产阶级社会主义革</span><span class=\"bl\" style=\"left:71px;top:733px;font-size:18.3px;max-width:35px\">阶段</span><span class=\"bl\" style=\"left:184px;top:733px;font-size:17.8px;max-width:45px\">代表作</span><span class=\"bl\" style=\"left:390px;top:733px;font-size:18.3px;max-width:34px\">内容</span><span class=\"bl\" style=\"left:522px;top:736px;font-size:13.9px;max-width:189px\">命的新时代。它使中国反帝反封建的民主</span><span class=\"bl\" style=\"left:523px;top:755px;font-size:13.9px;max-width:189px\">革命从旧的世界资产阶级民主革命的一部</span><span class=\"bl\" style=\"left:309px;top:767px;font-size:17.2px;max-width:181px\">第一次国内革命战争时期（1924一</span><span class=\"bl\" style=\"left:73px;top:776px;font-size:16.1px;max-width:33px\">萌芽</span><span class=\"bl\" style=\"left:108px;top:777px;font-size:16.1px;max-width:138px\">中国社会各阶级的分析</span><span class=\"bl\" style=\"left:522px;top:772px;font-size:13.9px;max-width:189px\">分，转变为新的世界无产阶级社会主义革</span><span class=\"bl\" style=\"left:308px;top:787px;font-size:16.1px;max-width:194px\">1927年），毛泽东深刻分析了中国</span><span class=\"bl\" style=\"left:72px;top:796px;font-size:15.5px;max-width:33px\">时期</span><span class=\"bl\" style=\"left:521px;top:791px;font-size:14.4px;max-width:65px\">命的一部分。</span><span class=\"bl\" style=\"left:108px;top:797px;font-size:15.5px;max-width:138px\">湖南农民运动考察报告</span><span class=\"bl\" style=\"left:308px;top:807px;font-size:17.2px;max-width:192px\">社会各阶级在革命中的地位和作用。</span><span class=\"bl\" style=\"left:522px;top:810px;font-size:13.9px;max-width:188px\">十月革命给中国送来了马克思列宁主义，</span><span class=\"bl\" style=\"left:522px;top:828px;font-size:13.9px;max-width:188px\">帮助中国的先进分子开始用无产阶级的世</span><span class=\"bl\" style=\"left:309px;top:840px;font-size:17.2px;max-width:194px\">土地革命战争时期（1927—1937年），</span><span class=\"bl\" style=\"left:110px;top:850px;font-size:16.1px;max-width:60px\">革命道路：</span><span class=\"bl\" style=\"left:522px;top:846px;font-size:13.9px;max-width:188px\">界观作为观察国家命运的工具，中国革命</span><span class=\"bl\" style=\"left:309px;top:860px;font-size:16.1px;max-width:194px\">毛泽东在同党内一度盛行的把马克思</span><span class=\"bl\" style=\"left:521px;top:863px;font-size:15.5px;max-width:123px\">从此有了科学的指导思想。</span><span class=\"bl\" style=\"left:108px;top:869px;font-size:16.1px;max-width:192px\">中国的红色政权为什么能够存在？</span><span class=\"bl\" style=\"left:309px;top:879px;font-size:17.2px;max-width:194px\">主义教条化、把共产国际决议和苏联</span><span class=\"bl\" style=\"left:522px;top:882px;font-size:13.9px;max-width:188px\">中国在革命取得胜利后，又经历了第二次</span><span class=\"bl\" style=\"left:71px;top:888px;font-size:15.0px;max-width:33px\">形成</span><span class=\"bl\" style=\"left:107px;top:889px;font-size:14.4px;max-width:93px\">井冈山的斗争</span><span class=\"bl\" style=\"left:308px;top:899px;font-size:16.1px;max-width:195px\">经验神圣化的错误倾向的斗争中，提</span><span class=\"bl\" style=\"left:521px;top:900px;font-size:13.9px;max-width:188px\">世界大战后两大阵营的对立和斗争，西方</span><span class=\"bl\" style=\"left:71px;top:908px;font-size:15.0px;max-width:33px\">时期</span><span class=\"bl\" style=\"left:107px;top:906px;font-size:17.8px;max-width:127px\">星星之火，可以燎原</span><span class=\"bl\" style=\"left:308px;top:918px;font-size:17.2px;max-width:194px\">出并阐述了农村包围城市、武装夺取</span><span class=\"bl\" style=\"left:522px;top:919px;font-size:12.2px;max-width:188px\">国家不仅对我国实行持续的封锁禁运，还</span><span class=\"bl\" style=\"left:108px;top:927px;font-size:16.1px;max-width:93px\">反对本本主义</span><span class=\"bl\" style=\"left:307px;top:937px;font-size:17.8px;max-width:195px\">政权的思想，标志着毛泽东思想的初</span><span class=\"bl\" style=\"left:521px;top:936px;font-size:13.9px;max-width:188px\">极力推行和平演变战略。毛泽东思想正是</span><span class=\"bl\" style=\"left:108px;top:945px;font-size:18.3px;max-width:68px\">“本斗红火”</span><span class=\"bl\" style=\"left:307px;top:956px;font-size:17.2px;max-width:46px\">步形成</span><span class=\"bl\" style=\"left:521px;top:954px;font-size:15.0px;max-width:183px\">在这样的时代条件下形成和发展起来的。</span></div></div>"}],pages:[4,7]};
  D["mzt_s2"] = {id:"mzt_s2",ch:"毛中特讲义 · 第一章 毛泽东思想及其历史地位",title:"第一章 毛泽东思想及其历史地位",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1090px\"><div class=\"bxnum\">第 7 页</div><div class=\"sidebox\" style=\"left:515px;top:512px;width:195px;height:461px\"></div><span class=\"bl b acc\" style=\"left:357px;top:110px;font-size:25.5px;max-width:66px\">第一章</span><span class=\"bl\" style=\"left:287px;top:160px;font-size:20.0px;max-width:207px\">毛泽东思想及其历史地位</span><span class=\"bl\" style=\"left:68px;top:211px;font-size:16.1px;max-width:99px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:379px;top:252px;font-size:15.5px;max-width:174px\">考点3毛泽东思想的形成和发展</span><span class=\"bl b hl\" style=\"left:379px;top:272px;font-size:17.2px;max-width:162px\">考点4毛泽东思想的主要内容</span><span class=\"bl\" style=\"left:190px;top:283px;font-size:15.5px;max-width:138px\">毛泽东思想及其历史地位</span><span class=\"bl b hl\" style=\"left:379px;top:293px;font-size:17.2px;max-width:151px\">考点5毛泽东思想活的灵魂</span><span class=\"bl b hl\" style=\"left:378px;top:314px;font-size:16.1px;max-width:162px\">考点6毛泽东思想的历史地位</span><span class=\"bl\" style=\"left:65px;top:364px;font-size:19.4px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:91px;top:392px;font-size:17.2px;max-width:621px\">本章主要介绍了毛泽东思想的形成与发展、主要内容与活的灵魂、历史地位等内容。本章是本门科目中考频一般的章</span><span class=\"bl\" style=\"left:68px;top:413px;font-size:16.1px;max-width:644px\">节，考试形式一般为选择题。考生在复习过程中，要重点掌握毛泽东思想的的代表作及其意义、毛泽东思想活的灵魂、毛泽</span><span class=\"bl\" style=\"left:66px;top:433px;font-size:17.2px;max-width:144px\">东思想的历史地位等内容。</span><span class=\"bl b hl\" style=\"left:77px;top:515px;font-size:18.9px;max-width:267px\">考点3毛泽东思想的形成和发展☆☆☆</span><span class=\"bl\" style=\"left:671px;top:518px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:65px;top:550px;font-size:17.8px;max-width:283px\">3.1毛泽东思想形成发展的历史条件（中频选择题）</span><span class=\"bl\" style=\"left:532px;top:546px;font-size:15.5px;max-width:91px\">火星姐姐考点提示1</span><span class=\"bl b\" style=\"left:89px;top:571px;font-size:17.8px;max-width:422px\">1.毛泽东思想：是马克思列宁主义在中国的运用和发展，是被实践证明了的关</span><span class=\"bl\" style=\"left:523px;top:569px;font-size:15.5px;max-width:112px\">毛泽东思想围绕的主题：</span><span class=\"bl\" style=\"left:67px;top:591px;font-size:18.3px;max-width:425px\">于中国革命和建设的正确的理论原则和经验总结，是中国共产党集体智慧的结晶。</span><span class=\"bl\" style=\"left:523px;top:587px;font-size:13.9px;max-width:82px\">中国革命和建设。</span><span class=\"bl\" style=\"left:522px;top:605px;font-size:15.5px;max-width:112px\">邓小平理论围绕的主题：</span><span class=\"bl b\" style=\"left:89px;top:614px;font-size:15.0px;max-width:422px\">2.毛泽东思想形成发展的实践基础：中国共产党领导人民进行的革命和建设的</span><span class=\"bl\" style=\"left:523px;top:624px;font-size:13.9px;max-width:82px\">中国建设和改革。</span><span class=\"bl\" style=\"left:66px;top:635px;font-size:16.1px;max-width:63px\">成功实践。</span><span class=\"bl\" style=\"left:464px;top:636px;font-size:14.4px;max-width:46px\">&gt;提示1</span><span class=\"bl b\" style=\"left:88px;top:654px;font-size:17.8px;max-width:423px\">3.毛泽东思想形成发展的时代背景/主题：帝国主义战争与无产阶级革命的时代</span><span class=\"bl\" style=\"left:533px;top:659px;font-size:15.0px;max-width:90px\">火星姐姐考点补充1</span><span class=\"bl\" style=\"left:66px;top:677px;font-size:15.0px;max-width:37px\">主题。</span><span class=\"bl\" style=\"left:463px;top:678px;font-size:15.0px;max-width:48px\">&gt;补充1</span><span class=\"bl\" style=\"left:522px;top:682px;font-size:13.9px;max-width:188px\">19世纪末20世纪初，世界进入帝国主义</span><span class=\"bl b\" style=\"left:65px;top:703px;font-size:17.2px;max-width:333px\">3.2毛泽东思想形成和发展的过程（中频选择题）（2017-11）</span><span class=\"bl\" style=\"left:521px;top:700px;font-size:15.0px;max-width:190px\">和无产阶级革命时代。1917年俄国十月革</span><span class=\"bl\" style=\"left:522px;top:718px;font-size:13.9px;max-width:189px\">命的胜利开辟了世界无产阶级社会主义革</span><span class=\"bl\" style=\"left:71px;top:733px;font-size:18.3px;max-width:35px\">阶段</span><span class=\"bl\" style=\"left:184px;top:733px;font-size:17.8px;max-width:45px\">代表作</span><span class=\"bl\" style=\"left:390px;top:733px;font-size:18.3px;max-width:34px\">内容</span><span class=\"bl\" style=\"left:522px;top:736px;font-size:13.9px;max-width:189px\">命的新时代。它使中国反帝反封建的民主</span><span class=\"bl\" style=\"left:523px;top:755px;font-size:13.9px;max-width:189px\">革命从旧的世界资产阶级民主革命的一部</span><span class=\"bl\" style=\"left:309px;top:767px;font-size:17.2px;max-width:181px\">第一次国内革命战争时期（1924一</span><span class=\"bl\" style=\"left:73px;top:776px;font-size:16.1px;max-width:33px\">萌芽</span><span class=\"bl\" style=\"left:108px;top:777px;font-size:16.1px;max-width:138px\">中国社会各阶级的分析</span><span class=\"bl\" style=\"left:522px;top:772px;font-size:13.9px;max-width:189px\">分，转变为新的世界无产阶级社会主义革</span><span class=\"bl\" style=\"left:308px;top:787px;font-size:16.1px;max-width:194px\">1927年），毛泽东深刻分析了中国</span><span class=\"bl\" style=\"left:72px;top:796px;font-size:15.5px;max-width:33px\">时期</span><span class=\"bl\" style=\"left:521px;top:791px;font-size:14.4px;max-width:65px\">命的一部分。</span><span class=\"bl\" style=\"left:108px;top:797px;font-size:15.5px;max-width:138px\">湖南农民运动考察报告</span><span class=\"bl\" style=\"left:308px;top:807px;font-size:17.2px;max-width:192px\">社会各阶级在革命中的地位和作用。</span><span class=\"bl\" style=\"left:522px;top:810px;font-size:13.9px;max-width:188px\">十月革命给中国送来了马克思列宁主义，</span><span class=\"bl\" style=\"left:522px;top:828px;font-size:13.9px;max-width:188px\">帮助中国的先进分子开始用无产阶级的世</span><span class=\"bl\" style=\"left:309px;top:840px;font-size:17.2px;max-width:194px\">土地革命战争时期（1927—1937年），</span><span class=\"bl\" style=\"left:110px;top:850px;font-size:16.1px;max-width:60px\">革命道路：</span><span class=\"bl\" style=\"left:522px;top:846px;font-size:13.9px;max-width:188px\">界观作为观察国家命运的工具，中国革命</span><span class=\"bl\" style=\"left:309px;top:860px;font-size:16.1px;max-width:194px\">毛泽东在同党内一度盛行的把马克思</span><span class=\"bl\" style=\"left:521px;top:863px;font-size:15.5px;max-width:123px\">从此有了科学的指导思想。</span><span class=\"bl\" style=\"left:108px;top:869px;font-size:16.1px;max-width:192px\">中国的红色政权为什么能够存在？</span><span class=\"bl\" style=\"left:309px;top:879px;font-size:17.2px;max-width:194px\">主义教条化、把共产国际决议和苏联</span><span class=\"bl\" style=\"left:522px;top:882px;font-size:13.9px;max-width:188px\">中国在革命取得胜利后，又经历了第二次</span><span class=\"bl\" style=\"left:71px;top:888px;font-size:15.0px;max-width:33px\">形成</span><span class=\"bl\" style=\"left:107px;top:889px;font-size:14.4px;max-width:93px\">井冈山的斗争</span><span class=\"bl\" style=\"left:308px;top:899px;font-size:16.1px;max-width:195px\">经验神圣化的错误倾向的斗争中，提</span><span class=\"bl\" style=\"left:521px;top:900px;font-size:13.9px;max-width:188px\">世界大战后两大阵营的对立和斗争，西方</span><span class=\"bl\" style=\"left:71px;top:908px;font-size:15.0px;max-width:33px\">时期</span><span class=\"bl\" style=\"left:107px;top:906px;font-size:17.8px;max-width:127px\">星星之火，可以燎原</span><span class=\"bl\" style=\"left:308px;top:918px;font-size:17.2px;max-width:194px\">出并阐述了农村包围城市、武装夺取</span><span class=\"bl\" style=\"left:522px;top:919px;font-size:12.2px;max-width:188px\">国家不仅对我国实行持续的封锁禁运，还</span><span class=\"bl\" style=\"left:108px;top:927px;font-size:16.1px;max-width:93px\">反对本本主义</span><span class=\"bl\" style=\"left:307px;top:937px;font-size:17.8px;max-width:195px\">政权的思想，标志着毛泽东思想的初</span><span class=\"bl\" style=\"left:521px;top:936px;font-size:13.9px;max-width:188px\">极力推行和平演变战略。毛泽东思想正是</span><span class=\"bl\" style=\"left:108px;top:945px;font-size:18.3px;max-width:68px\">“本斗红火”</span><span class=\"bl\" style=\"left:307px;top:956px;font-size:17.2px;max-width:46px\">步形成</span><span class=\"bl\" style=\"left:521px;top:954px;font-size:15.0px;max-width:183px\">在这样的时代条件下形成和发展起来的。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 8 页</div><div class=\"sidebox\" style=\"left:465px;top:100px;width:238px;height:126px\"></div><span class=\"bl\" style=\"left:462px;top:62px;font-size:15.6px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:471px;top:106px;font-size:17.8px;max-width:35px\">续表</span><span class=\"bl\" style=\"left:515px;top:116px;font-size:13.9px;max-width:190px\">（接上页）毛泽东思想正是在我国新民主</span><span class=\"bl\" style=\"left:64px;top:132px;font-size:18.3px;max-width:35px\">阶段</span><span class=\"bl\" style=\"left:177px;top:132px;font-size:17.8px;max-width:45px\">代表作</span><span class=\"bl\" style=\"left:383px;top:131px;font-size:18.3px;max-width:34px\">内容</span><span class=\"bl\" style=\"left:516px;top:135px;font-size:13.9px;max-width:189px\">主义革命、社会主义革命和社会主义建设</span><span class=\"bl\" style=\"left:515px;top:153px;font-size:13.9px;max-width:190px\">的实践过程中，在总结我国革命和建设正</span><span class=\"bl\" style=\"left:103px;top:168px;font-size:14.5px;max-width:93px\">新民主主义理论：</span><span class=\"bl\" style=\"left:302px;top:167px;font-size:15.6px;max-width:184px\">遵义会议以后，直至抗日战争时期。</span><span class=\"bl\" style=\"left:515px;top:172px;font-size:13.9px;max-width:190px\">反两方面历史经验的基础上，逐步形成和</span><span class=\"bl\" style=\"left:102px;top:187px;font-size:15.6px;max-width:109px\">实践论》《矛盾论</span><span class=\"bl\" style=\"left:304px;top:187px;font-size:13.9px;max-width:191px\">毛泽东科学阐述了新民主主义革命的</span><span class=\"bl\" style=\"left:515px;top:190px;font-size:13.9px;max-width:190px\">发展起来的。毛泽东思想是马克思主义中</span><span class=\"bl\" style=\"left:102px;top:206px;font-size:15.6px;max-width:126px\">&lt;共产党人&gt;发刊词</span><span class=\"bl\" style=\"left:302px;top:205px;font-size:16.7px;max-width:192px\">对象、动力、领导力量、性质和前途</span><span class=\"bl\" style=\"left:516px;top:208px;font-size:13.9px;max-width:132px\">国化的第一个重大理论成果。</span><span class=\"bl\" style=\"left:102px;top:225px;font-size:16.7px;max-width:92px\">新民主主义论</span><span class=\"bl\" style=\"left:304px;top:226px;font-size:13.9px;max-width:191px\">等基本问题，提出了新民主主义革命</span><span class=\"bl\" style=\"left:65px;top:244px;font-size:16.7px;max-width:33px\">成熟</span><span class=\"bl\" style=\"left:101px;top:246px;font-size:14.5px;max-width:81px\">论联合政府</span><span class=\"bl\" style=\"left:302px;top:246px;font-size:13.9px;max-width:192px\">的总路线。新民主主义革命理论的系</span><span class=\"bl\" style=\"left:65px;top:264px;font-size:15.6px;max-width:34px\">时期</span><span class=\"bl\" style=\"left:102px;top:266px;font-size:13.9px;max-width:136px\">中国革命和中国共产党</span><span class=\"bl\" style=\"left:302px;top:264px;font-size:16.7px;max-width:193px\">统阐述，标志着这毛泽东思想得到多</span><span class=\"bl\" style=\"left:103px;top:284px;font-size:15.6px;max-width:147px\">中国革命战争的战略问题</span><span class=\"bl\" style=\"left:302px;top:283px;font-size:17.2px;max-width:115px\">方面展开而趋于成熟</span><span class=\"bl\" style=\"left:103px;top:304px;font-size:15.6px;max-width:103px\">改造我们的学习</span><span class=\"bl\" style=\"left:303px;top:303px;font-size:15.6px;max-width:183px\">1945年党的七大，将毛泽东思想写</span><span class=\"bl\" style=\"left:103px;top:324px;font-size:14.5px;max-width:90px\">整顿党的作风</span><span class=\"bl\" style=\"left:302px;top:323px;font-size:15.6px;max-width:192px\">入党章，确立为党必须长期坚持的指</span><span class=\"bl\" style=\"left:100px;top:340px;font-size:21.1px;max-width:48px\">“党论”</span><span class=\"bl\" style=\"left:302px;top:343px;font-size:17.2px;max-width:45px\">导思想</span><span class=\"bl\" style=\"left:302px;top:376px;font-size:16.7px;max-width:174px\">解放战争时期和新中国成立以后。</span><span class=\"bl\" style=\"left:102px;top:385px;font-size:17.8px;max-width:102px\">人民民主专政理论</span><span class=\"bl\" style=\"left:304px;top:397px;font-size:13.9px;max-width:192px\">毛泽东明确提出了把马克思列宁主义</span><span class=\"bl\" style=\"left:103px;top:406px;font-size:15.6px;max-width:103px\">社会主义改造理论</span><span class=\"bl\" style=\"left:303px;top:416px;font-size:13.9px;max-width:194px\">的基本原理同中国革命和建设的具体</span><span class=\"bl\" style=\"left:65px;top:424px;font-size:17.2px;max-width:35px\">继续</span><span class=\"bl\" style=\"left:98px;top:425px;font-size:15.6px;max-width:107px\">论人民民主专政</span><span class=\"bl\" style=\"left:303px;top:436px;font-size:13.9px;max-width:194px\">实际进行“第二次结合，找出在中国</span><span class=\"bl\" style=\"left:66px;top:445px;font-size:15.6px;max-width:33px\">发展</span><span class=\"bl\" style=\"left:102px;top:445px;font-size:14.5px;max-width:80px\">论十大关系</span><span class=\"bl\" style=\"left:302px;top:455px;font-size:15.6px;max-width:195px\">怎样建设社会主义的道路”的任务，</span><span class=\"bl\" style=\"left:103px;top:465px;font-size:15.6px;max-width:193px\">关于正确处理人民内部矛盾的问题</span><span class=\"bl\" style=\"left:302px;top:475px;font-size:15.0px;max-width:195px\">并为开辟适合中国国情的社会主义建</span><span class=\"bl\" style=\"left:67px;top:479px;font-size:56.2px;max-width:228px\">微信众号</span><span class=\"bl\" style=\"left:105px;top:483px;font-size:20.0px;max-width:114px\">“正确处理民主关系”</span><span class=\"bl\" style=\"left:303px;top:494px;font-size:16.7px;max-width:129px\">设道路进行了艰辛探索。</span><span class=\"bl b hl\" style=\"left:70px;top:540px;font-size:17.8px;max-width:241px\">考点4毛泽东思想的主要内容</span><span class=\"bl b\" style=\"left:60px;top:576px;font-size:13.9px;max-width:216px\">4.1新民主主义革命理论（中频选择题）</span><span class=\"bl\" style=\"left:84px;top:597px;font-size:13.9px;max-width:420px\">新民主主义革命理论是反映中国新民主主义革命客观规律的完备的理论形态，是</span><span class=\"bl\" style=\"left:59px;top:618px;font-size:15.6px;max-width:178px\">毛泽东思想达到成熟的主要标志。</span><span class=\"bl b\" style=\"left:59px;top:645px;font-size:16.7px;max-width:294px\">4.2社会主义革命和社会主义建设理论（低频选择题）</span><span class=\"bl\" style=\"left:83px;top:668px;font-size:13.9px;max-width:297px\">1.采取社会主义工业化和社会主义改造同时并举的方针。</span><span class=\"bl\" style=\"left:83px;top:688px;font-size:13.9px;max-width:403px\">2.在社会主义制度建立以后，提出了一系列具有战略意义的正确思想和方针。</span><span class=\"bl b\" style=\"left:59px;top:714px;font-size:16.7px;max-width:281px\">4.3革命军队建设和军事战略的理论（低频选择题）</span><span class=\"bl\" style=\"left:82px;top:737px;font-size:15.6px;max-width:117px\">1.革命军队建设理论</span><span class=\"bl\" style=\"left:84px;top:757px;font-size:16.7px;max-width:421px\">毛泽东系统解决了如何把以农民为主要成分的革命军队建设成为一支无产阶级性</span><span class=\"bl\" style=\"left:60px;top:779px;font-size:13.9px;max-width:388px\">质的、具有严格纪律的、同人民群众保持亲密联系的新型人民军队的问题。</span><span class=\"bl\" style=\"left:84px;top:801px;font-size:13.9px;max-width:268px\">①规定全心全意为人民服务是人民军队的唯一宗旨</span><span class=\"bl\" style=\"left:84px;top:821px;font-size:13.9px;max-width:224px\">②规定了党指挥枪而不是枪指挥党的原则。</span><span class=\"bl\" style=\"left:84px;top:841px;font-size:13.9px;max-width:166px\">③制定了三大纪律、八项注意。</span><span class=\"bl\" style=\"left:84px;top:861px;font-size:15.6px;max-width:191px\">④实行政治、经济、军事三大民主。</span><span class=\"bl\" style=\"left:83px;top:881px;font-size:17.2px;max-width:421px\">5实行官兵一致、军民一致和瓦解敌军的原则，提出和总结了一套军队政治工作</span><span class=\"bl\" style=\"left:60px;top:904px;font-size:14.5px;max-width:84px\">的方针和方法。</span><span class=\"bl\" style=\"left:84px;top:922px;font-size:17.2px;max-width:421px\">6提出以人民军队为骨干，依靠广大人民群众，建立农村根据地，进行人民战争</span><span class=\"bl\" style=\"left:60px;top:945px;font-size:14.5px;max-width:49px\">的思想。</span><span class=\"bl\" style=\"left:85px;top:966px;font-size:13.9px;max-width:177px\">7解决了新型人民军队建设问题。</span><span class=\"bl\" style=\"left:83px;top:986px;font-size:14.5px;max-width:93px\">2.军事战略理论</span><span class=\"bl\" style=\"left:84px;top:1007px;font-size:15.6px;max-width:166px\">①把游击战争提到战略的地位。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 9 页</div><div class=\"sidebox\" style=\"left:512px;top:697px;width:195px;height:304px\"></div><span class=\"bl\" style=\"left:86px;top:107px;font-size:13.9px;max-width:118px\">②因势调整军事战略。</span><span class=\"bl\" style=\"left:85px;top:129px;font-size:13.9px;max-width:202px\">③制定了一系列人民战争的战略战术。</span><span class=\"bl\" style=\"left:86px;top:149px;font-size:13.9px;max-width:118px\">④制定十大军事原则。</span><span class=\"bl b\" style=\"left:62px;top:177px;font-size:13.9px;max-width:206px\">4.4政策和策略的理论（低频选择题）</span><span class=\"bl\" style=\"left:85px;top:197px;font-size:15.0px;max-width:419px\">1.论证了革命斗争中政策和策略问题的极端重要性，把原则性和灵活性结合起来。</span><span class=\"bl\" style=\"left:86px;top:221px;font-size:12.2px;max-width:308px\">2.在实践经验的基础上，提出许多重要的政策和策略思想。</span><span class=\"bl\" style=\"left:459px;top:220px;font-size:15.0px;max-width:47px\">&gt;补充1</span><span class=\"bl\" style=\"left:521px;top:223px;font-size:13.9px;max-width:99px\">火星姐姐背景补充1</span><span class=\"bl b\" style=\"left:63px;top:248px;font-size:12.2px;max-width:279px\">4.5思想政治工作和文化工作的理论（低频选择题）</span><span class=\"bl\" style=\"left:519px;top:244px;font-size:13.9px;max-width:190px\">毛泽东策略思想：弱小的革命力量在变化</span><span class=\"bl\" style=\"left:86px;top:268px;font-size:13.9px;max-width:286px\">1.思想政治工作是经济工作和其他一切工作的生命线。</span><span class=\"bl\" style=\"left:520px;top:264px;font-size:12.2px;max-width:188px\">着的主客观条件下能够最终战胜强大的反</span><span class=\"bl\" style=\"left:519px;top:282px;font-size:12.2px;max-width:188px\">动力量；战略上要视敌人，战术上要重</span><span class=\"bl\" style=\"left:85px;top:289px;font-size:13.9px;max-width:203px\">2.发展民族的、科学的、大众的文化。</span><span class=\"bl\" style=\"left:519px;top:300px;font-size:13.9px;max-width:189px\">视敌人；要掌握斗争的主要方向，不要四</span><span class=\"bl\" style=\"left:86px;top:310px;font-size:12.2px;max-width:367px\">3.实行百花齐放、百家争鸣和古为今用、洋为中用、推陈出新的方针。</span><span class=\"bl\" style=\"left:520px;top:318px;font-size:12.2px;max-width:188px\">面出击；对敌人要区别对待、分化瓦解，</span><span class=\"bl\" style=\"left:85px;top:330px;font-size:13.9px;max-width:299px\">4.知识分子同工农相结合，树立无产阶级世界观的思想。</span><span class=\"bl\" style=\"left:519px;top:335px;font-size:15.0px;max-width:189px\">实行利用矛盾、争取多数、反对少数、各</span><span class=\"bl b\" style=\"left:62px;top:358px;font-size:13.9px;max-width:180px\">4.6党的建设理论（低频选择题）</span><span class=\"bl\" style=\"left:519px;top:354px;font-size:13.9px;max-width:189px\">个击破的策略，并做到有理、有利、有</span><span class=\"bl\" style=\"left:519px;top:372px;font-size:13.9px;max-width:189px\">节；在反动统治地区，把公开斗争与秘密</span><span class=\"bl\" style=\"left:85px;top:379px;font-size:15.0px;max-width:204px\">1.不仅组织上入党，更要思想上人党。</span><span class=\"bl\" style=\"left:519px;top:391px;font-size:12.2px;max-width:188px\">斗争结合起来，在组织上采取隐蔽精干的</span><span class=\"bl b\" style=\"left:86px;top:401px;font-size:12.2px;max-width:328px\">2.中国共产党区别于其他任何政党的显著标志是：（三大作风）</span><span class=\"bl\" style=\"left:519px;top:409px;font-size:12.2px;max-width:188px\">方针；对被打倒的反动统治阶级成员和反</span><span class=\"bl\" style=\"left:85px;top:420px;font-size:16.7px;max-width:155px\">①理论和实践相结合的作风；</span><span class=\"bl\" style=\"left:520px;top:428px;font-size:12.2px;max-width:187px\">动分子，只要他们不造反、不捣乱，都给</span><span class=\"bl\" style=\"left:87px;top:443px;font-size:12.2px;max-width:199px\">②和人民群众紧密联系在一起的作风；</span><span class=\"bl\" style=\"left:520px;top:446px;font-size:12.2px;max-width:187px\">予生活出路，让他们在劳动中改造成为自</span><span class=\"bl\" style=\"left:86px;top:464px;font-size:12.2px;max-width:185px\">③自我批评的作风。（七大上提出）</span><span class=\"bl\" style=\"left:519px;top:463px;font-size:13.9px;max-width:93px\">食其力的劳动者等。</span><span class=\"bl b\" style=\"left:84px;top:504px;font-size:15.6px;max-width:162px\">4.提出两个务必：</span><span class=\"bl\" style=\"left:85px;top:526px;font-size:16.7px;max-width:237px\">①保持谦虚、谨慎、不骄、不躁的工作作风；</span><span class=\"bl\" style=\"left:338px;top:533px;font-size:52.3px;max-width:119px\">上</span><span class=\"bl\" style=\"left:87px;top:547px;font-size:13.9px;max-width:262px\">②保持艰苦奋斗的作风。（七届二中全会上提出）</span><span class=\"bl b hl\" style=\"left:74px;top:587px;font-size:15.6px;max-width:236px\">考点5毛泽东思想活的灵魂☆☆☆</span><span class=\"bl\" style=\"left:85px;top:615px;font-size:15.0px;max-width:423px\">提出：1981年党的十一届六中全会通过的《关于建国以来党的若干历史问题的</span><span class=\"bl\" style=\"left:63px;top:635px;font-size:14.5px;max-width:445px\">决议》指出：贯穿于毛泽东思想各个组成部分的立场、观点和方法，是毛泽东思想的</span><span class=\"bl\" style=\"left:63px;top:656px;font-size:13.9px;max-width:366px\">活的灵魂，它们有三个基本方面，即实事求是，群众路线，独立自主。</span><span class=\"bl b\" style=\"left:62px;top:683px;font-size:13.9px;max-width:255px\">5.1实事求是（中频选择题）（2012-5、2016-5）</span><span class=\"bl b\" style=\"left:86px;top:704px;font-size:13.9px;max-width:216px\">1.毛泽东思想的核心和精髓：实事求是。</span><span class=\"bl\" style=\"left:460px;top:702px;font-size:14.5px;max-width:46px\">&gt;提示1</span><span class=\"bl\" style=\"left:521px;top:703px;font-size:15.6px;max-width:99px\">火星姐姐考点提示1</span><span class=\"bl b\" style=\"left:85px;top:722px;font-size:13.9px;max-width:414px\">2.含义：一切从实际出发，理论联系实际，坚持在实践中检验真理和发展真理。</span><span class=\"bl\" style=\"left:519px;top:726px;font-size:13.9px;max-width:190px\">马列主义、毛泽东思想和邓小平理论的精</span><span class=\"bl\" style=\"left:460px;top:742px;font-size:15.0px;max-width:46px\">&gt;拓展1</span><span class=\"bl\" style=\"left:518px;top:744px;font-size:13.9px;max-width:74px\">髓：实事求是。</span><span class=\"bl b\" style=\"left:84px;top:761px;font-size:14.5px;max-width:65px\">3.重要性：</span><span class=\"bl\" style=\"left:86px;top:781px;font-size:13.9px;max-width:201px\">①实事求是是马克思主义的根本观点。</span><span class=\"bl\" style=\"left:520px;top:779px;font-size:15.6px;max-width:102px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:87px;top:801px;font-size:13.9px;max-width:318px\">②实事求是是中国共产党人认识世界、改造世界的根本要求。</span><span class=\"bl\" style=\"left:519px;top:802px;font-size:13.9px;max-width:189px\">毛泽东指出：“实事”就是客观存在着的</span><span class=\"bl\" style=\"left:86px;top:821px;font-size:14.5px;max-width:342px\">③实事求是是中国共产党的基本思想方法、工作方法、领导方法。</span><span class=\"bl\" style=\"left:519px;top:821px;font-size:13.9px;max-width:189px\">一切事物，‘是”就是客观事物的内部联</span><span class=\"bl\" style=\"left:86px;top:841px;font-size:13.9px;max-width:308px\">④实事求是是党的思想路线的核心，是党的根本思想路线。</span><span class=\"bl\" style=\"left:519px;top:838px;font-size:15.0px;max-width:181px\">系，即规律性，‘求”就是我们去研究。”</span><span class=\"bl b\" style=\"left:84px;top:860px;font-size:14.5px;max-width:53px\">4.要求：</span><span class=\"bl\" style=\"left:520px;top:857px;font-size:13.9px;max-width:189px\">习近平在纪念毛泽东同志诞辰120周年座</span><span class=\"bl\" style=\"left:86px;top:879px;font-size:15.0px;max-width:330px\">①深人事物本来面貌，把握内在必然联系，按照客观规律办事。</span><span class=\"bl\" style=\"left:519px;top:875px;font-size:14.5px;max-width:189px\">谈会上指出：“实事求是，是马克思主义</span><span class=\"bl\" style=\"left:86px;top:899px;font-size:15.0px;max-width:201px\">②清醒认识和正确把握我国基本国情。</span><span class=\"bl\" style=\"left:520px;top:894px;font-size:12.2px;max-width:188px\">的根本观点，是中国共产党人认识世界、</span><span class=\"bl\" style=\"left:519px;top:912px;font-size:12.2px;max-width:189px\">改造世界的根本要求，是我们党的基本</span><span class=\"bl\" style=\"left:86px;top:919px;font-size:13.9px;max-width:188px\">③不断推进实践基础上的理论创新。</span><span class=\"bl\" style=\"left:519px;top:930px;font-size:12.2px;max-width:188px\">思想方法、工作方法、领导方法。不论过</span><span class=\"bl b\" style=\"left:62px;top:945px;font-size:13.9px;max-width:155px\">5.2群众路线（中频选择题）</span><span class=\"bl\" style=\"left:519px;top:949px;font-size:12.2px;max-width:189px\">去、现在和将来，我们都要坚持一切从实</span><span class=\"bl b\" style=\"left:84px;top:965px;font-size:15.6px;max-width:424px\">1.含义：一切为了群众，一切依靠群众，从群众中来，到群众中去，把党的正</span><span class=\"bl\" style=\"left:518px;top:967px;font-size:13.9px;max-width:191px\">际出发，理论联系实际，在实践中检验真</span><span class=\"bl\" style=\"left:61px;top:985px;font-size:15.0px;max-width:446px\">确主张变为群众的自觉活动。群众路线本质上体现的是马克思主义关于人民群众是历</span><span class=\"bl\" style=\"left:519px;top:985px;font-size:12.2px;max-width:80px\">理和发展真理。”</span><span class=\"bl\" style=\"left:61px;top:1004px;font-size:15.0px;max-width:143px\">史的创造者这一基本原理。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 10 页</div><div class=\"sidebox\" style=\"left:507px;top:666px;width:195px;height:138px\"></div><span class=\"bl\" style=\"left:460px;top:61px;font-size:14.5px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:80px;top:106px;font-size:16.1px;max-width:64px\">2.重要性：</span><span class=\"bl\" style=\"left:81px;top:127px;font-size:15.0px;max-width:248px\">①群众路线是我们党的生命线和根本工作路线。</span><span class=\"bl\" style=\"left:81px;top:148px;font-size:15.0px;max-width:307px\">②群众路线是我们党永葆青春活力和战斗力的重要传家宝。</span><span class=\"bl b\" style=\"left:80px;top:169px;font-size:13.9px;max-width:111px\">3.群众路线的要求：</span><span class=\"bl\" style=\"left:80px;top:189px;font-size:15.0px;max-width:214px\">①坚持人民是推动历史发展的根本力量。</span><span class=\"bl\" style=\"left:81px;top:210px;font-size:15.0px;max-width:421px\">②坚持全心全意为人民服务的根本宗旨。全心全意为人民服务是我们党一切行动</span><span class=\"bl\" style=\"left:57px;top:231px;font-size:15.6px;max-width:353px\">的根本出发点和落脚点，是我们党区别于其他一切政党的根本标志。</span><span class=\"bl\" style=\"left:81px;top:252px;font-size:15.0px;max-width:421px\">③保持党和人民群众的血肉联系。因为党风问题、党同人民群众的联系问题关系</span><span class=\"bl\" style=\"left:57px;top:272px;font-size:17.8px;max-width:80px\">党的生死存亡</span><span class=\"bl b\" style=\"left:55px;top:300px;font-size:16.1px;max-width:158px\">5.3独立自主（中频选择题）</span><span class=\"bl b\" style=\"left:80px;top:321px;font-size:17.2px;max-width:53px\">1.含义：</span><span class=\"bl\" style=\"left:81px;top:344px;font-size:13.9px;max-width:421px\">坚持独立思考，走自已的路，就是坚定不移地维护民族独立、捍卫国家主权，把</span><span class=\"bl\" style=\"left:57px;top:364px;font-size:15.0px;max-width:445px\">立足点放在依靠自己力量的基础上，同时积极争取外援，开展国际经济文化交流，学</span><span class=\"bl\" style=\"left:57px;top:385px;font-size:15.0px;max-width:190px\">习外国一切对我们有益的先进事物。</span><span class=\"bl b\" style=\"left:80px;top:406px;font-size:14.5px;max-width:64px\">2.重要性：</span><span class=\"bl\" style=\"left:80px;top:426px;font-size:16.1px;max-width:190px\">①独立自主是中华民族的优良传统。</span><span class=\"bl\" style=\"left:81px;top:449px;font-size:13.9px;max-width:342px\">②独立自主是中国共产党、中华人民共和国立党立国的重要原则。</span><span class=\"bl\" style=\"left:80px;top:468px;font-size:16.1px;max-width:422px\">③独立自主是我们党从中国实际出发，依靠党和人民力量进行革命、建设、改革</span><span class=\"bl\" style=\"left:57px;top:490px;font-size:14.5px;max-width:71px\">的必然结论。</span><span class=\"bl b\" style=\"left:79px;top:511px;font-size:12.8px;max-width:52px\">3.要求：</span><span class=\"bl\" style=\"left:80px;top:529px;font-size:21.1px;max-width:278px\">①坚持中国的事情必须由中国人民自己处理。</span><span class=\"bl\" style=\"left:81px;top:550px;font-size:18.9px;max-width:315px\">②坚持独立自主的和平外交政策，坚定不移走和平发展道路</span><span class=\"bl b hl\" style=\"left:67px;top:592px;font-size:18.9px;max-width:253px\">考点6毛泽东思想的历史地位 ☆☆☆</span><span class=\"bl b\" style=\"left:57px;top:627px;font-size:16.1px;max-width:332px\">6.1马克思主义中国化的第一个重大理论成果（高频选择题）</span><span class=\"bl\" style=\"left:83px;top:650px;font-size:13.9px;max-width:420px\">毛泽东思想是马克思主义中国化的第一个理论成果，它实现了马克思主义中国化</span><span class=\"bl\" style=\"left:58px;top:671px;font-size:13.9px;max-width:366px\">的第一次历史性飞跃，以独创性的理论丰富和发展了马克思列宁主义。</span><span class=\"bl\" style=\"left:454px;top:670px;font-size:14.5px;max-width:48px\">&gt;提示1</span><span class=\"bl\" style=\"left:515px;top:672px;font-size:13.9px;max-width:101px\">火星姐姐考点提示1</span><span class=\"bl b\" style=\"left:56px;top:697px;font-size:16.1px;max-width:331px\">6.2毛泽东思想是中国革命和建设的科学指南（中频选择题）</span><span class=\"bl\" style=\"left:513px;top:693px;font-size:14.5px;max-width:190px\">1.马克思主义中国化的第一个理论成果是</span><span class=\"bl\" style=\"left:523px;top:713px;font-size:13.9px;max-width:63px\">毛泽东思想。</span><span class=\"bl\" style=\"left:81px;top:720px;font-size:13.9px;max-width:131px\">在毛泽东思想的指引下：</span><span class=\"bl\" style=\"left:513px;top:731px;font-size:13.9px;max-width:190px\">2.马克思主义中国化的第二个理论成果是</span><span class=\"bl\" style=\"left:81px;top:739px;font-size:17.2px;max-width:422px\">①我们党领导全国人民找到了一条新民主主义革命的正确道路，建立了中华人</span><span class=\"bl\" style=\"left:524px;top:749px;font-size:13.9px;max-width:132px\">中国特色社会主义理论体系。</span><span class=\"bl\" style=\"left:56px;top:760px;font-size:17.8px;max-width:63px\">民共和国。</span><span class=\"bl\" style=\"left:513px;top:767px;font-size:13.9px;max-width:191px\">3.“马克思主义中国化”不专指运用马克</span><span class=\"bl\" style=\"left:81px;top:782px;font-size:15.0px;max-width:421px\">②我们党找到了一条从新民主主义向社会主义过渡的道路，确立了社会主义基本</span><span class=\"bl\" style=\"left:523px;top:786px;font-size:13.9px;max-width:120px\">思主义“解决中国问题”。</span><span class=\"bl\" style=\"left:57px;top:803px;font-size:15.0px;max-width:38px\">制度。</span><span class=\"bl\" style=\"left:82px;top:824px;font-size:13.9px;max-width:307px\">③我们建立起独立的比较完整的工业体系和国民经济体系。</span><span class=\"bl\" style=\"left:81px;top:843px;font-size:15.0px;max-width:365px\">④毛泽东思想关于社会主义建设的基本思想观点，具有现实指导作用。</span><span class=\"bl b\" style=\"left:59px;top:873px;font-size:12.2px;max-width:316px\">6.3毛泽东思想是党和人民宝贵的精神财富（高频选择题）</span><span class=\"bl\" style=\"left:81px;top:892px;font-size:16.1px;max-width:421px\">1.毛泽东思想包含的基本原理、基本原则和科学方法，具有普遍和长久的指导</span><span class=\"bl\" style=\"left:57px;top:913px;font-size:17.2px;max-width:41px\">意义。</span><span class=\"bl\" style=\"left:80px;top:934px;font-size:15.6px;max-width:422px\">2.毛泽东思想依然是当今中国人民不断奋进的强大精神动力，将长期激励和指</span><span class=\"bl\" style=\"left:57px;top:955px;font-size:17.8px;max-width:74px\">导我们前进。</span><span class=\"bl b\" style=\"left:81px;top:978px;font-size:12.2px;max-width:215px\">3.科学评价毛泽东和毛泽东思想的意义：</span><span class=\"bl\" style=\"left:82px;top:997px;font-size:14.5px;max-width:271px\">①关系到怎样看待党和国家过去几十年奋斗的成就。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 11 页</div><div class=\"sidebox\" style=\"left:522px;top:277px;width:194px;height:156px\"></div><span class=\"bl\" style=\"left:89px;top:106px;font-size:16.1px;max-width:366px\">②关系到党的团结、国家的安定，也关系到党和国家未来的发展前途。</span><span class=\"bl\" style=\"left:530px;top:116px;font-size:15.5px;max-width:101px\">火星姐姐背景补充1</span><span class=\"bl\" style=\"left:89px;top:128px;font-size:13.9px;max-width:271px\">③不仅有重要的历史意义，而且有重要的现实意义。</span><span class=\"bl\" style=\"left:530px;top:141px;font-size:12.2px;max-width:188px\">毛泽东一生为党和人民的事业作出了杰出</span><span class=\"bl b\" style=\"left:89px;top:150px;font-size:12.2px;max-width:179px\">4.科学评价毛泽东和毛泽东思想：</span><span class=\"bl\" style=\"left:417px;top:149px;font-size:14.4px;max-width:50px\">&gt;补充1</span><span class=\"bl\" style=\"left:455px;top:149px;font-size:14.4px;max-width:54px\">&gt;提示1</span><span class=\"bl\" style=\"left:529px;top:159px;font-size:13.9px;max-width:190px\">的贡献，《关于建国以来党的若干历史问</span><span class=\"bl\" style=\"left:88px;top:169px;font-size:16.1px;max-width:417px\">①毛泽东同志是伟大的马克思主义者、伟大的无产阶级革命家、战略家、理论家。</span><span class=\"bl\" style=\"left:529px;top:177px;font-size:13.9px;max-width:190px\">题的决议》，对毛泽东和毛泽东思想的</span><span class=\"bl\" style=\"left:89px;top:190px;font-size:13.9px;max-width:366px\">②毛泽东同志是马克思主义中国化的伟大开拓者、爱国者和民族英雄。</span><span class=\"bl\" style=\"left:530px;top:196px;font-size:12.2px;max-width:189px\">历史地位作出了科学的、符合客观实际</span><span class=\"bl\" style=\"left:89px;top:211px;font-size:13.9px;max-width:260px\">③毛泽东同志是党的第一代中央领导集体的核心。</span><span class=\"bl\" style=\"left:528px;top:214px;font-size:14.4px;max-width:45px\">的评价。</span><span class=\"bl\" style=\"left:89px;top:232px;font-size:13.9px;max-width:376px\">④毛泽东同志是领导中国人民彻底改变自己命运和国家面貌的一代伟人。</span><span class=\"bl\" style=\"left:89px;top:253px;font-size:13.9px;max-width:248px\">③毛泽东的功绩是第一位的，错误是第二位的。</span><span class=\"bl\" style=\"left:88px;top:274px;font-size:13.9px;max-width:420px\">5.党坚持把经过长期历史考验形成为科学理论的毛泽东思想，同毛泽东晚年所</span><span class=\"bl\" style=\"left:530px;top:283px;font-size:13.9px;max-width:99px\">火星姐姐易错提示1</span><span class=\"bl\" style=\"left:65px;top:294px;font-size:13.9px;max-width:443px\">犯的错误区别开来，为我们完整准确地理解毛泽东思想、坚持和发展毛泽东思想指</span><span class=\"bl\" style=\"left:529px;top:305px;font-size:13.9px;max-width:189px\">1.毛泽东思想是中国共产党集体智慧的结</span><span class=\"bl\" style=\"left:64px;top:314px;font-size:16.1px;max-width:63px\">明了方向。</span><span class=\"bl\" style=\"left:539px;top:324px;font-size:13.9px;max-width:112px\">晶，不是其个人的思想。</span><span class=\"bl\" style=\"left:529px;top:343px;font-size:12.2px;max-width:189px\">2.毛泽东思想是正确的理论原则和经验总</span><span class=\"bl\" style=\"left:63px;top:350px;font-size:15.5px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:539px;top:361px;font-size:12.2px;max-width:171px\">结，但毛泽东的思想有正确也有错误。</span><span class=\"bl\" style=\"left:65px;top:378px;font-size:13.9px;max-width:444px\">1.【2016.5】毛泽东思想和中国特色社会主义理论体系是马克思主义中国化的两大理</span><span class=\"bl\" style=\"left:529px;top:379px;font-size:12.2px;max-width:189px\">3.毛泽东思想不包括改革内容，邓小平思</span><span class=\"bl\" style=\"left:81px;top:398px;font-size:14.4px;max-width:429px\">论成果。贯穿这两大理论成果始终，并体现在两大成果各个基本观点中的世界观</span><span class=\"bl\" style=\"left:539px;top:397px;font-size:13.9px;max-width:92px\">想不包括革命内容。</span><span class=\"bl\" style=\"left:81px;top:418px;font-size:15.5px;max-width:102px\">和方法论的基础是</span><span class=\"bl\" style=\"left:528px;top:415px;font-size:13.9px;max-width:141px\">4.毛泽东思想≠毛泽东的思想。</span><span class=\"bl\" style=\"left:80px;top:440px;font-size:14.4px;max-width:70px\">A.群众路线</span><span class=\"bl\" style=\"left:79px;top:460px;font-size:17.8px;max-width:72px\">B.独立自主</span><span class=\"bl\" style=\"left:79px;top:480px;font-size:18.3px;max-width:72px\">C.实事求是</span><span class=\"bl\" style=\"left:79px;top:500px;font-size:17.8px;max-width:73px\">D.改革创新</span><span class=\"bl\" style=\"left:64px;top:537px;font-size:17.2px;max-width:445px\">2.【2012.5】毛泽东曾在不同场合多次谈到，调查研究有两种方法，一种是走马看</span><span class=\"bl\" style=\"left:80px;top:558px;font-size:17.2px;max-width:429px\">花，一种是下马看花。走马看花、不深人，还必须用第二种方法，就是下马看花，</span><span class=\"bl\" style=\"left:81px;top:579px;font-size:15.0px;max-width:349px\">仔细看花，分析一朵花。毛泽东强调“下马看花”的实际意义在于</span><span class=\"bl\" style=\"left:81px;top:601px;font-size:13.9px;max-width:221px\">A.解决实际问题必须要有先进理论的指导</span><span class=\"bl\" style=\"left:80px;top:621px;font-size:15.5px;max-width:221px\">B.运用多种综合方法分析调查研究的材料</span><span class=\"bl\" style=\"left:80px;top:642px;font-size:15.0px;max-width:256px\">C.马克思主义理论必须适合中国革命的具体实际</span><span class=\"bl\" style=\"left:80px;top:663px;font-size:13.9px;max-width:268px\">D.只有全面深入地了解中国的实际，才能找出规律</span><span class=\"bl\" style=\"left:63px;top:698px;font-size:16.1px;max-width:445px\">3.【2021.5】毛泽东思想作为马克思主义中国化的第一个重大理论成果，是由一系列</span><span class=\"bl\" style=\"left:80px;top:719px;font-size:15.0px;max-width:427px\">相互联系的重要理论观点所构成的完整的科学思想体系。这一科学思想体系所围</span><span class=\"bl\" style=\"left:80px;top:740px;font-size:14.4px;max-width:67px\">绕的主题是</span><span class=\"bl\" style=\"left:79px;top:760px;font-size:15.5px;max-width:107px\">A.中国革命和建设</span><span class=\"bl\" style=\"left:79px;top:780px;font-size:17.8px;max-width:107px\">B.中国命运和前途</span><span class=\"bl\" style=\"left:79px;top:802px;font-size:15.5px;max-width:153px\">C.中国社会性质和阶级状况</span><span class=\"bl\" style=\"left:79px;top:822px;font-size:17.8px;max-width:107px\">D.中国改革和发展</span></div></div>"}],pages:[7,11]};
  D["mzt_s3"] = {id:"mzt_s3",ch:"毛中特讲义 · 第二章 新民主主义革命理论",title:"第二章 新民主主义革命理论",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 12 页</div><div class=\"sidebox\" style=\"left:504px;top:534px;width:197px;height:479px\"></div><span class=\"bl\" style=\"left:459px;top:61px;font-size:16.1px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:346px;top:111px;font-size:27.3px;max-width:66px\">第二章</span><span class=\"bl\" style=\"left:294px;top:162px;font-size:20.0px;max-width:171px\">新民主主义革命理论</span><span class=\"bl\" style=\"left:53px;top:211px;font-size:20.0px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:460px;top:255px;font-size:15.6px;max-width:232px\">考点7近代中国国情和中国革命的时代特征</span><span class=\"bl\" style=\"left:225px;top:265px;font-size:15.6px;max-width:173px\">新民主主义革命理论形成的依据</span><span class=\"bl b hl\" style=\"left:461px;top:277px;font-size:13.9px;max-width:208px\">考点8新民主主义革命理论的实践基础</span><span class=\"bl\" style=\"left:80px;top:305px;font-size:16.1px;max-width:69px\">新民主主义</span><span class=\"bl b hl\" style=\"left:461px;top:300px;font-size:13.9px;max-width:172px\">考点9新民主主义革命的总路线</span><span class=\"bl\" style=\"left:213px;top:309px;font-size:13.9px;max-width:196px\">新民主主义革命的总路线和基本纲领</span><span class=\"bl\" style=\"left:86px;top:326px;font-size:16.1px;max-width:56px\">革命理论</span><span class=\"bl b hl\" style=\"left:461px;top:321px;font-size:13.9px;max-width:166px\">考点10新民主主义的基本纲领</span><span class=\"bl b hl\" style=\"left:461px;top:344px;font-size:13.9px;max-width:165px\">考点11新民主主义革命的道路</span><span class=\"bl\" style=\"left:218px;top:363px;font-size:16.1px;max-width:186px\">新民主主义革命的道路和基本经验</span><span class=\"bl b hl\" style=\"left:460px;top:364px;font-size:16.1px;max-width:190px\">考点12新民主主义革命的三大法宝</span><span class=\"bl b hl\" style=\"left:461px;top:386px;font-size:13.9px;max-width:189px\">考点13新民主主义革命理论的意义</span><span class=\"bl b acc\" style=\"left:54px;top:436px;font-size:18.4px;max-width:102px\">考点考情分析</span><span class=\"bl\" style=\"left:79px;top:462px;font-size:16.1px;max-width:622px\">本章主要阐述新民主主义革命理论。本章是本门科目中考频一般的章节，考试形式一般为选择题。考生在复习过程中，</span><span class=\"bl\" style=\"left:56px;top:485px;font-size:13.9px;max-width:496px\">要重点掌握新民主主义革命的总路线和基本纲领、新民主主义革命的道路以及三大法宝等内容。</span><span class=\"bl\" style=\"left:72px;top:502px;font-size:18.4px;max-width:89px\">诚</span><span class=\"bl b hl\" style=\"left:66px;top:539px;font-size:17.8px;max-width:293px\">考点7近代中国国情和中国革命的时代特征</span><span class=\"bl\" style=\"left:660px;top:540px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:55px;top:575px;font-size:17.2px;max-width:183px\">7.1近代中国国情（高频选择题）</span><span class=\"bl\" style=\"left:524px;top:570px;font-size:14.5px;max-width:93px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:452px;top:575px;font-size:18.9px;max-width:49px\">&gt;解读1</span><span class=\"bl b\" style=\"left:80px;top:597px;font-size:13.9px;max-width:180px\">1.解决中国革命问题的基本依据：</span><span class=\"bl\" style=\"left:512px;top:593px;font-size:13.9px;max-width:103px\">毛特&amp;史纲底层逻辑：</span><span class=\"bl\" style=\"left:511px;top:610px;font-size:14.5px;max-width:84px\">1.国情决定矛盾。</span><span class=\"bl\" style=\"left:80px;top:617px;font-size:13.9px;max-width:420px\">认清中国国情。中国逐渐成为一个半殖民地半封建性质的社会，这是最基本的</span><span class=\"bl\" style=\"left:511px;top:628px;font-size:15.6px;max-width:125px\">2.社会矛盾决定革命对象。</span><span class=\"bl\" style=\"left:55px;top:636px;font-size:18.4px;max-width:41px\">国情。</span><span class=\"bl\" style=\"left:510px;top:646px;font-size:17.2px;max-width:126px\">3.革命对象决定革命任务。</span><span class=\"bl b\" style=\"left:79px;top:660px;font-size:15.6px;max-width:232px\">2.社会性质（国情）：半殖民地半封建社会</span><span class=\"bl\" style=\"left:453px;top:660px;font-size:15.0px;max-width:47px\">解读2</span><span class=\"bl\" style=\"left:511px;top:665px;font-size:13.9px;max-width:124px\">4.革命任务决定革命性质。</span><span class=\"bl b\" style=\"left:79px;top:681px;font-size:14.5px;max-width:76px\">3.社会矛盾：</span><span class=\"bl\" style=\"left:80px;top:700px;font-size:16.1px;max-width:262px\">近代中国诸多矛盾中，占支配地位的主要矛盾是：</span><span class=\"bl\" style=\"left:514px;top:701px;font-size:13.9px;max-width:104px\">火星姐姐考点解读2</span><span class=\"bl\" style=\"left:80px;top:722px;font-size:13.9px;max-width:299px\">帝国主义和中华民族的矛盾（各种矛盾中最主要的矛盾）</span><span class=\"bl\" style=\"left:533px;top:723px;font-size:13.9px;max-width:168px\">一方面，帝国主义的侵略虽然在一定</span><span class=\"bl\" style=\"left:80px;top:743px;font-size:13.9px;max-width:149px\">封建主义和人民大众的矛盾</span><span class=\"bl\" style=\"left:513px;top:742px;font-size:12.2px;max-width:189px\">程度上加速了封建社会自给自足的自然经</span><span class=\"bl b\" style=\"left:79px;top:762px;font-size:15.6px;max-width:147px\">4.近代中国革命根本任务：</span><span class=\"bl\" style=\"left:512px;top:760px;font-size:12.2px;max-width:189px\">济的解体，客观上为中国资本主义的发展</span><span class=\"bl\" style=\"left:514px;top:778px;font-size:13.9px;max-width:189px\">创造了一定条件，但并不能使中国发展成</span><span class=\"bl\" style=\"left:80px;top:783px;font-size:16.1px;max-width:421px\">推翻帝国主义、封建主义和官僚资本主义的统治，从根本上推翻反动腐朽的政治</span><span class=\"bl\" style=\"left:513px;top:796px;font-size:13.9px;max-width:189px\">为资本主义国家。这是因为封建制度的根</span><span class=\"bl\" style=\"left:58px;top:806px;font-size:13.9px;max-width:444px\">上层建筑，变革阻碍生产力发展的生产关系，为建设富强民主的国家、确立人民当</span><span class=\"bl\" style=\"left:513px;top:815px;font-size:13.9px;max-width:189px\">基——地主阶级对农民的剥削依旧存在，</span><span class=\"bl\" style=\"left:56px;top:826px;font-size:15.6px;max-width:335px\">家作主的政治制度、改善人民生活扫清障碍，创造必要的前提。</span><span class=\"bl\" style=\"left:513px;top:833px;font-size:13.9px;max-width:189px\">而且同买办资本和高利贷资本的剥削结合</span><span class=\"bl b\" style=\"left:79px;top:846px;font-size:15.0px;max-width:299px\">5.近代中国革命的性质：反帝反封的资产阶级民主革命。</span><span class=\"bl\" style=\"left:512px;top:850px;font-size:15.0px;max-width:190px\">在一起，在中国社会经济生活中占据着明</span><span class=\"bl b\" style=\"left:55px;top:873px;font-size:16.1px;max-width:244px\">7.2近代中国革命的时代特征（高频选择题）</span><span class=\"bl\" style=\"left:513px;top:868px;font-size:13.9px;max-width:189px\">显优势。又因为中国民族资本主义先天不</span><span class=\"bl\" style=\"left:513px;top:886px;font-size:15.0px;max-width:189px\">足，尽管有了某些发展，但它没有成为中</span><span class=\"bl b\" style=\"left:80px;top:896px;font-size:16.1px;max-width:76px\">1.革命性质：</span><span class=\"bl\" style=\"left:514px;top:905px;font-size:13.9px;max-width:113px\">国社会经济的主要形式。</span><span class=\"bl\" style=\"left:80px;top:916px;font-size:15.0px;max-width:379px\">近代中国的社会性质和主要矛盾，决定了中国革命是资产阶级民主革命。</span><span class=\"bl\" style=\"left:533px;top:921px;font-size:15.0px;max-width:168px\">另一方面，帝国主义列强通过政治的、</span><span class=\"bl b\" style=\"left:79px;top:937px;font-size:16.1px;max-width:77px\">2.时代特征：</span><span class=\"bl\" style=\"left:512px;top:940px;font-size:15.0px;max-width:190px\">经济的和文化的侵略，使中国半殖民地</span><span class=\"bl\" style=\"left:80px;top:957px;font-size:17.2px;max-width:395px\">中国资产阶级民主革命经历了从旧民主主义革命向新民主主义革命的转变。</span><span class=\"bl\" style=\"left:513px;top:959px;font-size:13.9px;max-width:190px\">化。帝国主义列强通过武装入侵和强迫清</span><span class=\"bl b\" style=\"left:80px;top:980px;font-size:13.9px;max-width:144px\">3.旧民主主义革命的范畴：</span><span class=\"bl\" style=\"left:513px;top:977px;font-size:13.9px;max-width:189px\">政府签订一系列不平等条约，不但操纵了</span><span class=\"bl\" style=\"left:81px;top:999px;font-size:15.0px;max-width:278px\">从鸦片战争到辛亥革命期间。（护法运动的失败结束）</span><span class=\"bl\" style=\"left:513px;top:994px;font-size:15.0px;max-width:190px\">中国的财政和经济命脉，而且操纵了中国</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1090px\"><div class=\"bxnum\">第 13 页</div><div class=\"sidebox\" style=\"left:515px;top:545px;width:194px;height:355px\"></div><span class=\"bl b\" style=\"left:89px;top:106px;font-size:14.4px;max-width:392px\">4.新民主主义革命的范畴：以五四运动为开端，进人新民主主义革命阶段。</span><span class=\"bl\" style=\"left:520px;top:113px;font-size:12.2px;max-width:190px\">（接上页）的政治和军事力量。中国的经</span><span class=\"bl b\" style=\"left:89px;top:127px;font-size:13.9px;max-width:133px\">5.中国革命转变的条件：</span><span class=\"bl\" style=\"left:522px;top:132px;font-size:12.2px;max-width:188px\">济、政治和文化的发展表现出极端的不平</span><span class=\"bl\" style=\"left:92px;top:149px;font-size:12.2px;max-width:419px\">①国际时代背景的转变：俄国十月革命的胜利，改变了整个世界历史的方向，划</span><span class=\"bl\" style=\"left:522px;top:152px;font-size:10.0px;max-width:187px\">衡性。由于帝国主义和封建主义的双重压</span><span class=\"bl\" style=\"left:66px;top:168px;font-size:14.4px;max-width:444px\">分了整个世界历史的时代，开辟了世界无产阶级社会主义革命的新纪元，标志着人类</span><span class=\"bl\" style=\"left:521px;top:168px;font-size:13.3px;max-width:189px\">迫，中国人民尤其是广大农民日益贫困化</span><span class=\"bl\" style=\"left:66px;top:189px;font-size:15.0px;max-width:246px\">历史开始了由资本主义向社会主义转变的进程。</span><span class=\"bl\" style=\"left:521px;top:186px;font-size:14.4px;max-width:189px\">以致大批破产，过着饥寒交迫和毫无政治</span><span class=\"bl\" style=\"left:91px;top:211px;font-size:13.9px;max-width:420px\">②国内工人阶级登上历史舞台：在十月革命的影响下，1919年五四运动之后，</span><span class=\"bl\" style=\"left:522px;top:206px;font-size:12.2px;max-width:61px\">权利的生活。</span><span class=\"bl\" style=\"left:67px;top:231px;font-size:13.9px;max-width:444px\">中国无产阶级开始以独立的政治力量登上历史舞台，由自在阶级转变为自为阶级。随</span><span class=\"bl\" style=\"left:67px;top:252px;font-size:13.9px;max-width:400px\">着马克思主义在中国的广泛传播，马克思主义逐步成为中国革命的指导思想。</span><span class=\"bl\" style=\"left:92px;top:274px;font-size:12.2px;max-width:418px\">③旧民主主义革命的失败、近代中国革命形势的发展，以及世界形势的新变化，</span><span class=\"bl\" style=\"left:67px;top:294px;font-size:12.2px;max-width:247px\">为新民主主义革命理论的形成提供了客观条件。</span><span class=\"bl b\" style=\"left:90px;top:315px;font-size:13.9px;max-width:157px\">6.新民主主义革命新在哪里：</span><span class=\"bl\" style=\"left:67px;top:357px;font-size:12.2px;max-width:442px\">和国，造成资产阶级专政，而是要造成各革命阶级在无产阶级领导之下的联合专政，</span><span class=\"bl\" style=\"left:67px;top:378px;font-size:12.2px;max-width:366px\">建立各革命阶级联合专政的民主共和国，为进入社会主义社会做准备。</span><span class=\"bl\" style=\"left:90px;top:397px;font-size:14.4px;max-width:421px\">②新民主主义革命与一般意义上的社会主义革命也不相同：它只推翻帝国主义、</span><span class=\"bl\" style=\"left:66px;top:418px;font-size:14.4px;max-width:444px\">封建主义和官僚资本主义的反动统治，而不破坏参加反帝反封建的资本主义成分。这</span><span class=\"bl\" style=\"left:66px;top:440px;font-size:13.9px;max-width:378px\">样的民主主义革命，不是旧范畴的民主主义革命，而是新民主主义革命。</span><span class=\"bl b\" style=\"left:89px;top:461px;font-size:13.9px;max-width:134px\">7.中国革命要分两步走：</span><span class=\"bl\" style=\"left:89px;top:481px;font-size:15.5px;max-width:422px\">第一步是完成反帝反封建的新民主主义革命任务，第二步是完成社会主义革命任</span><span class=\"bl\" style=\"left:66px;top:501px;font-size:16.1px;max-width:258px\">务，这是性质不同但又相互联系的两个革命过程。</span><span class=\"bl b hl\" style=\"left:76px;top:541px;font-size:17.8px;max-width:266px\">考点8新民主主义革命理论的实践基础</span><span class=\"bl\" style=\"left:531px;top:551px;font-size:13.9px;max-width:95px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:65px;top:577px;font-size:15.0px;max-width:368px\">8.1旧民主主义革命的失败呼唤新的革命理论的诞生（低频选择题）</span><span class=\"bl\" style=\"left:522px;top:574px;font-size:12.2px;max-width:187px\">在党的幼年时期，由于缺乏领导革命的</span><span class=\"bl\" style=\"left:522px;top:593px;font-size:12.2px;max-width:188px\">实践经验，加之理论上的不成热，在革</span><span class=\"bl\" style=\"left:91px;top:598px;font-size:14.4px;max-width:420px\">近代中国社会和革命斗争的发展，追切期待新的阶级及其政党领导新的革命，呼</span><span class=\"bl\" style=\"left:522px;top:611px;font-size:12.2px;max-width:188px\">命的领导权、武装斗争、革命道路等问</span><span class=\"bl\" style=\"left:65px;top:619px;font-size:15.0px;max-width:426px\">唤新的革命理论的产生。它的形成包含了对旧民主主义革命失败教训的深刻总结。</span><span class=\"bl\" style=\"left:522px;top:629px;font-size:12.2px;max-width:188px\">题上没有形成正确的认识，在革命的实</span><span class=\"bl b\" style=\"left:65px;top:647px;font-size:14.4px;max-width:430px\">8.2新民主主义革命的艰辛探索奠定了革命理论形成的实践基础（低频选择题）</span><span class=\"bl\" style=\"left:522px;top:648px;font-size:10.0px;max-width:189px\">践斗争中犯过一些错误，走过一些弯路。</span><span class=\"bl\" style=\"left:90px;top:668px;font-size:14.4px;max-width:420px\">新民主主义革命理论是在总结革命斗争正反两方面实践经验的基础上形成的，是</span><span class=\"bl\" style=\"left:522px;top:666px;font-size:12.2px;max-width:188px\">但党始终坚持以马克思主义为指导，注</span><span class=\"bl\" style=\"left:521px;top:682px;font-size:14.4px;max-width:189px\">重把马克思主义的基本原理与中国革命</span><span class=\"bl\" style=\"left:66px;top:689px;font-size:14.4px;max-width:444px\">对中国革命实践经验的概括和总结。新民主主义革命实践，是新民主主义理论得以形</span><span class=\"bl\" style=\"left:521px;top:701px;font-size:13.9px;max-width:64px\">实际相结合。</span><span class=\"bl\" style=\"left:67px;top:711px;font-size:13.9px;max-width:142px\">成的实践基础和智慧源泉。</span><span class=\"bl\" style=\"left:461px;top:711px;font-size:14.4px;max-width:48px\">&gt;解读1</span><span class=\"bl\" style=\"left:522px;top:720px;font-size:12.2px;max-width:188px\">尤其是经历了大革命的失败及井冈山的革</span><span class=\"bl\" style=\"left:522px;top:739px;font-size:10.0px;max-width:187px\">命斗争后，党总结革命的经验教训，提出</span><span class=\"bl b hl\" style=\"left:76px;top:749px;font-size:17.8px;max-width:266px\">考点9新民主主义革命的总路线☆☆☆</span><span class=\"bl\" style=\"left:522px;top:757px;font-size:12.2px;max-width:187px\">了“须知政权是由枪杆子中取得的”著名</span><span class=\"bl\" style=\"left:522px;top:775px;font-size:12.2px;max-width:187px\">论断和“工农武装割据”的思想，探索出</span><span class=\"bl b\" style=\"left:65px;top:785px;font-size:14.4px;max-width:268px\">9.1新民主主义革命总路线的提出（中频选择题）</span><span class=\"bl\" style=\"left:522px;top:793px;font-size:12.2px;max-width:186px\">了农村包围城市、武装夺取政权的革命道</span><span class=\"bl\" style=\"left:89px;top:806px;font-size:12.2px;max-width:261px\">1.总路线是相对于具体路线而言的根本指导路线。</span><span class=\"bl\" style=\"left:521px;top:812px;font-size:12.2px;max-width:188px\">路，领导革命不断向前发展。到抗日战争</span><span class=\"bl b\" style=\"left:88px;top:824px;font-size:13.9px;max-width:122px\">2.总路线第一次提出：</span><span class=\"bl\" style=\"left:521px;top:829px;font-size:12.2px;max-width:188px\">时期，党历经长期的革命斗争考验，积累</span><span class=\"bl\" style=\"left:89px;top:844px;font-size:15.0px;max-width:421px\">1939年，毛泽东在《中国革命和中国共产党》一文中，第一次提出了新民主主</span><span class=\"bl\" style=\"left:521px;top:848px;font-size:12.2px;max-width:189px\">了丰富的革命实践经验，对中国革命的认</span><span class=\"bl\" style=\"left:66px;top:863px;font-size:14.4px;max-width:189px\">义革命的科学概念和总路线的内容。</span><span class=\"bl\" style=\"left:522px;top:866px;font-size:12.2px;max-width:187px\">识趋于成熟，逐步形成了系统化的适合中</span><span class=\"bl b\" style=\"left:88px;top:883px;font-size:13.9px;max-width:146px\">3.总路线完整内容的提出：</span><span class=\"bl\" style=\"left:522px;top:884px;font-size:12.2px;max-width:140px\">国国情的新民主主义革命理论。</span><span class=\"bl\" style=\"left:89px;top:901px;font-size:16.1px;max-width:420px\">1948年，毛泽东在《在晋绥干部会议上的讲话》中完整地表述了总路线的内容，</span><span class=\"bl\" style=\"left:65px;top:921px;font-size:15.5px;max-width:437px\">即无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命。</span><span class=\"bl b\" style=\"left:64px;top:947px;font-size:14.4px;max-width:230px\">9.2新民主主义革命的对象（高频选择题）</span><span class=\"bl b\" style=\"left:88px;top:966px;font-size:15.5px;max-width:111px\">1.革命的首要问题：</span><span class=\"bl\" style=\"left:88px;top:986px;font-size:16.1px;max-width:421px\">分清敌友。近代中国社会的性质和主要矛盾，决定了中国革命的主要敌人是帝国</span><span class=\"bl\" style=\"left:64px;top:1005px;font-size:15.0px;max-width:178px\">主义、封建主义和官僚资本主义。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1091px\"><div class=\"bxnum\">第 14 页</div><div class=\"sidebox\" style=\"left:509px;top:881px;width:195px;height:100px\"></div><span class=\"bl\" style=\"left:462px;top:60px;font-size:15.0px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:82px;top:104px;font-size:16.1px;max-width:145px\">2.新民主主义革命的对象：</span><span class=\"bl\" style=\"left:82px;top:125px;font-size:17.2px;max-width:367px\">近代中国社会的性质和主要矛盾，决定了中国革命的主要敌人，就是：</span><span class=\"bl\" style=\"left:82px;top:145px;font-size:17.8px;max-width:68px\">①帝国主义</span><span class=\"bl\" style=\"left:83px;top:167px;font-size:17.2px;max-width:422px\">中国革命的首要对象，帝国主义是阻碍中国社会进步和发展的最大障碍，是近</span><span class=\"bl\" style=\"left:59px;top:188px;font-size:15.0px;max-width:445px\">代中国贫困落后和一切灾祸的总根源。推翻帝国主义的压迫是中国走向独立和富强的</span><span class=\"bl\" style=\"left:59px;top:208px;font-size:15.6px;max-width:37px\">前提。</span><span class=\"bl\" style=\"left:83px;top:230px;font-size:14.4px;max-width:66px\">②封建主义</span><span class=\"bl\" style=\"left:82px;top:250px;font-size:17.2px;max-width:422px\">封建地主阶级是帝国主义统治中国和封建军阀实行专制统治的社会基础。反对</span><span class=\"bl\" style=\"left:59px;top:271px;font-size:15.6px;max-width:446px\">封建主义，从根本上说，就是要在经济上消灭封建制度，在政治上消灭军阀的专制统</span><span class=\"bl\" style=\"left:59px;top:293px;font-size:15.0px;max-width:414px\">治，消灭地主阶级，解放生产力，为中国的经济现代化和政治民主化创造条件。</span><span class=\"bl\" style=\"left:83px;top:314px;font-size:14.4px;max-width:89px\">③官僚资本主义</span><span class=\"bl\" style=\"left:83px;top:335px;font-size:13.9px;max-width:420px\">官僚资本主义是依靠帝国主义、勾结封建势力、利用国家政权力量而发展起来的</span><span class=\"bl\" style=\"left:59px;top:355px;font-size:15.0px;max-width:445px\">买办的封建的国家垄断资本主义。反对官僚资本主义并非因为它是资本主义，而是因</span><span class=\"bl\" style=\"left:60px;top:376px;font-size:15.0px;max-width:247px\">为这种资本主义具有买办性、封建性和垄断性。</span><span class=\"bl\" style=\"left:82px;top:397px;font-size:13.9px;max-width:198px\">3.不同历史阶段革命的主要对象不同</span><span class=\"bl\" style=\"left:83px;top:418px;font-size:13.9px;max-width:305px\">大革命时期（1924一1927年）：帝国主义支持的北洋军阀</span><span class=\"bl\" style=\"left:83px;top:440px;font-size:13.9px;max-width:282px\">土地革命战争时期（1927一1937年）：国民党新军阀</span><span class=\"bl\" style=\"left:83px;top:460px;font-size:13.9px;max-width:258px\">抗日战争时期（1937一1945年）：日本帝国主义</span><span class=\"bl\" style=\"left:82px;top:480px;font-size:16.1px;max-width:366px\">解放战争时期（1945一1949年）：美帝国主义支持的蒋介石反动政权</span><span class=\"bl b\" style=\"left:82px;top:501px;font-size:15.0px;max-width:202px\">4.民族革命和民主革命的相互关系：</span><span class=\"bl\" style=\"left:83px;top:523px;font-size:13.9px;max-width:279px\">①民族革命：对外推翻帝国主义压迫。（最主要任务）</span><span class=\"bl\" style=\"left:83px;top:542px;font-size:17.2px;max-width:198px\">②民主革命：对内推翻封建地主压迫。</span><span class=\"bl\" style=\"left:82px;top:563px;font-size:16.1px;max-width:421px\">③二者既是相互区别，又是相互统一的。帝国主义是封建地主阶级的靠山，不推</span><span class=\"bl\" style=\"left:59px;top:585px;font-size:14.4px;max-width:444px\">翻帝国主义的统治，则不能消灭封建地主阶级的统治。地主阶级是帝国主义统治中国</span><span class=\"bl\" style=\"left:59px;top:605px;font-size:15.0px;max-width:366px\">的主要社会基础，不推翻地主阶级，就不能彻底铲除封建制度的根基。</span><span class=\"bl b\" style=\"left:59px;top:634px;font-size:13.9px;max-width:231px\">9.3新民主主义革命的动力（高频选择题）</span><span class=\"bl b\" style=\"left:82px;top:654px;font-size:15.0px;max-width:169px\">1.新民主主义革命的动力包括：</span><span class=\"bl\" style=\"left:84px;top:677px;font-size:13.9px;max-width:294px\">无产阶级、农民阶级、城市小资产阶级和民族资产阶级。</span><span class=\"bl b\" style=\"left:82px;top:697px;font-size:13.9px;max-width:76px\">2.无产阶级：</span><span class=\"bl\" style=\"left:84px;top:718px;font-size:13.9px;max-width:419px\">中国革命最基本的动力，中国无产阶级是新的社会生产力的代表，是最早出现的</span><span class=\"bl\" style=\"left:60px;top:739px;font-size:13.9px;max-width:377px\">一个新的社会阶级，是近代中国最进步的阶级，是中国革命的领导力量。</span><span class=\"bl b\" style=\"left:81px;top:760px;font-size:14.4px;max-width:53px\">3.农民：</span><span class=\"bl\" style=\"left:84px;top:780px;font-size:13.9px;max-width:419px\">中国革命的主力军，其中贫雇农是无产阶级最可靠的同盟军，中农是无产阶级可</span><span class=\"bl\" style=\"left:59px;top:801px;font-size:14.4px;max-width:71px\">靠的同盟军。</span><span class=\"bl\" style=\"left:83px;top:822px;font-size:13.9px;max-width:189px\">①农民问题是中国革命的基本问题。</span><span class=\"bl\" style=\"left:84px;top:842px;font-size:13.9px;max-width:318px\">②新民主主义革命实质上就是中国共产党领导下的农民革命。</span><span class=\"bl\" style=\"left:84px;top:865px;font-size:12.2px;max-width:260px\">③中国革命战争实质上就是党领导下的农民战争。</span><span class=\"bl\" style=\"left:84px;top:885px;font-size:13.9px;max-width:137px\">④实现革命领导权的基础</span><span class=\"bl\" style=\"left:213px;top:886px;font-size:12.2px;max-width:153px\">—工人阶级对农民的领导。</span><span class=\"bl\" style=\"left:456px;top:885px;font-size:14.4px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:524px;top:887px;font-size:13.9px;max-width:95px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:82px;top:904px;font-size:16.1px;max-width:229px\">4.城市小资产阶级：中国革命的动力之一。</span><span class=\"bl\" style=\"left:516px;top:910px;font-size:13.9px;max-width:189px\">由于近代中国社会阶层，呈现“两头小，</span><span class=\"bl\" style=\"left:83px;top:925px;font-size:15.6px;max-width:420px\">①城市小资产阶级是劳动者，不是剥削阶级，不是资产阶级的组成部分，是无产</span><span class=\"bl\" style=\"left:516px;top:927px;font-size:14.4px;max-width:189px\">中间大”的阶级结构，农民人口占大多数</span><span class=\"bl\" style=\"left:59px;top:946px;font-size:15.6px;max-width:108px\">阶级的可靠同盟者。</span><span class=\"bl\" style=\"left:515px;top:946px;font-size:14.4px;max-width:191px\">人，所以想要实现对这场革命的领导，就</span><span class=\"bl\" style=\"left:83px;top:966px;font-size:15.0px;max-width:421px\">②城市小资产阶级包括广大的知识分子、小商人、手工业者和自由职业者，同样</span><span class=\"bl\" style=\"left:515px;top:963px;font-size:14.4px;max-width:155px\">要领导革命中的大多数人即农民。</span><span class=\"bl\" style=\"left:60px;top:989px;font-size:12.2px;max-width:247px\">受帝国主义、封建主义和官僚资本主义的压迫。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 15 页</div><div class=\"sidebox\" style=\"left:514px;top:295px;width:194px;height:102px\"></div><span class=\"bl\" style=\"left:87px;top:104px;font-size:17.2px;max-width:357px\">5.民族资产阶级一中国革命的动力之一，民族资产阶级具有两面性：</span><span class=\"bl\" style=\"left:88px;top:126px;font-size:15.6px;max-width:390px\">①革命性：既受帝国主义的压迫，又受封建主义的束缚。一—政治上争取。</span><span class=\"bl\" style=\"left:88px;top:146px;font-size:15.0px;max-width:420px\">②动摇性和妥协性：在经济上和政治上与帝国主义和封建主义有着千丝万缕的联</span><span class=\"bl\" style=\"left:64px;top:166px;font-size:17.8px;max-width:447px\">系，没有彻底的反帝反封建的勇气，在革命的关键时刻表现出明显的动摇性。一批</span><span class=\"bl\" style=\"left:64px;top:189px;font-size:14.4px;max-width:62px\">评和斗争。</span><span class=\"bl\" style=\"left:88px;top:208px;font-size:15.0px;max-width:420px\">中国共产党对民族资产阶级在政治上争取它，在经济上实行保护民族工商业的政</span><span class=\"bl\" style=\"left:65px;top:231px;font-size:13.9px;max-width:317px\">策，又斗争又联合，是合乎实际的，是争取革命胜利的需要。</span><span class=\"bl b\" style=\"left:65px;top:259px;font-size:12.2px;max-width:227px\">9.4新民主主义革命的领导（高频选择题）</span><span class=\"bl\" style=\"left:86px;top:278px;font-size:16.1px;max-width:152px\">1.无产阶级领导权的重要性</span><span class=\"bl\" style=\"left:88px;top:301px;font-size:13.9px;max-width:329px\">①无产阶级及其政党的领导，是中国革命取得胜利的根本保证。</span><span class=\"bl\" style=\"left:460px;top:301px;font-size:14.4px;max-width:49px\">&gt;提示1</span><span class=\"bl\" style=\"left:521px;top:301px;font-size:13.9px;max-width:100px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:89px;top:322px;font-size:12.2px;max-width:420px\">②无产阶级的领导权是中国革命的中心问题，也是新民主主义革命理论的核心</span><span class=\"bl\" style=\"left:520px;top:323px;font-size:13.9px;max-width:143px\">①革命的首要问题：分清敌友。</span><span class=\"bl\" style=\"left:64px;top:341px;font-size:15.0px;max-width:37px\">问题。</span><span class=\"bl\" style=\"left:520px;top:342px;font-size:13.9px;max-width:161px\">②中国革命的基本问题：农民问题。</span><span class=\"bl\" style=\"left:89px;top:363px;font-size:13.9px;max-width:420px\">③区别新旧两种不同范畴的民主主义革命的根本标志是：革命的领导权掌握在无</span><span class=\"bl\" style=\"left:520px;top:359px;font-size:13.9px;max-width:190px\">③中国革命的中心问题：无产阶级的领</span><span class=\"bl\" style=\"left:530px;top:378px;font-size:15.0px;max-width:35px\">导权。</span><span class=\"bl\" style=\"left:65px;top:383px;font-size:13.9px;max-width:200px\">产阶级手中还是掌握在资产阶级手中。</span><span class=\"bl b\" style=\"left:88px;top:404px;font-size:13.9px;max-width:332px\">2.无产阶级的领导权：是由历史和中国无产阶级的特点决定的。</span><span class=\"bl\" style=\"left:86px;top:426px;font-size:13.9px;max-width:200px\">（1）近代中国历史发展表明（原因）：</span><span class=\"bl\" style=\"left:88px;top:445px;font-size:15.0px;max-width:413px\">①中国民族资产阶级的软弱性和妥协性，不能够彻底推翻帝国主义和封建势力；</span><span class=\"bl\" style=\"left:88px;top:466px;font-size:17.2px;max-width:415px\">②农民阶级和城市小资产阶级因其小生产的特点，不能成为革命的正确的领导者；</span><span class=\"bl\" style=\"left:84px;top:488px;font-size:13.9px;max-width:146px\">（2）中国无产阶级的特点：</span><span class=\"bl\" style=\"left:86px;top:507px;font-size:17.2px;max-width:423px\">①中国无产阶级与世界无产阶级的共同点：与先进的生产方式相联系，没有私人</span><span class=\"bl\" style=\"left:65px;top:529px;font-size:15.0px;max-width:194px\">占有的生产资料，富于组织纪律性。</span><span class=\"bl\" style=\"left:248px;top:536px;font-size:23.9px;max-width:116px\">口你</span><span class=\"bl\" style=\"left:358px;top:539px;font-size:25.0px;max-width:83px\">上F</span><span class=\"bl\" style=\"left:89px;top:550px;font-size:13.9px;max-width:126px\">②自身的特点和优点：</span><span class=\"bl\" style=\"left:86px;top:570px;font-size:16.1px;max-width:422px\">A.身受外国资本主义、本国封建势力和资产阶级的三重压迫。因此，中国无产</span><span class=\"bl\" style=\"left:65px;top:592px;font-size:13.9px;max-width:283px\">阶级在革命斗争中比任何别的阶级都来得坚决和彻底；</span><span class=\"bl\" style=\"left:86px;top:612px;font-size:16.1px;max-width:422px\">B.它分布集中，有利于无产阶级队伍的组织和团结，有利于革命思想的传播和</span><span class=\"bl\" style=\"left:64px;top:633px;font-size:15.6px;max-width:120px\">强大革命力量的形成；</span><span class=\"bl\" style=\"left:87px;top:653px;font-size:15.0px;max-width:421px\">C.它的成员中的大部分出身于破产农民，和农民有着天然的联系，这使得无产</span><span class=\"bl\" style=\"left:64px;top:674px;font-size:15.6px;max-width:259px\">阶级便于和农民结成亲密的联盟，共同团结战斗。</span><span class=\"bl\" style=\"left:86px;top:695px;font-size:15.0px;max-width:380px\">3.无产阶级对革命的领导权是在与资产阶级争夺领导权的斗争中实现的。</span><span class=\"bl\" style=\"left:88px;top:716px;font-size:15.0px;max-width:225px\">①实现领导权的必须具备的两个基本条件：</span><span class=\"bl\" style=\"left:87px;top:737px;font-size:15.0px;max-width:355px\">率领被领导者（同盟者）向着共同敌人作坚决的斗争，并取得胜利；</span><span class=\"bl\" style=\"left:87px;top:757px;font-size:17.2px;max-width:414px\">对被领导者给以物质福利，至少不损害其利益；同时对被领导者给以政治教育。</span><span class=\"bl\" style=\"left:87px;top:778px;font-size:17.2px;max-width:366px\">②实现领导权的关键：必须建立以工农联盟为基础的广泛的统一战线。</span><span class=\"bl\" style=\"left:88px;top:799px;font-size:15.6px;max-width:415px\">③坚持领导权的基本策略：必须坚持独立自主的原则，实行又联合又斗争的方针。</span><span class=\"bl\" style=\"left:88px;top:820px;font-size:15.6px;max-width:420px\">④保证领导权的坚强支柱：建立一支无产阶级领导的以农民为主体的强大的革命</span><span class=\"bl\" style=\"left:63px;top:840px;font-size:15.6px;max-width:38px\">武装。</span><span class=\"bl\" style=\"left:87px;top:862px;font-size:15.0px;max-width:283px\">5实现领导权的根本保证：加强无产阶级政党的建设。</span><span class=\"bl b\" style=\"left:63px;top:889px;font-size:16.1px;max-width:323px\">9.5新民主主义革命的性质和前途（高频选择题）（2012-10）</span><span class=\"bl\" style=\"left:86px;top:910px;font-size:15.0px;max-width:234px\">1.新民主主义革命与旧民主主义革命的区别</span><span class=\"bl\" style=\"left:93px;top:939px;font-size:17.2px;max-width:45px\">不同点</span><span class=\"bl\" style=\"left:204px;top:941px;font-size:14.4px;max-width:87px\">旧民主主义革命</span><span class=\"bl\" style=\"left:374px;top:941px;font-size:16.1px;max-width:89px\">新民主主义革命</span><span class=\"bl\" style=\"left:83px;top:972px;font-size:18.3px;max-width:61px\">根本区别：</span><span class=\"bl\" style=\"left:165px;top:982px;font-size:18.3px;max-width:56px\">资产阶级</span><span class=\"bl\" style=\"left:336px;top:984px;font-size:16.1px;max-width:56px\">无产阶级</span><span class=\"bl\" style=\"left:81px;top:992px;font-size:16.1px;max-width:67px\">革命领导权</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 16 页</div><span class=\"bl\" style=\"left:456px;top:62px;font-size:17.3px;max-width:244px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:465px;top:106px;font-size:19.5px;max-width:36px\">续表</span><span class=\"bl\" style=\"left:83px;top:132px;font-size:17.3px;max-width:45px\">不同点</span><span class=\"bl\" style=\"left:195px;top:132px;font-size:16.1px;max-width:89px\">旧民主主义革命</span><span class=\"bl\" style=\"left:365px;top:133px;font-size:16.1px;max-width:89px\">新民主主义革命</span><span class=\"bl\" style=\"left:76px;top:164px;font-size:20.0px;max-width:58px\">时代条件</span><span class=\"bl\" style=\"left:156px;top:166px;font-size:17.8px;max-width:102px\">世界资产阶级革命</span><span class=\"bl\" style=\"left:328px;top:168px;font-size:15.6px;max-width:136px\">世界无产阶社会主义革命</span><span class=\"bl\" style=\"left:66px;top:199px;font-size:16.1px;max-width:79px\">革命指导思想</span><span class=\"bl\" style=\"left:156px;top:199px;font-size:17.8px;max-width:125px\">资产阶级民主主义思想</span><span class=\"bl\" style=\"left:328px;top:201px;font-size:16.1px;max-width:89px\">马克思列宁主义</span><span class=\"bl\" style=\"left:327px;top:235px;font-size:16.1px;max-width:159px\">在中国建立以工人阶级领导的</span><span class=\"bl\" style=\"left:157px;top:254px;font-size:15.6px;max-width:158px\">在中国建立资产阶级专政的国</span><span class=\"bl\" style=\"left:329px;top:256px;font-size:13.9px;max-width:158px\">各革命阶级联合专政，然后再</span><span class=\"bl\" style=\"left:60px;top:263px;font-size:17.8px;max-width:91px\">革命目标和前途</span><span class=\"bl\" style=\"left:157px;top:274px;font-size:15.6px;max-width:136px\">家和资本主义的社会制度</span><span class=\"bl\" style=\"left:328px;top:274px;font-size:15.6px;max-width:158px\">过渡到社会主义社会，最终目</span><span class=\"bl\" style=\"left:328px;top:294px;font-size:15.6px;max-width:102px\">标是实现共产主义</span><span class=\"bl\" style=\"left:156px;top:327px;font-size:17.3px;max-width:332px\">近代中国半殖民地半封建社会的性质和中国革命的历史任务，决</span><span class=\"bl\" style=\"left:81px;top:344px;font-size:20.6px;max-width:47px\">相同点</span><span class=\"bl\" style=\"left:156px;top:347px;font-size:16.1px;max-width:332px\">定了中国革命的性质不是社会主义革命，而是资产阶级民主主义</span><span class=\"bl\" style=\"left:155px;top:365px;font-size:18.4px;max-width:34px\">革命</span><span class=\"bl\" style=\"left:76px;top:400px;font-size:17.3px;max-width:235px\">2.新民主主义革命与社会主义革命性质不同</span><span class=\"bl\" style=\"left:72px;top:425px;font-size:20.0px;max-width:36px\">考点</span><span class=\"bl\" style=\"left:170px;top:427px;font-size:16.1px;max-width:90px\">新民主主义革命</span><span class=\"bl\" style=\"left:359px;top:425px;font-size:19.5px;max-width:80px\">社会主义革命</span><span class=\"bl\" style=\"left:63px;top:461px;font-size:17.3px;max-width:55px\">性质不同</span><span class=\"bl\" style=\"left:127px;top:461px;font-size:16.1px;max-width:79px\">资产阶级性质</span><span class=\"bl\" style=\"left:309px;top:462px;font-size:16.1px;max-width:79px\">无产阶级性质</span><span class=\"bl\" style=\"left:129px;top:497px;font-size:13.9px;max-width:170px\">建立的是无产阶级领导的各革命</span><span class=\"bl\" style=\"left:310px;top:496px;font-size:15.6px;max-width:170px\">消灭资本主义剥削制度和改造小</span><span class=\"bl\" style=\"left:63px;top:505px;font-size:17.3px;max-width:55px\">前途不同</span><span class=\"bl\" style=\"left:128px;top:515px;font-size:14.5px;max-width:89px\">阶级的联合专政</span><span class=\"bl\" style=\"left:310px;top:515px;font-size:15.6px;max-width:170px\">生产的私有制；建立无产阶专政</span><span class=\"bl\" style=\"left:75px;top:549px;font-size:16.1px;max-width:32px\">二者</span><span class=\"bl\" style=\"left:127px;top:549px;font-size:15.6px;max-width:243px\">①新民主主义革命是社会主义革命的必要准备</span><span class=\"bl\" style=\"left:73px;top:568px;font-size:17.8px;max-width:35px\">联系</span><span class=\"bl\" style=\"left:126px;top:568px;font-size:17.3px;max-width:245px\">②社会主义革命是新民主主义革命的必然趋势</span><span class=\"bl\" style=\"left:128px;top:603px;font-size:15.6px;max-width:353px\">中国革命要分两步走：在中国共产党的领导下，先进行新民主主义革</span><span class=\"bl\" style=\"left:63px;top:621px;font-size:17.3px;max-width:56px\">正确观点</span><span class=\"bl\" style=\"left:127px;top:622px;font-size:16.1px;max-width:356px\">命，完成反帝反封建的任务；再进行一场社会主义革命，完成反资反</span><span class=\"bl\" style=\"left:127px;top:642px;font-size:15.6px;max-width:182px\">私的任务，最终建立社会主义制度</span><span class=\"bl\" style=\"left:127px;top:675px;font-size:15.6px;max-width:354px\">①王明“一次革命论”：只看到民主革命和社会主义革命的联系，混</span><span class=\"bl\" style=\"left:128px;top:696px;font-size:13.9px;max-width:353px\">淆了民主革命和社会主义革命的区别，主张在反帝反封建的同时，也</span><span class=\"bl\" style=\"left:127px;top:715px;font-size:16.1px;max-width:355px\">反对民族资产阶级。想要一步登天，两步变作一步，一次性完成这个</span><span class=\"bl\" style=\"left:126px;top:733px;font-size:19.5px;max-width:41px\">革命。</span><span class=\"bl\" style=\"left:63px;top:754px;font-size:16.1px;max-width:56px\">错误观点</span><span class=\"bl\" style=\"left:127px;top:754px;font-size:15.6px;max-width:347px\">②陈独秀“二次革命论”：只看到民主革命和社会主义革命的区别，</span><span class=\"bl\" style=\"left:128px;top:775px;font-size:13.9px;max-width:353px\">割裂了两个革命阶段的联系，放弃了党对民主革命的领导权，主张在</span><span class=\"bl\" style=\"left:127px;top:794px;font-size:15.6px;max-width:355px\">民主革命胜利之后，建立一个资产阶级专政的资本主义国家，将来再</span><span class=\"bl\" style=\"left:127px;top:813px;font-size:15.6px;max-width:187px\">进行社会主义革命，犯了右的错误。</span><span class=\"bl\" style=\"left:127px;top:833px;font-size:15.6px;max-width:259px\">③其他错误观点：毕其功于一役；“无间断”革命</span><span class=\"bl b hl\" style=\"left:63px;top:878px;font-size:18.9px;max-width:70px\">考点10</span><span class=\"bl\" style=\"left:121px;top:879px;font-size:17.8px;max-width:199px\">新民主主义的基本纲领☆☆☆</span><span class=\"bl b\" style=\"left:52px;top:913px;font-size:17.3px;max-width:271px\">10.1新民主主义基本纲领的提出：（低频选择题）</span><span class=\"bl b\" style=\"left:76px;top:935px;font-size:15.6px;max-width:264px\">1.首次阐述：1940年，毛泽东《新民主主义论》。</span><span class=\"bl b\" style=\"left:75px;top:955px;font-size:17.3px;max-width:421px\">2.进一步阐述：1945年，毛泽东在党的七大所作的《论联合政府》的政治报告。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1091px\"><div class=\"bxnum\">第 17 页</div><div class=\"sidebox\" style=\"left:518px;top:680px;width:193px;height:210px\"></div><span class=\"bl b\" style=\"left:67px;top:110px;font-size:15.0px;max-width:238px\">10.2新民主主义的政治纲领（中频选择题）</span><span class=\"bl\" style=\"left:524px;top:117px;font-size:15.5px;max-width:103px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:91px;top:131px;font-size:14.4px;max-width:52px\">1.内容：</span><span class=\"bl\" style=\"left:525px;top:141px;font-size:12.2px;max-width:187px\">新民主主义共和国既不同于欧美式的资产</span><span class=\"bl\" style=\"left:91px;top:150px;font-size:17.2px;max-width:421px\">推翻帝国主义和封建主义的统治，建立一个无产阶级领导的、以工农联盟为基础</span><span class=\"bl\" style=\"left:524px;top:160px;font-size:12.2px;max-width:188px\">阶级专政的共和国，又和苏联式的无产阶</span><span class=\"bl\" style=\"left:68px;top:173px;font-size:14.4px;max-width:260px\">的、各革命阶级联合专政的新民主主义的共和国。</span><span class=\"bl\" style=\"left:465px;top:172px;font-size:17.2px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:523px;top:176px;font-size:14.4px;max-width:152px\">级专政的社会主义共和国相区别。</span><span class=\"bl b\" style=\"left:92px;top:193px;font-size:15.0px;max-width:239px\">2.国家政权性质：各个革命阶级的联合专政。</span><span class=\"bl b\" style=\"left:92px;top:215px;font-size:13.9px;max-width:181px\">3.新民主主义国家的国体和政体：</span><span class=\"bl\" style=\"left:465px;top:215px;font-size:14.4px;max-width:46px\">&gt;提示1</span><span class=\"bl\" style=\"left:532px;top:212px;font-size:13.9px;max-width:91px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:92px;top:233px;font-size:17.8px;max-width:421px\">国体：各革命阶级联合专政一无产阶级领导的以工农联盟为基础，包括小资产</span><span class=\"bl\" style=\"left:524px;top:233px;font-size:15.5px;max-width:73px\">国体决定政体。</span><span class=\"bl\" style=\"left:68px;top:255px;font-size:14.4px;max-width:401px\">阶级、民族资产阶级和其他反帝反封建的人们在内的各革命阶级的联合专政。</span><span class=\"bl\" style=\"left:92px;top:277px;font-size:13.9px;max-width:212px\">政体：民主集中制的人民代表大会制度。</span><span class=\"bl\" style=\"left:93px;top:298px;font-size:13.9px;max-width:318px\">新民主主义国家制度的核心内容和基本准则：人民当家作主。</span><span class=\"bl b\" style=\"left:68px;top:325px;font-size:13.9px;max-width:237px\">10.3新民主主义的经济纲领（中频选择题）</span><span class=\"bl b\" style=\"left:91px;top:345px;font-size:16.1px;max-width:53px\">1.内容：</span><span class=\"bl\" style=\"left:93px;top:368px;font-size:13.9px;max-width:212px\">①没收封建地主阶级的土地归农民所有。</span><span class=\"bl\" style=\"left:93px;top:388px;font-size:13.9px;max-width:306px\">②没收官僚资产阶级的垄断资本归新民主主义的国家所有。</span><span class=\"bl\" style=\"left:92px;top:409px;font-size:15.5px;max-width:108px\">③保护民族工商业。</span><span class=\"bl b\" style=\"left:93px;top:431px;font-size:12.2px;max-width:214px\">2.没收封建地主阶级的土地归农民所有：</span><span class=\"bl\" style=\"left:93px;top:451px;font-size:13.9px;max-width:189px\">①这是新民主主义革命的主要内容。</span><span class=\"bl\" style=\"left:90px;top:470px;font-size:16.1px;max-width:423px\">②1948年4月，毛泽东在《在晋绥干部会议上的讲话》中提出了完整的土地改</span><span class=\"bl\" style=\"left:69px;top:492px;font-size:13.9px;max-width:444px\">革的总路线，即依靠贫雇农，团结中农，有步骤地、有分别地消灭封建剥削制度、发</span><span class=\"bl\" style=\"left:68px;top:511px;font-size:17.8px;max-width:73px\">展农业生产。</span><span class=\"bl b\" style=\"left:90px;top:533px;font-size:16.1px;max-width:312px\">3.没收官僚资产阶级的垄断资本归新民主主义的国家所有：</span><span class=\"bl\" style=\"left:397px;top:533px;font-size:43.9px;max-width:53px\">岸</span><span class=\"bl\" style=\"left:90px;top:549px;font-size:28.9px;max-width:311px\">①这是新民主主义革命的题中应有之义。</span><span class=\"bl\" style=\"left:94px;top:577px;font-size:12.2px;max-width:175px\">②没收官僚资本包含着双重性质：</span><span class=\"bl\" style=\"left:92px;top:595px;font-size:16.1px;max-width:422px\">A.从反对外国帝国主义的附庸（中国的买办资产阶级）的意义上看，它具有民</span><span class=\"bl\" style=\"left:69px;top:617px;font-size:14.4px;max-width:78px\">主革命的性质</span><span class=\"bl\" style=\"left:92px;top:639px;font-size:13.9px;max-width:374px\">B.从反对中国的大资产阶级的意义上看，它又具有社会主义革命的性质</span><span class=\"bl\" style=\"left:93px;top:659px;font-size:13.9px;max-width:411px\">③通过没收官僚资本建立起来的具有社会主义性质的国营经济，居于领导地位。</span><span class=\"bl b\" style=\"left:92px;top:681px;font-size:13.9px;max-width:109px\">4.保护民族工商业：</span><span class=\"bl\" style=\"left:465px;top:681px;font-size:14.4px;max-width:47px\">&gt;拓展1</span><span class=\"bl\" style=\"left:526px;top:686px;font-size:13.9px;max-width:100px\">&gt;火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:93px;top:701px;font-size:13.9px;max-width:213px\">①这是经济纲领中极具特色的一项内容。</span><span class=\"bl\" style=\"left:525px;top:709px;font-size:12.2px;max-width:187px\">同官僚资产阶级相比，民族资产阶级与帝</span><span class=\"bl\" style=\"left:93px;top:721px;font-size:13.9px;max-width:142px\">②保护民族工商业的原因：</span><span class=\"bl\" style=\"left:525px;top:727px;font-size:12.2px;max-width:187px\">国主义和封建主义联系较少。民族资本主</span><span class=\"bl\" style=\"left:93px;top:742px;font-size:13.9px;max-width:315px\">A.由新民主主义革命的性质决定一—反帝反封，而不是反资</span><span class=\"bl\" style=\"left:524px;top:745px;font-size:13.9px;max-width:188px\">义经济，是一种与新生产力相联系的先进</span><span class=\"bl\" style=\"left:93px;top:763px;font-size:13.9px;max-width:286px\">B.由中国生产力的发展水平决定一生产力比较落后。</span><span class=\"bl\" style=\"left:524px;top:764px;font-size:12.2px;max-width:188px\">的生产方式和经济成分，它对发展现代</span><span class=\"bl\" style=\"left:524px;top:781px;font-size:13.9px;max-width:189px\">技术、发展社会生产力具有积极作用。因</span><span class=\"bl b\" style=\"left:67px;top:790px;font-size:15.0px;max-width:238px\">10.4新民主主义的文化纲领（中频选择题）</span><span class=\"bl\" style=\"left:524px;top:799px;font-size:13.9px;max-width:188px\">此，对民族资本主义工商业必须采取保护</span><span class=\"bl b\" style=\"left:92px;top:812px;font-size:14.4px;max-width:52px\">1.内容：</span><span class=\"bl\" style=\"left:524px;top:818px;font-size:13.9px;max-width:189px\">的政策。但这种保护并不是无条件的。需</span><span class=\"bl\" style=\"left:92px;top:832px;font-size:14.4px;max-width:418px\">新民主主义文化就是无产阶级领导的人民大众的反帝反封建的文化，即民族的、</span><span class=\"bl\" style=\"left:525px;top:837px;font-size:12.2px;max-width:187px\">要保护和发展的资本主义，是有利于而不</span><span class=\"bl\" style=\"left:67px;top:853px;font-size:14.4px;max-width:295px\">科学的、大众的文化。其中共产主义思想居于指导地位。</span><span class=\"bl\" style=\"left:525px;top:855px;font-size:12.2px;max-width:187px\">是有害于国计民生的私人资本主义经济，</span><span class=\"bl b\" style=\"left:91px;top:874px;font-size:14.4px;max-width:64px\">2.民族的：</span><span class=\"bl\" style=\"left:525px;top:873px;font-size:12.2px;max-width:150px\">是不能操纵国计民生的资本主义。</span><span class=\"bl\" style=\"left:92px;top:893px;font-size:17.8px;max-width:366px\">①从内容上来说，是反对帝国主义压迫，主张中华民族的尊严和独立；</span><span class=\"bl\" style=\"left:92px;top:915px;font-size:15.5px;max-width:419px\">②从形式上来说，是具有鲜明的民族风格、民族形式和民族特色，要有中国作风</span><span class=\"bl\" style=\"left:68px;top:936px;font-size:13.9px;max-width:72px\">和中国气派。</span><span class=\"bl b\" style=\"left:90px;top:956px;font-size:15.0px;max-width:286px\">3.科学的：就是要反封建、迷信思想，主张实事求是。</span><span class=\"bl b\" style=\"left:91px;top:976px;font-size:16.1px;max-width:380px\">4.大众的：就是为大多数人服务的，不是为精英服务的，是民主的文化。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 18 页</div><div class=\"sidebox\" style=\"left:507px;top:701px;width:179px;height:132px\"></div><span class=\"bl\" style=\"left:459px;top:61px;font-size:16.1px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b hl\" style=\"left:65px;top:116px;font-size:22.8px;max-width:257px\">考点11 新民主主义革命的道路☆☆☆</span><span class=\"bl b\" style=\"left:56px;top:153px;font-size:16.1px;max-width:260px\">11.1新民主主义革命道路的提出（中频选择题）</span><span class=\"bl b\" style=\"left:80px;top:175px;font-size:15.0px;max-width:228px\">1.农村包围城市的革命道路理论初步形成：</span><span class=\"bl\" style=\"left:80px;top:195px;font-size:17.2px;max-width:422px\">①1927年大革命后，党的工作重心开始由城市转向农村，提出了“工农武装割</span><span class=\"bl\" style=\"left:57px;top:217px;font-size:14.4px;max-width:72px\">据”的思想。</span><span class=\"bl\" style=\"left:80px;top:237px;font-size:17.2px;max-width:422px\">②毛泽东在此过程中写下的代表著作：《中国的红色政权为什么能够存在？》《井</span><span class=\"bl\" style=\"left:57px;top:258px;font-size:15.0px;max-width:289px\">冈山的斗争》《星星之火，可以燎原》等。（2014一11）</span><span class=\"bl b\" style=\"left:80px;top:280px;font-size:13.9px;max-width:228px\">2.农村包围城市的革命道路理论最终确立：</span><span class=\"bl\" style=\"left:80px;top:299px;font-size:17.2px;max-width:422px\">①1938年11月，毛泽东在党的六届六中全会上，确立了经过长期武装斗争，先</span><span class=\"bl\" style=\"left:57px;top:321px;font-size:15.0px;max-width:271px\">占乡村，后取城市，最后夺取全国胜利的革命道路。</span><span class=\"bl\" style=\"left:81px;top:342px;font-size:15.0px;max-width:310px\">②革命道路理论最终确立的代表著作：《战争和战略问题》。</span><span class=\"bl b\" style=\"left:56px;top:370px;font-size:15.0px;max-width:350px\">11.2新民主主义革命道路形成的必然性（高频选择题）（2011-5）</span><span class=\"bl b\" style=\"left:80px;top:391px;font-size:15.0px;max-width:215px\">1.必要性：是由中国的具体国情决定的。</span><span class=\"bl\" style=\"left:81px;top:412px;font-size:15.0px;max-width:201px\">①在近代中国半殖民地半封建社会里：</span><span class=\"bl\" style=\"left:80px;top:434px;font-size:13.9px;max-width:198px\">A.内无民主制度而受封建主义的压迫</span><span class=\"bl\" style=\"left:81px;top:454px;font-size:13.9px;max-width:197px\">B.外无民族独立而受帝国主义的压迫</span><span class=\"bl\" style=\"left:79px;top:476px;font-size:13.9px;max-width:423px\">②近代中国是一个农业大国，农民占全国人口的绝大多数，是无产阶级可靠的同</span><span class=\"bl\" style=\"left:56px;top:496px;font-size:15.6px;max-width:120px\">盟军和革命的主力军。</span><span class=\"bl b\" style=\"left:80px;top:517px;font-size:13.9px;max-width:214px\">2.可能性：是由中国的特殊国情决定的。</span><span class=\"bl\" style=\"left:81px;top:537px;font-size:15.0px;max-width:233px\">①根本原因：社会政治经济发展极端不平衡。</span><span class=\"bl\" style=\"left:80px;top:558px;font-size:15.0px;max-width:377px\">②群众基础：人民革命愿望强烈，经历过民主革命的洗礼，群众基础好。</span><span class=\"bl\" style=\"left:80px;top:578px;font-size:17.2px;max-width:422px\">③客观条件：全国革命形势的继续向前发展，为在农村建设革命根据地提供了客</span><span class=\"bl\" style=\"left:57px;top:599px;font-size:14.4px;max-width:49px\">观条件。</span><span class=\"bl\" style=\"left:80px;top:620px;font-size:16.1px;max-width:213px\">④坚强后盾：相当力量正式红军的存在。</span><span class=\"bl\" style=\"left:81px;top:642px;font-size:13.9px;max-width:271px\">③主观条件：党的领导的有力量及其政策的不错误。</span><span class=\"bl b\" style=\"left:57px;top:670px;font-size:13.9px;max-width:300px\">11.3新民主主义革命道路的内容及意义（高频选择题）</span><span class=\"bl\" style=\"left:80px;top:692px;font-size:13.9px;max-width:421px\">1.中国革命走农村包围城市、武装夺取政权的道路，根本在于：处理好土地革</span><span class=\"bl\" style=\"left:513px;top:707px;font-size:15.6px;max-width:102px\">火星姐姐考点图解1</span><span class=\"bl\" style=\"left:57px;top:713px;font-size:14.4px;max-width:284px\">命、武装斗争和农村革命根据地建设三者之间的关系。</span><span class=\"bl\" style=\"left:453px;top:713px;font-size:14.4px;max-width:47px\">图解1</span><span class=\"bl\" style=\"left:80px;top:733px;font-size:15.0px;max-width:191px\">①土地革命是民主革命的基本内容。</span><span class=\"bl\" style=\"left:530px;top:731px;font-size:12.8px;max-width:48px\">土地革命</span><span class=\"bl\" style=\"left:584px;top:730px;font-size:13.9px;max-width:82px\">革命的基本内容</span><span class=\"bl\" style=\"left:80px;top:753px;font-size:16.1px;max-width:418px\">②武装斗争是中国革命的主要形式，是农村根据地建设和土地革命的强有力保证。</span><span class=\"bl\" style=\"left:585px;top:752px;font-size:13.9px;max-width:103px\">保证土地革命的进行</span><span class=\"bl\" style=\"left:528px;top:762px;font-size:15.0px;max-width:50px\">武装斗争</span><span class=\"bl\" style=\"left:81px;top:775px;font-size:13.9px;max-width:420px\">③农村革命根据地是中国革命的战略阵地，是进行武装斗争和开展土地革命的</span><span class=\"bl\" style=\"left:583px;top:772px;font-size:15.6px;max-width:104px\">保证革命根据地建设</span><span class=\"bl\" style=\"left:55px;top:794px;font-size:18.3px;max-width:40px\">依托。</span><span class=\"bl\" style=\"left:529px;top:798px;font-size:15.0px;max-width:49px\">农村革命</span><span class=\"bl\" style=\"left:581px;top:794px;font-size:14.4px;max-width:87px\">武装斗争的依托</span><span class=\"bl\" style=\"left:532px;top:811px;font-size:14.4px;max-width:42px\">根据地</span><span class=\"bl b\" style=\"left:80px;top:817px;font-size:13.9px;max-width:156px\">2.中国革命道路理论的意义：</span><span class=\"bl\" style=\"left:582px;top:815px;font-size:14.4px;max-width:86px\">土地革命的依托</span><span class=\"bl\" style=\"left:81px;top:837px;font-size:13.9px;max-width:420px\">①反映了中国半殖民地半封建社会民主革命发展的客观规律。②党在探索中国革</span><span class=\"bl\" style=\"left:58px;top:858px;font-size:13.9px;max-width:444px\">命道路的过程中，从中国的实际出发，开辟了引导中国革命走向胜利的正确道路，独</span><span class=\"bl\" style=\"left:57px;top:878px;font-size:15.0px;max-width:445px\">创性地发展了马克思列宁主义。③中国革命道路理论，是党运用马克思主义的立场、</span><span class=\"bl\" style=\"left:57px;top:898px;font-size:15.0px;max-width:444px\">观点和方法，分析、研究和解决中国革命具体问题的光辉典范，对于推进马克思主义</span><span class=\"bl\" style=\"left:58px;top:920px;font-size:13.9px;max-width:162px\">中国化具有重要的方法论意义。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 19 页</div><div class=\"sidebox\" style=\"left:515px;top:389px;width:194px;height:377px\"></div><span class=\"bl b hl\" style=\"left:76px;top:119px;font-size:17.8px;max-width:273px\">考点12新民主主义革命的三大法宝☆☆</span><span class=\"bl b\" style=\"left:65px;top:154px;font-size:13.9px;max-width:200px\">12.1三大法宝的提出（中频选择题）</span><span class=\"bl\" style=\"left:89px;top:174px;font-size:16.1px;max-width:422px\">1.毛泽东在《（共产党人》发刊词》一文中，总结了中国革命两次胜利和两次失</span><span class=\"bl\" style=\"left:65px;top:196px;font-size:15.0px;max-width:445px\">败的经验教训，揭示了中国革命发展的客观规律，指出：“统一战线，武装斗争，党</span><span class=\"bl\" style=\"left:66px;top:217px;font-size:13.9px;max-width:408px\">的建设，是中国共产党在中国革命中战胜敌人的三个法宝，三个主要的法宝。”</span><span class=\"bl\" style=\"left:89px;top:238px;font-size:14.4px;max-width:422px\">2.正确地理解和处理了这三个问题及其相互关系，就等于正确地领导了全部中国</span><span class=\"bl\" style=\"left:65px;top:258px;font-size:17.2px;max-width:38px\">革命。</span><span class=\"bl b\" style=\"left:66px;top:288px;font-size:12.2px;max-width:162px\">12.2统一战线（高频选择题）</span><span class=\"bl b\" style=\"left:90px;top:308px;font-size:14.4px;max-width:168px\">1.建立革命统一战线的必要性：</span><span class=\"bl\" style=\"left:90px;top:328px;font-size:14.4px;max-width:271px\">①由中国半殖民地半封建社会的阶级状况所决定的。</span><span class=\"bl\" style=\"left:90px;top:349px;font-size:14.4px;max-width:231px\">两头小：无产阶级和地主大资产阶级占少数</span><span class=\"bl\" style=\"left:92px;top:372px;font-size:12.2px;max-width:276px\">中间大：农民、城市小资产阶级以及其他的中间阶级</span><span class=\"bl\" style=\"left:91px;top:392px;font-size:13.9px;max-width:330px\">②由中国革命的长期性、残酷性及其发展的不平衡性所决定的。</span><span class=\"bl\" style=\"left:463px;top:391px;font-size:17.2px;max-width:47px\">解读1</span><span class=\"bl\" style=\"left:524px;top:395px;font-size:13.9px;max-width:100px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:91px;top:414px;font-size:12.2px;max-width:166px\">2.建立革命统一战线的可能性：</span><span class=\"bl\" style=\"left:463px;top:413px;font-size:14.4px;max-width:47px\">&gt;解读2</span><span class=\"bl\" style=\"left:522px;top:418px;font-size:12.2px;max-width:189px\">中国政治经济发展的不平衡性也造成了</span><span class=\"bl\" style=\"left:91px;top:433px;font-size:13.9px;max-width:420px\">在半殖民地半封建社会，诸多矛盾交织在一起，客观上为无产阶级及其政党利用</span><span class=\"bl\" style=\"left:522px;top:436px;font-size:12.2px;max-width:189px\">革命发展的不平衡性，这就使得无产阶</span><span class=\"bl\" style=\"left:67px;top:455px;font-size:12.2px;max-width:233px\">这些矛盾建立和发展统一战线提供了可能性。</span><span class=\"bl\" style=\"left:522px;top:454px;font-size:12.2px;max-width:189px\">级及其政党有必要采取正确的统一战线</span><span class=\"bl b\" style=\"left:87px;top:474px;font-size:14.4px;max-width:277px\">3.中国共产党领导的革命统一战线包含着两个联盟：</span><span class=\"bl\" style=\"left:522px;top:473px;font-size:12.2px;max-width:189px\">的策略，把一切可以团结和利用的力量</span><span class=\"bl\" style=\"left:90px;top:496px;font-size:13.9px;max-width:421px\">第一个联盟：工人阶级同农民阶级、广大知识分子及其他劳动者的联盟，主要是</span><span class=\"bl\" style=\"left:522px;top:489px;font-size:15.0px;max-width:190px\">尽可能团结在自己的周围，以逐步从根本</span><span class=\"bl\" style=\"left:522px;top:507px;font-size:15.0px;max-width:190px\">上改变敌强我弱的态势，夺取中国革命</span><span class=\"bl\" style=\"left:67px;top:516px;font-size:14.4px;max-width:57px\">工农联盟</span><span class=\"bl\" style=\"left:522px;top:527px;font-size:13.9px;max-width:64px\">的最终胜利。</span><span class=\"bl\" style=\"left:90px;top:537px;font-size:15.6px;max-width:400px\">第二个联盟：工人阶级和非劳动人民的联盟，主要是与民族资产阶级的联盟。</span><span class=\"bl b\" style=\"left:90px;top:559px;font-size:13.9px;max-width:136px\">4.两个联盟之间的关系：</span><span class=\"bl\" style=\"left:523px;top:562px;font-size:13.9px;max-width:104px\">火星姐姐考点解读2</span><span class=\"bl\" style=\"left:90px;top:579px;font-size:13.9px;max-width:421px\">①第一个联盟是统一战线的基础，只有争取农民、知识分子和其他劳动人民，巩</span><span class=\"bl\" style=\"left:521px;top:583px;font-size:14.4px;max-width:190px\">近代中国社会最大的压迫是民族压迫，决</span><span class=\"bl\" style=\"left:66px;top:599px;font-size:14.4px;max-width:248px\">固工农联盟，才能实现党对统一战线的领导权。</span><span class=\"bl\" style=\"left:522px;top:603px;font-size:13.9px;max-width:190px\">定了无产阶级及其政党可以把一切爱国</span><span class=\"bl\" style=\"left:90px;top:620px;font-size:15.0px;max-width:421px\">②第二个联盟也非常重要，只有建立这个联盟，联合一切可以联合的力量，壮大</span><span class=\"bl\" style=\"left:522px;top:622px;font-size:12.2px;max-width:188px\">的、不愿受帝国主义奴役的人们团结在自</span><span class=\"bl\" style=\"left:68px;top:642px;font-size:13.9px;max-width:443px\">自己，孤立主要的敌人，无产阶级及其政党才能掌握中国革命的全部领导权，中国革</span><span class=\"bl\" style=\"left:522px;top:638px;font-size:14.4px;max-width:189px\">已的周围。民族资产阶级深受帝国主义和</span><span class=\"bl\" style=\"left:67px;top:662px;font-size:13.9px;max-width:141px\">命的胜利才有完全的保障。</span><span class=\"bl\" style=\"left:523px;top:658px;font-size:12.2px;max-width:188px\">封建主义的压迫，因而能够在一定时期和</span><span class=\"bl\" style=\"left:522px;top:675px;font-size:13.9px;max-width:190px\">一定程度上参加反帝反封建的革命斗争。</span><span class=\"bl b\" style=\"left:90px;top:683px;font-size:13.9px;max-width:251px\">5.建立、巩固和发展革命统一战线的实践经验：</span><span class=\"bl\" style=\"left:523px;top:695px;font-size:12.2px;max-width:187px\">当革命的锋芒主要是反对某一个帝国主义</span><span class=\"bl\" style=\"left:90px;top:704px;font-size:13.9px;max-width:143px\">①要建立巩固的工农联盟。</span><span class=\"bl\" style=\"left:522px;top:712px;font-size:12.2px;max-width:188px\">的时候，受别的帝国主义支持的官僚资产</span><span class=\"bl\" style=\"left:90px;top:724px;font-size:14.4px;max-width:421px\">②要正确对待资产阶级，尤其是民族资产阶级。在革命斗争中要依据革命的需</span><span class=\"bl\" style=\"left:522px;top:731px;font-size:12.2px;max-width:189px\">阶级集团也可能在一定程度上和一定时期</span><span class=\"bl\" style=\"left:66px;top:745px;font-size:15.0px;max-width:447px\">要，对资产阶级实行既联合又斗争的策略。联合民族资产阶级要针对其两面性特点，</span><span class=\"bl\" style=\"left:522px;top:749px;font-size:13.9px;max-width:82px\">内参加统一战线。</span><span class=\"bl\" style=\"left:66px;top:766px;font-size:14.4px;max-width:332px\">在联合的过程中要在思想上、政治上、组织上进行必要的斗争。</span><span class=\"bl\" style=\"left:90px;top:787px;font-size:15.0px;max-width:420px\">③要采取区别对待的方针。在革命进程中，要坚持发展进步势力、争取中间势</span><span class=\"bl\" style=\"left:66px;top:809px;font-size:13.9px;max-width:166px\">力、孤立顽固势力的策略方针。</span><span class=\"bl\" style=\"left:463px;top:809px;font-size:14.4px;max-width:46px\">提示1</span><span class=\"bl\" style=\"left:523px;top:818px;font-size:15.6px;max-width:102px\">火星姐姐易错提示1</span><span class=\"bl\" style=\"left:90px;top:828px;font-size:14.4px;max-width:388px\">④要坚持独立自主的原则。要保持党在政治上、组织上和思想上的独立性。</span><span class=\"bl\" style=\"left:522px;top:842px;font-size:12.2px;max-width:189px\">1.抗日战争时期，中国共产党在同国民党</span><span class=\"bl b\" style=\"left:90px;top:849px;font-size:14.4px;max-width:262px\">6.在新民主主义革命时期，党领导的统一战线有：</span><span class=\"bl\" style=\"left:532px;top:860px;font-size:12.2px;max-width:179px\">顽固势力斗争时所遵循的原则：有理、</span><span class=\"bl\" style=\"left:90px;top:870px;font-size:15.0px;max-width:284px\">国民革命联合战线（第一次国共合作1924一1927年）</span><span class=\"bl\" style=\"left:531px;top:877px;font-size:15.6px;max-width:64px\">有利、有节。</span><span class=\"bl\" style=\"left:90px;top:891px;font-size:13.9px;max-width:295px\">工农民主统一战线（土地革命战争时期1927一1937年）</span><span class=\"bl\" style=\"left:521px;top:895px;font-size:13.9px;max-width:191px\">2.题目中出现“一切经过统一战线、一切</span><span class=\"bl\" style=\"left:89px;top:910px;font-size:15.0px;max-width:284px\">抗日民族统一战线（第二次国共合作1937一1945年）</span><span class=\"bl\" style=\"left:532px;top:914px;font-size:12.2px;max-width:179px\">服从统一战线”的观点是王明右倾投降</span><span class=\"bl\" style=\"left:89px;top:932px;font-size:13.9px;max-width:273px\">人民民主统一战线（解放战争时期1946一1949年）</span><span class=\"bl\" style=\"left:531px;top:932px;font-size:13.9px;max-width:113px\">主义的主张，是错误的。</span><span class=\"bl b\" style=\"left:65px;top:958px;font-size:15.6px;max-width:222px\">12.3武装斗争（中频选择题）（2018-11）</span><span class=\"bl\" style=\"left:89px;top:980px;font-size:16.1px;max-width:421px\">1.武装斗争是中国革命的主要斗争形式，是中国革命的特点和优点之一。革命</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1088px\"><div class=\"bxnum\">第 20 页</div><div class=\"sidebox\" style=\"left:505px;top:109px;width:194px;height:338px\"></div><span class=\"bl\" style=\"left:459px;top:59px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:56px;top:103px;font-size:15.0px;max-width:284px\">人民只有武装起来，以武装的革命反对武装的反革命。</span><span class=\"bl\" style=\"left:453px;top:104px;font-size:14.5px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:520px;top:115px;font-size:13.9px;max-width:93px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:79px;top:124px;font-size:13.9px;max-width:157px\">2.建设新型人民军队的经验：</span><span class=\"bl\" style=\"left:513px;top:137px;font-size:13.9px;max-width:189px\">与资本主义国家不同，在半殖民地半封建</span><span class=\"bl\" style=\"left:80px;top:144px;font-size:15.0px;max-width:224px\">①坚持中国共产党对人民军队的绝对领导。</span><span class=\"bl\" style=\"left:512px;top:155px;font-size:13.9px;max-width:189px\">的旧中国，无产阶级和广大人民群众无议</span><span class=\"bl\" style=\"left:80px;top:166px;font-size:13.9px;max-width:185px\">A.是建设新型人民军队的根本原则</span><span class=\"bl\" style=\"left:513px;top:174px;font-size:12.2px;max-width:188px\">会民主可以利用，无组织工人举行罢工的</span><span class=\"bl\" style=\"left:79px;top:187px;font-size:13.9px;max-width:292px\">B.是保持人民军队无产阶级性质和建军宗旨的根本前提</span><span class=\"bl\" style=\"left:512px;top:192px;font-size:13.9px;max-width:190px\">合法权利。帝国主义和封建主义总是凭</span><span class=\"bl\" style=\"left:80px;top:209px;font-size:12.2px;max-width:149px\">C.是毛泽东建军思想的核心</span><span class=\"bl\" style=\"left:511px;top:210px;font-size:13.9px;max-width:190px\">借着反革命暴力对革命人民实行残暴的</span><span class=\"bl\" style=\"left:80px;top:229px;font-size:13.9px;max-width:294px\">②要建设以全心全意为人民服务为唯一宗旨的人民军队。</span><span class=\"bl\" style=\"left:512px;top:228px;font-size:13.9px;max-width:189px\">镇压。革命人民只有武装起来，以武装</span><span class=\"bl\" style=\"left:80px;top:251px;font-size:12.2px;max-width:185px\">A.是建设新型人民军队的基本前提</span><span class=\"bl\" style=\"left:512px;top:246px;font-size:13.9px;max-width:189px\">的革命反对武装的反革命。毛泽东指出：</span><span class=\"bl\" style=\"left:512px;top:265px;font-size:12.2px;max-width:188px\">“在中国，离开了武装斗争，就没有无产</span><span class=\"bl\" style=\"left:80px;top:271px;font-size:13.9px;max-width:326px\">B.是人民军队一切行动的根本准则和一切工作的出发点与归宿</span><span class=\"bl\" style=\"left:512px;top:283px;font-size:12.2px;max-width:188px\">阶级的地位，就没有人民的地位，就没</span><span class=\"bl\" style=\"left:80px;top:291px;font-size:13.9px;max-width:161px\">C.集中体现了人民军队的本质</span><span class=\"bl\" style=\"left:513px;top:302px;font-size:12.2px;max-width:188px\">有共产党的地位，就没有革命的胜利。”</span><span class=\"bl\" style=\"left:80px;top:312px;font-size:13.9px;max-width:210px\">D.是人民军队立于不败之地的根本所在</span><span class=\"bl\" style=\"left:512px;top:319px;font-size:14.5px;max-width:189px\">中国革命的胜利，主要是依靠中国共产党</span><span class=\"bl\" style=\"left:80px;top:333px;font-size:13.9px;max-width:165px\">③要坚持正确的战略战术原则。</span><span class=\"bl\" style=\"left:512px;top:339px;font-size:12.2px;max-width:189px\">所领导的与广大人民群众血肉相连的新</span><span class=\"bl b\" style=\"left:56px;top:361px;font-size:13.9px;max-width:162px\">12.4党的建设（高频选择题）</span><span class=\"bl\" style=\"left:511px;top:356px;font-size:14.5px;max-width:190px\">型人民军队，通过长期人民战争战胜强</span><span class=\"bl\" style=\"left:511px;top:374px;font-size:14.5px;max-width:190px\">大敌人取得的。坚持武装斗争必须建立</span><span class=\"bl\" style=\"left:80px;top:382px;font-size:13.9px;max-width:420px\">中国共产党要领导革命取得胜利，必须不断加强党的思想建设、组织建设和作风</span><span class=\"bl\" style=\"left:511px;top:393px;font-size:13.9px;max-width:190px\">一支人民军队，没有一支人民的军队，便</span><span class=\"bl\" style=\"left:54px;top:402px;font-size:16.7px;max-width:40px\">建设。</span><span class=\"bl\" style=\"left:512px;top:411px;font-size:12.2px;max-width:189px\">没有人民的一切，就不可能有人民的解</span><span class=\"bl b\" style=\"left:80px;top:425px;font-size:12.2px;max-width:145px\">1.加强党的建设的必要性：</span><span class=\"bl\" style=\"left:512px;top:429px;font-size:13.9px;max-width:83px\">放和国家的独立。</span><span class=\"bl\" style=\"left:80px;top:445px;font-size:13.9px;max-width:412px\">①当时的国情使得中国共产党的成员中，农民和小资产阶级出身的党员占多数。</span><span class=\"bl\" style=\"left:80px;top:466px;font-size:13.9px;max-width:393px\">②无产阶级思想和非无产阶级思想之间的矛盾成为党内思想上的主要矛盾。</span><span class=\"bl\" style=\"left:80px;top:486px;font-size:15.6px;max-width:422px\">③党长期在农村发展，且处于战争环境之中，如果不加强党的组织建设、作风建</span><span class=\"bl\" style=\"left:56px;top:508px;font-size:13.9px;max-width:177px\">设，党就会组织松散、软弱涣散。</span><span class=\"bl b\" style=\"left:78px;top:529px;font-size:16.1px;max-width:219px\">2.党加强自身建设的经验（主要内容）：</span><span class=\"bl\" style=\"left:456px;top:529px;font-size:14.5px;max-width:43px\">提示1</span><span class=\"bl\" style=\"left:514px;top:533px;font-size:13.9px;max-width:100px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:80px;top:548px;font-size:16.1px;max-width:421px\">①必须把思想建设始终放在党的建设的首位，关键是要以无产阶级思想克服和改</span><span class=\"bl\" style=\"left:511px;top:555px;font-size:13.9px;max-width:190px\">1.新民主主义革命时期，党的思想建设放</span><span class=\"bl\" style=\"left:56px;top:570px;font-size:13.9px;max-width:131px\">造各种非无产阶级思想。</span><span class=\"bl\" style=\"left:521px;top:573px;font-size:14.5px;max-width:45px\">在首位。</span><span class=\"bl\" style=\"left:80px;top:591px;font-size:15.0px;max-width:379px\">②加强党的组织建设，根本上就是要贯彻民主集中制这一根本组织原则。</span><span class=\"bl\" style=\"left:452px;top:592px;font-size:14.5px;max-width:47px\">解读2</span><span class=\"bl\" style=\"left:511px;top:593px;font-size:12.2px;max-width:189px\">2.党的十八大以来，党的政治建设放在</span><span class=\"bl\" style=\"left:80px;top:612px;font-size:13.9px;max-width:143px\">③必须重视党的作风建设。</span><span class=\"bl\" style=\"left:521px;top:610px;font-size:15.0px;max-width:35px\">首位。</span><span class=\"bl\" style=\"left:80px;top:634px;font-size:13.9px;max-width:213px\">④必须联系党的政治路线加强党的建设。</span><span class=\"bl\" style=\"left:453px;top:633px;font-size:14.5px;max-width:46px\">解读3</span><span class=\"bl\" style=\"left:514px;top:645px;font-size:13.9px;max-width:102px\">火星姐姐考点解读2</span><span class=\"bl\" style=\"left:79px;top:654px;font-size:13.9px;max-width:164px\">3.三大优良作风（2014—12）</span><span class=\"bl\" style=\"left:513px;top:668px;font-size:12.2px;max-width:188px\">贯彻民主集中制：坚持在民主基础上的集</span><span class=\"bl\" style=\"left:80px;top:674px;font-size:15.0px;max-width:354px\">①提出：毛泽东在党的七大作的《论联合政府》的政治报告中提出。</span><span class=\"bl\" style=\"left:512px;top:686px;font-size:14.5px;max-width:189px\">中和在集中指导下的民主相结合，个人服</span><span class=\"bl\" style=\"left:80px;top:696px;font-size:13.9px;max-width:136px\">②内容：“论实联系批评”</span><span class=\"bl\" style=\"left:513px;top:704px;font-size:13.9px;max-width:189px\">从组织，少数服从多数，下级服从上级，</span><span class=\"bl\" style=\"left:80px;top:717px;font-size:13.9px;max-width:137px\">理论和实践相结合的作风</span><span class=\"bl\" style=\"left:512px;top:722px;font-size:13.9px;max-width:74px\">全党服从中央。</span><span class=\"bl\" style=\"left:80px;top:736px;font-size:13.9px;max-width:195px\">和人民群众紧密地联系在一起的作风</span><span class=\"bl\" style=\"left:80px;top:757px;font-size:14.5px;max-width:89px\">自我批评的作风</span><span class=\"bl\" style=\"left:514px;top:757px;font-size:13.9px;max-width:103px\">火星姐姐考点解读3</span><span class=\"bl\" style=\"left:80px;top:778px;font-size:15.0px;max-width:331px\">③三大优良作风是中国共产党区别于其他任何政党的显著标志。</span><span class=\"bl\" style=\"left:513px;top:780px;font-size:12.2px;max-width:188px\">党的政治路线是党的纲领在一定历史时期</span><span class=\"bl\" style=\"left:513px;top:799px;font-size:12.2px;max-width:189px\">的具体体现，是完成党在一定历史阶段的</span><span class=\"bl b\" style=\"left:56px;top:807px;font-size:13.9px;max-width:350px\">12.5统一战线、武装斗争和党的建设之间的关系（中频选择题）</span><span class=\"bl\" style=\"left:511px;top:816px;font-size:14.5px;max-width:190px\">政治任务的总政策，为全党的团结统一奠</span><span class=\"bl\" style=\"left:78px;top:827px;font-size:16.7px;max-width:421px\">1.统一战线和武装斗争是中国革命的两个基本特点，是战胜敌人的两个基本武器。</span><span class=\"bl\" style=\"left:512px;top:833px;font-size:15.0px;max-width:190px\">定政治基础。加强党的建设，必须同党的</span><span class=\"bl\" style=\"left:79px;top:847px;font-size:16.7px;max-width:393px\">2.统一战线是实行武装斗争的统一战线，武装斗争是统一战线的中心支柱。</span><span class=\"bl\" style=\"left:513px;top:853px;font-size:12.2px;max-width:188px\">政治路线紧密联系起来，在贯彻执行党的</span><span class=\"bl\" style=\"left:79px;top:869px;font-size:14.5px;max-width:422px\">3.党的建设是掌握统一战线和武装斗争这两个武器以实行对敌冲锋陷阵的英勇</span><span class=\"bl\" style=\"left:512px;top:869px;font-size:14.5px;max-width:152px\">政治纲领和路线中推进党的建设。</span><span class=\"bl\" style=\"left:55px;top:889px;font-size:16.7px;max-width:40px\">战士。</span><span class=\"bl b hl\" style=\"left:67px;top:929px;font-size:18.9px;max-width:58px\">考点13</span><span class=\"bl\" style=\"left:110px;top:928px;font-size:18.9px;max-width:310px\">新民主主义革命理论的意义☆（低频选择题）</span><span class=\"bl b\" style=\"left:80px;top:959px;font-size:14.5px;max-width:75px\">1.集中概括：</span><span class=\"bl\" style=\"left:80px;top:978px;font-size:16.7px;max-width:422px\">1949年，毛泽东在《论人民民主专政》一文中，对新民主主义革命的基本经验</span><span class=\"bl\" style=\"left:56px;top:998px;font-size:16.7px;max-width:402px\">作了集中概括，丰富和发展了马克思主义关于无产阶级领导人民革命的理论。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 21 页</div><span class=\"bl b\" style=\"left:87px;top:109px;font-size:14.4px;max-width:53px\">2.内涵：</span><span class=\"bl\" style=\"left:89px;top:129px;font-size:13.9px;max-width:420px\">新民主主义革命理论是以毛泽东为主要代表的中国共产党人，把马克思列宁主义</span><span class=\"bl\" style=\"left:65px;top:150px;font-size:14.4px;max-width:445px\">基本原理与中国革命具体实践相结合，在认真总结中国革命实践经验基础上，不断进</span><span class=\"bl\" style=\"left:65px;top:172px;font-size:12.2px;max-width:235px\">行理论创新而形成的具有独创性的革命理论。</span><span class=\"bl b\" style=\"left:88px;top:192px;font-size:13.9px;max-width:169px\">3.新民主主义革命理论的意义：</span><span class=\"bl\" style=\"left:89px;top:213px;font-size:13.9px;max-width:419px\">①解决了在一个以农民为主体的、落后的半殖民地半封建的东方大国进行革命的</span><span class=\"bl\" style=\"left:64px;top:234px;font-size:14.4px;max-width:445px\">一系列理论问题，科学地回答了近代中国革命向何处去的问题，正确地解决了中国革</span><span class=\"bl\" style=\"left:66px;top:255px;font-size:12.2px;max-width:104px\">命的发展阶段问题。</span><span class=\"bl\" style=\"left:90px;top:276px;font-size:12.2px;max-width:400px\">②马克思主义中国化的重要理论成果，开辟了马克思主义中国化的发展道路。</span><span class=\"bl\" style=\"left:89px;top:296px;font-size:13.9px;max-width:420px\">③从中国革命的具体实际出发，运用马克思主义独立自主地分析和研究中国革命</span><span class=\"bl\" style=\"left:66px;top:318px;font-size:12.2px;max-width:399px\">的实际问题，对中国革命经验的概括和总结，是中国共产党集体智慧的结晶。</span><span class=\"bl\" style=\"left:90px;top:339px;font-size:12.2px;max-width:418px\">④指导中国人民取得了新民主主义革命的胜利，建立了中华人民共和国，开创了</span><span class=\"bl\" style=\"left:65px;top:359px;font-size:13.9px;max-width:106px\">中国历史的新纪元。</span><span class=\"bl b\" style=\"left:88px;top:379px;font-size:14.4px;max-width:169px\">4.新民主主义革命胜利的意义：</span><span class=\"bl\" style=\"left:89px;top:400px;font-size:13.9px;max-width:420px\">中国新民主主义革命的伟大胜利，是20世纪继俄国十月社会主义革命以后改变</span><span class=\"bl\" style=\"left:64px;top:421px;font-size:14.4px;max-width:445px\">世界面貌的伟大历史事件，有力地鼓舞和推动了世界上被压迫民族和被压迫人民反抗</span><span class=\"bl\" style=\"left:65px;top:443px;font-size:13.9px;max-width:445px\">帝国主义、殖民主义的斗争，极大地增强了他们反对帝国主义斗争的信心，有力地支</span><span class=\"bl\" style=\"left:64px;top:462px;font-size:15.0px;max-width:390px\">持了世界人民反对帝国主义的斗争，增强了世界人民争取世界和平的力量。</span><span class=\"bl\" style=\"left:63px;top:498px;font-size:17.2px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:65px;top:524px;font-size:16.1px;max-width:445px\">1.【2012.10】毛泽东在《中国革命和中国共产党》中论述了民主革命和社会主义革</span><span class=\"bl\" style=\"left:81px;top:546px;font-size:15.0px;max-width:428px\">命的关系。他指出：“民主革命是社会主义革命的必要准备，社会主义革命是民主</span><span class=\"bl\" style=\"left:81px;top:589px;font-size:12.2px;max-width:162px\">A.资本主义道路在中国走不通</span><span class=\"bl\" style=\"left:80px;top:608px;font-size:14.4px;max-width:186px\">B.俄国十月革命为中国提供了经验</span><span class=\"bl\" style=\"left:81px;top:630px;font-size:13.9px;max-width:186px\">C.民主革命中包含了社会主义因素</span><span class=\"bl\" style=\"left:80px;top:650px;font-size:14.4px;max-width:210px\">D.中国国情决定中国革命必须分两步走</span><span class=\"bl\" style=\"left:64px;top:686px;font-size:15.6px;max-width:445px\">2.【2014.12】中共七大政治报告指出：“房子是应该经常打扫的，不打扫就会积满灰</span><span class=\"bl\" style=\"left:81px;top:707px;font-size:14.4px;max-width:428px\">尘；脸是应该经常洗的，不洗也就会灰尘满面。我们同志的思想、我们党的工作，</span><span class=\"bl\" style=\"left:81px;top:727px;font-size:15.0px;max-width:428px\">也会沾染灰尘的，也应该打扫和洗涤。”这段话形象地反映了中国共产党在长期革</span><span class=\"bl\" style=\"left:81px;top:748px;font-size:13.9px;max-width:101px\">命实践中所形成的</span><span class=\"bl\" style=\"left:80px;top:769px;font-size:13.9px;max-width:128px\">A.艰苦奋斗的优良作风</span><span class=\"bl\" style=\"left:81px;top:790px;font-size:13.9px;max-width:150px\">B.理论联系实际的优良作风</span><span class=\"bl\" style=\"left:81px;top:811px;font-size:13.9px;max-width:151px\">C.密切联系群众的优良作风</span><span class=\"bl\" style=\"left:81px;top:832px;font-size:13.9px;max-width:162px\">D.批评与自我批评的优良作风</span></div></div>"}],pages:[12,21]};
  D["mzt_s4"] = {id:"mzt_s4",ch:"毛中特讲义 · 第三章 社会主义改造理论",title:"第三章 社会主义改造理论",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 22 页</div><div class=\"sidebox\" style=\"left:506px;top:851px;width:195px;height:83px\"></div><span class=\"bl\" style=\"left:457px;top:58px;font-size:16.1px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:344px;top:109px;font-size:25.6px;max-width:65px\">第三章</span><span class=\"bl\" style=\"left:300px;top:159px;font-size:21.7px;max-width:154px\">社会主义改造理论</span><span class=\"bl\" style=\"left:53px;top:211px;font-size:18.3px;max-width:102px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:426px;top:252px;font-size:16.1px;max-width:201px\">考点14新民主主义社会的性质和特点</span><span class=\"bl\" style=\"left:200px;top:263px;font-size:13.9px;max-width:172px\">从新民主主义到社会主义的转变</span><span class=\"bl b hl\" style=\"left:426px;top:273px;font-size:13.9px;max-width:237px\">考点15党在过渡时期的总路线及其理论依据</span><span class=\"bl\" style=\"left:84px;top:303px;font-size:17.2px;max-width:58px\">社会主义</span><span class=\"bl b hl\" style=\"left:425px;top:301px;font-size:17.2px;max-width:227px\">考点16适合中国特点的社会主义改造道路</span><span class=\"bl\" style=\"left:205px;top:313px;font-size:15.6px;max-width:161px\">社会主义改造道路和历史经验</span><span class=\"bl\" style=\"left:84px;top:323px;font-size:17.2px;max-width:58px\">改造理论</span><span class=\"bl b hl\" style=\"left:426px;top:322px;font-size:16.1px;max-width:179px\">考点17社会主义改造的历史经验</span><span class=\"bl b hl\" style=\"left:426px;top:352px;font-size:13.9px;max-width:249px\">考点18社会主义基本制度的确立及其理论依据</span><span class=\"bl\" style=\"left:200px;top:363px;font-size:13.9px;max-width:172px\">社会主义基本制度在中国的确立</span><span class=\"bl b hl\" style=\"left:426px;top:372px;font-size:15.6px;max-width:225px\">考点19确立社会主义基本制度的重大意义</span><span class=\"bl\" style=\"left:52px;top:423px;font-size:19.4px;max-width:103px\">■考点考情分析</span><span class=\"bl\" style=\"left:79px;top:450px;font-size:17.8px;max-width:623px\">本章主要论述了我国的社会主义改造。本章是本门科目中考频较高的章节，考试形式一般为选择题。考生在复习过程</span><span class=\"bl\" style=\"left:55px;top:471px;font-size:17.8px;max-width:646px\">中，要重点掌握党在过渡时期的总路线、中国的农业、手工业和资本主义工商业的社会主义改造、我国确立社会主义基本制</span><span class=\"bl\" style=\"left:51px;top:488px;font-size:33.9px;max-width:426px\">度的重大意义等内容.么众亏：dJky66</span><span class=\"bl b hl\" style=\"left:66px;top:548px;font-size:17.8px;max-width:299px\">考点14新民主主义社会的性质和特点众</span><span class=\"bl\" style=\"left:660px;top:548px;font-size:14.4px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:55px;top:583px;font-size:17.2px;max-width:239px\">14.1新民主主义社会的性质（高频选择题）</span><span class=\"bl\" style=\"left:79px;top:603px;font-size:18.3px;max-width:380px\">新民主主义社会：是由新民主主义向社会主义转变的过渡性的社会形态。</span><span class=\"bl b\" style=\"left:79px;top:623px;font-size:17.2px;max-width:423px\">1.新民主主义到社会主义过渡的时期：新中国的成立，标志着我国新民主主义</span><span class=\"bl\" style=\"left:56px;top:643px;font-size:15.6px;max-width:445px\">革命阶段的基本结束和社会主义革命阶段的开始。从中华人民共和国成立到社会主义</span><span class=\"bl\" style=\"left:56px;top:664px;font-size:16.1px;max-width:86px\">改造基本完成。</span><span class=\"bl\" style=\"left:78px;top:682px;font-size:17.8px;max-width:424px\">2.这一过渡时期我国社会的性质是新民主主义社会，新民主主义社会不是一个</span><span class=\"bl\" style=\"left:56px;top:702px;font-size:17.8px;max-width:369px\">独立的社会形态，而是由新民主主义转变到社会主义的过渡性的社会。</span><span class=\"bl b\" style=\"left:55px;top:729px;font-size:17.8px;max-width:318px\">14.2新民主主义社会的经济成分（高频选择题）（2017-5）</span><span class=\"bl b\" style=\"left:79px;top:750px;font-size:16.1px;max-width:204px\">1.新民主主义社会中的五种经济成分：</span><span class=\"bl\" style=\"left:78px;top:769px;font-size:17.2px;max-width:234px\">（1）社会主义性质的国营经济—领导地位</span><span class=\"bl\" style=\"left:80px;top:789px;font-size:17.8px;max-width:391px\">通过没收官僚资本形成的国营经济，掌握了主要经济命脉，居于领导地位。</span><span class=\"bl\" style=\"left:79px;top:810px;font-size:16.1px;max-width:187px\">（2）半社会主义性质的合作社经济</span><span class=\"bl\" style=\"left:81px;top:828px;font-size:17.8px;max-width:225px\">个体经济向社会主义集体经济过渡的形式。</span><span class=\"bl\" style=\"left:79px;top:848px;font-size:18.3px;max-width:312px\">（3）农民和手工业者的个体经济一占绝对优势（体量大）</span><span class=\"bl\" style=\"left:455px;top:849px;font-size:14.4px;max-width:46px\">&gt;提示1</span><span class=\"bl\" style=\"left:514px;top:857px;font-size:13.9px;max-width:104px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:81px;top:867px;font-size:18.3px;max-width:418px\">十字路口的经济，它既可以被引导着走向社会主义，也可以自发地走向资本主义。</span><span class=\"bl\" style=\"left:513px;top:878px;font-size:15.6px;max-width:189px\">1.新民主主义社会，个体经济占绝对优势。</span><span class=\"bl\" style=\"left:79px;top:889px;font-size:15.6px;max-width:129px\">（4）国家资本主义经济</span><span class=\"bl\" style=\"left:512px;top:895px;font-size:15.6px;max-width:191px\">2.社会主义社会，社会主义经济成分占绝</span><span class=\"bl\" style=\"left:80px;top:907px;font-size:17.2px;max-width:272px\">私人资本主义经济向社会主义国营经济过渡的形式。</span><span class=\"bl\" style=\"left:523px;top:915px;font-size:15.0px;max-width:44px\">对优势。</span><span class=\"bl\" style=\"left:79px;top:928px;font-size:15.6px;max-width:129px\">（5）私人资本主义经济</span><span class=\"bl b\" style=\"left:80px;top:947px;font-size:17.2px;max-width:299px\">2.新民主主义社会中三种主要的经济成分及其代表阶级：</span><span class=\"bl\" style=\"left:81px;top:966px;font-size:17.8px;max-width:156px\">①社会主义经济：工人阶级；</span><span class=\"bl\" style=\"left:83px;top:988px;font-size:13.9px;max-width:165px\">②个体经济：农业和手工业者；</span><span class=\"bl\" style=\"left:81px;top:1007px;font-size:15.6px;max-width:155px\">③资本主义经济：资产阶级。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 23 页</div><div class=\"sidebox\" style=\"left:513px;top:630px;width:196px;height:395px\"></div><span class=\"bl b\" style=\"left:67px;top:107px;font-size:13.9px;max-width:321px\">14.3新民主主义社会的阶级构成（中频选择题）（2012-21）</span><span class=\"bl b\" style=\"left:91px;top:128px;font-size:13.9px;max-width:367px\">1.阶级构成：工人阶级、农民阶级、其他小资产阶级、民族资产阶级。</span><span class=\"bl b\" style=\"left:90px;top:148px;font-size:15.0px;max-width:422px\">2.土改完成后的社会主要矛盾：工人阶级与资产阶级、资本主义和社会主义两</span><span class=\"bl\" style=\"left:68px;top:171px;font-size:12.2px;max-width:83px\">条道路的矛盾。</span><span class=\"bl b\" style=\"left:66px;top:197px;font-size:14.4px;max-width:239px\">14.4新民主主义社会的前途（中频选择题）</span><span class=\"bl\" style=\"left:90px;top:218px;font-size:15.0px;max-width:420px\">1.在我国新民主主义社会中，社会主义的因素不论在经济上还是在政治上都已</span><span class=\"bl\" style=\"left:67px;top:241px;font-size:12.2px;max-width:94px\">经居于领导地位。</span><span class=\"bl\" style=\"left:89px;top:260px;font-size:15.0px;max-width:423px\">2.由于社会主义的因素和领导地位，加上当时有利于发展社会主义的国际条件，</span><span class=\"bl\" style=\"left:66px;top:281px;font-size:15.0px;max-width:445px\">决定了社会主义因素将不断增长并获得最终胜利，非社会主义因素将不断受到限制和</span><span class=\"bl\" style=\"left:66px;top:302px;font-size:15.0px;max-width:272px\">改造，新民主主义社会将逐步过渡到社会主义社会。</span><span class=\"bl b hl\" style=\"left:78px;top:341px;font-size:18.3px;max-width:343px\">考点15党在过渡时期的总路线及其理论依据 ☆☆☆</span><span class=\"bl b\" style=\"left:65px;top:378px;font-size:14.4px;max-width:276px\">15.1党在过渡时期的总路线的探索（中频选择题）</span><span class=\"bl\" style=\"left:89px;top:398px;font-size:15.6px;max-width:422px\">1.新中国成立前，毛泽东曾提出在新民主主义革命取得全国胜利以后，大约还</span><span class=\"bl\" style=\"left:66px;top:419px;font-size:14.4px;max-width:274px\">需要10年、15年或20年再向社会主义过渡的设想。</span><span class=\"bl b\" style=\"left:89px;top:441px;font-size:14.4px;max-width:248px\">2.1951年前后，“先搞工业化建设再一举过渡”</span><span class=\"bl\" style=\"left:89px;top:459px;font-size:17.8px;max-width:62px\">理论设想：</span><span class=\"bl\" style=\"left:89px;top:481px;font-size:18.3px;max-width:422px\">①在过渡的时间上，认为需要一个相当长的新民主主义建设阶段，一般估计为</span><span class=\"bl\" style=\"left:66px;top:503px;font-size:13.9px;max-width:104px\">15年到20年时间；</span><span class=\"bl\" style=\"left:90px;top:523px;font-size:15.6px;max-width:421px\">②在转变条件上，认为只有实现了国家工业化，才能实现私营工业国有化和农</span><span class=\"bl\" style=\"left:66px;top:544px;font-size:16.1px;max-width:73px\">业集体化；</span><span class=\"bl\" style=\"left:89px;top:565px;font-size:16.1px;max-width:421px\">③在过渡的步骤和方式上，认为当工业发展了、国营经济壮大了的时候，就可以</span><span class=\"bl\" style=\"left:65px;top:586px;font-size:14.4px;max-width:307px\">进一步实行资本主义工商业的国有化和个体农业的集体化。</span><span class=\"bl\" style=\"left:90px;top:607px;font-size:15.0px;max-width:354px\">实践操作：从1949年至1952年，实际上开始了向社会主义的过渡：</span><span class=\"bl\" style=\"left:90px;top:628px;font-size:15.0px;max-width:260px\">①没收官僚资本，建立社会主义性质的国营经济；</span><span class=\"bl\" style=\"left:522px;top:636px;font-size:15.6px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:89px;top:648px;font-size:16.1px;max-width:295px\">②在完成土地改革以后的农村及时地开展互助合作运动；</span><span class=\"bl\" style=\"left:521px;top:659px;font-size:14.4px;max-width:182px\">1952年后，关于总路线认识变化的原因：</span><span class=\"bl\" style=\"left:89px;top:669px;font-size:16.1px;max-width:420px\">③在调整工商业过程中，采取对私营工商业加工订货、经销代销等方式，广泛发</span><span class=\"bl\" style=\"left:521px;top:678px;font-size:14.4px;max-width:190px\">1.随着民主革命遗留任务的彻底完成，</span><span class=\"bl\" style=\"left:65px;top:690px;font-size:15.6px;max-width:354px\">展初级形式的国家资本主义等，为全面向社会主义过渡奠定了基础。</span><span class=\"bl\" style=\"left:532px;top:697px;font-size:12.2px;max-width:179px\">国内的阶级关系和主要矛盾发生了深刻</span><span class=\"bl\" style=\"left:88px;top:710px;font-size:16.1px;max-width:422px\">3.到1952年，民主革命的遗留任务已经完成，政治、经济及社会面貌发生了</span><span class=\"bl\" style=\"left:531px;top:714px;font-size:14.4px;max-width:34px\">变化；</span><span class=\"bl\" style=\"left:65px;top:732px;font-size:15.6px;max-width:443px\">巨大变化。开始向社会主义过渡的时机已经到来。建设和改造同时并举，逐步过渡。</span><span class=\"bl\" style=\"left:519px;top:732px;font-size:14.4px;max-width:191px\">2.随着国民经济的恢复和初步发展，中国</span><span class=\"bl\" style=\"left:461px;top:755px;font-size:15.0px;max-width:48px\">提示1</span><span class=\"bl\" style=\"left:530px;top:750px;font-size:14.4px;max-width:152px\">社会的生产关系发生了重要变化；</span><span class=\"bl\" style=\"left:519px;top:768px;font-size:14.4px;max-width:191px\">3.要把中国从落后农业国变为先进工业</span><span class=\"bl b\" style=\"left:64px;top:780px;font-size:15.6px;max-width:337px\">15.2党在过渡时期的总路线的正式提出和内容（高频选择题）</span><span class=\"bl\" style=\"left:530px;top:787px;font-size:14.4px;max-width:131px\">国，必须实现国家的工业化。</span><span class=\"bl b\" style=\"left:88px;top:802px;font-size:16.1px;max-width:418px\">1.过渡时期总路线的提出：1953年6月，毛泽东在中央政治局会议上正式提出。</span><span class=\"bl\" style=\"left:88px;top:823px;font-size:17.2px;max-width:117px\">2.总路线的主要内容</span><span class=\"bl\" style=\"left:460px;top:825px;font-size:15.0px;max-width:49px\">&gt;补充1</span><span class=\"bl\" style=\"left:522px;top:822px;font-size:15.6px;max-width:103px\">掌火星姐姐背景补充1</span><span class=\"bl\" style=\"left:89px;top:844px;font-size:13.9px;max-width:177px\">①总路线的主要内容：一化三改。</span><span class=\"bl\" style=\"left:521px;top:844px;font-size:14.4px;max-width:189px\">1953年6月，毛泽东在中央政治局会议</span><span class=\"bl\" style=\"left:88px;top:863px;font-size:15.6px;max-width:127px\">一化：社会主义工业化</span><span class=\"bl\" style=\"left:520px;top:862px;font-size:15.0px;max-width:190px\">上正式提出了过渡时期的总路线和总任</span><span class=\"bl\" style=\"left:89px;top:884px;font-size:17.2px;max-width:336px\">三改：对个体农业、手工业和对资本主义工商业的社会主义改造</span><span class=\"bl\" style=\"left:521px;top:882px;font-size:13.3px;max-width:189px\">务，同年12月形成关于总路线的完整的</span><span class=\"bl\" style=\"left:87px;top:903px;font-size:18.3px;max-width:262px\">②“一化三改”的关系：是“一体两翼”的关系，</span><span class=\"bl\" style=\"left:520px;top:899px;font-size:15.0px;max-width:190px\">表述：“从中华人民共和国成立，到社会</span><span class=\"bl\" style=\"left:520px;top:917px;font-size:15.0px;max-width:190px\">主义改造基本完成，这是一个过渡时期。</span><span class=\"bl\" style=\"left:88px;top:924px;font-size:18.9px;max-width:244px\">“一化”是社会主义工业化，如鸟之“主体”，</span><span class=\"bl\" style=\"left:520px;top:935px;font-size:14.4px;max-width:189px\">党在这个过渡时期的总路线和总任务，是</span><span class=\"bl\" style=\"left:88px;top:945px;font-size:18.9px;max-width:421px\">“三改”是对个体农业、手工业和对资本主义工商业的社会主义改造，如鸟之</span><span class=\"bl\" style=\"left:519px;top:953px;font-size:14.4px;max-width:190px\">要在一个相当长的时期内，逐步实现国家</span><span class=\"bl\" style=\"left:66px;top:967px;font-size:15.6px;max-width:190px\">“两翼”。二者相互促进，相辅相成。</span><span class=\"bl\" style=\"left:519px;top:972px;font-size:15.0px;max-width:190px\">的社会主义工业化，并逐步实现国家对农</span><span class=\"bl\" style=\"left:519px;top:990px;font-size:14.4px;max-width:190px\">业、对手工业和对资本主义工商业的社会</span><span class=\"bl\" style=\"left:520px;top:1009px;font-size:12.8px;max-width:59px\">主义改造。”</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 24 页</div><div class=\"sidebox\" style=\"left:507px;top:143px;width:196px;height:522px\"></div><span class=\"bl\" style=\"left:459px;top:59px;font-size:14.5px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:81px;top:107px;font-size:12.2px;max-width:142px\">③过渡时期总路线体现了：</span><span class=\"bl\" style=\"left:80px;top:127px;font-size:14.5px;max-width:222px\">A.社会主义建设和社会主义改造同时并举</span><span class=\"bl\" style=\"left:80px;top:148px;font-size:14.5px;max-width:232px\">B.社会主义工业化和社会主义改造紧密结合</span><span class=\"bl\" style=\"left:515px;top:149px;font-size:13.9px;max-width:102px\">火星姐姐背景补充1</span><span class=\"bl\" style=\"left:80px;top:169px;font-size:14.5px;max-width:212px\">C.解放生产力与发展生产力的有机统一</span><span class=\"bl\" style=\"left:513px;top:172px;font-size:14.5px;max-width:189px\">马、恩认为，从资本主义社会到社会主</span><span class=\"bl\" style=\"left:81px;top:191px;font-size:12.2px;max-width:221px\">D.变革生产关系和发展生产力的有机统一</span><span class=\"bl\" style=\"left:514px;top:190px;font-size:14.5px;max-width:189px\">义社会，需要经历一个从无产阶级夺取</span><span class=\"bl\" style=\"left:514px;top:209px;font-size:12.2px;max-width:188px\">政权到利用国家政权对旧的生产关系进</span><span class=\"bl b\" style=\"left:57px;top:218px;font-size:12.2px;max-width:296px\">15.3党在过渡时期的总路线的理论依据（中频选择题）</span><span class=\"bl\" style=\"left:514px;top:227px;font-size:12.2px;max-width:189px\">行革命性的改造，逐步消灭私有制、确</span><span class=\"bl b\" style=\"left:81px;top:240px;font-size:12.2px;max-width:74px\">1.理论依据：</span><span class=\"bl\" style=\"left:515px;top:246px;font-size:12.2px;max-width:188px\">立公有制并大力发展生产力的过渡时期，</span><span class=\"bl\" style=\"left:81px;top:261px;font-size:14.5px;max-width:356px\">①马克思、恩格斯关于从资本主义社会向社会主义社会过渡的理论。</span><span class=\"bl\" style=\"left:454px;top:259px;font-size:14.5px;max-width:47px\">&gt;补充1</span><span class=\"bl\" style=\"left:514px;top:264px;font-size:12.2px;max-width:188px\">这是一切走向共产主义的国家不可逾越</span><span class=\"bl\" style=\"left:81px;top:279px;font-size:15.6px;max-width:421px\">②列宁在十月革命后提出的必须经过一个相当长的从资本主义到社会主义的过渡</span><span class=\"bl\" style=\"left:513px;top:282px;font-size:13.9px;max-width:65px\">的发展阶段。</span><span class=\"bl\" style=\"left:58px;top:304px;font-size:12.2px;max-width:212px\">时期，俄国才能过渡到社会主义的思想。</span><span class=\"bl\" style=\"left:454px;top:302px;font-size:15.0px;max-width:48px\">&gt;补充2</span><span class=\"bl\" style=\"left:514px;top:316px;font-size:15.6px;max-width:105px\">火星姐姐背景补充2</span><span class=\"bl b\" style=\"left:81px;top:324px;font-size:12.2px;max-width:180px\">2.中国化的过渡时期理论的原因：</span><span class=\"bl\" style=\"left:81px;top:342px;font-size:15.6px;max-width:421px\">①我国经济和文化落后，需要一个相当长的时期来创造为保证社会主义完全胜利</span><span class=\"bl\" style=\"left:515px;top:341px;font-size:12.2px;max-width:188px\">列宁认为，落后国家在先进国家无产阶</span><span class=\"bl\" style=\"left:515px;top:358px;font-size:12.2px;max-width:188px\">级的帮助下，“可以不经过资本主义发展</span><span class=\"bl\" style=\"left:59px;top:366px;font-size:12.2px;max-width:176px\">所必要的经济上和文化上的前提。</span><span class=\"bl\" style=\"left:513px;top:375px;font-size:14.5px;max-width:191px\">阶段而过渡到苏维埃制度，然后经过一</span><span class=\"bl\" style=\"left:82px;top:384px;font-size:15.6px;max-width:414px\">②我国广大的个体农业、手工业以及资本主义工商业需要相当长的时期的改造。</span><span class=\"bl\" style=\"left:515px;top:394px;font-size:12.2px;max-width:188px\">定的发展阶段过渡到共产主义”。列宁还</span><span class=\"bl\" style=\"left:514px;top:412px;font-size:13.3px;max-width:190px\">认为，改变资产阶级和小资产阶级的经</span><span class=\"bl b hl\" style=\"left:69px;top:426px;font-size:15.6px;max-width:328px\">考点16适合中国特点的社会主义改造道路 ☆☆☆</span><span class=\"bl\" style=\"left:515px;top:431px;font-size:12.2px;max-width:189px\">营方式和习惯势力是一件极其困难的事</span><span class=\"bl\" style=\"left:514px;top:448px;font-size:15.0px;max-width:189px\">情，必须经过一个相当长的从资本主义</span><span class=\"bl b\" style=\"left:58px;top:462px;font-size:13.9px;max-width:284px\">16.1农业的社会主义改造（高频选择题）（2011-29）</span><span class=\"bl\" style=\"left:515px;top:468px;font-size:12.2px;max-width:189px\">到社会主义的过渡时期。过渡时期的根</span><span class=\"bl\" style=\"left:81px;top:483px;font-size:13.9px;max-width:250px\">1.积极引导农民组织起来，走互助合作的道路。</span><span class=\"bl\" style=\"left:515px;top:486px;font-size:12.2px;max-width:188px\">本任务是把剥削阶级的生产资料转化为</span><span class=\"bl\" style=\"left:81px;top:502px;font-size:14.5px;max-width:422px\">土地改革后，我国农民从封建剥削制度下解放出来，生产积极性得到提高。这种</span><span class=\"bl\" style=\"left:515px;top:504px;font-size:12.2px;max-width:188px\">公有财产，同时，通过合作社的形式使</span><span class=\"bl\" style=\"left:59px;top:523px;font-size:15.0px;max-width:320px\">积极性表现在：①个体经济的积极性；②互助合作的积极性。</span><span class=\"bl\" style=\"left:515px;top:521px;font-size:14.5px;max-width:189px\">农民走上集体化道路，并把创造高于资</span><span class=\"bl\" style=\"left:81px;top:543px;font-size:16.1px;max-width:422px\">2.遵循自愿互利、典型示范和国家帮助的原则，以互助合作的优越性吸引农民</span><span class=\"bl\" style=\"left:514px;top:540px;font-size:13.3px;max-width:190px\">本主义劳动生产率的根本任务提到首位，</span><span class=\"bl\" style=\"left:515px;top:557px;font-size:14.5px;max-width:191px\">以建立和发展社会主义的经济基础。俄</span><span class=\"bl\" style=\"left:515px;top:575px;font-size:14.5px;max-width:190px\">国十月革命胜利后，列宁也曾设想通过</span><span class=\"bl\" style=\"left:83px;top:586px;font-size:15.0px;max-width:331px\">①农民既是私有者又是劳动者；②对农民不能采取剥夺的方法；</span><span class=\"bl\" style=\"left:515px;top:594px;font-size:15.0px;max-width:190px\">国家资本主义对资产阶级进行和平买，</span><span class=\"bl\" style=\"left:83px;top:607px;font-size:15.0px;max-width:331px\">③对农民只能引导、说服和教育；④使农民自愿走合作化道路。</span><span class=\"bl\" style=\"left:515px;top:612px;font-size:15.0px;max-width:191px\">认为这对无产阶级是最有利的事情。但</span><span class=\"bl\" style=\"left:81px;top:627px;font-size:15.6px;max-width:310px\">3.正确分析农村的阶级和阶层状况，制定正确的阶级政策。</span><span class=\"bl\" style=\"left:516px;top:630px;font-size:15.0px;max-width:188px\">由于后来俄国资产阶级选择了国内战争的</span><span class=\"bl\" style=\"left:83px;top:647px;font-size:17.2px;max-width:442px\">根据土改后农村的新情况，党制定并贯彻执行了依靠贫下中农，团结其他中农，</span><span class=\"bl\" style=\"left:514px;top:649px;font-size:12.2px;max-width:155px\">反抗方式，列宁的设想未能实现。</span><span class=\"bl\" style=\"left:59px;top:670px;font-size:14.5px;max-width:273px\">发展互助合作，由逐步限制到最后消灭富农的政策。</span><span class=\"bl\" style=\"left:81px;top:690px;font-size:15.0px;max-width:311px\">4.坚持积极领导、稳步前进的方针，采取循序渐进的步骤。</span><span class=\"bl\" style=\"left:84px;top:712px;font-size:14.5px;max-width:222px\">①农业生产互助组（社会主义萌芽性质）：</span><span class=\"bl\" style=\"left:83px;top:731px;font-size:16.1px;max-width:417px\">土地耕畜和其他生产资料仍归农民个人所有，但在生产方面组织起来、互帮互助。</span><span class=\"bl\" style=\"left:84px;top:754px;font-size:14.5px;max-width:234px\">②初级农业生产合作社（半社会主义性质）：</span><span class=\"bl\" style=\"left:83px;top:774px;font-size:15.0px;max-width:237px\">集体劳动，按劳分配，土地入股分红相结合。</span><span class=\"bl\" style=\"left:84px;top:795px;font-size:14.5px;max-width:222px\">③高级农业生产合作社（社会主义性质）：</span><span class=\"bl\" style=\"left:83px;top:816px;font-size:14.5px;max-width:273px\">生产资料农民集体所有，按劳付酬，取消土地分红。</span><span class=\"bl b\" style=\"left:60px;top:844px;font-size:14.5px;max-width:239px\">16.2手工业的社会主义改造（中频选择题）</span><span class=\"bl b\" style=\"left:83px;top:864px;font-size:15.0px;max-width:227px\">1.改造采取的方针：积极领导、稳步前进。</span><span class=\"bl b\" style=\"left:83px;top:885px;font-size:15.6px;max-width:264px\">2.改造的实施方法：说服教育、示范和国家帮助。</span><span class=\"bl b\" style=\"left:83px;top:906px;font-size:14.5px;max-width:217px\">3.手工业社会主义改造的三个发展阶段：</span><span class=\"bl\" style=\"left:84px;top:927px;font-size:15.0px;max-width:222px\">①手工业供销小组（社会主义萌芽性质）：</span><span class=\"bl\" style=\"left:84px;top:946px;font-size:16.1px;max-width:389px\">把个体手工业者组织起来，由国营商业或供销合作社供给原料和包销产品。</span><span class=\"bl\" style=\"left:84px;top:968px;font-size:14.5px;max-width:223px\">②手工业供销合作社（半社会主义性质）：</span><span class=\"bl\" style=\"left:84px;top:987px;font-size:17.8px;max-width:422px\">由供销小组合并起来，开始是统一供销业务，分别核算，生产活动仍由各户分散</span><span class=\"bl\" style=\"left:61px;top:1008px;font-size:18.3px;max-width:443px\">独立完成；后来逐步有部分生产资料是公有的，合作社对各户的生产也有一定的干预。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1091px\"><div class=\"bxnum\">第 25 页</div><div class=\"sidebox\" style=\"left:512px;top:526px;width:195px;height:305px\"></div><span class=\"bl\" style=\"left:89px;top:105px;font-size:14.4px;max-width:292px\">③手工业生产合作社（社会主义性质的集体经济组织）：</span><span class=\"bl\" style=\"left:89px;top:125px;font-size:15.5px;max-width:420px\">手工业者的生产资料全部归集体所有，统一经营，人社人员参加集体劳动，实行</span><span class=\"bl\" style=\"left:64px;top:146px;font-size:14.4px;max-width:61px\">按劳分配。</span><span class=\"bl b\" style=\"left:64px;top:173px;font-size:15.0px;max-width:288px\">16.3资本主义工商业的社会主义改造（中频选择题）</span><span class=\"bl\" style=\"left:88px;top:195px;font-size:15.0px;max-width:299px\">1.用和平赎买的方法改造资本主义工商业。（2021一12）</span><span class=\"bl\" style=\"left:88px;top:216px;font-size:15.5px;max-width:421px\">①赎买的含义：国家有偿地将私营企业变为国营企业，将资本主义私有制改变为</span><span class=\"bl\" style=\"left:65px;top:236px;font-size:13.9px;max-width:96px\">社会主义公有制。</span><span class=\"bl\" style=\"left:88px;top:257px;font-size:16.1px;max-width:421px\">②赎买的具体方式：不是由国家支付一笔巨额补偿资金，而是资本家从企业经营</span><span class=\"bl\" style=\"left:64px;top:277px;font-size:15.0px;max-width:131px\">所得中获取一部分利润。</span><span class=\"bl\" style=\"left:88px;top:299px;font-size:15.0px;max-width:166px\">③实行和平赎买的现实可能性：</span><span class=\"bl\" style=\"left:88px;top:320px;font-size:16.1px;max-width:420px\">第一，民族资产阶级具有两面性。在社会主义革命阶段，民族资产阶级既有剥削</span><span class=\"bl\" style=\"left:65px;top:340px;font-size:15.5px;max-width:365px\">工人取得利润的一面，又有拥护宪法、愿意接受社会主义改造的一面。</span><span class=\"bl\" style=\"left:88px;top:361px;font-size:16.1px;max-width:420px\">第二，中国共产党与民族资产阶级长期保持着统一战线的关系。这就为将工人阶</span><span class=\"bl\" style=\"left:64px;top:381px;font-size:16.1px;max-width:444px\">级同民族资产阶级之间的对抗性的矛盾转化为非对抗性的矛盾并按照人民内部矛盾来</span><span class=\"bl\" style=\"left:64px;top:402px;font-size:15.5px;max-width:95px\">处理提供了前提。</span><span class=\"bl\" style=\"left:87px;top:422px;font-size:18.3px;max-width:421px\">第三，我国已经有了以工人阶级为领导、工农联盟为基础的人民民主专政的国家</span><span class=\"bl\" style=\"left:63px;top:444px;font-size:16.1px;max-width:445px\">政权，建立了强大的社会主义国营经济并掌握了国家的经济命脉。这就造成了私人资</span><span class=\"bl\" style=\"left:63px;top:465px;font-size:15.5px;max-width:237px\">本主义在政治上、经济上对社会主义的依赖。</span><span class=\"bl\" style=\"left:82px;top:487px;font-size:14.4px;max-width:268px\">2.采取从低级到高级的国家资本主义的过渡形式。</span><span class=\"bl\" style=\"left:86px;top:506px;font-size:19.4px;max-width:344px\">①国家资本主义含义：在国家直接控制和支配下的资本主义经济。</span><span class=\"bl\" style=\"left:459px;top:510px;font-size:14.4px;max-width:48px\">&gt;解读1</span><span class=\"bl\" style=\"left:88px;top:529px;font-size:13.9px;max-width:132px\">②国家资本主义的形式：</span><span class=\"bl\" style=\"left:521px;top:532px;font-size:13.9px;max-width:102px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:87px;top:549px;font-size:16.1px;max-width:335px\">第一，初级形式：委托加工、计划订货、统购包销、经销代销。</span><span class=\"bl\" style=\"left:460px;top:552px;font-size:12.8px;max-width:46px\">&gt;提示1</span><span class=\"bl\" style=\"left:520px;top:554px;font-size:14.4px;max-width:113px\">如何理解国家资本主义：</span><span class=\"bl\" style=\"left:87px;top:569px;font-size:16.1px;max-width:420px\">四马分肥：企业的利润，按国家所得税、企业公积金、工人福利费、资方红利四</span><span class=\"bl\" style=\"left:519px;top:573px;font-size:14.4px;max-width:190px\">是在人民政府管理之下的，用各种形式</span><span class=\"bl\" style=\"left:63px;top:590px;font-size:15.0px;max-width:95px\">个方面进行分配。</span><span class=\"bl\" style=\"left:520px;top:592px;font-size:12.2px;max-width:187px\">和国营社会主义经济联系着的，并受工人</span><span class=\"bl\" style=\"left:87px;top:611px;font-size:13.9px;max-width:148px\">第二，高级形式：公私合营</span><span class=\"bl\" style=\"left:519px;top:609px;font-size:14.4px;max-width:190px\">监督的资本主义经济。已经不是普通的</span><span class=\"bl\" style=\"left:86px;top:631px;font-size:17.2px;max-width:130px\">A.个别企业的公私合营</span><span class=\"bl\" style=\"left:519px;top:628px;font-size:14.4px;max-width:189px\">资本主义经济，而是一种特殊的资本主</span><span class=\"bl\" style=\"left:520px;top:646px;font-size:14.4px;max-width:189px\">义经济，即新式的国家资本主义经济。主</span><span class=\"bl\" style=\"left:86px;top:653px;font-size:13.9px;max-width:116px\">B.全行业的公私合营</span><span class=\"bl\" style=\"left:519px;top:664px;font-size:14.4px;max-width:189px\">要地不是为了资本家的利润而存在，而是</span><span class=\"bl\" style=\"left:86px;top:673px;font-size:15.0px;max-width:225px\">3.对资本主义工商业的社会主义改造步骤。</span><span class=\"bl\" style=\"left:520px;top:684px;font-size:12.2px;max-width:188px\">为了供应人民和国家的需要而存在。带着</span><span class=\"bl\" style=\"left:86px;top:694px;font-size:16.1px;max-width:269px\">①实行初级形式的国家资本主义（社会主义因素）：</span><span class=\"bl\" style=\"left:519px;top:701px;font-size:14.4px;max-width:190px\">很大的社会主义性质的，是对工人和国</span><span class=\"bl\" style=\"left:86px;top:715px;font-size:15.0px;max-width:272px\">在私营工业中实行委托加工、计划订货、统购包销。</span><span class=\"bl\" style=\"left:519px;top:719px;font-size:14.4px;max-width:53px\">家有利的。</span><span class=\"bl\" style=\"left:86px;top:735px;font-size:15.5px;max-width:225px\">在私营商业中采取委托经销、代销等形式。</span><span class=\"bl\" style=\"left:86px;top:756px;font-size:16.1px;max-width:420px\">利润按国家所得税、企业公积金、工人福利费、资方红利四个方面进行分配（四马</span><span class=\"bl\" style=\"left:520px;top:753px;font-size:16.1px;max-width:102px\">火星姐姐易错提示1</span><span class=\"bl\" style=\"left:62px;top:777px;font-size:14.4px;max-width:44px\">分肥）。</span><span class=\"bl\" style=\"left:518px;top:776px;font-size:13.3px;max-width:189px\">统购统销（即计划收购和计划供应）是我</span><span class=\"bl\" style=\"left:86px;top:798px;font-size:15.5px;max-width:257px\">②实行个别企业的公私合营（半社会主义性质）：</span><span class=\"bl\" style=\"left:519px;top:795px;font-size:13.3px;max-width:189px\">国工业化初创阶段采取的一项重大决策，</span><span class=\"bl\" style=\"left:518px;top:813px;font-size:14.4px;max-width:114px\">与统购包销不是一回事。</span><span class=\"bl\" style=\"left:86px;top:819px;font-size:16.1px;max-width:353px\">企业的经营管理以发展生产、满足人民需要和完成国家计划为目标。</span><span class=\"bl\" style=\"left:85px;top:839px;font-size:16.1px;max-width:246px\">③实行全行业公私合营（社会主义国营性质）：</span><span class=\"bl\" style=\"left:85px;top:860px;font-size:17.2px;max-width:420px\">生产资料为国家所有，企业生产关系发生根本变化，基本上成为社会主义国营性</span><span class=\"bl\" style=\"left:61px;top:879px;font-size:16.1px;max-width:61px\">质的企业。</span><span class=\"bl\" style=\"left:83px;top:901px;font-size:16.1px;max-width:311px\">4.把资本主义工商业者改造成自食其力的社会主义劳动者。</span><span class=\"bl\" style=\"left:83px;top:922px;font-size:18.3px;max-width:422px\">（1）采用此方法的具体办法：国家对资方在职人员和资方代理人采取“包下来”</span><span class=\"bl\" style=\"left:61px;top:942px;font-size:18.3px;max-width:444px\">的政策，以企业为基地，采用“量才使用，适当照顾”的原则，对他们在政治上适当</span><span class=\"bl\" style=\"left:60px;top:963px;font-size:18.3px;max-width:444px\">安排、工作上发挥作用、生活上妥善照顾，通过改造阶级成分的方式达到从整体上消</span><span class=\"bl\" style=\"left:60px;top:983px;font-size:15.0px;max-width:107px\">灭资产阶级的目的。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 26 页</div><div class=\"sidebox\" style=\"left:505px;top:284px;width:197px;height:470px\"></div><span class=\"bl\" style=\"left:457px;top:61px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:77px;top:108px;font-size:13.9px;max-width:132px\">（2）采用此方法的优点：</span><span class=\"bl\" style=\"left:79px;top:128px;font-size:15.0px;max-width:331px\">①通过改造阶级成分的方式达到从整体上消灭资产阶级的目的。</span><span class=\"bl\" style=\"left:79px;top:150px;font-size:13.9px;max-width:202px\">②对企业的改造和对人的改造相结合。</span><span class=\"bl\" style=\"left:80px;top:171px;font-size:12.2px;max-width:281px\">③改造资本家个人与消灭他们所属的资产阶级相结合。</span><span class=\"bl\" style=\"left:79px;top:189px;font-size:16.1px;max-width:423px\">④既避免了激烈的阶级对抗，减少了改造的阻力，又推动了生产力的发展和社</span><span class=\"bl\" style=\"left:56px;top:212px;font-size:14.5px;max-width:61px\">会的进步。</span><span class=\"bl b hl\" style=\"left:66px;top:250px;font-size:20.0px;max-width:354px\">考点17社会主义改造的历史经验☆☆（中频选择题）</span><span class=\"bl\" style=\"left:79px;top:281px;font-size:15.0px;max-width:286px\">1.坚持社会主义工业化建设与社会主义改造同时并举。</span><span class=\"bl\" style=\"left:513px;top:290px;font-size:15.6px;max-width:102px\">火星姐姐背景补充1</span><span class=\"bl\" style=\"left:79px;top:303px;font-size:12.2px;max-width:191px\">2.采取积极引导、逐步过渡的方式。</span><span class=\"bl\" style=\"left:512px;top:312px;font-size:14.5px;max-width:189px\">1956年，我国基本上完成对生产资料私</span><span class=\"bl\" style=\"left:78px;top:321px;font-size:17.2px;max-width:135px\">3.用和平方法进行改造。</span><span class=\"bl\" style=\"left:513px;top:332px;font-size:12.2px;max-width:188px\">有制的社会主义改造，基本上实现生产资</span><span class=\"bl\" style=\"left:512px;top:350px;font-size:12.2px;max-width:189px\">料公有制和按劳分配，建立起社会主义</span><span class=\"bl b hl\" style=\"left:66px;top:360px;font-size:19.5px;max-width:434px\">考点18社会主义基本制度的确立及其理论依据☆☆☆（中频选择题）</span><span class=\"bl\" style=\"left:511px;top:368px;font-size:14.5px;max-width:55px\">经济制度。</span><span class=\"bl\" style=\"left:512px;top:386px;font-size:14.5px;max-width:190px\">党领导确立人民代表大会制度、中国共产</span><span class=\"bl\" style=\"left:79px;top:391px;font-size:15.0px;max-width:297px\">1.建立了以生产资料公有制为基础的社会主义经济制度。</span><span class=\"bl\" style=\"left:512px;top:404px;font-size:14.5px;max-width:190px\">党领导的多党合作和政治协商制度、民族</span><span class=\"bl\" style=\"left:80px;top:414px;font-size:13.9px;max-width:189px\">社会主义经济成分已经占绝对优势。</span><span class=\"bl\" style=\"left:452px;top:410px;font-size:17.8px;max-width:49px\">&gt;补充1</span><span class=\"bl\" style=\"left:512px;top:422px;font-size:14.5px;max-width:190px\">区域自治制度，为人民当家作主提供了制</span><span class=\"bl\" style=\"left:79px;top:434px;font-size:13.9px;max-width:146px\">2.政治领域发生重大变化。</span><span class=\"bl\" style=\"left:512px;top:441px;font-size:14.5px;max-width:45px\">度保证。</span><span class=\"bl\" style=\"left:80px;top:453px;font-size:17.2px;max-width:421px\">1954年第一届全国人大的召开和《中华人民共和国宪法》的制定和颁布施行，</span><span class=\"bl\" style=\"left:512px;top:458px;font-size:14.5px;max-width:189px\">党领导实现和巩固了全国各族人民的大团</span><span class=\"bl\" style=\"left:57px;top:477px;font-size:12.2px;max-width:228px\">成为我国社会主义民主政治建设的里程碑。</span><span class=\"bl\" style=\"left:453px;top:474px;font-size:14.5px;max-width:47px\">解读1</span><span class=\"bl\" style=\"left:512px;top:477px;font-size:14.5px;max-width:189px\">结，形成和发展了各民族平等互助的社会</span><span class=\"bl\" style=\"left:79px;top:496px;font-size:13.9px;max-width:147px\">3.阶级关系发生根本变化。</span><span class=\"bl\" style=\"left:513px;top:495px;font-size:14.5px;max-width:189px\">主义民族关系，实现和巩固了全国工人、</span><span class=\"bl\" style=\"left:80px;top:515px;font-size:17.2px;max-width:421px\">①帝国主义侵略势力被清除出中国大陆。②官僚资产阶级被消灭。③地主和富</span><span class=\"bl\" style=\"left:512px;top:513px;font-size:14.5px;max-width:189px\">农民、知识分子和其他各阶层人民的大团</span><span class=\"bl\" style=\"left:513px;top:532px;font-size:13.4px;max-width:153px\">结，加强和扩大了广泛统一战线。</span><span class=\"bl\" style=\"left:56px;top:536px;font-size:16.1px;max-width:444px\">农被改造成自食其力的新人。④民族资产阶级被改造成自食其力的社会主义劳动者。</span><span class=\"bl\" style=\"left:512px;top:549px;font-size:15.0px;max-width:189px\">社会主义制度的建立，为我国一切进步和</span><span class=\"bl\" style=\"left:56px;top:557px;font-size:17.8px;max-width:446px\">5工人阶级成为国家领导阶级。6农民和其他个体劳动者成为社会主义的集体劳动</span><span class=\"bl\" style=\"left:514px;top:569px;font-size:13.9px;max-width:103px\">发展奠定了重要基础。</span><span class=\"bl\" style=\"left:56px;top:579px;font-size:14.5px;max-width:247px\">者。知识界组成一支为社会主义服务的队伍。</span><span class=\"bl b\" style=\"left:80px;top:601px;font-size:13.9px;max-width:204px\">4.社会主义基本制度确立的理论根据：</span><span class=\"bl\" style=\"left:515px;top:604px;font-size:13.9px;max-width:102px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:80px;top:620px;font-size:16.1px;max-width:318px\">列宁关于经济文化比较落后的国家可以走向社会主义的理论。</span><span class=\"bl\" style=\"left:514px;top:627px;font-size:12.2px;max-width:188px\">这部宪法明确规定了我国人民民主专政的</span><span class=\"bl\" style=\"left:514px;top:644px;font-size:14.5px;max-width:188px\">国体和人民代表大会的政体。人民代表</span><span class=\"bl b hl\" style=\"left:67px;top:659px;font-size:20.0px;max-width:425px\">考点19确立社会主义基本制度的重大意义☆☆☆（中频选择题）</span><span class=\"bl\" style=\"left:513px;top:662px;font-size:15.0px;max-width:190px\">大会制度这一根本政治制度、中国共产党</span><span class=\"bl\" style=\"left:513px;top:680px;font-size:14.5px;max-width:189px\">领导的多党合作和政治协商制度、民族区</span><span class=\"bl\" style=\"left:80px;top:688px;font-size:17.2px;max-width:421px\">1.社会主义基本制度的确立，极大地提高了工人阶级和广大劳动人民的积极性</span><span class=\"bl\" style=\"left:513px;top:698px;font-size:14.5px;max-width:190px\">域自治制度这些基本政治制度的确立，表</span><span class=\"bl\" style=\"left:57px;top:710px;font-size:16.1px;max-width:445px\">和创造性，极大地促进了我国社会生产力的发展。我国工业化、现代化建设取得的辉</span><span class=\"bl\" style=\"left:514px;top:716px;font-size:14.5px;max-width:190px\">明中国由一个新民主主义的国家转变为社</span><span class=\"bl\" style=\"left:57px;top:731px;font-size:15.0px;max-width:308px\">煌成就，离不开选择了社会主义道路这个根本的前提条件。</span><span class=\"bl\" style=\"left:514px;top:736px;font-size:13.9px;max-width:64px\">会主义国家。</span><span class=\"bl\" style=\"left:80px;top:751px;font-size:17.2px;max-width:423px\">2.社会主义基本制度的确立，使广大劳动人民真正成为国家的主人。这是中国</span><span class=\"bl\" style=\"left:58px;top:772px;font-size:17.2px;max-width:445px\">几千年来阶级关系的最根本变革，极大地巩固和扩大了工人阶级领导的，以工农联盟</span><span class=\"bl\" style=\"left:455px;top:794px;font-size:14.5px;max-width:47px\">&gt;提示1</span><span class=\"bl\" style=\"left:516px;top:789px;font-size:13.9px;max-width:103px\">火星姐姐易错提示1</span><span class=\"bl\" style=\"left:57px;top:795px;font-size:15.0px;max-width:296px\">为基础的人民民主专政国家政权的阶级基础和经济基础。</span><span class=\"bl\" style=\"left:80px;top:814px;font-size:17.2px;max-width:423px\">3.社会主义基本制度的确立，使占世界人口1/4的东方大国进人了社会主义社</span><span class=\"bl\" style=\"left:514px;top:810px;font-size:15.0px;max-width:189px\">1956年，社会主义基本制度在中国确立，</span><span class=\"bl\" style=\"left:514px;top:828px;font-size:15.6px;max-width:190px\">马克思主义同中国实际的“第二次结合”</span><span class=\"bl\" style=\"left:58px;top:834px;font-size:17.2px;max-width:445px\">会，这是世界社会主义运动史上又一个历史性的伟大胜利。它进一步改变了世界政治</span><span class=\"bl\" style=\"left:515px;top:847px;font-size:13.9px;max-width:112px\">刚刚开始，并没有完成。</span><span class=\"bl\" style=\"left:57px;top:855px;font-size:16.1px;max-width:367px\">经济格局，增强了社会主义的力量，对维护世界和平产生了积极影响。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 27 页</div><span class=\"bl\" style=\"left:67px;top:105px;font-size:16.1px;max-width:98px\">经典真题回顾</span><span class=\"bl\" style=\"left:66px;top:131px;font-size:15.6px;max-width:445px\">1.【2012.21】从中华人民共和国成立到社会主义改造基本完成，是我国从新民主主</span><span class=\"bl\" style=\"left:83px;top:152px;font-size:17.8px;max-width:349px\">义到社会主义的过渡时期。这一时期中国社会的阶级构成主要包括</span><span class=\"bl\" style=\"left:82px;top:174px;font-size:14.4px;max-width:70px\">A.工人阶级</span><span class=\"bl\" style=\"left:80px;top:193px;font-size:16.1px;max-width:71px\">B.农民阶级</span><span class=\"bl\" style=\"left:82px;top:215px;font-size:14.4px;max-width:92px\">C.民族资产阶级</span><span class=\"bl\" style=\"left:81px;top:235px;font-size:15.6px;max-width:106px\">D.城市小资产阶级</span><span class=\"bl\" style=\"left:64px;top:271px;font-size:17.8px;max-width:447px\">2.【2017.5】从中华人民共和国成立到社会主义改造基本完成，是我国从新民主义到</span><span class=\"bl\" style=\"left:81px;top:292px;font-size:17.8px;max-width:430px\">社会主义的过渡时期。这一时期，个体经济向社会主义集体经济过渡的形式是</span><span class=\"bl\" style=\"left:81px;top:334px;font-size:14.4px;max-width:70px\">A.国营经济</span><span class=\"bl\" style=\"left:81px;top:355px;font-size:15.6px;max-width:117px\">B.私人资本主义经济</span><span class=\"bl\" style=\"left:81px;top:375px;font-size:16.1px;max-width:81px\">C.合作社经济</span><span class=\"bl\" style=\"left:80px;top:396px;font-size:15.6px;max-width:118px\">D.国家资本主义经济</span><span class=\"bl\" style=\"left:64px;top:431px;font-size:18.3px;max-width:446px\">3.【2010.22】1952年，党中央在配酿过渡时期总路线时，毛泽东把实现向社会主义</span><span class=\"bl\" style=\"left:80px;top:452px;font-size:18.3px;max-width:430px\">转变的设想，由建国之初的“先搞工业化建设，再一举过渡”改变为“建设和改</span><span class=\"bl\" style=\"left:80px;top:473px;font-size:18.3px;max-width:268px\">造同时并举，逐步过渡”。这一改变原因和条件是</span><span class=\"bl\" style=\"left:80px;top:494px;font-size:18.3px;max-width:332px\">A.我国社会主义经济因素的不断增长和对资本主义经济的限制</span><span class=\"bl\" style=\"left:80px;top:514px;font-size:17.2px;max-width:237px\">B.为了确定我国工业化建设的社会主义方向</span><span class=\"bl\" style=\"left:81px;top:536px;font-size:15.6px;max-width:189px\">C.我国工业化建设取得了重大成就</span><span class=\"bl\" style=\"left:265px;top:532px;font-size:51.7px;max-width:194px\">祝您上</span><span class=\"bl\" style=\"left:80px;top:556px;font-size:17.8px;max-width:177px\">D.民主革命的遗留任务已经完成</span></div></div>"}],pages:[22,27]};
  D["mzt_s5"] = {id:"mzt_s5",ch:"毛中特讲义 · 第四章 社会主义建设道路初步探索的理论成果",title:"第四章 社会主义建设道路初步探索的理论成果",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 28 页</div><div class=\"sidebox\" style=\"left:506px;top:607px;width:197px;height:413px\"></div><span class=\"bl\" style=\"left:456px;top:58px;font-size:16.1px;max-width:244px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:345px;top:111px;font-size:25.6px;max-width:65px\">第四章</span><span class=\"bl\" style=\"left:218px;top:160px;font-size:21.1px;max-width:318px\">社会主义建设道路初步探索的理论成果</span><span class=\"bl\" style=\"left:54px;top:212px;font-size:16.1px;max-width:100px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:421px;top:254px;font-size:13.9px;max-width:284px\">考点20调动一切积极因素为社会主义事业服务的思想</span><span class=\"bl\" style=\"left:223px;top:264px;font-size:15.6px;max-width:150px\">社会主义建设道路初步探索</span><span class=\"bl b hl\" style=\"left:420px;top:273px;font-size:15.6px;max-width:261px\">考点21正确认识和处理社会主义社会矛盾的思想</span><span class=\"bl\" style=\"left:223px;top:285px;font-size:14.5px;max-width:90px\">的重要理论成果</span><span class=\"bl b hl\" style=\"left:420px;top:293px;font-size:16.1px;max-width:180px\">考点22走中国工业化道路的思想</span><span class=\"bl\" style=\"left:61px;top:301px;font-size:15.6px;max-width:103px\">社会主义建设道路</span><span class=\"bl\" style=\"left:55px;top:321px;font-size:15.6px;max-width:114px\">初步探索的理论成果</span><span class=\"bl b hl\" style=\"left:420px;top:337px;font-size:16.1px;max-width:226px\">考点23社会主义建设道路初步探索的意义</span><span class=\"bl\" style=\"left:223px;top:348px;font-size:13.9px;max-width:148px\">初步探索的意义和经验教训</span><span class=\"bl b hl\" style=\"left:422px;top:358px;font-size:13.9px;max-width:249px\">考点24社会主义建设道路初步探索的经验教训</span><span class=\"bl\" style=\"left:54px;top:410px;font-size:20.0px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:79px;top:435px;font-size:18.3px;max-width:622px\">本章主要论述新中国成立后对社会主义建设初步探索的理论成果。本章是本门科目中考频较高的章节，考试形式一般为</span><span class=\"bl\" style=\"left:56px;top:456px;font-size:18.3px;max-width:646px\">选择题。考生在复习过程中，要重点掌握毛泽东的《论十大关系》和《关于正确处理人民内部矛盾的问题》的报告的相关知</span><span class=\"bl\" style=\"left:44px;top:467px;font-size:67.8px;max-width:440px\">联</span><span class=\"bl b hl\" style=\"left:66px;top:549px;font-size:18.9px;max-width:436px\">考点20调动一切积极因素为社会主义享业服务的思想☆☆（高</span><span class=\"bl\" style=\"left:660px;top:549px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl\" style=\"left:67px;top:567px;font-size:18.3px;max-width:74px\">频选择题）</span><span class=\"bl b\" style=\"left:79px;top:605px;font-size:17.2px;max-width:54px\">1.背景：</span><span class=\"bl\" style=\"left:523px;top:613px;font-size:15.6px;max-width:95px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:80px;top:624px;font-size:17.8px;max-width:422px\">新中国成立初期，我国主要是学习苏联经验，这在当时是必要的。但是，后来的</span><span class=\"bl\" style=\"left:513px;top:635px;font-size:13.9px;max-width:190px\">“十大关系”涉及生产力和生产关系、经</span><span class=\"bl\" style=\"left:56px;top:644px;font-size:18.3px;max-width:447px\">实践表明，照抄照搬苏联模式不符合中国国情，需要积极探索适合中国特点的社会主</span><span class=\"bl\" style=\"left:512px;top:653px;font-size:13.9px;max-width:134px\">济基础和上层建筑各个方面。</span><span class=\"bl\" style=\"left:57px;top:667px;font-size:16.1px;max-width:74px\">义建设道路。</span><span class=\"bl\" style=\"left:513px;top:672px;font-size:13.9px;max-width:190px\">前五条主要讨论经济问题，着眼于调动经</span><span class=\"bl b\" style=\"left:79px;top:687px;font-size:18.3px;max-width:383px\">2.《论十大关系》的意义：党探索中国社会主义建设道路良好开端的标志</span><span class=\"bl\" style=\"left:512px;top:691px;font-size:13.9px;max-width:133px\">济领域各个方面的积极因素。</span><span class=\"bl b\" style=\"left:79px;top:709px;font-size:16.1px;max-width:153px\">3.（论十大关系）明确提出：</span><span class=\"bl\" style=\"left:512px;top:708px;font-size:15.0px;max-width:190px\">其中前三条讲重工业和轻工业、农业的关</span><span class=\"bl\" style=\"left:81px;top:728px;font-size:17.8px;max-width:327px\">以苏为鉴，独立自主地探索适合中国情况的社会主义建设道路</span><span class=\"bl\" style=\"left:513px;top:726px;font-size:15.6px;max-width:190px\">系，沿海工业和内地工业的关系，经济建</span><span class=\"bl b\" style=\"left:80px;top:751px;font-size:15.0px;max-width:216px\">4.《论十大关系》基本方针：（2016一6）</span><span class=\"bl\" style=\"left:512px;top:744px;font-size:15.6px;max-width:191px\">设和国防建设的关系。这里涉及的实际上</span><span class=\"bl\" style=\"left:512px;top:762px;font-size:15.6px;max-width:191px\">是开辟一条和苏联有所不同的工业化道路</span><span class=\"bl\" style=\"left:80px;top:770px;font-size:18.3px;max-width:423px\">努力把党内外、国内外的一切积极的因素，直接的、间接的积极因素全部调动起</span><span class=\"bl\" style=\"left:513px;top:782px;font-size:13.3px;max-width:33px\">问题。</span><span class=\"bl\" style=\"left:57px;top:791px;font-size:18.3px;max-width:374px\">来，为社会主义建设服务。即：调动一切积极因素为社会主义事业服务</span><span class=\"bl\" style=\"left:513px;top:799px;font-size:15.0px;max-width:190px\">第四、五条讲国家、生产单位和生产者个</span><span class=\"bl b\" style=\"left:80px;top:814px;font-size:15.6px;max-width:129px\">5.《论十大关系》内容：</span><span class=\"bl\" style=\"left:513px;top:817px;font-size:15.0px;max-width:191px\">人的关系，开始涉及经济体制改革。这样</span><span class=\"bl\" style=\"left:80px;top:832px;font-size:18.3px;max-width:423px\">涉及生产力和生产关系、经济基础和上层建筑各方面，提出“向外国学习”的</span><span class=\"bl\" style=\"left:513px;top:835px;font-size:15.0px;max-width:191px\">就初步提出了中国社会主义经济建设的若</span><span class=\"bl\" style=\"left:59px;top:857px;font-size:13.3px;max-width:38px\">口号。</span><span class=\"bl\" style=\"left:455px;top:854px;font-size:14.5px;max-width:47px\">&gt;拓展1</span><span class=\"bl\" style=\"left:513px;top:853px;font-size:15.6px;max-width:94px\">干新方针、新思路。</span><span class=\"bl b\" style=\"left:81px;top:875px;font-size:16.1px;max-width:216px\">6.毛泽东强调，社会主义事业前进需要：</span><span class=\"bl\" style=\"left:513px;top:871px;font-size:15.6px;max-width:190px\">后五条，讲汉族与少数民族的关系、党与</span><span class=\"bl\" style=\"left:513px;top:889px;font-size:15.6px;max-width:190px\">非党的关系、革命和反革命的关系、是非</span><span class=\"bl\" style=\"left:82px;top:894px;font-size:18.9px;max-width:417px\">充分调动一切积极因素，尽可能地克服消极因素，并努力化消极因素为积极因素。</span><span class=\"bl\" style=\"left:514px;top:907px;font-size:15.6px;max-width:190px\">关系、中国和外国的关系，都属于政治生活</span><span class=\"bl b\" style=\"left:80px;top:916px;font-size:17.2px;max-width:253px\">7.调动一切积极因素为社会主义事业服务要求：</span><span class=\"bl\" style=\"left:514px;top:925px;font-size:15.0px;max-width:187px\">和思想文化生活调动各种积极因素的问题。</span><span class=\"bl\" style=\"left:82px;top:938px;font-size:15.6px;max-width:167px\">①必须坚持中国共产党的领导。</span><span class=\"bl\" style=\"left:82px;top:958px;font-size:17.2px;max-width:167px\">②必须发展社会主义民主政治。</span><span class=\"bl\" style=\"left:526px;top:962px;font-size:12.2px;max-width:93px\">火星姐姐考点拓展2</span><span class=\"bl\" style=\"left:82px;top:979px;font-size:17.2px;max-width:273px\">③必须认识社会主义发展阶段和社会主义建设规律。</span><span class=\"bl\" style=\"left:456px;top:978px;font-size:15.0px;max-width:48px\">&gt;拓展2</span><span class=\"bl\" style=\"left:515px;top:982px;font-size:16.1px;max-width:191px\">在探索中国社会主义建设道路过程中，毛</span><span class=\"bl\" style=\"left:514px;top:1000px;font-size:15.6px;max-width:183px\">泽东提出，社会主义又可分为两个阶段，</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 29 页</div><div class=\"sidebox\" style=\"left:465px;top:304px;width:245px;height:250px\"></div><span class=\"bl b hl\" style=\"left:76px;top:117px;font-size:18.9px;max-width:374px\">考点21正确认识和处理社会主义社会矛盾的思想☆☆☆</span><span class=\"bl\" style=\"left:521px;top:115px;font-size:14.5px;max-width:51px\">（接上页）</span><span class=\"bl\" style=\"left:523px;top:134px;font-size:13.9px;max-width:156px\">第一个阶段是不发达的社会主义；</span><span class=\"bl b\" style=\"left:67px;top:154px;font-size:13.9px;max-width:250px\">21.1社会主义社会矛盾的提出（高频选择题）</span><span class=\"bl\" style=\"left:524px;top:152px;font-size:12.2px;max-width:188px\">第二个阶段是比较发达的社会主义。后</span><span class=\"bl b\" style=\"left:90px;top:176px;font-size:13.9px;max-width:421px\">1.背景：我国社会主义改造的任务完成以后，国内的社会矛盾和阶级关系发生</span><span class=\"bl\" style=\"left:524px;top:171px;font-size:12.2px;max-width:188px\">一个阶段可能比前一个阶段需要更长的</span><span class=\"bl\" style=\"left:523px;top:189px;font-size:13.4px;max-width:34px\">时间。</span><span class=\"bl\" style=\"left:67px;top:196px;font-size:14.5px;max-width:445px\">重大变化，无产阶级同资产阶级之间的矛盾已经基本上解决。在这种情况下，大量人</span><span class=\"bl\" style=\"left:66px;top:216px;font-size:15.0px;max-width:283px\">民内部矛盾逐步成为政治生活中居于主导地位的矛盾。</span><span class=\"bl b\" style=\"left:89px;top:237px;font-size:15.0px;max-width:422px\">2.提出：1957年2月，毛泽东所作的《关于正确处理人民内部矛盾的问题》的</span><span class=\"bl\" style=\"left:66px;top:258px;font-size:15.0px;max-width:237px\">报告，系统论证了社会主义社会矛盾的理论。</span><span class=\"bl b\" style=\"left:66px;top:286px;font-size:13.9px;max-width:251px\">21.2社会主义社会的基本矛盾（高频选择题）</span><span class=\"bl b\" style=\"left:90px;top:308px;font-size:14.5px;max-width:321px\">1.内容：生产力和生产关系，经济基础和上层建筑间的矛盾。</span><span class=\"bl\" style=\"left:471px;top:310px;font-size:13.4px;max-width:37px\">提示1</span><span class=\"bl b\" style=\"left:90px;top:330px;font-size:13.9px;max-width:146px\">2.性质：非对抗性的矛盾。</span><span class=\"bl\" style=\"left:463px;top:330px;font-size:14.5px;max-width:48px\">解读1</span><span class=\"bl\" style=\"left:532px;top:328px;font-size:12.2px;max-width:93px\">火星姐姐易错提示1</span><span class=\"bl b\" style=\"left:90px;top:350px;font-size:13.9px;max-width:171px\">3.特点：“又相适应又相矛盾”。</span><span class=\"bl\" style=\"left:524px;top:351px;font-size:12.2px;max-width:125px\">社会主义社会没有矛盾。×</span><span class=\"bl\" style=\"left:90px;top:370px;font-size:15.0px;max-width:403px\">①相适应：社会主义生产关系已经建立起来，它是和生产力的发展相适应的。</span><span class=\"bl\" style=\"left:523px;top:370px;font-size:12.2px;max-width:189px\">矛盾是普遍存在的，社会主义社会同样充</span><span class=\"bl\" style=\"left:90px;top:390px;font-size:15.6px;max-width:421px\">②相矛盾：生产关系还很不完善，这些不完善的方面和生产力的发展又是相矛</span><span class=\"bl\" style=\"left:522px;top:387px;font-size:14.5px;max-width:54px\">满着矛盾。</span><span class=\"bl\" style=\"left:66px;top:412px;font-size:13.4px;max-width:37px\">盾的。</span><span class=\"bl\" style=\"left:524px;top:422px;font-size:13.9px;max-width:102px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:89px;top:432px;font-size:15.6px;max-width:321px\">4.解决途径：通过社会主义制度本身不断得到完善加以解决。</span><span class=\"bl\" style=\"left:521px;top:445px;font-size:14.5px;max-width:190px\">如何理解社会主义社会的基本矛盾其性质</span><span class=\"bl b\" style=\"left:66px;top:460px;font-size:15.6px;max-width:288px\">21.3我国社会的主要矛盾和根本任务（高频选择题）</span><span class=\"bl\" style=\"left:521px;top:463px;font-size:13.9px;max-width:74px\">是非对抗性的？</span><span class=\"bl\" style=\"left:89px;top:480px;font-size:17.8px;max-width:249px\">党的八大指出，我们国内的主要矛盾，已经是：</span><span class=\"bl\" style=\"left:523px;top:482px;font-size:12.2px;max-width:188px\">因为社会主义社会的基本矛盾是在生产关</span><span class=\"bl\" style=\"left:89px;top:501px;font-size:17.8px;max-width:380px\">①人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾；</span><span class=\"bl\" style=\"left:524px;top:501px;font-size:12.2px;max-width:187px\">系和生产力基本适应、上层建筑和经济基</span><span class=\"bl\" style=\"left:90px;top:523px;font-size:15.6px;max-width:420px\">②人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之</span><span class=\"bl\" style=\"left:523px;top:519px;font-size:12.2px;max-width:188px\">础基本适应条件下的矛盾，是在人民根本</span><span class=\"bl\" style=\"left:522px;top:536px;font-size:13.9px;max-width:113px\">利益一致基础上的矛盾。</span><span class=\"bl\" style=\"left:66px;top:544px;font-size:13.9px;max-width:61px\">间的矛盾。</span><span class=\"bl b\" style=\"left:65px;top:571px;font-size:18.4px;max-width:434px\">21.4关于社会主义社会存在两种不同性质矛盾的理论（高频选择题）（2012-29）</span><span class=\"bl\" style=\"left:89px;top:593px;font-size:16.1px;max-width:393px\">1.社会主义社会的矛盾反映在政治上可以划分为敌我矛盾和人民内部矛盾。</span><span class=\"bl\" style=\"left:88px;top:614px;font-size:15.0px;max-width:321px\">2.敌我矛盾是根本利益对立基础上的矛盾，是对抗性的矛盾。</span><span class=\"bl\" style=\"left:88px;top:635px;font-size:15.6px;max-width:420px\">3.人民内部矛盾是在人民利益根本一致的基础上的矛盾，因而是非对抗性的矛盾。</span><span class=\"bl b\" style=\"left:87px;top:655px;font-size:18.4px;max-width:424px\">4.社会主义国家政治生活的主题：关于正确处理人民内部矛盾的问题。这一论</span><span class=\"bl\" style=\"left:65px;top:676px;font-size:16.1px;max-width:445px\">断的根本着眼点，在于调动一切积极因素，团结一切可以团结的力量，把全党的注意</span><span class=\"bl\" style=\"left:65px;top:696px;font-size:17.2px;max-width:144px\">力转到社会主义建设上来。</span><span class=\"bl b\" style=\"left:65px;top:725px;font-size:17.2px;max-width:446px\">21.5关于正确处理两类不同性质社会矛盾的基本方法、方针和意义（高频选择题）</span><span class=\"bl b\" style=\"left:88px;top:747px;font-size:15.6px;max-width:251px\">1.正确处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:461px;top:750px;font-size:14.5px;max-width:48px\">&gt;解读2</span><span class=\"bl\" style=\"left:522px;top:750px;font-size:13.9px;max-width:104px\">火星姐姐考点解读2</span><span class=\"bl\" style=\"left:88px;top:767px;font-size:15.0px;max-width:144px\">①敌我矛盾：专政的方法。</span><span class=\"bl\" style=\"left:521px;top:772px;font-size:13.9px;max-width:190px\">所谓专政方法，就是运用人民民主专政的</span><span class=\"bl\" style=\"left:88px;top:787px;font-size:15.6px;max-width:167px\">②人民内部矛盾：民主的方法。</span><span class=\"bl\" style=\"left:521px;top:790px;font-size:14.5px;max-width:189px\">国家机器，对于国家内部那些反抗社会主</span><span class=\"bl b\" style=\"left:87px;top:809px;font-size:15.0px;max-width:310px\">2.在政治思想领域处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:521px;top:808px;font-size:15.0px;max-width:189px\">义改造、破坏社会主义建设的敌对分子</span><span class=\"bl\" style=\"left:88px;top:830px;font-size:15.6px;max-width:237px\">①敌我矛盾：实行团结一批评一团结的方针。</span><span class=\"bl\" style=\"left:521px;top:828px;font-size:12.2px;max-width:188px\">和严重犯罪分子依法治罪，剥夺他们的政</span><span class=\"bl\" style=\"left:88px;top:850px;font-size:16.1px;max-width:248px\">②人民内部矛盾：坚持说服教育、讨论的方法。</span><span class=\"bl\" style=\"left:520px;top:845px;font-size:14.5px;max-width:189px\">治权利，强迫他们从事劳动，并在劳动中</span><span class=\"bl\" style=\"left:520px;top:862px;font-size:16.1px;max-width:125px\">尽量使他们改造成为新人。</span><span class=\"bl\" style=\"left:87px;top:871px;font-size:16.1px;max-width:345px\">3.在物质利益、分配方面处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:520px;top:881px;font-size:14.5px;max-width:190px\">所谓民主方法，就是讨论的方法、批评的</span><span class=\"bl\" style=\"left:87px;top:892px;font-size:15.0px;max-width:190px\">①实行统筹兼顾、适当安排的方针。</span><span class=\"bl\" style=\"left:520px;top:900px;font-size:13.9px;max-width:114px\">方法、说服教育的方法。</span><span class=\"bl\" style=\"left:87px;top:912px;font-size:15.6px;max-width:214px\">②兼顾国家、集体和个人三方面的利益。</span><span class=\"bl b\" style=\"left:86px;top:932px;font-size:16.1px;max-width:311px\">4.在科学文化领域处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:86px;top:953px;font-size:15.6px;max-width:203px\">实行“百花齐放、百家争鸣”的方针。</span><span class=\"bl\" style=\"left:85px;top:975px;font-size:16.1px;max-width:358px\">5.在共产党和民主党派之间处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:86px;top:995px;font-size:17.2px;max-width:417px\">实行在坚持社会主义道路和共产党领导的前提下“长期共存，互相监督”的方针。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 30 页</div><span class=\"bl\" style=\"left:460px;top:62px;font-size:13.9px;max-width:241px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:80px;top:108px;font-size:13.9px;max-width:346px\">6.在人民群众和政府机关处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:81px;top:128px;font-size:15.6px;max-width:119px\">坚持民主集中制原则；</span><span class=\"bl\" style=\"left:81px;top:149px;font-size:13.9px;max-width:166px\">努力克服政府机关的官僚主义；</span><span class=\"bl\" style=\"left:81px;top:171px;font-size:13.9px;max-width:131px\">加强对群众的思想教育。</span><span class=\"bl b\" style=\"left:80px;top:191px;font-size:13.9px;max-width:286px\">7.在民族之间处理两类不同性质社会矛盾的基本方法：</span><span class=\"bl\" style=\"left:81px;top:213px;font-size:13.9px;max-width:177px\">实行民族平等、团结互助的方针；</span><span class=\"bl\" style=\"left:80px;top:233px;font-size:14.5px;max-width:96px\">反对大汉族主义；</span><span class=\"bl\" style=\"left:80px;top:254px;font-size:13.9px;max-width:107px\">反对地方民族主义。</span><span class=\"bl b\" style=\"left:79px;top:275px;font-size:13.9px;max-width:193px\">8.社会主义社会矛盾的理论的意义：</span><span class=\"bl\" style=\"left:81px;top:296px;font-size:13.9px;max-width:422px\">①科学揭示了社会主义社会发展的动力，为正确处理社会主义社会各种矛盾、创</span><span class=\"bl\" style=\"left:57px;top:318px;font-size:12.3px;max-width:296px\">造良好的社会环境和政治环境，提供了基本的理论依据。</span><span class=\"bl\" style=\"left:81px;top:338px;font-size:13.9px;max-width:421px\">②为后来的社会主义改革奠定了理论基础，对中国社会主义事业具有长远的指导</span><span class=\"bl\" style=\"left:56px;top:359px;font-size:15.1px;max-width:38px\">意义。</span><span class=\"bl\" style=\"left:81px;top:380px;font-size:13.9px;max-width:422px\">③以独创性的内容丰富了马克思主义的理论宝库，是对科学社会主义理论的重大</span><span class=\"bl\" style=\"left:55px;top:400px;font-size:17.3px;max-width:40px\">发展。</span><span class=\"bl b hl\" style=\"left:66px;top:440px;font-size:18.4px;max-width:276px\">考点22走中国工业化道路的思想☆☆☆</span><span class=\"bl b\" style=\"left:56px;top:477px;font-size:13.9px;max-width:276px\">22.1走中国工业化道路问题的提出（中频选择题）</span><span class=\"bl\" style=\"left:79px;top:496px;font-size:17.3px;max-width:424px\">1.实现工业化是中国近代以来历史发展的必然要求，是国家独立和富强的必要</span><span class=\"bl\" style=\"left:56px;top:520px;font-size:13.4px;max-width:38px\">条件。</span><span class=\"bl\" style=\"left:363px;top:531px;font-size:54.6px;max-width:97px\">上</span><span class=\"bl\" style=\"left:81px;top:540px;font-size:15.6px;max-width:284px\">实现工业化的根本政治前提：中华人民共和国的成立。</span><span class=\"bl b\" style=\"left:80px;top:559px;font-size:17.8px;max-width:313px\">2.促使党和毛泽东思考如何走中国工业化道路问题的因素：</span><span class=\"bl\" style=\"left:81px;top:581px;font-size:15.1px;max-width:298px\">①我国的工业化基础薄弱，且是在苏联的影响下起步的。</span><span class=\"bl\" style=\"left:81px;top:602px;font-size:15.6px;max-width:403px\">②社会主义改造时期，把实现国家的工业化作为党在过渡时期总路线的主体。</span><span class=\"bl\" style=\"left:81px;top:623px;font-size:15.1px;max-width:422px\">③受苏联影响，我国一度过多强调重工业和基础设施的发展，影响农业和轻工业</span><span class=\"bl\" style=\"left:57px;top:645px;font-size:13.9px;max-width:190px\">的发展，造成一定程度的比例失调。</span><span class=\"bl b\" style=\"left:57px;top:673px;font-size:13.9px;max-width:305px\">22.2走中国工业化道路的思想（中频选择题）（2015-5）</span><span class=\"bl\" style=\"left:81px;top:693px;font-size:15.1px;max-width:421px\">1.毛泽东在《关于正确处理人民内部矛盾的问题》中指出中国工业化道路的问题：</span><span class=\"bl\" style=\"left:82px;top:714px;font-size:15.1px;max-width:401px\">①中国工业化道路的问题主要是关于重工业、轻工业和农业的发展关系问题。</span><span class=\"bl\" style=\"left:82px;top:735px;font-size:16.2px;max-width:320px\">②中国工业化道路要走出一条有别于苏联的中国工业化道路。</span><span class=\"bl\" style=\"left:81px;top:776px;font-size:17.8px;max-width:392px\">①发展国民经济的总方针：以农业为基础，以工业为主导，以农轻重为序。</span><span class=\"bl\" style=\"left:82px;top:799px;font-size:13.9px;max-width:249px\">②毛泽东提出了一整套“两条腿走路”的方针：</span><span class=\"bl\" style=\"left:82px;top:818px;font-size:17.3px;max-width:137px\">重工业和轻工业同时并举</span><span class=\"bl\" style=\"left:81px;top:840px;font-size:16.2px;max-width:162px\">中央工业和地方工业同时并举</span><span class=\"bl\" style=\"left:82px;top:861px;font-size:15.1px;max-width:161px\">沿海工业和内地工业同时并举</span><span class=\"bl\" style=\"left:82px;top:881px;font-size:15.6px;max-width:172px\">大型企业和中小型企业同时并举</span><span class=\"bl b\" style=\"left:58px;top:910px;font-size:13.9px;max-width:251px\">22.3走中国工业化道路的要求（低频选择题）</span><span class=\"bl b\" style=\"left:81px;top:930px;font-size:15.6px;max-width:288px\">1.走中国工业化道路，必须明确战略目标和战略步骤：</span><span class=\"bl\" style=\"left:82px;top:950px;font-size:16.2px;max-width:422px\">①战略目标：把中国建设成为一个具有现代农业、现代工业、现代国防和现代科</span><span class=\"bl\" style=\"left:59px;top:973px;font-size:13.9px;max-width:84px\">学技术的强国。</span><span class=\"bl\" style=\"left:82px;top:991px;font-size:17.8px;max-width:297px\">②为了实现战略目标，应当采取“两步走”的发展战略：</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1089px\"><div class=\"bxnum\">第 31 页</div><span class=\"bl\" style=\"left:90px;top:103px;font-size:15.0px;max-width:330px\">第一步：建成一个独立的比较完整的工业体系和国民经济体系。</span><span class=\"bl\" style=\"left:89px;top:124px;font-size:14.4px;max-width:364px\">第二步：全面实现工农国防和科学技术现代化，使中国走在世界前列。</span><span class=\"bl b\" style=\"left:88px;top:145px;font-size:13.9px;max-width:286px\">2.走中国工业化道路，必须采取正确的经济建设方针：</span><span class=\"bl\" style=\"left:89px;top:166px;font-size:15.0px;max-width:355px\">党的八大提出了既反保守又反冒进、在综合平衡中稳步前进的方针。</span><span class=\"bl\" style=\"left:88px;top:186px;font-size:14.4px;max-width:288px\">3.走中国工业化道路，必须发展科学技术和文化教育。</span><span class=\"bl\" style=\"left:89px;top:207px;font-size:15.0px;max-width:214px\">①党中央提出了“向科学进军”的口号。</span><span class=\"bl\" style=\"left:89px;top:228px;font-size:15.5px;max-width:421px\">②刘少奇提出实行“两种劳动制度、两种教育制度”，一种是全日制的劳动者全</span><span class=\"bl\" style=\"left:65px;top:248px;font-size:17.8px;max-width:411px\">日制的教育制度；一种是半日制劳动制度，半日制的教育制度（即半工半读）。</span><span class=\"bl b\" style=\"left:88px;top:270px;font-size:14.4px;max-width:252px\">4.走中国工业化道路，必须重视知识分子工作：</span><span class=\"bl\" style=\"left:89px;top:291px;font-size:15.0px;max-width:419px\">毛泽东提出，知识分子在革命和建设中都具有重要作用，要建设一支宏大的工人</span><span class=\"bl\" style=\"left:65px;top:312px;font-size:13.9px;max-width:107px\">阶级知识分子队伍。</span><span class=\"bl b\" style=\"left:88px;top:332px;font-size:15.0px;max-width:274px\">5.走中国工业化道路，必须调整和完善所有制结构：</span><span class=\"bl\" style=\"left:88px;top:352px;font-size:15.5px;max-width:421px\">①毛泽东、刘少奇、周恩来提出：把资本主义经济作为社会主义经济的补充的</span><span class=\"bl\" style=\"left:64px;top:373px;font-size:15.0px;max-width:37px\">思想。</span><span class=\"bl\" style=\"left:88px;top:394px;font-size:16.1px;max-width:420px\">②毛泽东提出，在社会主义经济占优势的条件下“可以消灭了资本主义，又搞资</span><span class=\"bl\" style=\"left:64px;top:414px;font-size:15.5px;max-width:59px\">本主义”。</span><span class=\"bl\" style=\"left:88px;top:436px;font-size:15.0px;max-width:260px\">③陈云：提出了“三个主体，三个补充”的设想：</span><span class=\"bl\" style=\"left:88px;top:457px;font-size:16.1px;max-width:420px\">在工商业经营方面：国家经营和集体经营是工商业的主体，一定数量的个体经营</span><span class=\"bl\" style=\"left:64px;top:477px;font-size:15.5px;max-width:444px\">是补充；在生产计划方面：计划生产是工农业生产的主体，按照市场变化在国家计划</span><span class=\"bl\" style=\"left:64px;top:498px;font-size:17.2px;max-width:443px\">许可范围内的自由生产是补充；在社会主义的统一市场里：国家市场是它的主体，一</span><span class=\"bl\" style=\"left:64px;top:520px;font-size:14.4px;max-width:212px\">定范围内的国家领导的自由市场是补充。</span><span class=\"bl\" style=\"left:88px;top:540px;font-size:15.5px;max-width:309px\">④朱德：提出要注意发展手工业和农业多种经营的思想。</span><span class=\"bl\" style=\"left:87px;top:561px;font-size:16.1px;max-width:392px\">6.走中国工业化道路，必须积极探索适合我国情况的经济体制和运行机制：</span><span class=\"bl\" style=\"left:88px;top:582px;font-size:17.2px;max-width:419px\">①毛泽东提出：发展商品生产、利用价值规律的思想，认为商品生产在社会主义</span><span class=\"bl\" style=\"left:64px;top:602px;font-size:16.1px;max-width:443px\">条件下，还是一个不可缺少的、有利的工具，要有计划地大力地发展社会主义的商品</span><span class=\"bl\" style=\"left:64px;top:624px;font-size:12.8px;max-width:36px\">生产。</span><span class=\"bl\" style=\"left:87px;top:643px;font-size:17.2px;max-width:421px\">2毛泽东主张“两参一改三结合”：实行干部参加劳动，工人参加管理，改革不</span><span class=\"bl\" style=\"left:64px;top:664px;font-size:16.1px;max-width:306px\">合理的规章制度，工人群众、领导干部和技术人员三结合。</span><span class=\"bl\" style=\"left:87px;top:685px;font-size:15.5px;max-width:236px\">③邓小平提出：实行职工代表大会制的观点。</span><span class=\"bl\" style=\"left:87px;top:706px;font-size:16.1px;max-width:330px\">④陈云提出：建立适合我国情况和人民需要的社会主义的市场。</span><span class=\"bl\" style=\"left:87px;top:727px;font-size:17.2px;max-width:420px\">5刘少奇提出：使社会主义经济既有计划性又有多样性和灵活性的主张，以及按</span><span class=\"bl\" style=\"left:63px;top:748px;font-size:15.0px;max-width:142px\">经济办法管理经济的思想。</span><span class=\"bl b hl\" style=\"left:73px;top:787px;font-size:20.0px;max-width:399px\">考点23社会主义建设道路初步探索的意义☆（低频选择题）</span><span class=\"bl\" style=\"left:86px;top:816px;font-size:16.1px;max-width:203px\">1.巩固和发展了我国的社会主义制度。</span><span class=\"bl\" style=\"left:85px;top:837px;font-size:17.2px;max-width:357px\">2.为开创中国特色社会主义提供了宝贵经验、理论准备、物质基础。</span><span class=\"bl\" style=\"left:85px;top:858px;font-size:17.8px;max-width:421px\">3.丰富了科学社会主义的理论与实践，为其他国家的社会主义建设提供经验和</span><span class=\"bl\" style=\"left:61px;top:878px;font-size:15.5px;max-width:37px\">借鉴。</span><span class=\"bl b hl\" style=\"left:72px;top:918px;font-size:19.4px;max-width:425px\">考点24社会主义建设道路初步探索的经验教训☆（低频选择题）</span><span class=\"bl\" style=\"left:85px;top:946px;font-size:17.8px;max-width:418px\">1.必须把马克思主义与中国实际相结合，探索符合中国特点的社会主义建设道路。</span><span class=\"bl\" style=\"left:84px;top:966px;font-size:18.3px;max-width:404px\">2.必须正确认识社会主义社会的主要矛盾和根本任务，集中力量发展生产力。</span><span class=\"bl\" style=\"left:83px;top:988px;font-size:18.3px;max-width:422px\">3.必须从实际出发进行社会主义建设，建设规模和速度要和国力相适应，不能</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1089px\"><div class=\"bxnum\">第 32 页</div><span class=\"bl\" style=\"left:458px;top:59px;font-size:15.6px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:102px;font-size:16.1px;max-width:61px\">急于求成。</span><span class=\"bl\" style=\"left:77px;top:124px;font-size:16.7px;max-width:252px\">4.必须发展社会主义民主、健全社会主义法制。</span><span class=\"bl\" style=\"left:78px;top:144px;font-size:16.7px;max-width:334px\">5.必须坚持党的民主集中制和集体领导制度，加强执政党建设。</span><span class=\"bl\" style=\"left:78px;top:166px;font-size:15.6px;max-width:422px\">6.必须坚持对外开放，借鉴和吸收人类文明成果建设社会主义，不能关起门来搞</span><span class=\"bl\" style=\"left:55px;top:187px;font-size:15.0px;max-width:37px\">建设。</span><span class=\"bl\" style=\"left:52px;top:222px;font-size:18.9px;max-width:102px\">■经典真题回顾</span><span class=\"bl\" style=\"left:54px;top:249px;font-size:18.3px;max-width:446px\">1.【2015.5】新中国的工业化是在苏联的影响下起步的。走中国工业化道路，是中国</span><span class=\"bl\" style=\"left:71px;top:271px;font-size:16.1px;max-width:429px\">共产党初步探索我国社会主义建设道路的一个重要思想。当时所讲的工业化道路</span><span class=\"bl\" style=\"left:70px;top:291px;font-size:14.5px;max-width:90px\">问题，主要是指</span><span class=\"bl\" style=\"left:70px;top:312px;font-size:15.0px;max-width:141px\">A.中央和地方的关系问题</span><span class=\"bl\" style=\"left:70px;top:333px;font-size:15.0px;max-width:187px\">B.经济建设和国防建设的关系问题</span><span class=\"bl\" style=\"left:70px;top:353px;font-size:16.1px;max-width:188px\">C.沿海工业和内地工业的关系问题</span><span class=\"bl\" style=\"left:70px;top:375px;font-size:15.6px;max-width:222px\">D.重工业、轻工业和农业的发展关系问题</span><span class=\"bl\" style=\"left:53px;top:410px;font-size:18.3px;max-width:447px\">2.【2016.6】社会主义基本制度确立后，如何在中国这样一个经济文化比较落后的</span><span class=\"bl\" style=\"left:71px;top:431px;font-size:15.6px;max-width:426px\">东方大国建设和巩固社会主义，是党面临的全新课题。1956年4月，毛泽东作了</span><span class=\"bl\" style=\"left:69px;top:452px;font-size:16.7px;max-width:430px\">论十大关系》的报告，在初步总结我国社会主义建设经验的基础上，从十个方面</span><span class=\"bl\" style=\"left:69px;top:473px;font-size:17.8px;max-width:429px\">论述了我国社会主义建设需要重点把握的重大关系。“十大关系”所围绕的基本方</span><span class=\"bl\" style=\"left:70px;top:494px;font-size:15.0px;max-width:34px\">针是</span><span class=\"bl\" style=\"left:162px;top:492px;font-size:23.4px;max-width:128px\">瓜伙专</span><span class=\"bl\" style=\"left:70px;top:514px;font-size:16.7px;max-width:129px\">A.集中力量向科学进军</span><span class=\"bl\" style=\"left:305px;top:527px;font-size:53.4px;max-width:154px\">您上</span><span class=\"bl\" style=\"left:69px;top:535px;font-size:16.7px;max-width:221px\">B.调动一切积极因素为社会主义事业服务</span><span class=\"bl\" style=\"left:70px;top:556px;font-size:15.6px;max-width:245px\">C.既反保守又反冒进、在综合平衡中稳步前进</span><span class=\"bl\" style=\"left:70px;top:577px;font-size:15.0px;max-width:140px\">D.正确处理人民内部矛盾</span><span class=\"bl\" style=\"left:52px;top:613px;font-size:16.7px;max-width:446px\">3.【2021.22】社会主义基本制度确立以后，如何在中国这样一个经济文化比较落后</span><span class=\"bl\" style=\"left:70px;top:634px;font-size:15.6px;max-width:428px\">的东方大国建设和巩固社会主义，是党面临的一项崭新课题。为找到一条适合中</span><span class=\"bl\" style=\"left:69px;top:654px;font-size:16.7px;max-width:429px\">国国情的社会主义建设道路，党带领人民进行了艰难曲折的初步探索。这一初步</span><span class=\"bl\" style=\"left:70px;top:677px;font-size:13.9px;max-width:125px\">探索的意义主要体现在</span><span class=\"bl\" style=\"left:69px;top:698px;font-size:13.9px;max-width:225px\">A.实现了马克思主义中国化的第二次飞跃</span><span class=\"bl\" style=\"left:69px;top:719px;font-size:13.9px;max-width:200px\">B.丰富了科学社会主义的理论和实践</span><span class=\"bl\" style=\"left:70px;top:740px;font-size:13.9px;max-width:200px\">C.巩固和发展了我国的社会主义制度</span><span class=\"bl\" style=\"left:69px;top:759px;font-size:16.7px;max-width:356px\">D.为开创中国特色社会主义提供了宝贵经验、理论准备和物质基础</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 33 页</div><div class=\"sidebox\" style=\"left:517px;top:549px;width:196px;height:351px\"></div><span class=\"bl b acc\" style=\"left:356px;top:115px;font-size:23.9px;max-width:65px\">第五章</span><span class=\"bl\" style=\"left:339px;top:163px;font-size:22.8px;max-width:99px\">邓小平理论</span><span class=\"bl\" style=\"left:65px;top:216px;font-size:18.3px;max-width:101px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:382px;top:257px;font-size:15.6px;max-width:167px\">考点25邓小平理论的形成条件</span><span class=\"bl\" style=\"left:227px;top:266px;font-size:17.8px;max-width:104px\">邓小平理论的形成</span><span class=\"bl\" style=\"left:381px;top:277px;font-size:15.6px;max-width:127px\">邓小平理论的形成过程</span><span class=\"bl b hl\" style=\"left:464px;top:307px;font-size:15.0px;max-width:191px\">考点26邓小平理论回答的基本问题</span><span class=\"bl\" style=\"left:106px;top:318px;font-size:16.1px;max-width:69px\">邓小平理论</span><span class=\"bl\" style=\"left:228px;top:318px;font-size:16.1px;max-width:185px\">邓小平理论的基本问题和主要内容</span><span class=\"bl b hl\" style=\"left:464px;top:328px;font-size:16.1px;max-width:169px\">考点27邓小平理论的主要内容</span><span class=\"bl\" style=\"left:407px;top:358px;font-size:16.1px;max-width:231px\">马克思列宁主义、毛泽东思想的继承和发展</span><span class=\"bl\" style=\"left:228px;top:380px;font-size:15.6px;max-width:127px\">邓小平理论的历史地位</span><span class=\"bl\" style=\"left:407px;top:379px;font-size:15.0px;max-width:207px\">中国特色社会主义理论体系的开篇之作</span><span class=\"bl\" style=\"left:407px;top:400px;font-size:15.0px;max-width:231px\">改革开放和社会主义现代化建设的科学指南</span><span class=\"bl b acc\" style=\"left:66px;top:453px;font-size:16.1px;max-width:101px\">考点考情分析</span><span class=\"bl\" style=\"left:90px;top:477px;font-size:18.9px;max-width:622px\">本章主要论述邓小平理论。本章内容是本门科目中考频一般的章节，考试形式为选择题。考生在复习过程中，对邓小平</span><span class=\"bl\" style=\"left:67px;top:499px;font-size:17.2px;max-width:340px\">理论回答的基本问题、主要内容以及历史地位有一定了解即可。</span><span class=\"bl b hl\" style=\"left:77px;top:556px;font-size:17.8px;max-width:232px\">考点25邓小平理论的形成☆女</span><span class=\"bl\" style=\"left:672px;top:555px;font-size:14.5px;max-width:39px\">记笔记</span><span class=\"bl\" style=\"left:525px;top:585px;font-size:15.6px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl b\" style=\"left:67px;top:591px;font-size:15.6px;max-width:239px\">25.1邓小平理论的形成条件（低频选择题）</span><span class=\"bl\" style=\"left:464px;top:592px;font-size:15.0px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:90px;top:612px;font-size:17.2px;max-width:311px\">1.和平与发展成为时代主题是邓小平理论形成的时代背景。</span><span class=\"bl\" style=\"left:523px;top:607px;font-size:15.0px;max-width:190px\">邓小平明确地指出：“现在世界上真正大</span><span class=\"bl\" style=\"left:523px;top:625px;font-size:15.0px;max-width:190px\">的问题，带全球性的战略问题，一个是</span><span class=\"bl\" style=\"left:90px;top:633px;font-size:15.0px;max-width:308px\">2.社会主义建设的经验教训是邓小平理论形成的历史根据。</span><span class=\"bl\" style=\"left:523px;top:645px;font-size:13.9px;max-width:191px\">和平问题，一个是经济问题或者说发展</span><span class=\"bl\" style=\"left:90px;top:653px;font-size:15.0px;max-width:335px\">3.改革开放和现代化建设的实践是邓小平理论形成的现实依据。</span><span class=\"bl\" style=\"left:523px;top:663px;font-size:13.9px;max-width:190px\">问题。和平问题是东西问题，发展问题是</span><span class=\"bl b\" style=\"left:68px;top:681px;font-size:15.6px;max-width:244px\">25.2邓小平理论的形成过程（中频选择题）</span><span class=\"bl\" style=\"left:523px;top:681px;font-size:15.0px;max-width:190px\">南北问题。概括起来，就是东西南北四个</span><span class=\"bl b\" style=\"left:90px;top:701px;font-size:15.6px;max-width:147px\">1.邓小平理论的主题形成：</span><span class=\"bl\" style=\"left:524px;top:700px;font-size:13.9px;max-width:129px\">字。南北问题是核心问题。”</span><span class=\"bl\" style=\"left:523px;top:718px;font-size:13.9px;max-width:190px\">社会主义建设初期走了不少弯路，其原</span><span class=\"bl\" style=\"left:523px;top:737px;font-size:14.5px;max-width:24px\">因：</span><span class=\"bl\" style=\"left:67px;top:743px;font-size:16.1px;max-width:446px\">我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义，这就是我们</span><span class=\"bl\" style=\"left:524px;top:755px;font-size:13.9px;max-width:190px\">一是偏离了党的实事求是的思想路线，对</span><span class=\"bl\" style=\"left:69px;top:763px;font-size:15.0px;max-width:445px\">总结长期历史经验得出的基本结论。”从此，“中国特色社会主义”成为我们党的全部</span><span class=\"bl\" style=\"left:525px;top:772px;font-size:13.9px;max-width:189px\">国际国内的形势、对我国社会主义时期的</span><span class=\"bl\" style=\"left:68px;top:785px;font-size:13.9px;max-width:131px\">理论和实践创新的主题。</span><span class=\"bl\" style=\"left:525px;top:791px;font-size:13.9px;max-width:190px\">主要矛盾和中国现实的具体国情作出了错</span><span class=\"bl\" style=\"left:91px;top:804px;font-size:16.1px;max-width:422px\">②从党的十二大到十三大，邓小平提出了关于社会主义的许多重要的科学论断，</span><span class=\"bl\" style=\"left:523px;top:809px;font-size:15.6px;max-width:83px\">误的估量和判断；</span><span class=\"bl\" style=\"left:68px;top:826px;font-size:13.9px;max-width:285px\">形成了一系列的方针政策以及与此相对应的理论观点。</span><span class=\"bl\" style=\"left:523px;top:827px;font-size:15.0px;max-width:190px\">二是对什么是社会主义和如何建设社会主</span><span class=\"bl b\" style=\"left:90px;top:845px;font-size:16.1px;max-width:268px\">2.邓小平理论的轮廓形成：1987年，党的十三大。</span><span class=\"bl\" style=\"left:524px;top:845px;font-size:14.5px;max-width:190px\">义问题没有完全搞清楚，因而也就不可能</span><span class=\"bl\" style=\"left:91px;top:866px;font-size:16.1px;max-width:297px\">①第一次比较系统地论述了我国社会主义初级阶段理论。</span><span class=\"bl\" style=\"left:524px;top:864px;font-size:13.9px;max-width:189px\">集中精力发展生产力，也不可能对社会主</span><span class=\"bl\" style=\"left:92px;top:887px;font-size:15.6px;max-width:343px\">②明确概括和全面阐发了“一个中心、两个基本点”的基本路线。</span><span class=\"bl\" style=\"left:525px;top:883px;font-size:13.9px;max-width:172px\">义的某些制度和体制进行有效的改革。</span><span class=\"bl\" style=\"left:92px;top:908px;font-size:13.9px;max-width:318px\">③第一次对中国特色社会主义理论的主要内容作了系统概括。</span><span class=\"bl b\" style=\"left:91px;top:928px;font-size:13.9px;max-width:267px\">3.邓小平理论逐步走向成熟：1992年，南方谈话。</span><span class=\"bl\" style=\"left:92px;top:949px;font-size:13.9px;max-width:421px\">①南方谈话从理论上深刻回答了：困扰和束缚人们思想的一系列重大问题，推动</span><span class=\"bl\" style=\"left:68px;top:969px;font-size:13.9px;max-width:237px\">改革开放和社会主义现代化建设进人新阶段。</span><span class=\"bl\" style=\"left:91px;top:988px;font-size:16.1px;max-width:422px\">②南方谈话提出了一系列重要论断：社会主义本质；“三个有利于”标准；社会</span><span class=\"bl\" style=\"left:67px;top:1009px;font-size:15.6px;max-width:119px\">主义可以搞市场经济。</span></div></div>"}],pages:[28,33]};
  D["mzt_s6"] = {id:"mzt_s6",ch:"毛中特讲义 · 第五章 邓小平理论",title:"第五章 邓小平理论",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 33 页</div><div class=\"sidebox\" style=\"left:517px;top:549px;width:196px;height:351px\"></div><span class=\"bl b acc\" style=\"left:356px;top:115px;font-size:23.9px;max-width:65px\">第五章</span><span class=\"bl\" style=\"left:339px;top:163px;font-size:22.8px;max-width:99px\">邓小平理论</span><span class=\"bl\" style=\"left:65px;top:216px;font-size:18.3px;max-width:101px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:382px;top:257px;font-size:15.6px;max-width:167px\">考点25邓小平理论的形成条件</span><span class=\"bl\" style=\"left:227px;top:266px;font-size:17.8px;max-width:104px\">邓小平理论的形成</span><span class=\"bl\" style=\"left:381px;top:277px;font-size:15.6px;max-width:127px\">邓小平理论的形成过程</span><span class=\"bl b hl\" style=\"left:464px;top:307px;font-size:15.0px;max-width:191px\">考点26邓小平理论回答的基本问题</span><span class=\"bl\" style=\"left:106px;top:318px;font-size:16.1px;max-width:69px\">邓小平理论</span><span class=\"bl\" style=\"left:228px;top:318px;font-size:16.1px;max-width:185px\">邓小平理论的基本问题和主要内容</span><span class=\"bl b hl\" style=\"left:464px;top:328px;font-size:16.1px;max-width:169px\">考点27邓小平理论的主要内容</span><span class=\"bl\" style=\"left:407px;top:358px;font-size:16.1px;max-width:231px\">马克思列宁主义、毛泽东思想的继承和发展</span><span class=\"bl\" style=\"left:228px;top:380px;font-size:15.6px;max-width:127px\">邓小平理论的历史地位</span><span class=\"bl\" style=\"left:407px;top:379px;font-size:15.0px;max-width:207px\">中国特色社会主义理论体系的开篇之作</span><span class=\"bl\" style=\"left:407px;top:400px;font-size:15.0px;max-width:231px\">改革开放和社会主义现代化建设的科学指南</span><span class=\"bl b acc\" style=\"left:66px;top:453px;font-size:16.1px;max-width:101px\">考点考情分析</span><span class=\"bl\" style=\"left:90px;top:477px;font-size:18.9px;max-width:622px\">本章主要论述邓小平理论。本章内容是本门科目中考频一般的章节，考试形式为选择题。考生在复习过程中，对邓小平</span><span class=\"bl\" style=\"left:67px;top:499px;font-size:17.2px;max-width:340px\">理论回答的基本问题、主要内容以及历史地位有一定了解即可。</span><span class=\"bl b hl\" style=\"left:77px;top:556px;font-size:17.8px;max-width:232px\">考点25邓小平理论的形成☆女</span><span class=\"bl\" style=\"left:672px;top:555px;font-size:14.5px;max-width:39px\">记笔记</span><span class=\"bl\" style=\"left:525px;top:585px;font-size:15.6px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl b\" style=\"left:67px;top:591px;font-size:15.6px;max-width:239px\">25.1邓小平理论的形成条件（低频选择题）</span><span class=\"bl\" style=\"left:464px;top:592px;font-size:15.0px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:90px;top:612px;font-size:17.2px;max-width:311px\">1.和平与发展成为时代主题是邓小平理论形成的时代背景。</span><span class=\"bl\" style=\"left:523px;top:607px;font-size:15.0px;max-width:190px\">邓小平明确地指出：“现在世界上真正大</span><span class=\"bl\" style=\"left:523px;top:625px;font-size:15.0px;max-width:190px\">的问题，带全球性的战略问题，一个是</span><span class=\"bl\" style=\"left:90px;top:633px;font-size:15.0px;max-width:308px\">2.社会主义建设的经验教训是邓小平理论形成的历史根据。</span><span class=\"bl\" style=\"left:523px;top:645px;font-size:13.9px;max-width:191px\">和平问题，一个是经济问题或者说发展</span><span class=\"bl\" style=\"left:90px;top:653px;font-size:15.0px;max-width:335px\">3.改革开放和现代化建设的实践是邓小平理论形成的现实依据。</span><span class=\"bl\" style=\"left:523px;top:663px;font-size:13.9px;max-width:190px\">问题。和平问题是东西问题，发展问题是</span><span class=\"bl b\" style=\"left:68px;top:681px;font-size:15.6px;max-width:244px\">25.2邓小平理论的形成过程（中频选择题）</span><span class=\"bl\" style=\"left:523px;top:681px;font-size:15.0px;max-width:190px\">南北问题。概括起来，就是东西南北四个</span><span class=\"bl b\" style=\"left:90px;top:701px;font-size:15.6px;max-width:147px\">1.邓小平理论的主题形成：</span><span class=\"bl\" style=\"left:524px;top:700px;font-size:13.9px;max-width:129px\">字。南北问题是核心问题。”</span><span class=\"bl\" style=\"left:523px;top:718px;font-size:13.9px;max-width:190px\">社会主义建设初期走了不少弯路，其原</span><span class=\"bl\" style=\"left:523px;top:737px;font-size:14.5px;max-width:24px\">因：</span><span class=\"bl\" style=\"left:67px;top:743px;font-size:16.1px;max-width:446px\">我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义，这就是我们</span><span class=\"bl\" style=\"left:524px;top:755px;font-size:13.9px;max-width:190px\">一是偏离了党的实事求是的思想路线，对</span><span class=\"bl\" style=\"left:69px;top:763px;font-size:15.0px;max-width:445px\">总结长期历史经验得出的基本结论。”从此，“中国特色社会主义”成为我们党的全部</span><span class=\"bl\" style=\"left:525px;top:772px;font-size:13.9px;max-width:189px\">国际国内的形势、对我国社会主义时期的</span><span class=\"bl\" style=\"left:68px;top:785px;font-size:13.9px;max-width:131px\">理论和实践创新的主题。</span><span class=\"bl\" style=\"left:525px;top:791px;font-size:13.9px;max-width:190px\">主要矛盾和中国现实的具体国情作出了错</span><span class=\"bl\" style=\"left:91px;top:804px;font-size:16.1px;max-width:422px\">②从党的十二大到十三大，邓小平提出了关于社会主义的许多重要的科学论断，</span><span class=\"bl\" style=\"left:523px;top:809px;font-size:15.6px;max-width:83px\">误的估量和判断；</span><span class=\"bl\" style=\"left:68px;top:826px;font-size:13.9px;max-width:285px\">形成了一系列的方针政策以及与此相对应的理论观点。</span><span class=\"bl\" style=\"left:523px;top:827px;font-size:15.0px;max-width:190px\">二是对什么是社会主义和如何建设社会主</span><span class=\"bl b\" style=\"left:90px;top:845px;font-size:16.1px;max-width:268px\">2.邓小平理论的轮廓形成：1987年，党的十三大。</span><span class=\"bl\" style=\"left:524px;top:845px;font-size:14.5px;max-width:190px\">义问题没有完全搞清楚，因而也就不可能</span><span class=\"bl\" style=\"left:91px;top:866px;font-size:16.1px;max-width:297px\">①第一次比较系统地论述了我国社会主义初级阶段理论。</span><span class=\"bl\" style=\"left:524px;top:864px;font-size:13.9px;max-width:189px\">集中精力发展生产力，也不可能对社会主</span><span class=\"bl\" style=\"left:92px;top:887px;font-size:15.6px;max-width:343px\">②明确概括和全面阐发了“一个中心、两个基本点”的基本路线。</span><span class=\"bl\" style=\"left:525px;top:883px;font-size:13.9px;max-width:172px\">义的某些制度和体制进行有效的改革。</span><span class=\"bl\" style=\"left:92px;top:908px;font-size:13.9px;max-width:318px\">③第一次对中国特色社会主义理论的主要内容作了系统概括。</span><span class=\"bl b\" style=\"left:91px;top:928px;font-size:13.9px;max-width:267px\">3.邓小平理论逐步走向成熟：1992年，南方谈话。</span><span class=\"bl\" style=\"left:92px;top:949px;font-size:13.9px;max-width:421px\">①南方谈话从理论上深刻回答了：困扰和束缚人们思想的一系列重大问题，推动</span><span class=\"bl\" style=\"left:68px;top:969px;font-size:13.9px;max-width:237px\">改革开放和社会主义现代化建设进人新阶段。</span><span class=\"bl\" style=\"left:91px;top:988px;font-size:16.1px;max-width:422px\">②南方谈话提出了一系列重要论断：社会主义本质；“三个有利于”标准；社会</span><span class=\"bl\" style=\"left:67px;top:1009px;font-size:15.6px;max-width:119px\">主义可以搞市场经济。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 34 页</div><div class=\"sidebox\" style=\"left:502px;top:201px;width:196px;height:323px\"></div><span class=\"bl\" style=\"left:457px;top:64px;font-size:15.0px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:53px;top:108px;font-size:15.6px;max-width:446px\">4.正式提出“邓小平理论”这一概念、确立为党的指导思想并写入党章：1997年，</span><span class=\"bl\" style=\"left:66px;top:128px;font-size:16.1px;max-width:74px\">党的十五大。</span><span class=\"bl b hl\" style=\"left:64px;top:169px;font-size:18.9px;max-width:290px\">考点26邓小平理论回答的基本问题☆☆☆</span><span class=\"bl b\" style=\"left:54px;top:205px;font-size:15.0px;max-width:250px\">26.1社会主义本质理论的提出（高频选择题）</span><span class=\"bl\" style=\"left:450px;top:207px;font-size:15.0px;max-width:48px\">&gt;提示1</span><span class=\"bl\" style=\"left:511px;top:207px;font-size:13.9px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:77px;top:226px;font-size:14.5px;max-width:421px\">1.邓小平在领导改革开放和现代化建设这一新的革命过程中，不断提出和反复</span><span class=\"bl\" style=\"left:511px;top:229px;font-size:14.5px;max-width:141px\">党的指导思想回答的基本问题：</span><span class=\"bl\" style=\"left:54px;top:247px;font-size:15.6px;max-width:379px\">思考的首要的基本的理论问题是：什么是社会主义、怎样建设社会主义。</span><span class=\"bl\" style=\"left:510px;top:246px;font-size:15.0px;max-width:190px\">①邓小平理论：什么是社会主义，怎样建</span><span class=\"bl\" style=\"left:76px;top:268px;font-size:15.0px;max-width:369px\">2.什么是社会主义、怎样建设社会主义，搞清楚这个基本问题的关键：</span><span class=\"bl\" style=\"left:509px;top:265px;font-size:14.5px;max-width:64px\">设社会主义；</span><span class=\"bl\" style=\"left:510px;top:283px;font-size:13.9px;max-width:190px\">②“三个代表”重要思想：建设什么样的</span><span class=\"bl\" style=\"left:77px;top:289px;font-size:15.0px;max-width:408px\">要在坚持社会主义基本制度的基础上进一步认清社会主义的本质。（2020一5）</span><span class=\"bl\" style=\"left:510px;top:302px;font-size:13.9px;max-width:82px\">党，怎样建设党；</span><span class=\"bl b\" style=\"left:76px;top:311px;font-size:13.9px;max-width:111px\">3.社会主义的本质：</span><span class=\"bl\" style=\"left:451px;top:312px;font-size:14.5px;max-width:46px\">&gt;提示2</span><span class=\"bl\" style=\"left:510px;top:320px;font-size:13.9px;max-width:190px\">③科学发展观：实现什么样的发展，怎样</span><span class=\"bl\" style=\"left:76px;top:330px;font-size:17.2px;max-width:386px\">解放生产力、发展生产力，消灭剥削、消除两极分化，最终达到共同富裕</span><span class=\"bl\" style=\"left:508px;top:339px;font-size:15.0px;max-width:35px\">发展；</span><span class=\"bl b\" style=\"left:54px;top:359px;font-size:15.0px;max-width:336px\">26.2社会主义本质理论的科学概括（高频选择题）（2013-25）</span><span class=\"bl\" style=\"left:510px;top:356px;font-size:13.9px;max-width:190px\">④习近平新时代中国特色社会主义思想：</span><span class=\"bl\" style=\"left:77px;top:381px;font-size:13.9px;max-width:421px\">1.既包括了社会主义社会的生产力问题，又包括了以社会主义生产关系为基础</span><span class=\"bl\" style=\"left:511px;top:376px;font-size:12.2px;max-width:188px\">新时代坚持和发展什么样的中国特色社</span><span class=\"bl\" style=\"left:511px;top:394px;font-size:12.2px;max-width:188px\">会主义，怎样坚持和发展中国特色社会</span><span class=\"bl\" style=\"left:54px;top:401px;font-size:15.0px;max-width:202px\">的社会关系问题，是一个有机的整体。</span><span class=\"bl\" style=\"left:510px;top:412px;font-size:13.3px;max-width:34px\">主义。</span><span class=\"bl\" style=\"left:77px;top:421px;font-size:15.0px;max-width:421px\">①突出地强调“解放生产力，发展生产力”，纠正了过去忽视生产力发展的错误</span><span class=\"bl\" style=\"left:54px;top:443px;font-size:15.0px;max-width:38px\">观念。</span><span class=\"bl\" style=\"left:510px;top:445px;font-size:15.6px;max-width:104px\">拿火星姐姐考点提示2</span><span class=\"bl\" style=\"left:77px;top:464px;font-size:15.0px;max-width:421px\">②突出地强调“消灭剥削、消除两极分化，最终达到共同富裕”，阐明了社会主</span><span class=\"bl\" style=\"left:509px;top:468px;font-size:15.0px;max-width:190px\">对社会主义本质作了总结性理论概括是</span><span class=\"bl\" style=\"left:55px;top:483px;font-size:17.2px;max-width:444px\">义社会的发展目标以及实现这个目标必须以解放和发展生产力为基础，指出了我们发</span><span class=\"bl\" style=\"left:510px;top:487px;font-size:14.5px;max-width:189px\">邓小平在1992年年初南方谈话中提练概</span><span class=\"bl\" style=\"left:54px;top:505px;font-size:15.0px;max-width:316px\">展生产力与剥削阶级统治的社会发展生产力的目的根本不同。</span><span class=\"bl\" style=\"left:508px;top:505px;font-size:15.0px;max-width:35px\">括的。</span><span class=\"bl\" style=\"left:77px;top:528px;font-size:13.9px;max-width:323px\">2.为我们坚持公有制又完善和发展公有制指出了正确的方向。</span><span class=\"bl\" style=\"left:76px;top:546px;font-size:18.9px;max-width:423px\">①邓小平说：在改革中，我们始终坚持两条根本原则：一是以社会主义公有制经</span><span class=\"bl\" style=\"left:54px;top:568px;font-size:15.0px;max-width:144px\">济为主体；一是共同富裕。</span><span class=\"bl\" style=\"left:78px;top:589px;font-size:13.9px;max-width:401px\">②毫不动摇地坚持公有制和按劳分配，维护公有制和按劳分配的主体地位，是</span><span class=\"bl\" style=\"left:467px;top:589px;font-size:13.9px;max-width:19px\">是</span><span class=\"bl\" style=\"left:54px;top:610px;font-size:13.9px;max-width:131px\">现社会主义本质的前提。</span><span class=\"bl b\" style=\"left:53px;top:638px;font-size:15.0px;max-width:318px\">26.3社会主义本质理论的科学概括的意义（低频选择题）</span><span class=\"bl\" style=\"left:78px;top:660px;font-size:13.9px;max-width:188px\">①遵循了科学社会主义的基本原则；</span><span class=\"bl\" style=\"left:77px;top:681px;font-size:13.9px;max-width:188px\">②反映了人民的利益和时代的要求；</span><span class=\"bl\" style=\"left:77px;top:701px;font-size:15.0px;max-width:284px\">③廓清了不合乎时代进步和社会发展规律的模糊概念；</span><span class=\"bl\" style=\"left:77px;top:722px;font-size:15.0px;max-width:354px\">④摆脱了长期以来拘泥于具体模式而忽略社会主义本质的错误倾向；</span><span class=\"bl\" style=\"left:77px;top:743px;font-size:13.9px;max-width:176px\">③深化了对科学社会主义的认识。</span><span class=\"bl b hl\" style=\"left:64px;top:782px;font-size:18.9px;max-width:260px\">考点27邓小平理论的主要内容☆☆☆</span><span class=\"bl\" style=\"left:511px;top:780px;font-size:13.9px;max-width:102px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:508px;top:802px;font-size:14.5px;max-width:190px\">社会主义初级阶段同新民主主义社会的</span><span class=\"bl b\" style=\"left:54px;top:819px;font-size:13.9px;max-width:209px\">27.1解放思想、实事求是的思想路线</span><span class=\"bl\" style=\"left:509px;top:821px;font-size:13.3px;max-width:31px\">区别：</span><span class=\"bl\" style=\"left:77px;top:839px;font-size:14.5px;max-width:278px\">①地位：邓小平理论的活的灵魂，邓小平理论的精髓</span><span class=\"bl\" style=\"left:510px;top:839px;font-size:12.2px;max-width:188px\">①从经济基础方面看，它们之间的根本区</span><span class=\"bl\" style=\"left:77px;top:860px;font-size:15.6px;max-width:422px\">②提出：1978年党的十一届三中全会召开前夕，在中央工作会议上邓小平发表</span><span class=\"bl\" style=\"left:509px;top:856px;font-size:14.5px;max-width:191px\">别在于：社会主义公有制经济是否成为社</span><span class=\"bl\" style=\"left:511px;top:876px;font-size:12.2px;max-width:188px\">会经济的主体。新民主主义社会公有制</span><span class=\"bl\" style=\"left:53px;top:883px;font-size:12.2px;max-width:266px\">解放思想，实事求是，团结一致向前看》的讲话。</span><span class=\"bl\" style=\"left:510px;top:894px;font-size:12.2px;max-width:188px\">经济处于领导地位，但不是社会经济的主</span><span class=\"bl b\" style=\"left:54px;top:909px;font-size:13.9px;max-width:239px\">27.2社会主义初级阶段理论（中频选择题）</span><span class=\"bl\" style=\"left:450px;top:910px;font-size:14.5px;max-width:46px\">&gt;拓展1</span><span class=\"bl\" style=\"left:509px;top:911px;font-size:13.9px;max-width:25px\">体。</span><span class=\"bl b\" style=\"left:77px;top:931px;font-size:13.9px;max-width:204px\">1.社会主义初级阶段理论的提出过程：</span><span class=\"bl\" style=\"left:510px;top:930px;font-size:12.2px;max-width:188px\">②从上层建筑方面看，它们之间的根本区</span><span class=\"bl\" style=\"left:76px;top:950px;font-size:16.1px;max-width:422px\">①萌芽：十一届三中全会前，党对于社会主义发展阶段的认识处在不完全清醒的</span><span class=\"bl\" style=\"left:509px;top:947px;font-size:14.5px;max-width:191px\">别在于：社会主义根本政治制度、基本政</span><span class=\"bl\" style=\"left:509px;top:965px;font-size:14.5px;max-width:191px\">治制度是否确立，马克思主义世界观在整</span><span class=\"bl\" style=\"left:53px;top:971px;font-size:16.1px;max-width:39px\">状态。</span><span class=\"bl\" style=\"left:509px;top:983px;font-size:14.5px;max-width:191px\">个社会思想文化领域中的指导地位是否得</span><span class=\"bl\" style=\"left:77px;top:991px;font-size:16.1px;max-width:399px\">②第一次提出：十一届六中全会《关于建国以来党的若干历史问题的决议》。</span><span class=\"bl\" style=\"left:509px;top:1000px;font-size:15.6px;max-width:65px\">到基本确立。</span><span class=\"bl\" style=\"left:77px;top:1012px;font-size:15.6px;max-width:396px\">③系统论述：党的十三大，系统论述了社会主义初级阶段理论。（2015一6）</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 35 页</div><div class=\"sidebox\" style=\"left:518px;top:355px;width:195px;height:193px\"></div><span class=\"bl b\" style=\"left:91px;top:109px;font-size:12.2px;max-width:209px\">2.社会主义初级阶段理论：（2016一7）</span><span class=\"bl\" style=\"left:91px;top:128px;font-size:14.5px;max-width:236px\">①社会主义初级阶段理论是特指而不是泛指。</span><span class=\"bl\" style=\"left:91px;top:147px;font-size:15.6px;max-width:421px\">A.社会主义初级阶段，是指我国在生产力落后、商品经济不发达条件下建设社</span><span class=\"bl\" style=\"left:68px;top:168px;font-size:15.0px;max-width:161px\">会主义必然要经历的特定阶段</span><span class=\"bl\" style=\"left:91px;top:188px;font-size:15.0px;max-width:352px\">B.从我国进入社会主义到基本实现社会主义现代化的整个历史阶段</span><span class=\"bl\" style=\"left:93px;top:210px;font-size:12.2px;max-width:212px\">2社会主义初级阶段理论包含两层含义：</span><span class=\"bl\" style=\"left:92px;top:229px;font-size:15.0px;max-width:328px\">A.我国已经进人社会主义社会，必须坚持而不能离开社会主义</span><span class=\"bl\" style=\"left:91px;top:249px;font-size:15.0px;max-width:399px\">B.我国的社会主义社会还处在不发达的阶段，必须正视而不能超越初级阶段</span><span class=\"bl\" style=\"left:93px;top:270px;font-size:12.2px;max-width:200px\">③社会主义初级阶段理论的重要意义：</span><span class=\"bl\" style=\"left:92px;top:289px;font-size:15.0px;max-width:352px\">A.揭示了当代中国的历史方位，是建设中国特色社会主义的总依据</span><span class=\"bl\" style=\"left:92px;top:309px;font-size:15.0px;max-width:363px\">B.是对马克思主义关于社会主义发展阶段理论的重大发展和重大突破</span><span class=\"bl\" style=\"left:92px;top:330px;font-size:15.0px;max-width:376px\">C.使我们对社会主义建设的长期性、复杂性、艰巨性有了更清醒的认识</span><span class=\"bl b\" style=\"left:69px;top:359px;font-size:12.2px;max-width:248px\">27.3党的基本路线（中频选择题）（2017-22）</span><span class=\"bl\" style=\"left:465px;top:358px;font-size:15.0px;max-width:48px\">&gt;拓展工</span><span class=\"bl\" style=\"left:526px;top:361px;font-size:13.9px;max-width:102px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:94px;top:378px;font-size:13.9px;max-width:419px\">党的十三大报告提出了党在社会主义初级阶段的基本路线：领导和团结全国各</span><span class=\"bl\" style=\"left:525px;top:384px;font-size:12.2px;max-width:188px\">党的基本路线高度概括了党在社会主义</span><span class=\"bl\" style=\"left:69px;top:399px;font-size:13.9px;max-width:446px\">族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创</span><span class=\"bl\" style=\"left:525px;top:402px;font-size:12.2px;max-width:189px\">初级阶段的奋斗目标、基本途径和根本</span><span class=\"bl\" style=\"left:68px;top:418px;font-size:15.0px;max-width:379px\">业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。</span><span class=\"bl\" style=\"left:524px;top:420px;font-size:14.5px;max-width:190px\">保证、领导力量和依靠力量以及实现这一</span><span class=\"bl\" style=\"left:92px;top:438px;font-size:14.5px;max-width:422px\">1.建设“富强、民主、文明的社会主义现代化国家”。这是基本路线规定的党在</span><span class=\"bl\" style=\"left:525px;top:437px;font-size:14.5px;max-width:189px\">目标的基本方针，既紧紧抓住了中国现阶</span><span class=\"bl\" style=\"left:70px;top:460px;font-size:12.2px;max-width:444px\">社会主义初级阶段的奋斗目标，体现了社会主义社会的经济、政治、文化和社会全面</span><span class=\"bl\" style=\"left:524px;top:456px;font-size:14.5px;max-width:191px\">段的主要矛盾，又体现了运用社会主义社</span><span class=\"bl\" style=\"left:68px;top:479px;font-size:14.5px;max-width:446px\">发展的要求。这三个方面的目标和要求，在现实中表现为经济建设、政治建设、文化</span><span class=\"bl\" style=\"left:525px;top:476px;font-size:12.2px;max-width:188px\">会基本矛盾运动的规律，全面推动历史进</span><span class=\"bl\" style=\"left:68px;top:498px;font-size:18.9px;max-width:84px\">建设的统一。</span><span class=\"bl\" style=\"left:525px;top:494px;font-size:12.2px;max-width:189px\">步，实现民富国强、民族振兴的要求。党</span><span class=\"bl\" style=\"left:524px;top:511px;font-size:14.5px;max-width:190px\">的基本路线是党和国家的生命线、人民的</span><span class=\"bl\" style=\"left:93px;top:520px;font-size:13.9px;max-width:152px\">2.“一个中心、两个基本点”</span><span class=\"bl\" style=\"left:275px;top:521px;font-size:12.2px;max-width:130px\">基本路线最主要的内容：</span><span class=\"bl\" style=\"left:524px;top:530px;font-size:14.5px;max-width:44px\">幸福线。</span><span class=\"bl\" style=\"left:93px;top:540px;font-size:13.9px;max-width:421px\">①“以经济建设为中心”回答了社会主义的根本任务问题，体现了发展生产力的</span><span class=\"bl\" style=\"left:69px;top:560px;font-size:14.5px;max-width:58px\">本质要求。</span><span class=\"bl\" style=\"left:92px;top:580px;font-size:15.0px;max-width:422px\">②“坚持四项基本原则”回答了解放和发展生产力的政治保证问题，体现了社会</span><span class=\"bl\" style=\"left:70px;top:601px;font-size:13.9px;max-width:119px\">主义基本制度的要求。</span><span class=\"bl\" style=\"left:93px;top:621px;font-size:13.9px;max-width:421px\">③“坚持改革开放”回答了社会主义的发展动力和外部条件问题，体现了解放生</span><span class=\"bl\" style=\"left:69px;top:640px;font-size:15.6px;max-width:94px\">产力的本质要求。</span><span class=\"bl\" style=\"left:92px;top:662px;font-size:13.9px;max-width:422px\">3.“领导和团结全国各族人民”。这是实现社会主义现代化奋斗目标的领导力量</span><span class=\"bl\" style=\"left:70px;top:682px;font-size:13.9px;max-width:73px\">和依靠力量。</span><span class=\"bl\" style=\"left:92px;top:702px;font-size:13.9px;max-width:422px\">4.“自力更生，艰苦创业”。这是我们党的优良传统，也是实现社会主义初级阶</span><span class=\"bl\" style=\"left:68px;top:722px;font-size:13.9px;max-width:143px\">段奋斗目标的根本立足点。</span><span class=\"bl\" style=\"left:92px;top:743px;font-size:12.2px;max-width:421px\">5.坚持党的基本路线，必须紧紧围绕经济建设这一中心。以经济建设为中心是</span><span class=\"bl\" style=\"left:71px;top:763px;font-size:12.2px;max-width:292px\">兴国之要，是党和国家兴旺发达、长治久安的根本要求。</span><span class=\"bl\" style=\"left:91px;top:781px;font-size:17.3px;max-width:423px\">6.坚持党的基本路线，必须把坚持四项基本原则同坚持改革开放结合起来，正</span><span class=\"bl\" style=\"left:68px;top:803px;font-size:14.5px;max-width:214px\">确处理改革开放和四项基本原则的关系。</span><span class=\"bl\" style=\"left:92px;top:824px;font-size:12.2px;max-width:185px\">7.党的基本路线的不断充实和完善</span><span class=\"bl\" style=\"left:92px;top:843px;font-size:15.0px;max-width:391px\">①党的十七大：把“和谐”与“富强、民主、文明”一起写人了基本路线。</span><span class=\"bl\" style=\"left:92px;top:863px;font-size:14.5px;max-width:422px\">②党的十九大：提出“为把我国建设成为富强民主文明和谐美丽的社会主义现</span><span class=\"bl\" style=\"left:68px;top:903px;font-size:15.0px;max-width:443px\">“现代化强国”，扩展了党的基本路线的内涵，提升了社会主义初级阶段的奋斗目标。</span><span class=\"bl b\" style=\"left:68px;top:929px;font-size:15.0px;max-width:228px\">27.4社会主义的根本任务（中频选择题）</span><span class=\"bl b\" style=\"left:91px;top:950px;font-size:15.0px;max-width:204px\">1.社会主义的根本任务：发展生产力。</span><span class=\"bl b\" style=\"left:91px;top:970px;font-size:15.0px;max-width:422px\">2.强调发展是硬道理，中国解决所有问题的关键：要靠自己的发展，发展要抓住</span><span class=\"bl\" style=\"left:68px;top:991px;font-size:13.4px;max-width:36px\">机遇。</span><span class=\"bl\" style=\"left:91px;top:1011px;font-size:15.0px;max-width:298px\">3.邓小平概括出“科学技术是第一生产力”这个新论断。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 36 页</div><div class=\"sidebox\" style=\"left:502px;top:365px;width:194px;height:337px\"></div><span class=\"bl\" style=\"left:455px;top:63px;font-size:14.4px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:53px;top:109px;font-size:15.0px;max-width:196px\">27.5“三步走”战略（中频选择题）</span><span class=\"bl b\" style=\"left:76px;top:130px;font-size:15.6px;max-width:141px\">1.“三步走”战略的提出：</span><span class=\"bl\" style=\"left:76px;top:151px;font-size:15.0px;max-width:384px\">①1987年4月，邓小平第一次提出分“三步走”基本实现现代化的战略。</span><span class=\"bl\" style=\"left:77px;top:172px;font-size:15.6px;max-width:284px\">②党的十三大，把发展战略构想确定下来，明确提出：</span><span class=\"bl\" style=\"left:77px;top:194px;font-size:13.9px;max-width:419px\">A.从1981年到1990年实现国民生产总值比1980年翻一番，解决人民的温饱问题</span><span class=\"bl\" style=\"left:76px;top:214px;font-size:15.0px;max-width:363px\">B.从1991年到20世纪末，使国民生产总值再翻一番，达到小康水平</span><span class=\"bl\" style=\"left:76px;top:235px;font-size:15.0px;max-width:421px\">C.21世纪中叶，国民生产总值再翻两番，达到中等发达国家水平，基本实现现</span><span class=\"bl\" style=\"left:53px;top:255px;font-size:15.0px;max-width:33px\">代化</span><span class=\"bl b\" style=\"left:76px;top:277px;font-size:15.0px;max-width:240px\">2.实现“三步走”发展战略的两个重要思想：</span><span class=\"bl\" style=\"left:78px;top:298px;font-size:13.9px;max-width:328px\">①争取隔几年使国民经济上一个新台阶的“台阶式”发展思想。</span><span class=\"bl\" style=\"left:77px;top:319px;font-size:14.4px;max-width:377px\">②允许和鼓励一部分地区和一部分人先富起来逐步达到共同富裕的思想。</span><span class=\"bl b\" style=\"left:54px;top:347px;font-size:13.9px;max-width:190px\">27.6改革开放理论（中频选择题）</span><span class=\"bl\" style=\"left:77px;top:369px;font-size:13.9px;max-width:157px\">1.改革是中国的第二次革命。</span><span class=\"bl\" style=\"left:450px;top:369px;font-size:15.0px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:519px;top:371px;font-size:13.9px;max-width:92px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:77px;top:388px;font-size:15.0px;max-width:260px\">①改革的目的：同革命一样都是为了解放生产力。</span><span class=\"bl\" style=\"left:509px;top:393px;font-size:13.9px;max-width:162px\">如何理解改革是中国的第二次革命？</span><span class=\"bl\" style=\"left:78px;top:410px;font-size:13.9px;max-width:306px\">②改革的特点：同革命一样具有根本性、广泛性和深刻性。</span><span class=\"bl\" style=\"left:510px;top:412px;font-size:12.2px;max-width:187px\">中国共产党领导的第一次革命，把一个</span><span class=\"bl\" style=\"left:78px;top:431px;font-size:13.9px;max-width:419px\">③改革的性质：改革不是否定和抛弃社会主义基本制度，改革是社会主义制度的</span><span class=\"bl\" style=\"left:509px;top:431px;font-size:12.2px;max-width:188px\">半殖民地半封建的旧中国变成了一个社会</span><span class=\"bl\" style=\"left:54px;top:451px;font-size:15.6px;max-width:96px\">自我完善和发展。</span><span class=\"bl\" style=\"left:510px;top:448px;font-size:12.2px;max-width:187px\">主义新中国；中国共产党领导的第二次革</span><span class=\"bl\" style=\"left:509px;top:466px;font-size:13.9px;max-width:189px\">命，将把一个经济文化比较落后的社会主</span><span class=\"bl\" style=\"left:76px;top:472px;font-size:15.6px;max-width:120px\">4改革的实质和目标：</span><span class=\"bl\" style=\"left:510px;top:486px;font-size:12.2px;max-width:188px\">义中国变成一个现代化的社会主义国家。</span><span class=\"bl\" style=\"left:76px;top:492px;font-size:17.2px;max-width:243px\">从根本上改变束缚我国生产力发展的经济体制</span><span class=\"bl\" style=\"left:508px;top:502px;font-size:14.4px;max-width:190px\">改革作为一次新的革命，不是也不允许否</span><span class=\"bl\" style=\"left:77px;top:514px;font-size:13.9px;max-width:230px\">建立充满生机和活力的社会主义新经济体制</span><span class=\"bl\" style=\"left:509px;top:522px;font-size:12.2px;max-width:189px\">定和抛弃我们建立起来的社会主义基本</span><span class=\"bl\" style=\"left:77px;top:534px;font-size:16.1px;max-width:208px\">相应地改革政治体制和其他方面的体制</span><span class=\"bl\" style=\"left:215px;top:528px;font-size:55.6px;max-width:243px\">妍祝您上</span><span class=\"bl\" style=\"left:509px;top:540px;font-size:12.2px;max-width:188px\">制度，它是社会主义制度的自我完善和发</span><span class=\"bl\" style=\"left:77px;top:555px;font-size:15.6px;max-width:151px\">实现中国的社会主义现代化</span><span class=\"bl\" style=\"left:509px;top:558px;font-size:12.2px;max-width:189px\">展。改革不是一个阶级推翻另一个阶级那</span><span class=\"bl\" style=\"left:78px;top:577px;font-size:13.9px;max-width:354px\">5所谓第二次革命，是与中国共产党领导的第一次革命相对而言的。</span><span class=\"bl\" style=\"left:508px;top:575px;font-size:14.4px;max-width:190px\">种原来意义上的革命，也不是原有经济体</span><span class=\"bl\" style=\"left:77px;top:598px;font-size:13.9px;max-width:215px\">2.改革是社会主义社会发展的直接动力。</span><span class=\"bl\" style=\"left:510px;top:595px;font-size:12.2px;max-width:187px\">制的细枝末节的修补，而是对体制的根本</span><span class=\"bl\" style=\"left:508px;top:612px;font-size:14.4px;max-width:190px\">性变革。它的实质和目标，是要从根本上</span><span class=\"bl b\" style=\"left:76px;top:619px;font-size:13.9px;max-width:192px\">3.判断改革的三个“有利于”标准：</span><span class=\"bl\" style=\"left:509px;top:632px;font-size:12.2px;max-width:189px\">改变束缚我国生产力发展的经济体制，建</span><span class=\"bl\" style=\"left:78px;top:640px;font-size:13.9px;max-width:224px\">①是否有利于发展社会主义社会的生产力。</span><span class=\"bl\" style=\"left:510px;top:649px;font-size:12.2px;max-width:188px\">立充满生机和活力的社会主义新经济体</span><span class=\"bl\" style=\"left:78px;top:661px;font-size:13.9px;max-width:224px\">②是否有利于增强社会主义国家综合国力。</span><span class=\"bl\" style=\"left:510px;top:668px;font-size:12.2px;max-width:188px\">制，同时相应地改革政治体制和其他方面</span><span class=\"bl\" style=\"left:77px;top:682px;font-size:13.9px;max-width:190px\">③是否有利于提高人民的生活水平。</span><span class=\"bl\" style=\"left:509px;top:686px;font-size:12.2px;max-width:180px\">的体制，以实现中国的社会主义现代化。</span><span class=\"bl\" style=\"left:76px;top:702px;font-size:13.9px;max-width:98px\">4.开放也是改革。</span><span class=\"bl\" style=\"left:78px;top:723px;font-size:13.9px;max-width:282px\">①对外开放是建设中国特色社会主义的一项基本国策。</span><span class=\"bl\" style=\"left:78px;top:745px;font-size:12.2px;max-width:282px\">②坚持这一基本国策的立足点：独立自主、自力更生。</span><span class=\"bl b\" style=\"left:77px;top:765px;font-size:13.9px;max-width:180px\">5.实行对外开放要处理好的关系：</span><span class=\"bl\" style=\"left:78px;top:787px;font-size:12.2px;max-width:258px\">①要正确对待资本主义社会创造的现代文明成果。</span><span class=\"bl\" style=\"left:76px;top:805px;font-size:16.1px;max-width:367px\">②要高度珍惜并坚决维护中国人民经过长期奋斗得来的独立自主权利。</span><span class=\"bl b\" style=\"left:55px;top:835px;font-size:12.2px;max-width:236px\">27.7社会主义市场经济理论（中频选择题）</span><span class=\"bl b\" style=\"left:76px;top:854px;font-size:15.0px;max-width:391px\">1.我国经济体制改革的核心问题：如何正确认识和处理计划与市场的关系。</span><span class=\"bl b\" style=\"left:77px;top:877px;font-size:13.9px;max-width:204px\">2.社会主义市场经济理论的三个要点：</span><span class=\"bl\" style=\"left:77px;top:896px;font-size:15.0px;max-width:421px\">①计划经济和市场经济不是划分社会制度的标志，计划经济不等于社会主义，市</span><span class=\"bl\" style=\"left:55px;top:918px;font-size:13.9px;max-width:142px\">场经济也不等于资本主义。</span><span class=\"bl\" style=\"left:77px;top:938px;font-size:15.0px;max-width:421px\">②计划和市场都是经济手段，对经济活动的调节各有优势和长处，社会主义实行</span><span class=\"bl\" style=\"left:55px;top:959px;font-size:13.9px;max-width:153px\">市场经济要把两者结合起来。</span><span class=\"bl\" style=\"left:78px;top:979px;font-size:15.0px;max-width:420px\">③市场经济作为资源配置的一种方式本身不具有制度属性，可以和不同的社会制</span><span class=\"bl\" style=\"left:54px;top:1000px;font-size:16.1px;max-width:179px\">度结合，从而表现出不同的性质。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 37 页</div><span class=\"bl\" style=\"left:90px;top:109px;font-size:13.9px;max-width:168px\">3.建立社会主义市场经济体制。</span><span class=\"bl\" style=\"left:90px;top:129px;font-size:15.0px;max-width:422px\">①十四大确立了社会主义市场经济改革目标：使市场在国家宏观调控下对资源配</span><span class=\"bl\" style=\"left:66px;top:151px;font-size:15.0px;max-width:95px\">置起基础性作用。</span><span class=\"bl\" style=\"left:91px;top:171px;font-size:15.0px;max-width:413px\">②社会主义市场经济的特色、优势所在：坚持社会主义制度与市场经济的结合。</span><span class=\"bl\" style=\"left:92px;top:193px;font-size:12.3px;max-width:235px\">③社会主义市场经济的基本特征主要体现在：</span><span class=\"bl\" style=\"left:90px;top:213px;font-size:15.0px;max-width:341px\">A.在所有制结构上：以公有制为主体、多种所有制经济共同发展</span><span class=\"bl\" style=\"left:90px;top:233px;font-size:16.2px;max-width:305px\">B.在分配制度上：以按劳分配为主体、多种分配方式并存</span><span class=\"bl\" style=\"left:91px;top:255px;font-size:13.9px;max-width:328px\">C.在宏观调控上：以实现最广大劳动人民利益为出发点和归宿</span><span class=\"bl b\" style=\"left:67px;top:284px;font-size:12.3px;max-width:239px\">27.8“两手抓，两手都要硬”（中频选择题）</span><span class=\"bl b\" style=\"left:91px;top:304px;font-size:13.9px;max-width:239px\">1.我国社会主义现代化建设的一个根本方针：</span><span class=\"bl\" style=\"left:91px;top:325px;font-size:13.9px;max-width:322px\">一手抓物质文明，一手抓精神文明，“两手抓，两手都要硬”。</span><span class=\"bl b\" style=\"left:90px;top:347px;font-size:13.9px;max-width:76px\">2.主要内容：</span><span class=\"bl\" style=\"left:90px;top:368px;font-size:13.9px;max-width:422px\">一手抓物质文明，一手抓精神文明；一手抓建设，一手抓法制；一手抓改革开</span><span class=\"bl\" style=\"left:66px;top:388px;font-size:13.9px;max-width:120px\">放，一手抓惩治腐败。</span><span class=\"bl b\" style=\"left:67px;top:416px;font-size:13.9px;max-width:178px\">27.9“一国两制”（中频选择题）</span><span class=\"bl b\" style=\"left:90px;top:437px;font-size:13.9px;max-width:203px\">1.“和平统一，一国两制”构想的提出：</span><span class=\"bl\" style=\"left:91px;top:458px;font-size:13.9px;max-width:306px\">最早针对台湾问题提出，首先运用于解决香港和澳门问题。</span><span class=\"bl\" style=\"left:89px;top:478px;font-size:16.2px;max-width:365px\">①台湾问题的实质：中国国内战争遗留下来的问题，属于中国的内政</span><span class=\"bl\" style=\"left:89px;top:499px;font-size:16.2px;max-width:366px\">②香港问题和澳门问题的实质：历史上殖民主义侵略遗留下来的问题。</span><span class=\"bl b\" style=\"left:91px;top:523px;font-size:12.3px;max-width:226px\">2.“和平统一，一国两制”构想的基本内容：</span><span class=\"bl\" style=\"left:91px;top:542px;font-size:13.9px;max-width:421px\">①坚持一个中国：是“和平统一、一国两制”的核心，是发展两岸关系和实现和</span><span class=\"bl\" style=\"left:65px;top:556px;font-size:24.0px;max-width:339px\">平统一的基础。大写叻芯</span><span class=\"bl\" style=\"left:91px;top:584px;font-size:13.9px;max-width:420px\">②两制并存，在祖国统一的前提下，国家的主体部分实行社会主义制度，同时在</span><span class=\"bl\" style=\"left:67px;top:605px;font-size:13.9px;max-width:318px\">台湾、香港、澳门保持原有的社会制度和生活方式长期不变。</span><span class=\"bl\" style=\"left:91px;top:625px;font-size:15.0px;max-width:421px\">③高度自治，祖国完全统一后，台湾、香港、澳门作为特别行政区，享有不同于</span><span class=\"bl\" style=\"left:66px;top:646px;font-size:14.5px;max-width:446px\">中国其他省、市、自治区的高度自治权，台湾、香港、澳门同胞各种合法权益将得到</span><span class=\"bl\" style=\"left:66px;top:666px;font-size:15.6px;max-width:96px\">切实尊重和维护。</span><span class=\"bl\" style=\"left:90px;top:688px;font-size:15.0px;max-width:285px\">④尽最大努力争取和平统一，但不承诺放弃使用武力。</span><span class=\"bl\" style=\"left:90px;top:709px;font-size:15.0px;max-width:307px\">5解决台湾问题，实现祖国完全统一，寄希望于台湾人民。</span><span class=\"bl b\" style=\"left:89px;top:730px;font-size:13.9px;max-width:152px\">3.“一国两制”构想的意义：</span><span class=\"bl\" style=\"left:90px;top:749px;font-size:17.8px;max-width:423px\">“一国两制”的构想是邓小平运用辩证唯物主义和历史唯物主义，坚持实事求是，</span><span class=\"bl\" style=\"left:65px;top:770px;font-size:16.2px;max-width:447px\">把和平共处的原则用之于解决一个国家的统一问题，既体现了坚持祖国统一、维护国</span><span class=\"bl\" style=\"left:65px;top:792px;font-size:15.6px;max-width:447px\">家主权的原则性，又体现了照顾历史实际和现实可能的灵活性，是对马克思主义国家</span><span class=\"bl\" style=\"left:66px;top:814px;font-size:13.9px;max-width:108px\">学说的创造性发展。</span><span class=\"bl b\" style=\"left:66px;top:842px;font-size:13.9px;max-width:169px\">27.10中国问题的关键在于党</span><span class=\"bl b\" style=\"left:89px;top:862px;font-size:15.0px;max-width:335px\">1.建设中国特色社会主义的关键：坚持、加强和改善党的领导。</span><span class=\"bl b\" style=\"left:88px;top:882px;font-size:15.6px;max-width:358px\">2.我们党领导人民取得革命和建设胜利的一个法宝：加强党的建设。</span><span class=\"bl\" style=\"left:88px;top:903px;font-size:14.5px;max-width:253px\">3.要加强党的思想建设、组织建设、作风建设。</span><span class=\"bl\" style=\"left:88px;top:924px;font-size:15.0px;max-width:423px\">4.提出了加强党的制度建设的一系列方针原则。领导制度、组织制度问题更带</span><span class=\"bl\" style=\"left:65px;top:945px;font-size:15.0px;max-width:201px\">有根本性、全局性、稳定性和长期性。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 38 页</div><span class=\"bl\" style=\"left:459px;top:61px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b hl\" style=\"left:66px;top:117px;font-size:18.9px;max-width:325px\">考点28邓小平理论的历史地位☆（低频选择题）</span><span class=\"bl\" style=\"left:80px;top:146px;font-size:17.2px;max-width:322px\">1.邓小平理论是马克思列宁主义、毛泽东思想的继承和发展。</span><span class=\"bl\" style=\"left:79px;top:168px;font-size:15.0px;max-width:300px\">2.邓小平理论是中国特色社会主义理论体系的开篇之作。</span><span class=\"bl\" style=\"left:80px;top:189px;font-size:13.9px;max-width:322px\">3.邓小平理论是改革开放和社会主义现代化建设的科学指南。</span><span class=\"bl\" style=\"left:55px;top:225px;font-size:15.6px;max-width:102px\">经典真题回顾</span><span class=\"bl\" style=\"left:56px;top:250px;font-size:16.1px;max-width:446px\">1.【2013.25】1992年年初，邓小平在南方谈话中指出：“社会主义的本质，是解放生</span><span class=\"bl\" style=\"left:73px;top:272px;font-size:15.6px;max-width:428px\">产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。”这一概括对</span><span class=\"bl\" style=\"left:73px;top:294px;font-size:13.9px;max-width:196px\">社会主义传统认识的突破主要体现在</span><span class=\"bl\" style=\"left:71px;top:314px;font-size:16.1px;max-width:272px\">A.破除了脱离生产力水平抽象谈论社会主义的认识</span><span class=\"bl\" style=\"left:72px;top:335px;font-size:15.6px;max-width:305px\">B.否定了社会主义必须坚持公有制和按劳分配原则的认识</span><span class=\"bl\" style=\"left:73px;top:356px;font-size:13.9px;max-width:304px\">C.纠正了把社会主义本质等同于社会主义具体做法的认识</span><span class=\"bl\" style=\"left:72px;top:376px;font-size:15.0px;max-width:317px\">D.摆脱了长期以来忽视建设社会主义根本目的和目标的认识</span><span class=\"bl\" style=\"left:73px;top:433px;font-size:15.6px;max-width:428px\">持不忘初心、继续前进，要坚持党的基本路线不动摇，不断把中国特色社会主义</span><span class=\"bl\" style=\"left:73px;top:454px;font-size:15.0px;max-width:422px\">伟大事业推向前进。”改革开放以来，党和国家领导人一再强调要毫不动摇地坚持</span><span class=\"bl\" style=\"left:72px;top:475px;font-size:15.0px;max-width:327px\">党的基本路线，这主要是因为，实践已经证明党的基本路线是</span><span class=\"bl\" style=\"left:72px;top:495px;font-size:16.1px;max-width:202px\">A.党和国家的生命线、人民的幸福线</span><span class=\"bl\" style=\"left:74px;top:518px;font-size:13.9px;max-width:174px\">B.兴国、立国、强国的重大法宝</span><span class=\"bl\" style=\"left:64px;top:531px;font-size:58.4px;max-width:396px\">研祝您上</span><span class=\"bl\" style=\"left:74px;top:538px;font-size:15.6px;max-width:153px\">C.实现科学发展的政治保证</span><span class=\"bl\" style=\"left:56px;top:593px;font-size:17.2px;max-width:447px\">3.【2020.5】“什么是社会主义、怎样建设社会主义”是邓小平在领导改革开放和现</span><span class=\"bl\" style=\"left:74px;top:614px;font-size:17.2px;max-width:428px\">代化建设这一新的革命过程中，不断提出和反复思考的首要的基本理论问题。搞</span><span class=\"bl\" style=\"left:74px;top:635px;font-size:15.6px;max-width:126px\">清楚这一问题的关键是</span><span class=\"bl\" style=\"left:74px;top:656px;font-size:16.1px;max-width:354px\">A.在认清基本国情的基础上，进一步把握我国社会主义的发展阶段</span><span class=\"bl\" style=\"left:74px;top:678px;font-size:15.0px;max-width:402px\">B.在正确分析我国社会主要矛盾的基础上，进一步明确社会主义的根本任务</span><span class=\"bl\" style=\"left:74px;top:697px;font-size:17.2px;max-width:355px\">C.在坚持社会主义基本制度的基础上，进一步认清社会主义的本质</span><span class=\"bl\" style=\"left:74px;top:719px;font-size:16.1px;max-width:429px\">D.在总结我国社会主义历史经验的基础上，进一步揭示社会主义社会发展的一</span><span class=\"bl\" style=\"left:88px;top:741px;font-size:15.0px;max-width:45px\">般规律</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 39 页</div><span class=\"bl b acc\" style=\"left:357px;top:111px;font-size:25.6px;max-width:66px\">第六章</span><span class=\"bl\" style=\"left:303px;top:160px;font-size:23.9px;max-width:182px\">“三个代表”重要思想</span><span class=\"bl\" style=\"left:65px;top:210px;font-size:19.5px;max-width:101px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:337px;top:253px;font-size:17.2px;max-width:203px\">考点29“三个代表”重要思想的形成</span><span class=\"bl\" style=\"left:165px;top:271px;font-size:20.0px;max-width:122px\">“三个代表”重要思想</span><span class=\"bl b hl\" style=\"left:337px;top:274px;font-size:17.8px;max-width:286px\">考点30“三个代表”重要思想的核心观点和主要内容</span><span class=\"bl b hl\" style=\"left:337px;top:295px;font-size:17.2px;max-width:227px\">考点31“三个代表”重要思想的历史地位</span><span class=\"bl b acc\" style=\"left:64px;top:345px;font-size:20.6px;max-width:101px\">考点考情分析</span><span class=\"bl\" style=\"left:89px;top:373px;font-size:18.4px;max-width:591px\">本章论述“三个代表”重要思想。本章节在本科目中考频一般，考生掌握“三个代表”重要思想的核心观点即可。</span><span class=\"bl b hl\" style=\"left:76px;top:426px;font-size:21.1px;max-width:268px\">考点29“三个代表”重要思想的形成☆</span><span class=\"bl\" style=\"left:670px;top:431px;font-size:15.6px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:463px;font-size:17.2px;max-width:296px\">29.1“三个代表”重要思想的形成条件（低频选择题）</span><span class=\"bl b\" style=\"left:87px;top:485px;font-size:15.6px;max-width:207px\">1.“三个代表”重要思想的形成条件：</span><span class=\"bl\" style=\"left:87px;top:505px;font-size:18.9px;max-width:294px\">①是在对冷战结束后国际局势科学判断的基础上形成的。</span><span class=\"bl\" style=\"left:88px;top:526px;font-size:18.4px;max-width:345px\">②是在科学判断党的历史方位和总结历史经验的基础上提出来的。</span><span class=\"bl\" style=\"left:88px;top:547px;font-size:18.4px;max-width:297px\">③是在建设中国特色社会主义伟大实践的基础上形成的。</span><span class=\"bl b\" style=\"left:87px;top:569px;font-size:15.6px;max-width:194px\">2.党必须解决好的两大历史性课题：</span><span class=\"bl\" style=\"left:88px;top:588px;font-size:18.9px;max-width:367px\">①提高党的领导水平和执政水平。②提高拒腐防变和抵御风险的能力。</span><span class=\"bl b\" style=\"left:63px;top:616px;font-size:17.8px;max-width:297px\">29.2“三个代表”重要思想的形成过程（低频选择题）</span><span class=\"bl b\" style=\"left:87px;top:638px;font-size:16.1px;max-width:76px\">1.酝酿阶段：</span><span class=\"bl\" style=\"left:86px;top:659px;font-size:18.9px;max-width:424px\">从十三届四中全会提出加强党的建设到十五大提出新时期党的建设新的伟大工程</span><span class=\"bl\" style=\"left:64px;top:680px;font-size:16.1px;max-width:62px\">的总目标。</span><span class=\"bl b\" style=\"left:86px;top:701px;font-size:16.1px;max-width:77px\">2.正式提出：</span><span class=\"bl\" style=\"left:87px;top:721px;font-size:18.4px;max-width:394px\">2000年江泽民在广东考察时，首次对“三个代表”进行了比较全面的阐述。</span><span class=\"bl b\" style=\"left:86px;top:742px;font-size:16.1px;max-width:76px\">3.逐步深化：</span><span class=\"bl\" style=\"left:86px;top:763px;font-size:18.9px;max-width:423px\">党的十六大报告中，江泽民全面阐述了“三个代表”重要思想形成的时代背景、</span><span class=\"bl\" style=\"left:63px;top:784px;font-size:17.8px;max-width:248px\">历史地位、精神实质和指导意义，并列人党章。</span><span class=\"bl b\" style=\"left:85px;top:806px;font-size:15.6px;max-width:148px\">4.贯彻“三个代表”要求：</span><span class=\"bl\" style=\"left:86px;top:825px;font-size:18.9px;max-width:423px\">①关键在于坚持与时俱进。②核心在于保持党的先进性。③本质在于坚持执政</span><span class=\"bl\" style=\"left:62px;top:846px;font-size:17.8px;max-width:40px\">为民。</span><span class=\"bl b hl\" style=\"left:73px;top:886px;font-size:18.9px;max-width:67px\">考点30</span><span class=\"bl\" style=\"left:124px;top:886px;font-size:20.6px;max-width:332px\">“三个代表”重要思想的核心观点和主要内容☆☆</span><span class=\"bl b\" style=\"left:62px;top:921px;font-size:18.4px;max-width:295px\">30.1“三个代表”重要思想的核心观点（低频选择题）</span><span class=\"bl b\" style=\"left:85px;top:943px;font-size:16.1px;max-width:199px\">1.“三个代表”重要思想的基本问题：</span><span class=\"bl\" style=\"left:86px;top:963px;font-size:18.4px;max-width:280px\">创造性地回答了建设什么样的党、怎样建设党的问题</span><span class=\"bl b\" style=\"left:84px;top:984px;font-size:17.2px;max-width:201px\">2.“三个代表”重要思想的集中概括：</span><span class=\"bl\" style=\"left:85px;top:1005px;font-size:18.9px;max-width:423px\">中国共产党必须始终代表中国先进生产力的发展要求，代表中国先进文化的前进</span></div></div>"}],pages:[33,39]};
  D["mzt_s7"] = {id:"mzt_s7",ch:"毛中特讲义 · 第六章 “三个代表”重要思想",title:"第六章 “三个代表”重要思想",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 39 页</div><span class=\"bl b acc\" style=\"left:357px;top:111px;font-size:25.6px;max-width:66px\">第六章</span><span class=\"bl\" style=\"left:303px;top:160px;font-size:23.9px;max-width:182px\">“三个代表”重要思想</span><span class=\"bl\" style=\"left:65px;top:210px;font-size:19.5px;max-width:101px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:337px;top:253px;font-size:17.2px;max-width:203px\">考点29“三个代表”重要思想的形成</span><span class=\"bl\" style=\"left:165px;top:271px;font-size:20.0px;max-width:122px\">“三个代表”重要思想</span><span class=\"bl b hl\" style=\"left:337px;top:274px;font-size:17.8px;max-width:286px\">考点30“三个代表”重要思想的核心观点和主要内容</span><span class=\"bl b hl\" style=\"left:337px;top:295px;font-size:17.2px;max-width:227px\">考点31“三个代表”重要思想的历史地位</span><span class=\"bl b acc\" style=\"left:64px;top:345px;font-size:20.6px;max-width:101px\">考点考情分析</span><span class=\"bl\" style=\"left:89px;top:373px;font-size:18.4px;max-width:591px\">本章论述“三个代表”重要思想。本章节在本科目中考频一般，考生掌握“三个代表”重要思想的核心观点即可。</span><span class=\"bl b hl\" style=\"left:76px;top:426px;font-size:21.1px;max-width:268px\">考点29“三个代表”重要思想的形成☆</span><span class=\"bl\" style=\"left:670px;top:431px;font-size:15.6px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:463px;font-size:17.2px;max-width:296px\">29.1“三个代表”重要思想的形成条件（低频选择题）</span><span class=\"bl b\" style=\"left:87px;top:485px;font-size:15.6px;max-width:207px\">1.“三个代表”重要思想的形成条件：</span><span class=\"bl\" style=\"left:87px;top:505px;font-size:18.9px;max-width:294px\">①是在对冷战结束后国际局势科学判断的基础上形成的。</span><span class=\"bl\" style=\"left:88px;top:526px;font-size:18.4px;max-width:345px\">②是在科学判断党的历史方位和总结历史经验的基础上提出来的。</span><span class=\"bl\" style=\"left:88px;top:547px;font-size:18.4px;max-width:297px\">③是在建设中国特色社会主义伟大实践的基础上形成的。</span><span class=\"bl b\" style=\"left:87px;top:569px;font-size:15.6px;max-width:194px\">2.党必须解决好的两大历史性课题：</span><span class=\"bl\" style=\"left:88px;top:588px;font-size:18.9px;max-width:367px\">①提高党的领导水平和执政水平。②提高拒腐防变和抵御风险的能力。</span><span class=\"bl b\" style=\"left:63px;top:616px;font-size:17.8px;max-width:297px\">29.2“三个代表”重要思想的形成过程（低频选择题）</span><span class=\"bl b\" style=\"left:87px;top:638px;font-size:16.1px;max-width:76px\">1.酝酿阶段：</span><span class=\"bl\" style=\"left:86px;top:659px;font-size:18.9px;max-width:424px\">从十三届四中全会提出加强党的建设到十五大提出新时期党的建设新的伟大工程</span><span class=\"bl\" style=\"left:64px;top:680px;font-size:16.1px;max-width:62px\">的总目标。</span><span class=\"bl b\" style=\"left:86px;top:701px;font-size:16.1px;max-width:77px\">2.正式提出：</span><span class=\"bl\" style=\"left:87px;top:721px;font-size:18.4px;max-width:394px\">2000年江泽民在广东考察时，首次对“三个代表”进行了比较全面的阐述。</span><span class=\"bl b\" style=\"left:86px;top:742px;font-size:16.1px;max-width:76px\">3.逐步深化：</span><span class=\"bl\" style=\"left:86px;top:763px;font-size:18.9px;max-width:423px\">党的十六大报告中，江泽民全面阐述了“三个代表”重要思想形成的时代背景、</span><span class=\"bl\" style=\"left:63px;top:784px;font-size:17.8px;max-width:248px\">历史地位、精神实质和指导意义，并列人党章。</span><span class=\"bl b\" style=\"left:85px;top:806px;font-size:15.6px;max-width:148px\">4.贯彻“三个代表”要求：</span><span class=\"bl\" style=\"left:86px;top:825px;font-size:18.9px;max-width:423px\">①关键在于坚持与时俱进。②核心在于保持党的先进性。③本质在于坚持执政</span><span class=\"bl\" style=\"left:62px;top:846px;font-size:17.8px;max-width:40px\">为民。</span><span class=\"bl b hl\" style=\"left:73px;top:886px;font-size:18.9px;max-width:67px\">考点30</span><span class=\"bl\" style=\"left:124px;top:886px;font-size:20.6px;max-width:332px\">“三个代表”重要思想的核心观点和主要内容☆☆</span><span class=\"bl b\" style=\"left:62px;top:921px;font-size:18.4px;max-width:295px\">30.1“三个代表”重要思想的核心观点（低频选择题）</span><span class=\"bl b\" style=\"left:85px;top:943px;font-size:16.1px;max-width:199px\">1.“三个代表”重要思想的基本问题：</span><span class=\"bl\" style=\"left:86px;top:963px;font-size:18.4px;max-width:280px\">创造性地回答了建设什么样的党、怎样建设党的问题</span><span class=\"bl b\" style=\"left:84px;top:984px;font-size:17.2px;max-width:201px\">2.“三个代表”重要思想的集中概括：</span><span class=\"bl\" style=\"left:85px;top:1005px;font-size:18.9px;max-width:423px\">中国共产党必须始终代表中国先进生产力的发展要求，代表中国先进文化的前进</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 40 页</div><span class=\"bl\" style=\"left:459px;top:58px;font-size:15.6px;max-width:244px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:106px;font-size:16.2px;max-width:211px\">方向，代表中国最广大人民的根本利益。</span><span class=\"bl\" style=\"left:77px;top:126px;font-size:17.9px;max-width:325px\">3.我们党站在时代前列，保持先进性的根本体现和根本要求：</span><span class=\"bl\" style=\"left:79px;top:147px;font-size:17.9px;max-width:356px\">始终代表中国先进生产力的发展要求，大力促进先进生产力的发展。</span><span class=\"bl b\" style=\"left:78px;top:170px;font-size:14.0px;max-width:195px\">4.我们全部工作的出发点和落脚点：</span><span class=\"bl\" style=\"left:79px;top:191px;font-size:14.0px;max-width:283px\">不断实现好、维护好、发展好最广大人民的根本利益。</span><span class=\"bl b\" style=\"left:78px;top:211px;font-size:17.3px;max-width:265px\">5.党和国家一切工作和方针政策的最高衡量标准：</span><span class=\"bl\" style=\"left:78px;top:232px;font-size:16.2px;max-width:205px\">是否符合最广大人民群众的根本利益。</span><span class=\"bl b\" style=\"left:55px;top:261px;font-size:14.0px;max-width:297px\">30.2“三个代表”重要思想的主要内容（低频选择题）</span><span class=\"bl\" style=\"left:79px;top:283px;font-size:14.0px;max-width:182px\">1.发展是党执政兴国的第一要务。</span><span class=\"bl\" style=\"left:78px;top:302px;font-size:15.6px;max-width:423px\">2.建立社会主义市场经济体制，党的十四大正式把建立社会主义市场经济体制</span><span class=\"bl\" style=\"left:56px;top:324px;font-size:14.0px;max-width:178px\">确立为我国经济体制改革的目标。</span><span class=\"bl\" style=\"left:79px;top:345px;font-size:14.0px;max-width:123px\">3.全面建设小康社会。</span><span class=\"bl\" style=\"left:79px;top:367px;font-size:14.0px;max-width:147px\">4.建设社会主义政治文明。</span><span class=\"bl\" style=\"left:79px;top:387px;font-size:14.0px;max-width:155px\">推进党的建设新的伟大工程。</span><span class=\"bl b hl\" style=\"left:67px;top:428px;font-size:18.4px;max-width:310px\">考点31“三个代表”重要思想的历史地位☆☆</span><span class=\"bl\" style=\"left:79px;top:455px;font-size:17.9px;max-width:354px\">1.“三个代表”重要思想是中国特色社会主义理论体系的接续发展。</span><span class=\"bl\" style=\"left:75px;top:475px;font-size:19.6px;max-width:428px\">“三个代表”重要思想是对马克思列宁主义、毛泽东思想和邓小平理论的继承和</span><span class=\"bl\" style=\"left:55px;top:497px;font-size:17.9px;max-width:448px\">发展，是中国特色社会主义理论体系的重要组成部分。始终做到“三个代表”，是我</span><span class=\"bl\" style=\"left:55px;top:518px;font-size:17.3px;max-width:217px\">们党的立党之本、执政之基、力量之源。</span><span class=\"bl\" style=\"left:79px;top:537px;font-size:19.0px;max-width:424px\">2.“三个代表”重要思想是加强和改进党的建设，推进中国特色社会主义事业的</span><span class=\"bl\" style=\"left:57px;top:562px;font-size:14.0px;max-width:88px\">强大理论武器。</span><span class=\"bl\" style=\"left:79px;top:580px;font-size:19.0px;max-width:427px\">“三个代表”重要思想在邓小平理论的基础上，进一步回答了什么是社会主义、</span><span class=\"bl\" style=\"left:56px;top:601px;font-size:18.4px;max-width:449px\">怎样建设社会主义的问题，创造性地回答了建设什么样的党、怎样建设党的问题，集</span><span class=\"bl\" style=\"left:57px;top:624px;font-size:15.1px;max-width:249px\">中起来就是深化了对中国特色社会主义的认识。</span><span class=\"bl\" style=\"left:57px;top:661px;font-size:15.6px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:71px;top:686px;font-size:17.3px;max-width:311px\">【2007.11】“三个代表”重要思想的根本出发点和落脚点是</span><span class=\"bl\" style=\"left:73px;top:708px;font-size:17.3px;max-width:130px\">A.实现社会主义现代化</span><span class=\"bl\" style=\"left:73px;top:729px;font-size:17.3px;max-width:153px\">B.发展社会主义社会生产力</span><span class=\"bl\" style=\"left:74px;top:751px;font-size:15.1px;max-width:211px\">C.发展社会主义民主，尊重和保障人权</span><span class=\"bl\" style=\"left:74px;top:771px;font-size:15.6px;max-width:259px\">D.实现人民愿望、满足人民需要、维护人民利益</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 41 页</div><span class=\"bl b acc\" style=\"left:357px;top:111px;font-size:25.6px;max-width:66px\">第七章</span><span class=\"bl\" style=\"left:339px;top:160px;font-size:22.8px;max-width:99px\">科学发展观</span><span class=\"bl\" style=\"left:65px;top:211px;font-size:18.4px;max-width:101px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:333px;top:254px;font-size:15.6px;max-width:167px\">考点32科学发展观的形成条件</span><span class=\"bl\" style=\"left:215px;top:273px;font-size:16.1px;max-width:69px\">科学发展观</span><span class=\"bl b hl\" style=\"left:333px;top:275px;font-size:15.0px;max-width:226px\">考点33科学发展观的科学内涵和主要内容</span><span class=\"bl b hl\" style=\"left:332px;top:295px;font-size:17.8px;max-width:168px\">考点34科学发展观的历史地位</span><span class=\"bl\" style=\"left:63px;top:345px;font-size:19.5px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:89px;top:372px;font-size:18.9px;max-width:462px\">本章论述科学发展观。本章在本科目中考频一般，考生掌握科学发展观的科学内涵即可。</span><span class=\"bl b hl\" style=\"left:75px;top:438px;font-size:18.4px;max-width:232px\">考点32科学发展观的形成条件</span><span class=\"bl\" style=\"left:671px;top:441px;font-size:15.0px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:473px;font-size:18.4px;max-width:223px\">32.1科学发展观的形成（低频选择题）</span><span class=\"bl b\" style=\"left:85px;top:494px;font-size:18.9px;max-width:419px\">1.科学发展观形成的现实依据：社会主义初级阶段基本国情和新的阶段性特征。</span><span class=\"bl b\" style=\"left:87px;top:515px;font-size:18.4px;max-width:424px\">2.科学发展观形成的实践基础：党带领人民战胜各种风险挑战、坚持和发展中</span><span class=\"bl\" style=\"left:64px;top:534px;font-size:23.9px;max-width:298px\">国特色社会主义的成功探索。工口</span><span class=\"bl b\" style=\"left:86px;top:556px;font-size:18.4px;max-width:395px\">3.科学发展观形成的时代背景：当今世界发展大势、国外发展的经验教训。</span><span class=\"bl b\" style=\"left:64px;top:585px;font-size:15.6px;max-width:163px\">32.2科学发展观的形成过程</span><span class=\"bl b\" style=\"left:87px;top:606px;font-size:18.4px;max-width:423px\">1.科学发展观首次提出的文件：十六届三中全会《中共中央关于完善社会主义</span><span class=\"bl\" style=\"left:65px;top:626px;font-size:17.2px;max-width:176px\">市场经济体制若干问题的决定》。</span><span class=\"bl b\" style=\"left:86px;top:647px;font-size:18.9px;max-width:425px\">2.科学发展观的形成：2004年3月，胡锦涛在中央人口资源环境座谈会上发表</span><span class=\"bl\" style=\"left:64px;top:669px;font-size:16.1px;max-width:74px\">的重要讲话。</span><span class=\"bl b\" style=\"left:86px;top:689px;font-size:17.8px;max-width:240px\">3.科学发展观进一步走向成熟：党的十七大。</span><span class=\"bl b hl\" style=\"left:75px;top:730px;font-size:18.9px;max-width:303px\">考点33科学发展观的科学内涵和主要内容☆</span><span class=\"bl b\" style=\"left:63px;top:765px;font-size:17.2px;max-width:236px\">33.1科学发展观的科学内涵（低频选择题）</span><span class=\"bl\" style=\"left:86px;top:786px;font-size:19.5px;max-width:424px\">科学发展观创造性地回答了：新形势下实现什么样的发展、怎样发展等重大问</span><span class=\"bl\" style=\"left:63px;top:807px;font-size:19.5px;max-width:447px\">题。科学发展观，第一要义是发展，核心立场是以人为本，基本要求是全面协调可持</span><span class=\"bl\" style=\"left:62px;top:828px;font-size:18.4px;max-width:310px\">续，根本方法是统筹兼顾。这是对科学发展观的集中概括。</span><span class=\"bl\" style=\"left:85px;top:848px;font-size:17.8px;max-width:247px\">1.推动经济社会发展是科学发展观的第一要义</span><span class=\"bl\" style=\"left:86px;top:869px;font-size:17.8px;max-width:250px\">坚持发展是硬道理的本质要求：坚持科学发展。</span><span class=\"bl\" style=\"left:85px;top:890px;font-size:17.2px;max-width:200px\">2.以人为本是科学发展观的核心立场</span><span class=\"bl\" style=\"left:85px;top:911px;font-size:17.2px;max-width:198px\">①科学发展观的核心立场：以人为本</span><span class=\"bl\" style=\"left:85px;top:931px;font-size:20.0px;max-width:423px\">②坚持以人为本，就要坚持发展为了人民，始终把最广大人民的根本利益放在</span><span class=\"bl\" style=\"left:62px;top:951px;font-size:20.6px;max-width:446px\">第一位；就要坚持发展依靠人民，从人民群众的伟大创造中汲取智慧和力量；就要</span><span class=\"bl\" style=\"left:61px;top:973px;font-size:19.5px;max-width:448px\">坚持发展成果由人民共享，着力提高人民物质文化生活水平；最终是为了实现人的</span><span class=\"bl\" style=\"left:60px;top:992px;font-size:18.4px;max-width:64px\">全面发展。</span></div></div>"}],pages:[39,41]};
  D["mzt_s8"] = {id:"mzt_s8",ch:"毛中特讲义 · 第七章 科学发展观",title:"第七章 科学发展观",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 41 页</div><span class=\"bl b acc\" style=\"left:357px;top:111px;font-size:25.6px;max-width:66px\">第七章</span><span class=\"bl\" style=\"left:339px;top:160px;font-size:22.8px;max-width:99px\">科学发展观</span><span class=\"bl\" style=\"left:65px;top:211px;font-size:18.4px;max-width:101px\">考点逻辑总览</span><span class=\"bl b hl\" style=\"left:333px;top:254px;font-size:15.6px;max-width:167px\">考点32科学发展观的形成条件</span><span class=\"bl\" style=\"left:215px;top:273px;font-size:16.1px;max-width:69px\">科学发展观</span><span class=\"bl b hl\" style=\"left:333px;top:275px;font-size:15.0px;max-width:226px\">考点33科学发展观的科学内涵和主要内容</span><span class=\"bl b hl\" style=\"left:332px;top:295px;font-size:17.8px;max-width:168px\">考点34科学发展观的历史地位</span><span class=\"bl\" style=\"left:63px;top:345px;font-size:19.5px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:89px;top:372px;font-size:18.9px;max-width:462px\">本章论述科学发展观。本章在本科目中考频一般，考生掌握科学发展观的科学内涵即可。</span><span class=\"bl b hl\" style=\"left:75px;top:438px;font-size:18.4px;max-width:232px\">考点32科学发展观的形成条件</span><span class=\"bl\" style=\"left:671px;top:441px;font-size:15.0px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:473px;font-size:18.4px;max-width:223px\">32.1科学发展观的形成（低频选择题）</span><span class=\"bl b\" style=\"left:85px;top:494px;font-size:18.9px;max-width:419px\">1.科学发展观形成的现实依据：社会主义初级阶段基本国情和新的阶段性特征。</span><span class=\"bl b\" style=\"left:87px;top:515px;font-size:18.4px;max-width:424px\">2.科学发展观形成的实践基础：党带领人民战胜各种风险挑战、坚持和发展中</span><span class=\"bl\" style=\"left:64px;top:534px;font-size:23.9px;max-width:298px\">国特色社会主义的成功探索。工口</span><span class=\"bl b\" style=\"left:86px;top:556px;font-size:18.4px;max-width:395px\">3.科学发展观形成的时代背景：当今世界发展大势、国外发展的经验教训。</span><span class=\"bl b\" style=\"left:64px;top:585px;font-size:15.6px;max-width:163px\">32.2科学发展观的形成过程</span><span class=\"bl b\" style=\"left:87px;top:606px;font-size:18.4px;max-width:423px\">1.科学发展观首次提出的文件：十六届三中全会《中共中央关于完善社会主义</span><span class=\"bl\" style=\"left:65px;top:626px;font-size:17.2px;max-width:176px\">市场经济体制若干问题的决定》。</span><span class=\"bl b\" style=\"left:86px;top:647px;font-size:18.9px;max-width:425px\">2.科学发展观的形成：2004年3月，胡锦涛在中央人口资源环境座谈会上发表</span><span class=\"bl\" style=\"left:64px;top:669px;font-size:16.1px;max-width:74px\">的重要讲话。</span><span class=\"bl b\" style=\"left:86px;top:689px;font-size:17.8px;max-width:240px\">3.科学发展观进一步走向成熟：党的十七大。</span><span class=\"bl b hl\" style=\"left:75px;top:730px;font-size:18.9px;max-width:303px\">考点33科学发展观的科学内涵和主要内容☆</span><span class=\"bl b\" style=\"left:63px;top:765px;font-size:17.2px;max-width:236px\">33.1科学发展观的科学内涵（低频选择题）</span><span class=\"bl\" style=\"left:86px;top:786px;font-size:19.5px;max-width:424px\">科学发展观创造性地回答了：新形势下实现什么样的发展、怎样发展等重大问</span><span class=\"bl\" style=\"left:63px;top:807px;font-size:19.5px;max-width:447px\">题。科学发展观，第一要义是发展，核心立场是以人为本，基本要求是全面协调可持</span><span class=\"bl\" style=\"left:62px;top:828px;font-size:18.4px;max-width:310px\">续，根本方法是统筹兼顾。这是对科学发展观的集中概括。</span><span class=\"bl\" style=\"left:85px;top:848px;font-size:17.8px;max-width:247px\">1.推动经济社会发展是科学发展观的第一要义</span><span class=\"bl\" style=\"left:86px;top:869px;font-size:17.8px;max-width:250px\">坚持发展是硬道理的本质要求：坚持科学发展。</span><span class=\"bl\" style=\"left:85px;top:890px;font-size:17.2px;max-width:200px\">2.以人为本是科学发展观的核心立场</span><span class=\"bl\" style=\"left:85px;top:911px;font-size:17.2px;max-width:198px\">①科学发展观的核心立场：以人为本</span><span class=\"bl\" style=\"left:85px;top:931px;font-size:20.0px;max-width:423px\">②坚持以人为本，就要坚持发展为了人民，始终把最广大人民的根本利益放在</span><span class=\"bl\" style=\"left:62px;top:951px;font-size:20.6px;max-width:446px\">第一位；就要坚持发展依靠人民，从人民群众的伟大创造中汲取智慧和力量；就要</span><span class=\"bl\" style=\"left:61px;top:973px;font-size:19.5px;max-width:448px\">坚持发展成果由人民共享，着力提高人民物质文化生活水平；最终是为了实现人的</span><span class=\"bl\" style=\"left:60px;top:992px;font-size:18.4px;max-width:64px\">全面发展。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1098px\"><div class=\"bxnum\">第 42 页</div><span class=\"bl\" style=\"left:460px;top:60px;font-size:15.1px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:78px;top:107px;font-size:17.3px;max-width:236px\">3.全面协调可持续是科学发展观的基本要求</span><span class=\"bl\" style=\"left:79px;top:129px;font-size:14.0px;max-width:199px\">4.统筹兼顾是科学发展观的根本方法</span><span class=\"bl b\" style=\"left:55px;top:157px;font-size:15.1px;max-width:242px\">33.2科学发展观的主要内容（低频选择题）</span><span class=\"bl\" style=\"left:79px;top:178px;font-size:15.6px;max-width:142px\">1.加快转变经济发展方式</span><span class=\"bl\" style=\"left:80px;top:197px;font-size:16.2px;max-width:424px\">推动经济持续健康发展，必须坚持以科学发展为主题，以加快转变经济发展方式</span><span class=\"bl\" style=\"left:56px;top:218px;font-size:17.9px;max-width:343px\">为主线。全面深化经济体制改革是加快转变经济发展方式的关键。</span><span class=\"bl\" style=\"left:79px;top:240px;font-size:17.3px;max-width:142px\">2.发展社会主义民主政治</span><span class=\"bl\" style=\"left:79px;top:260px;font-size:18.4px;max-width:424px\">人民民主是社会主义的生命，是我们党始终高扬的光辉旗帜。科学发展观强调，</span><span class=\"bl\" style=\"left:56px;top:281px;font-size:18.4px;max-width:447px\">社会主义民主政治的本质和核心是人民当家作主。发展社会主义民主政治，必须坚定</span><span class=\"bl\" style=\"left:57px;top:303px;font-size:16.2px;max-width:446px\">不移地走中国特色社会主义政治发展道路，坚持党的领导、人民当家作主、依法治国</span><span class=\"bl\" style=\"left:56px;top:324px;font-size:17.9px;max-width:73px\">的有机统一。</span><span class=\"bl\" style=\"left:79px;top:346px;font-size:15.6px;max-width:166px\">3.推进社会主义文化强国建设</span><span class=\"bl\" style=\"left:82px;top:365px;font-size:18.4px;max-width:421px\">文化是民族的血脉，是人民的精神家园。科学发展观强调，要树立高度的文化自</span><span class=\"bl\" style=\"left:57px;top:386px;font-size:18.4px;max-width:447px\">觉和文化自信，加快建设与我国深厚文化底蕴和丰富文化资源相匹配、与中国特色社</span><span class=\"bl\" style=\"left:58px;top:407px;font-size:17.3px;max-width:447px\">会主义事业总体布局相适应、与建设富强民主文明和谐的社会主义现代化国家的目标</span><span class=\"bl\" style=\"left:57px;top:429px;font-size:16.2px;max-width:157px\">相承接的社会主义文化强国。</span><span class=\"bl\" style=\"left:81px;top:452px;font-size:14.0px;max-width:140px\">4.构建社会主义和谐社会</span><span class=\"bl\" style=\"left:82px;top:471px;font-size:17.3px;max-width:237px\">①中国特色社会主义的本质属性：社会和谐。</span><span class=\"bl\" style=\"left:81px;top:490px;font-size:19.5px;max-width:424px\">②构建社会主义和谐社会的总要求：民主法治、公平正义、诚信友爱、充满活</span><span class=\"bl\" style=\"left:58px;top:513px;font-size:17.3px;max-width:191px\">力、安定有序、人与自然和谐相处。</span><span class=\"bl\" style=\"left:80px;top:532px;font-size:24.6px;max-width:225px\">5.推进生态文明建设士工T汇</span><span class=\"bl\" style=\"left:83px;top:553px;font-size:19.5px;max-width:423px\">良好生态环境是人和社会持续发展的根本基础。建设生态文明建设实质上就是要</span><span class=\"bl\" style=\"left:58px;top:577px;font-size:15.1px;max-width:191px\">建设资源节约型和环境友好型社会。</span><span class=\"bl\" style=\"left:81px;top:597px;font-size:16.2px;max-width:178px\">6.全面提高党的建设科学化水平</span><span class=\"bl\" style=\"left:82px;top:618px;font-size:17.3px;max-width:239px\">党执政后的一项根本建设是：执政能力建设。</span><span class=\"bl\" style=\"left:83px;top:637px;font-size:18.4px;max-width:402px\">马克思主义政党自身建设的根本任务和永恒课题是：保持和发展党的先进性。</span><span class=\"bl b hl\" style=\"left:70px;top:678px;font-size:20.7px;max-width:312px\">考点34科学发展观的历史地位☆（2013-22）</span><span class=\"bl\" style=\"left:83px;top:707px;font-size:18.4px;max-width:298px\">1.科学发展观是中国特色社会主义理论体系的接续发展。</span><span class=\"bl\" style=\"left:82px;top:728px;font-size:18.4px;max-width:346px\">2.科学发展观是发展中国特色社会主义必须长期坚持的指导思想。</span><span class=\"bl\" style=\"left:60px;top:765px;font-size:17.9px;max-width:100px\">经典真题回顾</span><span class=\"bl\" style=\"left:73px;top:791px;font-size:17.9px;max-width:199px\">【2009.11】科学发展观的根本方法是</span><span class=\"bl\" style=\"left:77px;top:813px;font-size:16.2px;max-width:129px\">A.把发展作为第一要义</span><span class=\"bl\" style=\"left:226px;top:813px;font-size:16.2px;max-width:72px\">B.以人为本</span><span class=\"bl\" style=\"left:76px;top:835px;font-size:16.2px;max-width:71px\">C.统筹兼顾</span><span class=\"bl\" style=\"left:226px;top:833px;font-size:17.9px;max-width:96px\">D.全面协调发展</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 43 页</div><span class=\"bl b acc\" style=\"left:355px;top:112px;font-size:25.6px;max-width:65px\">第八章</span><span class=\"bl\" style=\"left:183px;top:161px;font-size:22.8px;max-width:410px\">习近平新时代中国特色社会主义思想及其历史地位</span><span class=\"bl\" style=\"left:64px;top:211px;font-size:16.1px;max-width:100px\">■考点逻辑总览</span><span class=\"bl\" style=\"left:222px;top:262px;font-size:15.6px;max-width:114px\">习近平新时代中国特</span><span class=\"bl b hl\" style=\"left:386px;top:262px;font-size:17.2px;max-width:213px\">考点35中国特色社会主义进入新时代</span><span class=\"bl\" style=\"left:221px;top:281px;font-size:17.8px;max-width:114px\">色社会主义思想创立</span><span class=\"bl b hl\" style=\"left:386px;top:282px;font-size:17.2px;max-width:177px\">考点36世界百年未有之大变局</span><span class=\"bl\" style=\"left:232px;top:302px;font-size:17.8px;max-width:92px\">的社会历史条件</span><span class=\"bl b hl\" style=\"left:387px;top:304px;font-size:17.2px;max-width:235px\">考点37中华民族伟大复兴正处于关键时期</span><span class=\"bl\" style=\"left:86px;top:319px;font-size:14.5px;max-width:79px\">习近平新时代</span><span class=\"bl\" style=\"left:85px;top:339px;font-size:16.1px;max-width:80px\">中国特色社会</span><span class=\"bl\" style=\"left:221px;top:349px;font-size:15.6px;max-width:114px\">习近平新时代中国特</span><span class=\"bl b hl\" style=\"left:386px;top:350px;font-size:15.6px;max-width:305px\">考点38习近平新时代中国特色社会主义思想的核心要义</span><span class=\"bl\" style=\"left:84px;top:358px;font-size:17.8px;max-width:81px\">主义思想及其</span><span class=\"bl\" style=\"left:221px;top:369px;font-size:15.6px;max-width:114px\">色社会主义思想的科</span><span class=\"bl b hl\" style=\"left:386px;top:370px;font-size:17.8px;max-width:306px\">考点39习近平新时代中国特色社会主义思想的主要内容</span><span class=\"bl\" style=\"left:97px;top:380px;font-size:16.1px;max-width:56px\">历史地位</span><span class=\"bl\" style=\"left:255px;top:389px;font-size:17.8px;max-width:46px\">学体系</span><span class=\"bl b hl\" style=\"left:385px;top:390px;font-size:20.0px;max-width:308px\">考点40习近平新时代中国特色社会主义思想的理论特质</span><span class=\"bl b hl\" style=\"left:222px;top:435px;font-size:18.3px;max-width:307px\">考点41习近平新时代中国特色社会主义思想的历史地位</span><span class=\"bl\" style=\"left:240px;top:476px;font-size:42.8px;max-width:239px\">号：dikv66</span><span class=\"bl\" style=\"left:61px;top:494px;font-size:19.5px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:86px;top:522px;font-size:20.6px;max-width:623px\">本章主要阐述习近平新时代中国特色社会主义思想及其历史地位。本章在本科目中考频较高，考试形式既可能为选择</span><span class=\"bl\" style=\"left:63px;top:542px;font-size:21.7px;max-width:645px\">题，也可能为材料分析题。考生在复习过程中，要重点掌握我国社会主要矛盾的变化、习近平新时代中国特色社会主义思想</span><span class=\"bl\" style=\"left:62px;top:562px;font-size:20.0px;max-width:377px\">的核心要义、习近平新时代中国特色社会主义思想的历史地位等内容。</span><span class=\"bl b hl\" style=\"left:71px;top:615px;font-size:21.1px;max-width:305px\">考点35中国特色社会主义进入新时代 ☆☆☆</span><span class=\"bl\" style=\"left:667px;top:621px;font-size:15.0px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:61px;top:652px;font-size:17.8px;max-width:347px\">35.1党的十八大以来的历史性成就和历史性变革（中频选择题）</span><span class=\"bl\" style=\"left:84px;top:672px;font-size:19.5px;max-width:423px\">党的十八大召开至今已经十年了。十年来，我们经历了对党和人民事业具有重大</span><span class=\"bl\" style=\"left:62px;top:692px;font-size:20.0px;max-width:446px\">现实意义和深远历史意义的三件大事：一是迎来中国共产党成立一百周年，二是中国</span><span class=\"bl\" style=\"left:61px;top:713px;font-size:20.0px;max-width:447px\">特色社会主义进人新时代，三是完成脱贫攻坚、全面建成小康社会的历史任务，实现</span><span class=\"bl\" style=\"left:61px;top:735px;font-size:20.0px;max-width:447px\">第一个百年奋斗目标。这是中国共产党和中国人民团结奋斗赢得的历史性胜利，是彪</span><span class=\"bl\" style=\"left:61px;top:756px;font-size:18.9px;max-width:403px\">炳中华民族发展史册的历史性胜利，也是对世界具有深远影响的历史性胜利。</span><span class=\"bl\" style=\"left:84px;top:777px;font-size:19.5px;max-width:423px\">新时代十年的伟大变革，在党史、新中国史、改革开放史、社会主义发展史、中</span><span class=\"bl\" style=\"left:61px;top:797px;font-size:20.6px;max-width:445px\">华民族发展史上具有里程碑意义。走过百年奋斗历程的中国共产党在革命性锻造中更</span><span class=\"bl\" style=\"left:60px;top:818px;font-size:20.6px;max-width:445px\">加坚强有力，在坚持和发展中国特色社会主义的历史进程中始终成为坚强领导核心。</span><span class=\"bl\" style=\"left:60px;top:838px;font-size:20.6px;max-width:446px\">中国人民的前进动力更加强大、奋斗精神更加昂扬、必胜信念更加坚定，中国共产党</span><span class=\"bl\" style=\"left:60px;top:859px;font-size:20.0px;max-width:446px\">和中国人民正信心百倍推进中华民族从站起来、富起来到强起来的伟大飞跃。改革开</span><span class=\"bl\" style=\"left:60px;top:880px;font-size:20.0px;max-width:446px\">放和社会主义现代化建设深人推进，实现中华民族伟大复兴进人了不可逆转的历史进</span><span class=\"bl\" style=\"left:59px;top:901px;font-size:20.0px;max-width:447px\">程。科学社会主义在二十一世纪的中国焕发出新的蓬勃生机，中国式现代化为人类实</span><span class=\"bl\" style=\"left:59px;top:921px;font-size:20.6px;max-width:446px\">现现代化提供了新的选择，中国共产党和中国人民为解决人类面临的共同问题提供更</span><span class=\"bl\" style=\"left:59px;top:942px;font-size:21.1px;max-width:447px\">多更好的中国智慧、中国方案、中国力量，为人类和平与发展崇高事业作出新的更大</span><span class=\"bl\" style=\"left:59px;top:963px;font-size:15.0px;max-width:50px\">的贡献！</span></div></div>"}],pages:[41,43]};
  D["mzt_s9"] = {id:"mzt_s9",ch:"毛中特讲义 · 第八章 习近平新时代中国特色社会主义思想及其历史地位",title:"第八章 习近平新时代中国特色社会主义思想及其历史地位",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 43 页</div><span class=\"bl b acc\" style=\"left:355px;top:112px;font-size:25.6px;max-width:65px\">第八章</span><span class=\"bl\" style=\"left:183px;top:161px;font-size:22.8px;max-width:410px\">习近平新时代中国特色社会主义思想及其历史地位</span><span class=\"bl\" style=\"left:64px;top:211px;font-size:16.1px;max-width:100px\">■考点逻辑总览</span><span class=\"bl\" style=\"left:222px;top:262px;font-size:15.6px;max-width:114px\">习近平新时代中国特</span><span class=\"bl b hl\" style=\"left:386px;top:262px;font-size:17.2px;max-width:213px\">考点35中国特色社会主义进入新时代</span><span class=\"bl\" style=\"left:221px;top:281px;font-size:17.8px;max-width:114px\">色社会主义思想创立</span><span class=\"bl b hl\" style=\"left:386px;top:282px;font-size:17.2px;max-width:177px\">考点36世界百年未有之大变局</span><span class=\"bl\" style=\"left:232px;top:302px;font-size:17.8px;max-width:92px\">的社会历史条件</span><span class=\"bl b hl\" style=\"left:387px;top:304px;font-size:17.2px;max-width:235px\">考点37中华民族伟大复兴正处于关键时期</span><span class=\"bl\" style=\"left:86px;top:319px;font-size:14.5px;max-width:79px\">习近平新时代</span><span class=\"bl\" style=\"left:85px;top:339px;font-size:16.1px;max-width:80px\">中国特色社会</span><span class=\"bl\" style=\"left:221px;top:349px;font-size:15.6px;max-width:114px\">习近平新时代中国特</span><span class=\"bl b hl\" style=\"left:386px;top:350px;font-size:15.6px;max-width:305px\">考点38习近平新时代中国特色社会主义思想的核心要义</span><span class=\"bl\" style=\"left:84px;top:358px;font-size:17.8px;max-width:81px\">主义思想及其</span><span class=\"bl\" style=\"left:221px;top:369px;font-size:15.6px;max-width:114px\">色社会主义思想的科</span><span class=\"bl b hl\" style=\"left:386px;top:370px;font-size:17.8px;max-width:306px\">考点39习近平新时代中国特色社会主义思想的主要内容</span><span class=\"bl\" style=\"left:97px;top:380px;font-size:16.1px;max-width:56px\">历史地位</span><span class=\"bl\" style=\"left:255px;top:389px;font-size:17.8px;max-width:46px\">学体系</span><span class=\"bl b hl\" style=\"left:385px;top:390px;font-size:20.0px;max-width:308px\">考点40习近平新时代中国特色社会主义思想的理论特质</span><span class=\"bl b hl\" style=\"left:222px;top:435px;font-size:18.3px;max-width:307px\">考点41习近平新时代中国特色社会主义思想的历史地位</span><span class=\"bl\" style=\"left:240px;top:476px;font-size:42.8px;max-width:239px\">号：dikv66</span><span class=\"bl\" style=\"left:61px;top:494px;font-size:19.5px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:86px;top:522px;font-size:20.6px;max-width:623px\">本章主要阐述习近平新时代中国特色社会主义思想及其历史地位。本章在本科目中考频较高，考试形式既可能为选择</span><span class=\"bl\" style=\"left:63px;top:542px;font-size:21.7px;max-width:645px\">题，也可能为材料分析题。考生在复习过程中，要重点掌握我国社会主要矛盾的变化、习近平新时代中国特色社会主义思想</span><span class=\"bl\" style=\"left:62px;top:562px;font-size:20.0px;max-width:377px\">的核心要义、习近平新时代中国特色社会主义思想的历史地位等内容。</span><span class=\"bl b hl\" style=\"left:71px;top:615px;font-size:21.1px;max-width:305px\">考点35中国特色社会主义进入新时代 ☆☆☆</span><span class=\"bl\" style=\"left:667px;top:621px;font-size:15.0px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:61px;top:652px;font-size:17.8px;max-width:347px\">35.1党的十八大以来的历史性成就和历史性变革（中频选择题）</span><span class=\"bl\" style=\"left:84px;top:672px;font-size:19.5px;max-width:423px\">党的十八大召开至今已经十年了。十年来，我们经历了对党和人民事业具有重大</span><span class=\"bl\" style=\"left:62px;top:692px;font-size:20.0px;max-width:446px\">现实意义和深远历史意义的三件大事：一是迎来中国共产党成立一百周年，二是中国</span><span class=\"bl\" style=\"left:61px;top:713px;font-size:20.0px;max-width:447px\">特色社会主义进人新时代，三是完成脱贫攻坚、全面建成小康社会的历史任务，实现</span><span class=\"bl\" style=\"left:61px;top:735px;font-size:20.0px;max-width:447px\">第一个百年奋斗目标。这是中国共产党和中国人民团结奋斗赢得的历史性胜利，是彪</span><span class=\"bl\" style=\"left:61px;top:756px;font-size:18.9px;max-width:403px\">炳中华民族发展史册的历史性胜利，也是对世界具有深远影响的历史性胜利。</span><span class=\"bl\" style=\"left:84px;top:777px;font-size:19.5px;max-width:423px\">新时代十年的伟大变革，在党史、新中国史、改革开放史、社会主义发展史、中</span><span class=\"bl\" style=\"left:61px;top:797px;font-size:20.6px;max-width:445px\">华民族发展史上具有里程碑意义。走过百年奋斗历程的中国共产党在革命性锻造中更</span><span class=\"bl\" style=\"left:60px;top:818px;font-size:20.6px;max-width:445px\">加坚强有力，在坚持和发展中国特色社会主义的历史进程中始终成为坚强领导核心。</span><span class=\"bl\" style=\"left:60px;top:838px;font-size:20.6px;max-width:446px\">中国人民的前进动力更加强大、奋斗精神更加昂扬、必胜信念更加坚定，中国共产党</span><span class=\"bl\" style=\"left:60px;top:859px;font-size:20.0px;max-width:446px\">和中国人民正信心百倍推进中华民族从站起来、富起来到强起来的伟大飞跃。改革开</span><span class=\"bl\" style=\"left:60px;top:880px;font-size:20.0px;max-width:446px\">放和社会主义现代化建设深人推进，实现中华民族伟大复兴进人了不可逆转的历史进</span><span class=\"bl\" style=\"left:59px;top:901px;font-size:20.0px;max-width:447px\">程。科学社会主义在二十一世纪的中国焕发出新的蓬勃生机，中国式现代化为人类实</span><span class=\"bl\" style=\"left:59px;top:921px;font-size:20.6px;max-width:446px\">现现代化提供了新的选择，中国共产党和中国人民为解决人类面临的共同问题提供更</span><span class=\"bl\" style=\"left:59px;top:942px;font-size:21.1px;max-width:447px\">多更好的中国智慧、中国方案、中国力量，为人类和平与发展崇高事业作出新的更大</span><span class=\"bl\" style=\"left:59px;top:963px;font-size:15.0px;max-width:50px\">的贡献！</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1090px\"><div class=\"bxnum\">第 44 页</div><span class=\"bl\" style=\"left:460px;top:56px;font-size:12.2px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:57px;top:103px;font-size:13.9px;max-width:228px\">35.2社会主要矛盾的变化（中频选择题）</span><span class=\"bl b\" style=\"left:80px;top:123px;font-size:15.0px;max-width:357px\">1.制定党的路线方针政策的基本依据：对社会主要矛盾的科学判断。</span><span class=\"bl b\" style=\"left:80px;top:146px;font-size:13.9px;max-width:170px\">2.党的八大提出社会主要矛盾：</span><span class=\"bl\" style=\"left:81px;top:166px;font-size:14.5px;max-width:378px\">①人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾。</span><span class=\"bl\" style=\"left:81px;top:186px;font-size:14.5px;max-width:421px\">②人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之</span><span class=\"bl\" style=\"left:57px;top:208px;font-size:14.5px;max-width:61px\">间的矛盾。</span><span class=\"bl b\" style=\"left:80px;top:228px;font-size:15.0px;max-width:422px\">3.党的十一届六中全会提出社会主要矛盾：人民日益增长的物质文化需要同落</span><span class=\"bl\" style=\"left:58px;top:251px;font-size:13.9px;max-width:198px\">后的社会生产之间的矛盾。（2010-5）</span><span class=\"bl b\" style=\"left:80px;top:270px;font-size:15.0px;max-width:423px\">4.党的十九大提出社会主要矛盾：人民日益增长的美好生活需要和不平衡不充</span><span class=\"bl\" style=\"left:58px;top:293px;font-size:12.2px;max-width:118px\">分的发展之间的矛盾。</span><span class=\"bl b\" style=\"left:82px;top:314px;font-size:12.2px;max-width:263px\">5.我国社会主要矛盾已经转化的依据：（2020-22）</span><span class=\"bl\" style=\"left:82px;top:332px;font-size:15.6px;max-width:421px\">①社会生产方面，我国进人社会主义初级阶段以来的“落后的社会生产”已经发</span><span class=\"bl\" style=\"left:58px;top:355px;font-size:12.2px;max-width:118px\">生了新的阶段性变化。</span><span class=\"bl\" style=\"left:82px;top:374px;font-size:15.0px;max-width:421px\">②社会需求方面，不久将全面建成小康社会，人民美好生活需要日益广泛，人民</span><span class=\"bl\" style=\"left:57px;top:395px;font-size:15.0px;max-width:445px\">群众对于日益增长的“物质文化需要”层次更高、内容范围更广，出现了阶段性的新</span><span class=\"bl\" style=\"left:57px;top:417px;font-size:15.0px;max-width:37px\">特征。</span><span class=\"bl\" style=\"left:82px;top:437px;font-size:15.0px;max-width:416px\">③影响满足人们美好生活需要的因素有很多，但主要是发展的不平衡不充分问题。</span><span class=\"bl b\" style=\"left:82px;top:459px;font-size:14.5px;max-width:216px\">6.我国社会主要矛盾的变化，没有改变：</span><span class=\"bl\" style=\"left:82px;top:479px;font-size:15.0px;max-width:421px\">我们对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初</span><span class=\"bl\" style=\"left:58px;top:500px;font-size:15.0px;max-width:445px\">级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变，必须坚持</span><span class=\"bl\" style=\"left:58px;top:521px;font-size:15.0px;max-width:333px\">党的基本路线，既不落后于时代，也不能脱离实际、超越阶段。</span><span class=\"bl\" style=\"left:82px;top:571px;font-size:14.5px;max-width:208px\">1.中国特色社会主义进入新时代的内涵</span><span class=\"bl\" style=\"left:83px;top:591px;font-size:16.1px;max-width:420px\">从历史脉络看，新时代是承前启后、继往开来、在新的历史条件下继续夺取中国</span><span class=\"bl\" style=\"left:58px;top:612px;font-size:15.0px;max-width:446px\">特色社会主义伟大胜利的时代。从实践主题看，新时代是决胜全面建成小康社会、进</span><span class=\"bl\" style=\"left:59px;top:632px;font-size:15.6px;max-width:445px\">而全面建设社会主义现代化强国的时代。从人民性来看，新时代是全国各族人民团结</span><span class=\"bl\" style=\"left:58px;top:653px;font-size:16.1px;max-width:445px\">奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代。从民族性来看，新时</span><span class=\"bl\" style=\"left:58px;top:674px;font-size:16.1px;max-width:446px\">代是全体中华儿女力同心、奋力实现中华民族伟大复兴中国梦的时代。从世界性来</span><span class=\"bl\" style=\"left:58px;top:695px;font-size:16.1px;max-width:401px\">看，新时代是我国日益走近世界舞台中央、不断为人类作出更大贡献的时代。</span><span class=\"bl\" style=\"left:82px;top:717px;font-size:14.5px;max-width:209px\">2.中国特色社会主义进入新时代的意义</span><span class=\"bl\" style=\"left:84px;top:737px;font-size:15.6px;max-width:421px\">①从中华民族复兴的历史进程看，意味着近代以来久经磨难的中华民族迎来了</span><span class=\"bl\" style=\"left:59px;top:757px;font-size:17.8px;max-width:446px\">从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景；</span><span class=\"bl\" style=\"left:59px;top:778px;font-size:16.1px;max-width:445px\">②从科学社会主义发展进程看，意味着科学社会主义在21世纪的中国焕发出强大生</span><span class=\"bl\" style=\"left:59px;top:799px;font-size:16.7px;max-width:446px\">机活力，在世界上高高举起了中国特色社会主义伟大旗帜。③从人类文明进程看，意</span><span class=\"bl\" style=\"left:59px;top:821px;font-size:15.6px;max-width:446px\">味着中国特色社会主义道路、理论、制度、文化不断发展，拓展了发展中国家走向现</span><span class=\"bl\" style=\"left:60px;top:841px;font-size:16.1px;max-width:445px\">代化的途径，给世界上那些既希望加快发展又希望保持自身独立性的国家和民族提供</span><span class=\"bl\" style=\"left:60px;top:862px;font-size:15.0px;max-width:307px\">了全新选择，为解决人类问题贡献了中国智慧和中国方案。</span><span class=\"bl b hl\" style=\"left:71px;top:903px;font-size:16.7px;max-width:231px\">考点36世界百年未有之大变局☆</span><span class=\"bl\" style=\"left:84px;top:929px;font-size:17.8px;max-width:421px\">世界百年未有之大变局正在加速演变。和平与发展仍然是时代主题，但是不稳定</span><span class=\"bl\" style=\"left:60px;top:950px;font-size:17.8px;max-width:446px\">性不确定性更加突出。在世界大变局中，中国成为世界格局演变的主要推动力量。大</span><span class=\"bl\" style=\"left:60px;top:971px;font-size:17.8px;max-width:446px\">变局带来大挑战，也带来大机遇。面对世情的深刻变化，中国共产党和中国人民迫切</span><span class=\"bl\" style=\"left:60px;top:992px;font-size:16.7px;max-width:445px\">需要因势而谋、应势而动、顺势而为的科学理论。习近平新时代中国特色社会主义思</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 45 页</div><div class=\"sidebox\" style=\"left:511px;top:701px;width:195px;height:231px\"></div><span class=\"bl\" style=\"left:65px;top:106px;font-size:14.5px;max-width:446px\">想，正是在把握世界发展大势、应对全球共同挑战、维护人类共同利益、完善全球治</span><span class=\"bl\" style=\"left:66px;top:128px;font-size:12.2px;max-width:212px\">理体系的过程中创立并不断丰富发展的。</span><span class=\"bl b hl\" style=\"left:75px;top:166px;font-size:18.3px;max-width:414px\">考点37中华民族伟大复兴正处于关键时期☆☆（中频选择题）</span><span class=\"bl\" style=\"left:89px;top:195px;font-size:15.0px;max-width:421px\">我国发展步人近代以来的最好时期，正处于实现中华民族伟大复兴的关键时期。</span><span class=\"bl\" style=\"left:65px;top:216px;font-size:15.0px;max-width:445px\">中国共产党是实现中华民族伟大复兴的根本保证。中国共产党和中国人民迫切需要</span><span class=\"bl\" style=\"left:65px;top:236px;font-size:15.6px;max-width:445px\">凝心聚力、谋篇布局、攻坚克难的科学理论。习近平新时代中国特色社会主义思想，</span><span class=\"bl\" style=\"left:65px;top:258px;font-size:15.0px;max-width:444px\">正是在中华民族迎来从站起来、富起来到强起来的伟大飞跃中，在不断推进党的自</span><span class=\"bl\" style=\"left:65px;top:278px;font-size:15.0px;max-width:445px\">我革命，实现党的自我净化、自我完善、自我革新、自我提高的过程中创立并不断</span><span class=\"bl\" style=\"left:65px;top:299px;font-size:15.6px;max-width:445px\">丰富发展的。习近平新时代中国特色社会主义思想，是党和人民实践经验和集体智</span><span class=\"bl\" style=\"left:65px;top:321px;font-size:14.5px;max-width:59px\">慧的结晶。</span><span class=\"bl b hl\" style=\"left:75px;top:359px;font-size:17.8px;max-width:401px\">考点38习近平新时代中国特色社会主义思想的核心要义☆☆</span><span class=\"bl\" style=\"left:88px;top:388px;font-size:15.6px;max-width:421px\">1.习近平同志对关系新时代党和国家事业发展的一系列重大理论和实践问题进行</span><span class=\"bl\" style=\"left:66px;top:409px;font-size:15.6px;max-width:443px\">了深邃思考和科学判断，就新时代坚持和发展什么样的中国特色社会主义、怎样坚持</span><span class=\"bl\" style=\"left:64px;top:430px;font-size:16.1px;max-width:446px\">和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现</span><span class=\"bl\" style=\"left:65px;top:451px;font-size:15.6px;max-width:445px\">代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主</span><span class=\"bl\" style=\"left:65px;top:472px;font-size:16.1px;max-width:445px\">义政党等重大时代课题，提出一系列原创性的治国理政新理念新思想新战略，是习近</span><span class=\"bl\" style=\"left:64px;top:492px;font-size:18.3px;max-width:412px\">平新时代中国特色社会主义思想的主要创立者。OKVO○</span><span class=\"bl\" style=\"left:86px;top:513px;font-size:17.2px;max-width:423px\">2.习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克</span><span class=\"bl\" style=\"left:64px;top:534px;font-size:16.1px;max-width:425px\">思主义，是中华文化和中国精神的时代精华，实现了马克思主义中国化新的飞跃。</span><span class=\"bl b\" style=\"left:84px;top:552px;font-size:23.4px;max-width:364px\">3.坚持和发展中国特色社会主义是：（2019-5）</span><span class=\"bl\" style=\"left:86px;top:577px;font-size:15.0px;max-width:273px\">①改革开放以来我们党全部理论和实践的鲜明主题。</span><span class=\"bl\" style=\"left:87px;top:597px;font-size:15.0px;max-width:249px\">②习近平新时代中国特色社会主义的核心要义。</span><span class=\"bl b hl\" style=\"left:73px;top:635px;font-size:20.0px;max-width:405px\">考点39习近平新时代中国特色社会主义思想的主要内容☆☆</span><span class=\"bl\" style=\"left:87px;top:665px;font-size:16.1px;max-width:421px\">习近平新时代中国特色社会主义思想的主要内容是党的十九大报告和党的十九届</span><span class=\"bl\" style=\"left:62px;top:687px;font-size:16.1px;max-width:446px\">六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》概括</span><span class=\"bl\" style=\"left:62px;top:708px;font-size:15.0px;max-width:187px\">的“十个明确”和“十四个坚持”。</span><span class=\"bl\" style=\"left:459px;top:710px;font-size:14.5px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:520px;top:707px;font-size:15.6px;max-width:102px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:519px;top:730px;font-size:14.5px;max-width:189px\">①“十个明确”：指导思想层面的表述，</span><span class=\"bl b\" style=\"left:62px;top:735px;font-size:17.2px;max-width:441px\">39.1“十个明确”是习近平新时代中国特色社会主义思想最重要、最核心的内容。</span><span class=\"bl\" style=\"left:519px;top:749px;font-size:14.5px;max-width:190px\">重点讲的是怎么看，回答的是新时代坚</span><span class=\"bl\" style=\"left:85px;top:757px;font-size:16.1px;max-width:422px\">1.明确中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义</span><span class=\"bl\" style=\"left:518px;top:766px;font-size:15.0px;max-width:190px\">持和发展什么样的中国特色社会主义的</span><span class=\"bl\" style=\"left:62px;top:777px;font-size:16.1px;max-width:445px\">制度的最大优势是中国共产党领导，中国共产党是最高政治领导力量，全党必须增强</span><span class=\"bl\" style=\"left:519px;top:785px;font-size:13.3px;max-width:33px\">问题。</span><span class=\"bl\" style=\"left:62px;top:798px;font-size:16.1px;max-width:287px\">“四个意识”、坚定“四个自信”、做到“两个维护”。</span><span class=\"bl\" style=\"left:518px;top:803px;font-size:15.6px;max-width:190px\">②“十四个坚持”：行动纲领层面的表</span><span class=\"bl\" style=\"left:84px;top:819px;font-size:16.1px;max-width:423px\">2.明确坚持和发展中国特色社会主义，总任务是实现社会主义现代化和中华民族</span><span class=\"bl\" style=\"left:518px;top:823px;font-size:12.2px;max-width:189px\">述，重点讲的是怎么办，回答的是新时</span><span class=\"bl\" style=\"left:62px;top:839px;font-size:17.2px;max-width:445px\">伟大复兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明</span><span class=\"bl\" style=\"left:518px;top:841px;font-size:12.2px;max-width:190px\">代怎样坚持和发展中国特色社会主义的</span><span class=\"bl\" style=\"left:62px;top:860px;font-size:17.8px;max-width:389px\">和谐美丽的社会主义现代化强国，以中国式现代化推进中华民族伟大复兴。</span><span class=\"bl\" style=\"left:518px;top:859px;font-size:13.3px;max-width:34px\">问题。</span><span class=\"bl\" style=\"left:84px;top:881px;font-size:17.2px;max-width:422px\">3.明确新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分</span><span class=\"bl\" style=\"left:517px;top:876px;font-size:14.5px;max-width:191px\">③“十个明确”和“十四个坚持”体现</span><span class=\"bl\" style=\"left:518px;top:894px;font-size:15.0px;max-width:190px\">了习近平新时代中国特色社会主义思想</span><span class=\"bl\" style=\"left:61px;top:901px;font-size:17.8px;max-width:446px\">的发展之间的矛盾，必须坚持以人民为中心的发展思想，发展全过程人民民主，推动</span><span class=\"bl\" style=\"left:517px;top:911px;font-size:17.2px;max-width:94px\">理论与实践的统一。</span><span class=\"bl\" style=\"left:61px;top:921px;font-size:17.2px;max-width:332px\">人的全面发展、全体人民共同富裕取得更为明显的实质性进展。</span><span class=\"bl\" style=\"left:83px;top:943px;font-size:18.3px;max-width:422px\">4.明确中国特色社会主义事业总体布局是经济建设、政治建设、文化建设、社会</span><span class=\"bl\" style=\"left:61px;top:963px;font-size:18.3px;max-width:446px\">建设、生态文明建设五位一体，战略布局是全面建设社会主义现代化国家、全面深化</span><span class=\"bl\" style=\"left:60px;top:984px;font-size:16.1px;max-width:250px\">改革、全面依法治国、全面从严治党四个全面。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 46 页</div><span class=\"bl\" style=\"left:458px;top:62px;font-size:12.2px;max-width:242px\">毛泽东患想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:76px;top:106px;font-size:15.0px;max-width:423px\">5.明确全面深化改革总目标是完善和发展中国特色社会主义制度、推进国家治理</span><span class=\"bl\" style=\"left:55px;top:129px;font-size:13.9px;max-width:130px\">体系和治理能力现代化。</span><span class=\"bl\" style=\"left:77px;top:149px;font-size:15.0px;max-width:423px\">6.明确全面推进依法治国总目标是建设中国特色社会主义法治体系、建设社会主</span><span class=\"bl\" style=\"left:55px;top:170px;font-size:14.5px;max-width:71px\">义法治国家。</span><span class=\"bl\" style=\"left:77px;top:190px;font-size:15.0px;max-width:423px\">7.明确必须坚持和完善社会主义基本经济制度，使市场在资源配置中起决定性作</span><span class=\"bl\" style=\"left:54px;top:211px;font-size:15.6px;max-width:446px\">用，更好发挥政府作用，把握新发展阶段，贯彻创新、协调、绿色、开放、共享的新</span><span class=\"bl\" style=\"left:54px;top:232px;font-size:15.0px;max-width:445px\">发展理念，加快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，</span><span class=\"bl\" style=\"left:55px;top:255px;font-size:12.2px;max-width:188px\">推动高质量发展，统筹发展和安全。</span><span class=\"bl\" style=\"left:77px;top:274px;font-size:15.0px;max-width:423px\">8.明确党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民</span><span class=\"bl\" style=\"left:55px;top:296px;font-size:13.9px;max-width:223px\">军队，把人民军队建设成为世界一流军队。</span><span class=\"bl\" style=\"left:77px;top:316px;font-size:15.6px;max-width:423px\">9.明确中国特色大国外交要服务民族复兴、促进人类进步，推动构建新型国际关</span><span class=\"bl\" style=\"left:55px;top:338px;font-size:13.9px;max-width:166px\">系，推动构建人类命运共同体。</span><span class=\"bl\" style=\"left:78px;top:357px;font-size:17.3px;max-width:423px\">10.明确全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的</span><span class=\"bl\" style=\"left:55px;top:378px;font-size:15.6px;max-width:445px\">政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深人</span><span class=\"bl\" style=\"left:55px;top:400px;font-size:15.6px;max-width:414px\">推进反腐败斗争，落实管党治党政治责任，以伟大自我革命引领伟大社会革命。</span><span class=\"bl b\" style=\"left:55px;top:428px;font-size:13.9px;max-width:259px\">39.2坚持和发展中国特色社会主义的基本方略</span><span class=\"bl\" style=\"left:79px;top:448px;font-size:15.6px;max-width:311px\">坚持和发展中国特色社会主义的基本方略：“十四个坚持”。</span><span class=\"bl\" style=\"left:78px;top:469px;font-size:17.3px;max-width:412px\">第一，坚持党对一切工作的领导。党政军民学，东西南北中，党是领导一切的。</span><span class=\"bl\" style=\"left:78px;top:491px;font-size:17.3px;max-width:145px\">第二，坚持以人民为中心。</span><span class=\"bl\" style=\"left:217px;top:488px;font-size:35.6px;max-width:260px\">次号：</span><span class=\"bl\" style=\"left:78px;top:511px;font-size:16.1px;max-width:143px\">第三，坚持全面深化改革。</span><span class=\"bl\" style=\"left:76px;top:529px;font-size:29.5px;max-width:284px\">第四，坚持新发展理念。工迎你</span><span class=\"bl\" style=\"left:78px;top:552px;font-size:17.8px;max-width:423px\">第五，坚持人民当家作主。坚持党的领导、人民当家作主、依法治国有机统一是</span><span class=\"bl\" style=\"left:56px;top:576px;font-size:13.9px;max-width:167px\">社会主义政治发展的必然要求。</span><span class=\"bl\" style=\"left:79px;top:594px;font-size:17.3px;max-width:423px\">第六，坚持全面依法治国。全面依法治国是中国特色社会主义的本质要求和重要</span><span class=\"bl\" style=\"left:56px;top:617px;font-size:15.0px;max-width:38px\">保障。</span><span class=\"bl\" style=\"left:80px;top:637px;font-size:15.0px;max-width:189px\">第七，坚持社会主义核心价值体系。</span><span class=\"bl\" style=\"left:80px;top:657px;font-size:16.1px;max-width:378px\">第八，坚持在发展中保障和改善民生。增进民生福社是发展的根本目的。</span><span class=\"bl\" style=\"left:80px;top:680px;font-size:13.9px;max-width:167px\">第九，坚持人与自然和谐共生。</span><span class=\"bl\" style=\"left:80px;top:701px;font-size:13.9px;max-width:154px\">第十，坚持总体国家安全观。</span><span class=\"bl\" style=\"left:79px;top:721px;font-size:17.3px;max-width:215px\">第十一，坚持党对人民军队的绝对领导。</span><span class=\"bl\" style=\"left:80px;top:741px;font-size:17.3px;max-width:237px\">第十二，坚持“一国两制”和推进祖国统一。</span><span class=\"bl\" style=\"left:80px;top:762px;font-size:15.6px;max-width:212px\">第十三，坚持推动构建人类命运共同体。</span><span class=\"bl\" style=\"left:80px;top:782px;font-size:18.4px;max-width:423px\">第十四，坚持全面从严治党。（我们党最鲜明的品格：勇于自我革命，从严管党</span><span class=\"bl\" style=\"left:56px;top:806px;font-size:15.0px;max-width:48px\">治党。）</span><span class=\"bl b hl\" style=\"left:67px;top:843px;font-size:20.6px;max-width:392px\">考点40 习近平新时代中国特色社会主义思想的理论特质☆</span><span class=\"bl\" style=\"left:81px;top:871px;font-size:18.9px;max-width:423px\">习近平新时代中国特色社会主义思想，充满着对马克思主义的坚定信仰，充满</span><span class=\"bl\" style=\"left:57px;top:892px;font-size:17.3px;max-width:445px\">着对社会主义和共产主义的坚定信念，展现了当代中国共产党人的政治品格、价值追</span><span class=\"bl\" style=\"left:57px;top:913px;font-size:17.8px;max-width:446px\">求、精神风范，彰显和贯穿着坚定的理想信念、真挚的人民情怀、高度的自觉自信、</span><span class=\"bl\" style=\"left:58px;top:933px;font-size:18.9px;max-width:445px\">无畏的担当精神、科学的思想方法。这一思想秉持人民至上；彰显历史自觉；坚持实</span><span class=\"bl\" style=\"left:57px;top:956px;font-size:16.1px;max-width:296px\">事求是；突出问题导向；强化战略思维；发扬斗争精神。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 47 页</div><span class=\"bl b hl\" style=\"left:77px;top:116px;font-size:17.3px;max-width:416px\">考点41习近平新时代中国特色社会主义思想的历史地位☆☆☆</span><span class=\"bl\" style=\"left:90px;top:144px;font-size:15.0px;max-width:240px\">1.当代中国马克思主义、21世纪马克思主义。</span><span class=\"bl\" style=\"left:90px;top:166px;font-size:15.0px;max-width:422px\">习近平新时代中国特色社会主义思想是新时代中国共产党的思想旗帜，是国家</span><span class=\"bl\" style=\"left:66px;top:186px;font-size:15.6px;max-width:446px\">政治生活和社会生活的根本指针，是引领中国、影响世界的当代中国马克思主义、21</span><span class=\"bl\" style=\"left:67px;top:208px;font-size:13.9px;max-width:95px\">世纪马克思主义。</span><span class=\"bl\" style=\"left:90px;top:228px;font-size:15.6px;max-width:422px\">习近平新时代中国特色社会主义思想以全新视野深化了对共产党执政规律、社会</span><span class=\"bl\" style=\"left:66px;top:249px;font-size:15.6px;max-width:445px\">主义建设规律和人类社会发展规律的认识，充分彰显了科学理论的强大生命力和中国</span><span class=\"bl\" style=\"left:66px;top:270px;font-size:15.6px;max-width:445px\">共产党人的理论创造力，是当代最现实最鲜活的马克思主义。在当代中国，坚持和发</span><span class=\"bl\" style=\"left:66px;top:291px;font-size:15.6px;max-width:446px\">展习近平新时代中国特色社会主义思想，就是真正坚持和发展马克思主义，就是真正</span><span class=\"bl\" style=\"left:66px;top:312px;font-size:13.9px;max-width:143px\">坚持和发展科学社会主义。</span><span class=\"bl\" style=\"left:90px;top:333px;font-size:13.9px;max-width:202px\">2.实现中华民族伟大复兴的行动指南。</span><span class=\"bl\" style=\"left:90px;top:352px;font-size:16.1px;max-width:421px\">①习近平新时代中国特色社会主义思想为新时代坚持和发展中国特色社会主义提</span><span class=\"bl\" style=\"left:66px;top:375px;font-size:13.9px;max-width:84px\">供了根本指引。</span><span class=\"bl\" style=\"left:90px;top:416px;font-size:15.6px;max-width:421px\">③习近平新时代中国特色社会主义思想为全面从严治党、把党建设成为中国特色</span><span class=\"bl\" style=\"left:65px;top:436px;font-size:16.1px;max-width:414px\">社会主义事业的坚强领导核心提供了强大思想武器。实现民族复兴，关键在党。</span><span class=\"bl\" style=\"left:88px;top:458px;font-size:14.5px;max-width:214px\">3.建设美好世界的中国智慧和中国方案。</span><span class=\"bl\" style=\"left:64px;top:492px;font-size:17.8px;max-width:101px\">■经典真题回顾</span><span class=\"bl\" style=\"left:65px;top:534px;font-size:17.8px;max-width:445px\">1.【2019.22】中国特色社会主义进人新时代，我国社会主要矛盾已经转化为人民日</span><span class=\"bl\" style=\"left:83px;top:556px;font-size:17.3px;max-width:428px\">益增长的美好生活需要和不平衡不充分的发展之间的矛盾。但是，我国社会主义</span><span class=\"bl\" style=\"left:81px;top:576px;font-size:17.3px;max-width:433px\">矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断，依据是（）</span><span class=\"bl\" style=\"left:81px;top:597px;font-size:15.6px;max-width:210px\">A.我国仍然是世界上最大的发展中国家</span><span class=\"bl\" style=\"left:81px;top:619px;font-size:14.5px;max-width:198px\">B.我国仍然面临极其复杂的国际环境</span><span class=\"bl\" style=\"left:81px;top:639px;font-size:15.0px;max-width:174px\">C.我国总体上仍处于不发达阶段</span><span class=\"bl\" style=\"left:81px;top:660px;font-size:17.3px;max-width:387px\">D.我国社会主要矛盾的变化只是社会主义初级阶段这个历史阶段中的变化</span><span class=\"bl\" style=\"left:65px;top:695px;font-size:17.8px;max-width:445px\">2.【2020.22】中国特色社会主义进人新时代，人民群众的新期特内容更广泛，不仅</span><span class=\"bl\" style=\"left:81px;top:717px;font-size:17.3px;max-width:429px\">关注“有没有”，更关注“好不好”；不仅包括既有的物质文化需求，更包括在此</span><span class=\"bl\" style=\"left:81px;top:738px;font-size:16.1px;max-width:430px\">基础上衍生出来的获得感、幸福感、安全感及尊严、权利等新需求。这一变化表</span><span class=\"bl\" style=\"left:80px;top:759px;font-size:13.9px;max-width:20px\">明</span><span class=\"bl\" style=\"left:80px;top:779px;font-size:15.6px;max-width:211px\">A.我国社会主要矛盾发生了历史性变化</span><span class=\"bl\" style=\"left:80px;top:800px;font-size:15.6px;max-width:233px\">B.我国已经满足了人民“从有到优”的需求</span><span class=\"bl\" style=\"left:80px;top:821px;font-size:15.6px;max-width:316px\">C.人民群众对日益增长的物质文化需要出现了阶段性新特征</span><span class=\"bl\" style=\"left:80px;top:842px;font-size:16.1px;max-width:341px\">D.我国不平衡不充分的发展已成为制约满足人民需要的主要根源</span><span class=\"bl\" style=\"left:63px;top:877px;font-size:17.3px;max-width:446px\">3.【2019.5】习近平新时代中国特色社会主义思想是对马克思列宁主义、毛泽东思</span><span class=\"bl\" style=\"left:80px;top:898px;font-size:17.8px;max-width:429px\">想、邓小平理论、“三个代表”重要思想、科学发展观的继承和发展，是马克思主</span><span class=\"bl\" style=\"left:80px;top:919px;font-size:17.3px;max-width:429px\">义中国化最新理论成果，是党和人民实践经验和集体智慧的结晶，是中国特色社</span><span class=\"bl\" style=\"left:80px;top:939px;font-size:17.8px;max-width:429px\">会主义理论体系的重要组成部分，是全党全国人民为实现中华民族伟大复兴而奋</span><span class=\"bl\" style=\"left:80px;top:959px;font-size:15.6px;max-width:208px\">斗的行动指南。这一思想的核心要义是</span><span class=\"bl\" style=\"left:84px;top:979px;font-size:19.5px;max-width:352px\">A.推进马克思主义中国化时代化大众化B.坚持以经济建设为中心</span><span class=\"bl\" style=\"left:85px;top:1001px;font-size:15.0px;max-width:174px\">C.坚持和发展中国特色社会主义</span><span class=\"bl\" style=\"left:297px;top:1003px;font-size:15.6px;max-width:128px\">D.实现社会主义现代化</span></div></div>"}],pages:[43,47]};
  D["mzt_s10"] = {id:"mzt_s10",ch:"毛中特讲义 · 第九章 坚持和发展中国特色社会主义的总任务",title:"第九章 坚持和发展中国特色社会主义的总任务",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 48 页</div><div class=\"sidebox\" style=\"left:507px;top:613px;width:194px;height:151px\"></div><span class=\"bl\" style=\"left:459px;top:61px;font-size:16.2px;max-width:245px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:346px;top:113px;font-size:25.8px;max-width:66px\">第九章</span><span class=\"bl\" style=\"left:218px;top:163px;font-size:21.3px;max-width:320px\">坚持和发展中国特色社会主义的总任务</span><span class=\"bl\" style=\"left:52px;top:214px;font-size:18.5px;max-width:102px\">■考点逻辑总览</span><span class=\"bl\" style=\"left:409px;top:257px;font-size:14.6px;max-width:79px\">中国梦的提出</span><span class=\"bl b hl\" style=\"left:222px;top:266px;font-size:17.9px;max-width:132px\">考点42实现中华民族</span><span class=\"bl\" style=\"left:409px;top:278px;font-size:15.7px;max-width:103px\">中国梦的科学内涵</span><span class=\"bl\" style=\"left:236px;top:288px;font-size:15.7px;max-width:103px\">伟大复兴的中国梦</span><span class=\"bl\" style=\"left:409px;top:300px;font-size:14.6px;max-width:90px\">奋力实现中国梦</span><span class=\"bl\" style=\"left:73px;top:328px;font-size:16.2px;max-width:92px\">坚持和发展中国</span><span class=\"bl b hl\" style=\"left:223px;top:340px;font-size:16.2px;max-width:131px\">考点43建成社会主义</span><span class=\"bl\" style=\"left:409px;top:341px;font-size:15.7px;max-width:234px\">开启全面建设社会主义现代化强国的新征程</span><span class=\"bl\" style=\"left:74px;top:351px;font-size:14.6px;max-width:91px\">特色社会主义的</span><span class=\"bl\" style=\"left:224px;top:361px;font-size:15.7px;max-width:128px\">现代化强国的战略安排</span><span class=\"bl\" style=\"left:408px;top:361px;font-size:17.4px;max-width:282px\">实现社会主义现代化强国“两步走”战略的具体安排</span><span class=\"bl\" style=\"left:95px;top:369px;font-size:19.0px;max-width:47px\">总任务</span><span class=\"bl\" style=\"left:409px;top:403px;font-size:14.6px;max-width:91px\">立足新发展阶段</span><span class=\"bl b hl\" style=\"left:223px;top:412px;font-size:16.2px;max-width:131px\">考点44建设社会主义</span><span class=\"bl\" style=\"left:409px;top:424px;font-size:14.6px;max-width:90px\">贯彻新发展理念</span><span class=\"bl\" style=\"left:224px;top:434px;font-size:15.7px;max-width:128px\">现代化国家的战略导向</span><span class=\"bl\" style=\"left:408px;top:445px;font-size:14.6px;max-width:91px\">构建新发展格局</span><span class=\"bl\" style=\"left:52px;top:495px;font-size:18.5px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:77px;top:523px;font-size:16.2px;max-width:626px\">本章主要阐述坚持和发展中国特色社会主义的总任务。本章在本科目中的考频较高，考生形式既可能为选择题，也可</span><span class=\"bl\" style=\"left:54px;top:545px;font-size:14.0px;max-width:649px\">能为材料分析题。考生在复习过程中，要重点掌握中国梦的科学内涵、实现社会主义现代化强国“两步走”战略的具体安</span><span class=\"bl\" style=\"left:54px;top:565px;font-size:14.6px;max-width:79px\">排等内容。</span><span class=\"bl b hl\" style=\"left:64px;top:619px;font-size:18.5px;max-width:306px\">考点42 实现中华民族伟大复兴的中国梦☆☆</span><span class=\"bl\" style=\"left:661px;top:619px;font-size:17.4px;max-width:41px\">记笔记</span><span class=\"bl b\" style=\"left:53px;top:654px;font-size:17.9px;max-width:109px\">42.1中国梦的提出</span><span class=\"bl\" style=\"left:514px;top:650px;font-size:14.0px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:453px;top:656px;font-size:15.1px;max-width:47px\">拓展1</span><span class=\"bl b\" style=\"left:77px;top:677px;font-size:14.0px;max-width:424px\">1.坚持和发展中国特色社会主义的总任务：实现社会主义现代化和中华民族伟大</span><span class=\"bl\" style=\"left:513px;top:673px;font-size:14.0px;max-width:190px\">习近平引用三句诗，生动诠释了近代以来</span><span class=\"bl\" style=\"left:513px;top:691px;font-size:14.0px;max-width:181px\">中国人民寻梦、追梦、圆梦的历史进程：</span><span class=\"bl\" style=\"left:53px;top:697px;font-size:17.9px;max-width:35px\">复兴</span><span class=\"bl\" style=\"left:514px;top:711px;font-size:12.3px;max-width:184px\">①中华民族的昨天，“雄关漫道真如铁”。</span><span class=\"bl b\" style=\"left:77px;top:719px;font-size:14.0px;max-width:424px\">2.中国梦的提出：2012年11月29日，习近平在参观《复兴之路》展览时提出：</span><span class=\"bl\" style=\"left:513px;top:728px;font-size:14.0px;max-width:184px\">②中华民族的今天，“人间正道是沧桑”。</span><span class=\"bl\" style=\"left:54px;top:739px;font-size:15.7px;max-width:348px\">“实现中华民族伟大复兴，就是中华民族近代以来最伟大的梦想。”</span><span class=\"bl\" style=\"left:513px;top:746px;font-size:14.0px;max-width:185px\">③中华民族的明天，“长风破浪会有时”。</span><span class=\"bl b\" style=\"left:77px;top:762px;font-size:14.0px;max-width:242px\">3.提出中国梦这一重要战略思想的重要意义：</span><span class=\"bl\" style=\"left:77px;top:782px;font-size:15.1px;max-width:424px\">①中国梦，反映了近代以来一代又一代中国人的美好夙愿，进一步揭示了中华民</span><span class=\"bl\" style=\"left:54px;top:803px;font-size:15.7px;max-width:428px\">族的历史命运和当代中国的发展走向，指明了全党全国各族人民共同的奋斗目标。</span><span class=\"bl\" style=\"left:78px;top:824px;font-size:15.7px;max-width:425px\">②这一重要战略思想，是以习近平同志为核心的党中央对全体人民的庄严承诺，</span><span class=\"bl\" style=\"left:54px;top:844px;font-size:17.4px;max-width:449px\">是党和国家面向未来的政治宣言，充分体现了我们党高度的历史担当和使命追求，为</span><span class=\"bl\" style=\"left:54px;top:866px;font-size:15.7px;max-width:251px\">坚持和发展中国特色社会主义注人了崭新内涵。</span><span class=\"bl b\" style=\"left:54px;top:894px;font-size:15.7px;max-width:138px\">42.2中国梦的科学内涵</span><span class=\"bl b\" style=\"left:78px;top:916px;font-size:14.0px;max-width:122px\">1.中国梦的科学内涵：</span><span class=\"bl\" style=\"left:515px;top:926px;font-size:15.7px;max-width:105px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:77px;top:935px;font-size:17.4px;max-width:270px\">①中国梦的本质：国家富强、民族振兴、人民幸福</span><span class=\"bl\" style=\"left:454px;top:936px;font-size:14.6px;max-width:48px\">&gt;解读1</span><span class=\"bl\" style=\"left:513px;top:949px;font-size:15.1px;max-width:192px\">国家富强，是指我国综合国力进一步增</span><span class=\"bl\" style=\"left:78px;top:957px;font-size:14.6px;max-width:86px\">②三者的关系：</span><span class=\"bl\" style=\"left:514px;top:967px;font-size:15.7px;max-width:191px\">强，中国特色社会主义事业进一步发展和</span><span class=\"bl\" style=\"left:78px;top:979px;font-size:14.0px;max-width:249px\">国家富强、民族振兴是人民幸福的基础和保障。</span><span class=\"bl\" style=\"left:514px;top:985px;font-size:15.7px;max-width:191px\">完善。经济更加发达，科技创新在经济发</span><span class=\"bl\" style=\"left:78px;top:998px;font-size:15.1px;max-width:297px\">人民幸福是国家富强、民族振兴的题中之义和必然要求。</span><span class=\"bl\" style=\"left:513px;top:1003px;font-size:15.1px;max-width:192px\">展中的驱动力更加强劲，政治更加民主，</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 49 页</div><div class=\"sidebox\" style=\"left:516px;top:110px;width:196px;height:263px\"></div><span class=\"bl\" style=\"left:89px;top:108px;font-size:15.1px;max-width:296px\">人民幸福是国家富强、民族振兴的根本出发点和落脚点。</span><span class=\"bl\" style=\"left:522px;top:116px;font-size:13.4px;max-width:190px\">（接上页）文化更加繁荣，社会更加和谐，</span><span class=\"bl\" style=\"left:88px;top:130px;font-size:14.0px;max-width:90px\">2.中国梦的特点</span><span class=\"bl\" style=\"left:524px;top:135px;font-size:14.0px;max-width:74px\">生态更加美好。</span><span class=\"bl\" style=\"left:88px;top:150px;font-size:15.1px;max-width:297px\">①中国梦是国家情怀、民族情怀、人民情怀相统一的梦。</span><span class=\"bl\" style=\"left:524px;top:154px;font-size:12.3px;max-width:189px\">民族振兴，就是通过自身的不断发展与强</span><span class=\"bl\" style=\"left:88px;top:170px;font-size:15.1px;max-width:424px\">②中国梦归根到底是人民的梦。人民是中国梦的主体，是中国梦的创造者和享</span><span class=\"bl\" style=\"left:524px;top:172px;font-size:12.3px;max-width:189px\">大，继承并创造中华民族的优秀文化以及</span><span class=\"bl\" style=\"left:64px;top:192px;font-size:15.1px;max-width:38px\">有者。</span><span class=\"bl\" style=\"left:523px;top:189px;font-size:14.6px;max-width:190px\">先进的文明成果，进而使中华民族再次处</span><span class=\"bl\" style=\"left:89px;top:213px;font-size:15.1px;max-width:308px\">③中国梦是国家的梦、民族的梦，也是每一个中国人的梦。</span><span class=\"bl\" style=\"left:523px;top:208px;font-size:14.6px;max-width:191px\">于世界领先的地位，再次以高昂的姿态屹</span><span class=\"bl\" style=\"left:524px;top:228px;font-size:12.3px;max-width:93px\">立于世界民族之林。</span><span class=\"bl\" style=\"left:89px;top:235px;font-size:14.0px;max-width:225px\">④中国梦与世界各国人民的美好梦想相通。</span><span class=\"bl\" style=\"left:524px;top:246px;font-size:12.3px;max-width:189px\">民族振兴，也会更好地造福世界人民，共</span><span class=\"bl b\" style=\"left:65px;top:263px;font-size:14.0px;max-width:123px\">42.3奋力实现中国梦</span><span class=\"bl\" style=\"left:524px;top:265px;font-size:12.3px;max-width:189px\">创世界美好的未来。人民幸福，就是人民</span><span class=\"bl\" style=\"left:87px;top:284px;font-size:14.6px;max-width:328px\">1.实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量</span><span class=\"bl\" style=\"left:524px;top:283px;font-size:12.3px;max-width:189px\">权利保障更加充分、人人得享共同发展，</span><span class=\"bl\" style=\"left:89px;top:305px;font-size:14.0px;max-width:95px\">实现中国梦必须：</span><span class=\"bl\" style=\"left:524px;top:301px;font-size:12.3px;max-width:189px\">生活在伟大祖国和伟大时代的中国人民，</span><span class=\"bl\" style=\"left:523px;top:318px;font-size:14.6px;max-width:191px\">共同享有人生出彩的机会，共同享有梦想</span><span class=\"bl\" style=\"left:89px;top:326px;font-size:14.0px;max-width:224px\">①走中国道路，即中国特色社会主义道路。</span><span class=\"bl\" style=\"left:524px;top:337px;font-size:14.0px;max-width:190px\">成真的机会，共同享有同祖国和时代一起</span><span class=\"bl\" style=\"left:89px;top:347px;font-size:14.0px;max-width:423px\">②弘扬中国精神，即以爱国主义为核心的民族精神和以改革创新为核心的时代</span><span class=\"bl\" style=\"left:524px;top:356px;font-size:14.0px;max-width:92px\">成长与进步的机会。</span><span class=\"bl\" style=\"left:65px;top:368px;font-size:13.4px;max-width:37px\">精神。</span><span class=\"bl\" style=\"left:90px;top:390px;font-size:12.3px;max-width:258px\">③凝聚中国力量，即全国各族人民大团结的力量。</span><span class=\"bl\" style=\"left:89px;top:409px;font-size:14.6px;max-width:296px\">④实现中华民族伟大复兴是海内外中华儿女的共同梦想。</span><span class=\"bl\" style=\"left:88px;top:431px;font-size:14.0px;max-width:114px\">2.实干才能梦想成真</span><span class=\"bl\" style=\"left:89px;top:452px;font-size:14.0px;max-width:422px\">①实现中华民族伟大复兴，是一项光荣而艰巨的任务，需要每一个人付出艰苦努</span><span class=\"bl\" style=\"left:66px;top:473px;font-size:14.0px;max-width:247px\">力，用实干托起中国梦。空谈误国，实干兴邦。</span><span class=\"bl\" style=\"left:80px;top:490px;font-size:20.7px;max-width:350px\">②实现中国梦任重而道远，需要锲而不舍、驰而不息的艰苦努力。</span><span class=\"bl b hl\" style=\"left:75px;top:534px;font-size:17.9px;max-width:363px\">考点43建成社会主义现代化强国的战略安排☆☆☆</span><span class=\"bl b\" style=\"left:64px;top:569px;font-size:16.2px;max-width:350px\">43.1开启全面建设社会主义现代化强国的新征程（低频选择题）</span><span class=\"bl\" style=\"left:89px;top:593px;font-size:12.3px;max-width:422px\">1.改革开放之后，我们党对我国社会主义现代化建设作出战略安排，提出“三步</span><span class=\"bl\" style=\"left:65px;top:612px;font-size:15.1px;max-width:361px\">走”战略目标。党的十二大提出分两个10年“两步走”的战略部署。</span><span class=\"bl\" style=\"left:88px;top:635px;font-size:12.3px;max-width:309px\">2.党的十三大确定了我国现代化建设“三步走”发展战略。</span><span class=\"bl\" style=\"left:88px;top:654px;font-size:14.6px;max-width:424px\">第一步，解决人民的温饱问题；第二步，人民生活达到小康水平：第三步，到</span><span class=\"bl\" style=\"left:64px;top:675px;font-size:14.6px;max-width:265px\">21世纪中叶人民生活比较富裕，基本实现现代化。</span><span class=\"bl\" style=\"left:88px;top:697px;font-size:14.0px;max-width:424px\">3.党的十五大对实现第三步战略目标作了进一步规划，提出了新的“三步走”发</span><span class=\"bl\" style=\"left:64px;top:717px;font-size:14.6px;max-width:49px\">展目标。</span><span class=\"bl\" style=\"left:87px;top:738px;font-size:15.7px;max-width:424px\">4.党的十八大把实现社会主义现代化和中华民族伟大复兴作为建设中国特色社会</span><span class=\"bl\" style=\"left:65px;top:759px;font-size:15.1px;max-width:355px\">主义总任务，明确了党和国家在整个社会主义初级阶段的奋斗目标。</span><span class=\"bl\" style=\"left:87px;top:780px;font-size:15.7px;max-width:425px\">5.综合分析国际国内形势和我国发展条件，习近平在党的十九大报告中提出，我</span><span class=\"bl\" style=\"left:64px;top:801px;font-size:14.6px;max-width:447px\">们要全面建成小康社会、实现第一个百年奋斗目标，然后再乘势而上开启全面建设社</span><span class=\"bl\" style=\"left:64px;top:821px;font-size:15.1px;max-width:447px\">会主义现代化国家新征程，向第二个百年奋斗目标进军。全面建设社会主义现代化国</span><span class=\"bl\" style=\"left:65px;top:843px;font-size:12.3px;max-width:153px\">家的进程分两个阶段来安排。</span><span class=\"bl b\" style=\"left:64px;top:870px;font-size:15.7px;max-width:405px\">43.2实现社会主义现代化强国“两步走”战略的具体安排（中频选择题）</span><span class=\"bl\" style=\"left:464px;top:872px;font-size:14.6px;max-width:47px\">&gt;提示1</span><span class=\"bl\" style=\"left:525px;top:870px;font-size:12.3px;max-width:100px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:87px;top:891px;font-size:15.7px;max-width:333px\">1.从2020年到2035年，基本实现社会主义现代化的目标要求：</span><span class=\"bl\" style=\"left:524px;top:891px;font-size:14.0px;max-width:106px\">“两步走”战略的特点：</span><span class=\"bl\" style=\"left:87px;top:912px;font-size:15.7px;max-width:424px\">2021年十三届全国人大四次会议通过《中华人民共和国国民经济和社会发展第</span><span class=\"bl\" style=\"left:523px;top:910px;font-size:14.0px;max-width:190px\">1.把基本实现社会主义现代化的时间提前</span><span class=\"bl\" style=\"left:65px;top:933px;font-size:16.2px;max-width:446px\">十四个五年规划和2035年远景目标纲要》。从“十四五”开局之年开始，我国开启</span><span class=\"bl\" style=\"left:532px;top:928px;font-size:13.4px;max-width:36px\">15年。</span><span class=\"bl\" style=\"left:522px;top:947px;font-size:12.3px;max-width:190px\">2.提出把我国建成富强民主文明和谐美丽</span><span class=\"bl\" style=\"left:64px;top:954px;font-size:14.6px;max-width:202px\">全面建设社会主义现代化国家新征程。</span><span class=\"bl\" style=\"left:532px;top:964px;font-size:14.6px;max-width:113px\">的社会主义现代化强国。</span><span class=\"bl\" style=\"left:87px;top:974px;font-size:15.7px;max-width:303px\">到2035年，我国基本实现社会主义现代化的远景目标是：</span><span class=\"bl\" style=\"left:521px;top:983px;font-size:15.1px;max-width:118px\">3.不提GDP翻番的目标。</span><span class=\"bl\" style=\"left:86px;top:995px;font-size:15.7px;max-width:425px\">经济实力、科技实力、综合国力将大幅跃升，经济总量和城乡居民人均收人将再</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 50 页</div><span class=\"bl\" style=\"left:455px;top:61px;font-size:14.5px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:107px;font-size:13.9px;max-width:365px\">迈上新的大台阶，关键核心技术实现重大突破，进入创新型国家前列。</span><span class=\"bl\" style=\"left:76px;top:127px;font-size:14.5px;max-width:402px\">基本实现新型工业化、信息化、城镇化、农业现代化，建成现代化经济体系。</span><span class=\"bl\" style=\"left:76px;top:148px;font-size:15.0px;max-width:421px\">基本实现国家治理体系和治理能力现代化，人民平等参与、平等发展权利得到充</span><span class=\"bl\" style=\"left:54px;top:169px;font-size:14.5px;max-width:269px\">分保障，基本建成法治国家、法治政府、法治社会。</span><span class=\"bl\" style=\"left:76px;top:190px;font-size:15.0px;max-width:421px\">建成文化强国、教育强国、人才强国、体育强国、健康中国，国民素质和社会文</span><span class=\"bl\" style=\"left:53px;top:211px;font-size:14.5px;max-width:249px\">明程度达到新高度，国家文化软实力显著增强。</span><span class=\"bl\" style=\"left:76px;top:233px;font-size:12.2px;max-width:421px\">广泛形成绿色生产生活方式，碳排放达峰后稳中有降，生态环境根本好转，美丽</span><span class=\"bl\" style=\"left:54px;top:253px;font-size:13.9px;max-width:128px\">中国建设目标基本实现。</span><span class=\"bl\" style=\"left:77px;top:275px;font-size:12.2px;max-width:340px\">形成对外开放新格局，参与国际经济合作和竞争新优势明显增强。</span><span class=\"bl\" style=\"left:76px;top:294px;font-size:14.5px;max-width:421px\">人均国内生产总值达到中等发达国家水平，中等收人群体显著扩大，基本公共服</span><span class=\"bl\" style=\"left:54px;top:317px;font-size:12.2px;max-width:340px\">务实现均等化，城乡区域发展差距和居民生活水平差距显著缩小。</span><span class=\"bl\" style=\"left:77px;top:338px;font-size:12.2px;max-width:305px\">平安中国建设达到更高水平，基本实现国防和军队现代化。</span><span class=\"bl\" style=\"left:77px;top:358px;font-size:12.2px;max-width:420px\">人民生活更加美好，人的全面发展、全体人民共同富裕取得更为明显的实质性</span><span class=\"bl\" style=\"left:53px;top:379px;font-size:13.3px;max-width:38px\">进展。</span><span class=\"bl\" style=\"left:76px;top:399px;font-size:14.5px;max-width:354px\">2.从2035年到21世纪中叶，建成社会主义现代化强国的目标要求：</span><span class=\"bl\" style=\"left:76px;top:418px;font-size:16.1px;max-width:421px\">①我国将拥有高度的物质文明，社会生产力水平大幅提高，核心竞争力名列世界</span><span class=\"bl\" style=\"left:54px;top:441px;font-size:13.9px;max-width:401px\">前茅，经济总量和市场规模超越其他国家，建成富强的社会主义现代化强国。</span><span class=\"bl\" style=\"left:77px;top:463px;font-size:12.2px;max-width:419px\">②我国将拥有高度的政治文明，形成又有集中又有民主、又有纪律又有自由、又</span><span class=\"bl\" style=\"left:53px;top:483px;font-size:15.0px;max-width:443px\">有统一意志又有个人心情舒畅生动活泼的政治局面，依法治国和以德治国有机结合，</span><span class=\"bl\" style=\"left:54px;top:504px;font-size:12.2px;max-width:178px\">建成民主的社会主义现代化强国。</span><span class=\"bl\" style=\"left:77px;top:524px;font-size:15.6px;max-width:421px\">③我国将拥有高度的精神文明，践行社会主义核心价值观成为全社会自觉行动，</span><span class=\"bl\" style=\"left:54px;top:546px;font-size:13.9px;max-width:444px\">国民素质显著提高，中国精神、中国价值、中国力量成为中国发展的重要影响力和推</span><span class=\"bl\" style=\"left:54px;top:567px;font-size:12.2px;max-width:214px\">动力，建成文明的社会主义现代化强国。</span><span class=\"bl\" style=\"left:77px;top:588px;font-size:13.9px;max-width:421px\">4我国将拥有高度的社会文明，城乡居民将普遍拥有较高的收入、富裕的生活、</span><span class=\"bl\" style=\"left:54px;top:608px;font-size:13.9px;max-width:443px\">健全的基本公共服务，享有更加幸福安康的生活，全体人民共同富裕基本实现，公平</span><span class=\"bl\" style=\"left:53px;top:628px;font-size:14.5px;max-width:413px\">正义普遍彰显，社会充满活力而又规范有序，建成和谐的社会主义现代化强国。</span><span class=\"bl\" style=\"left:76px;top:649px;font-size:16.1px;max-width:422px\">5我国将拥有高度的生态文明，天蓝、地绿、水清的优美生态环境成为普遍常</span><span class=\"bl\" style=\"left:54px;top:672px;font-size:13.9px;max-width:364px\">态，开创人与自然和谐共生新境界，建成美丽的社会主义现代化强国。</span><span class=\"bl b hl\" style=\"left:64px;top:710px;font-size:18.9px;max-width:347px\">考点44建设社会主义现代化国家的战略导向 ☆☆☆</span><span class=\"bl b\" style=\"left:54px;top:746px;font-size:15.6px;max-width:118px\">44.1立足新发展阶段</span><span class=\"bl b\" style=\"left:76px;top:767px;font-size:15.0px;max-width:421px\">1.提出：党的十九届五中全会提出，全面建成小康社会、实现第一个百年奋斗目</span><span class=\"bl\" style=\"left:54px;top:788px;font-size:14.5px;max-width:444px\">标之后，我们要乘势而上开启全面建设社会主义现代化国家新征程、向第二个百年奋</span><span class=\"bl\" style=\"left:55px;top:810px;font-size:13.9px;max-width:271px\">斗目标进军，这标志着我国进人了一个新发展阶段。</span><span class=\"bl b\" style=\"left:75px;top:829px;font-size:15.0px;max-width:423px\">2.新发展阶段在社会主义发展进程中的地位：新发展阶段是我国社会主义发展</span><span class=\"bl\" style=\"left:54px;top:850px;font-size:15.0px;max-width:444px\">进程中的一个重要阶段。社会主义初级阶段不是一个静态、一成不变、停滞不前的阶</span><span class=\"bl\" style=\"left:54px;top:871px;font-size:15.0px;max-width:445px\">段，也不是一个自发、被动、不用费多大气力自然而然就可以跨过的阶段，而是一个</span><span class=\"bl\" style=\"left:54px;top:892px;font-size:14.5px;max-width:445px\">动态、积极有为、始终洋溢着蓬勃生机活力的过程，是一个阶梯式递进、不断发展进</span><span class=\"bl\" style=\"left:55px;top:914px;font-size:13.9px;max-width:283px\">步、日益接近质的飞跃的量的积累和发展变化的过程。</span><span class=\"bl b\" style=\"left:76px;top:935px;font-size:13.9px;max-width:145px\">3.进入新发展阶段的依据：</span><span class=\"bl\" style=\"left:77px;top:954px;font-size:16.1px;max-width:421px\">①从理论上看，马克思主义是远大理想和现实目标相结合、历史必然性和发展阶</span><span class=\"bl\" style=\"left:55px;top:974px;font-size:16.1px;max-width:444px\">段性相统一的统一论者，坚信人类社会必然走向共产主义，但实现这一崇高目标必然</span><span class=\"bl\" style=\"left:55px;top:998px;font-size:12.2px;max-width:106px\">经历若干历史阶段。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 51 页</div><span class=\"bl\" style=\"left:91px;top:104px;font-size:16.1px;max-width:422px\">②从历史依据来看，新发展阶段是我们党带领人民迎来从站起来、富起来到强起</span><span class=\"bl\" style=\"left:68px;top:130px;font-size:13.9px;max-width:130px\">来历史性跨越的新阶段。</span><span class=\"bl\" style=\"left:90px;top:152px;font-size:16.1px;max-width:423px\">③就现实依据来讲，我们已经拥有开启新征程、实现新的更高目标的雄厚物质基</span><span class=\"bl\" style=\"left:67px;top:175px;font-size:16.1px;max-width:446px\">础。特别是全面建成小康社会取得伟大历史成果，解决困扰中华民族几千年的绝对贫</span><span class=\"bl\" style=\"left:67px;top:200px;font-size:13.9px;max-width:446px\">困问题取得历史性成就。这在我国社会主义现代化建设进程中具有里程碑意义，为我</span><span class=\"bl\" style=\"left:67px;top:224px;font-size:13.9px;max-width:354px\">国进人新发展阶段、朝着第二个百年奋斗目标进军奠定了坚实基础。</span><span class=\"bl b\" style=\"left:67px;top:254px;font-size:13.9px;max-width:203px\">44.2贯彻新发展理念（中频选择题）</span><span class=\"bl\" style=\"left:90px;top:278px;font-size:13.9px;max-width:230px\">1.新发展理念的地位（为什么）（2017-25）</span><span class=\"bl\" style=\"left:91px;top:302px;font-size:12.2px;max-width:259px\">①是我国经济社会发展必须长期坚持的重要遵循。</span><span class=\"bl\" style=\"left:92px;top:325px;font-size:13.9px;max-width:401px\">②是针对我国经济发展进人新常态、世界经济复苏乏力形势提出的治本之策。</span><span class=\"bl\" style=\"left:92px;top:349px;font-size:13.9px;max-width:332px\">③是针对当前我国发展面临的突出问题和挑战提出的战略指引。</span><span class=\"bl\" style=\"left:91px;top:371px;font-size:15.0px;max-width:178px\">④具有战略性、纲领性、引领性。</span><span class=\"bl\" style=\"left:92px;top:396px;font-size:13.9px;max-width:365px\">5集中体现了我们党对新的发展阶段基本特征的深刻洞察和科学把握。</span><span class=\"bl\" style=\"left:92px;top:420px;font-size:13.9px;max-width:318px\">标志着我们党对经济社会发展规律的认识达到了新的高度。</span><span class=\"bl b\" style=\"left:90px;top:443px;font-size:13.9px;max-width:348px\">2.新发展理念的内容：创新、协调、绿色、开放、共享（2021-8）</span><span class=\"bl\" style=\"left:78px;top:478px;font-size:17.8px;max-width:33px\">考点</span><span class=\"bl\" style=\"left:295px;top:479px;font-size:18.4px;max-width:34px\">内容</span><span class=\"bl\" style=\"left:72px;top:476px;font-size:51.8px;max-width:97px\">微信</span><span class=\"bl\" style=\"left:164px;top:514px;font-size:13.9px;max-width:160px\">A.创新是引领发展的第一动力</span><span class=\"bl\" style=\"left:164px;top:533px;font-size:15.6px;max-width:185px\">B.创新发展注重解决发展动力问题</span><span class=\"bl\" style=\"left:121px;top:541px;font-size:18.9px;max-width:34px\">定位</span><span class=\"bl\" style=\"left:164px;top:551px;font-size:17.8px;max-width:241px\">C.是国家综合国力和核心竞争力的最关键因素</span><span class=\"bl\" style=\"left:77px;top:569px;font-size:15.6px;max-width:33px\">创新</span><span class=\"bl\" style=\"left:164px;top:573px;font-size:13.9px;max-width:149px\">D.是引领新常态的根本之策</span><span class=\"bl\" style=\"left:164px;top:606px;font-size:15.0px;max-width:342px\">把创新摆在国家发展全局的核心位置，让创新贯穿党和国家一切</span><span class=\"bl\" style=\"left:121px;top:615px;font-size:16.1px;max-width:33px\">措施</span><span class=\"bl\" style=\"left:165px;top:626px;font-size:13.9px;max-width:169px\">工作，让创新在全社会蔚然成风</span><span class=\"bl\" style=\"left:164px;top:659px;font-size:15.0px;max-width:184px\">A.协调是持续健康发展的内在要求</span><span class=\"bl\" style=\"left:162px;top:678px;font-size:16.1px;max-width:198px\">B.协调发展注重解决发展不平衡问题</span><span class=\"bl\" style=\"left:121px;top:688px;font-size:16.1px;max-width:33px\">定位</span><span class=\"bl\" style=\"left:164px;top:698px;font-size:15.0px;max-width:183px\">C.协调既是发展手段又是发展目标</span><span class=\"bl\" style=\"left:164px;top:718px;font-size:15.0px;max-width:184px\">D.同时还是评价发展的标准和尺度</span><span class=\"bl\" style=\"left:76px;top:734px;font-size:17.8px;max-width:35px\">协调</span><span class=\"bl\" style=\"left:162px;top:752px;font-size:16.1px;max-width:93px\">A.区域协调发展</span><span class=\"bl\" style=\"left:163px;top:772px;font-size:14.5px;max-width:92px\">B.城乡协调发展</span><span class=\"bl\" style=\"left:121px;top:780px;font-size:15.6px;max-width:33px\">措施</span><span class=\"bl\" style=\"left:162px;top:790px;font-size:16.1px;max-width:173px\">C.物质文明和精神文明协调发展</span><span class=\"bl\" style=\"left:163px;top:810px;font-size:17.3px;max-width:196px\">D.推动经济建设和国防建设融合发展</span><span class=\"bl\" style=\"left:163px;top:844px;font-size:15.0px;max-width:162px\">A.绿色是永续发展的必要条件</span><span class=\"bl\" style=\"left:162px;top:864px;font-size:13.9px;max-width:230px\">B.绿色发展注重解决人与自然和谐共生问题</span><span class=\"bl\" style=\"left:121px;top:873px;font-size:15.6px;max-width:33px\">定位</span><span class=\"bl\" style=\"left:162px;top:883px;font-size:15.0px;max-width:277px\">C.绿色发展是构建高质量现代化经济体系的必然要求</span><span class=\"bl\" style=\"left:162px;top:902px;font-size:16.1px;max-width:208px\">D.绿色发展是解决污染问题的根本之策</span><span class=\"bl\" style=\"left:75px;top:918px;font-size:18.4px;max-width:34px\">绿色</span><span class=\"bl\" style=\"left:162px;top:936px;font-size:15.0px;max-width:160px\">A.解决人与自然和谐共生问题</span><span class=\"bl\" style=\"left:161px;top:955px;font-size:17.3px;max-width:276px\">B.走生产发展、生活富裕、生态良好的文明发展道路</span><span class=\"bl\" style=\"left:120px;top:964px;font-size:16.1px;max-width:33px\">措施</span><span class=\"bl\" style=\"left:162px;top:975px;font-size:15.6px;max-width:218px\">C.加快建设资源节约型、环境友好型社会</span><span class=\"bl\" style=\"left:162px;top:995px;font-size:15.6px;max-width:334px\">D.形成人与自然和谐发展现代化建设新格局，推进美丽中国建设</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1095px\"><div class=\"bxnum\">第 52 页</div><span class=\"bl\" style=\"left:457px;top:63px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:466px;top:108px;font-size:15.6px;max-width:34px\">续表</span><span class=\"bl\" style=\"left:63px;top:132px;font-size:18.4px;max-width:34px\">考点</span><span class=\"bl\" style=\"left:282px;top:134px;font-size:16.7px;max-width:33px\">内容</span><span class=\"bl\" style=\"left:150px;top:167px;font-size:16.7px;max-width:183px\">A.开放是国家繁荣发展的必由之路</span><span class=\"bl\" style=\"left:106px;top:175px;font-size:19.5px;max-width:35px\">定位</span><span class=\"bl\" style=\"left:150px;top:189px;font-size:13.9px;max-width:206px\">B.开放发展注重解决发展内外联动问题</span><span class=\"bl\" style=\"left:151px;top:223px;font-size:13.9px;max-width:229px\">A.提高对外开放的质量和发展的内外联动性</span><span class=\"bl\" style=\"left:63px;top:233px;font-size:15.6px;max-width:33px\">开放</span><span class=\"bl\" style=\"left:150px;top:241px;font-size:13.9px;max-width:332px\">B.主动参与和推动经济全球化进程，发展更高层次的开放型经济</span><span class=\"bl\" style=\"left:109px;top:260px;font-size:15.6px;max-width:33px\">措施</span><span class=\"bl\" style=\"left:150px;top:261px;font-size:13.9px;max-width:218px\">C.积极参与全球经济治理和公共产品供给</span><span class=\"bl\" style=\"left:151px;top:281px;font-size:13.9px;max-width:341px\">D.提高我国在全球经济治理中的制度性话语权，不断壮大我国经</span><span class=\"bl\" style=\"left:150px;top:300px;font-size:15.6px;max-width:100px\">济实力和综合国力</span><span class=\"bl\" style=\"left:151px;top:335px;font-size:13.9px;max-width:207px\">A.共享是中国特色社会主义的本质要求</span><span class=\"bl\" style=\"left:108px;top:343px;font-size:16.7px;max-width:33px\">定位</span><span class=\"bl\" style=\"left:150px;top:354px;font-size:15.6px;max-width:208px\">B.共享发展注重解决社会公平正义问题</span><span class=\"bl\" style=\"left:64px;top:389px;font-size:16.7px;max-width:33px\">共享</span><span class=\"bl\" style=\"left:150px;top:387px;font-size:15.6px;max-width:184px\">A.全民共享，人人享有、各得其所</span><span class=\"bl\" style=\"left:149px;top:406px;font-size:16.7px;max-width:288px\">B.全面共享，共享经济、政治、文化、社会、生态成果</span><span class=\"bl\" style=\"left:108px;top:416px;font-size:16.7px;max-width:33px\">措施</span><span class=\"bl\" style=\"left:150px;top:427px;font-size:13.9px;max-width:286px\">C.共建共享，共建才能共享，共建过程也是共享的过程</span><span class=\"bl\" style=\"left:151px;top:447px;font-size:13.9px;max-width:275px\">D.渐进共享，从低级到高级、从不均衡到均衡的过程</span><span class=\"bl\" style=\"left:76px;top:479px;font-size:17.2px;max-width:199px\">3.完整、准确、全面贯彻新发展理念</span><span class=\"bl\" style=\"left:79px;top:500px;font-size:16.7px;max-width:420px\">①从根本宗旨把握新发展理念。人民是我们党执政的最深厚基础和最大底气。为</span><span class=\"bl\" style=\"left:54px;top:520px;font-size:17.2px;max-width:446px\">人民谋幸福、为民族谋复兴，是我们党的初心和使命，是党领导现代化建设的出发点</span><span class=\"bl\" style=\"left:55px;top:541px;font-size:15.0px;max-width:263px\">和落脚点，也是新发展理念的“根”和“魂”。</span><span class=\"bl\" style=\"left:78px;top:560px;font-size:15.6px;max-width:421px\">②从问题导向把握新发展理念。要根据新发展阶段的新要求，坚持问题导向，更</span><span class=\"bl\" style=\"left:54px;top:580px;font-size:17.2px;max-width:344px\">加精准地贯彻新发展理念，切实解决好发展不平衡不充分的问题。</span><span class=\"bl\" style=\"left:78px;top:601px;font-size:15.0px;max-width:421px\">③从忧患意识把握新发展理念。随着我国社会主要矛盾变化和国际力量对比深刻</span><span class=\"bl\" style=\"left:55px;top:621px;font-size:14.5px;max-width:446px\">调整，我国发展面临的内外部风险空前上升，必须增强忧患意识、坚持底线思维，随</span><span class=\"bl\" style=\"left:53px;top:641px;font-size:16.7px;max-width:403px\">时准备应对更加复杂困难的局面，把安全发展贯穿国家发展各领域和全过程。</span><span class=\"bl b\" style=\"left:55px;top:670px;font-size:13.9px;max-width:202px\">44.3构建新发展格局（高频选择题）</span><span class=\"bl\" style=\"left:78px;top:690px;font-size:13.9px;max-width:158px\">1.新发展格局的地位（意义）</span><span class=\"bl\" style=\"left:79px;top:710px;font-size:13.9px;max-width:258px\">①是与时俱进提升我国经济发展水平的战略执择。</span><span class=\"bl\" style=\"left:80px;top:730px;font-size:13.9px;max-width:281px\">②是塑造我国国际经济合作和竞争新优势的战略执择。</span><span class=\"bl\" style=\"left:80px;top:751px;font-size:13.9px;max-width:154px\">③是经济现代化的路径选择。</span><span class=\"bl\" style=\"left:80px;top:770px;font-size:13.9px;max-width:258px\">④是把握未来发展主动权的战略性布局和先手棋。</span><span class=\"bl\" style=\"left:77px;top:789px;font-size:16.7px;max-width:172px\">2.新发展格局的依据（为什么）</span><span class=\"bl\" style=\"left:78px;top:810px;font-size:15.0px;max-width:422px\">①从发展进程看，改革开放特别是加人世界贸易组织后，我国深度参与国际分</span><span class=\"bl\" style=\"left:56px;top:829px;font-size:15.6px;max-width:444px\">工，融人国际大循环，形成市场和资源“两头在外”的发展格局。基于国内外形势的</span><span class=\"bl\" style=\"left:55px;top:849px;font-size:15.6px;max-width:446px\">发展变化，我们要坚持扩大内需这个战略基点，使生产、分配、流通、消费更多依托</span><span class=\"bl\" style=\"left:56px;top:870px;font-size:13.9px;max-width:188px\">国内市场，形成国民经济良性循环。</span><span class=\"bl\" style=\"left:79px;top:888px;font-size:18.4px;max-width:423px\">②从世界比较看，大国经济的特征都是内需为主导、内部可循环。我国作为全球</span><span class=\"bl\" style=\"left:55px;top:909px;font-size:16.7px;max-width:446px\">第二大经济体和制造业第一大国，国内经济循环同国际经济循环的关系客观上早有调</span><span class=\"bl\" style=\"left:56px;top:930px;font-size:14.5px;max-width:60px\">整的要求。</span><span class=\"bl\" style=\"left:79px;top:948px;font-size:17.8px;max-width:422px\">③从国际形势看，近几年全球政治经济环境发生深刻变化，逆全球化趋势加剧，</span><span class=\"bl\" style=\"left:56px;top:969px;font-size:17.2px;max-width:445px\">有的国家大搞单边主义、保护主义。我国作为一个人口众多和超大市场规模的社会主</span><span class=\"bl\" style=\"left:56px;top:988px;font-size:16.7px;max-width:445px\">义国家，必须坚持立足国内、依托国内大市场优势，化解外部冲击和外需下降带来的</span><span class=\"bl\" style=\"left:55px;top:1009px;font-size:15.0px;max-width:285px\">影响，增强我们的生存力、竞争力、发展力、持续力。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 53 页</div><span class=\"bl\" style=\"left:93px;top:110px;font-size:12.2px;max-width:180px\">3.如何构建新发展格局（怎么办）</span><span class=\"bl\" style=\"left:94px;top:129px;font-size:13.9px;max-width:420px\">①扭住扩大内需战略基点，畅通国民经济循环。我们必须坚持深化供给侧结构性</span><span class=\"bl\" style=\"left:70px;top:150px;font-size:13.9px;max-width:444px\">改革这条主线，继续完成“三去一降一补”的重要任务，实现经济在高水平上的动态</span><span class=\"bl\" style=\"left:68px;top:170px;font-size:17.2px;max-width:41px\">平衡。</span><span class=\"bl\" style=\"left:94px;top:191px;font-size:15.0px;max-width:420px\">②大力推动科技创新，打造经济发展新动能。构建新发展格局最本质的特征是实</span><span class=\"bl\" style=\"left:69px;top:212px;font-size:13.9px;max-width:118px\">现高水平的自立自强。</span><span class=\"bl\" style=\"left:93px;top:233px;font-size:15.0px;max-width:419px\">③发挥全面深化改革在构建新发展格局中的关键作用，要围绕实现高水平自立自</span><span class=\"bl\" style=\"left:69px;top:254px;font-size:13.9px;max-width:73px\">强深化改革。</span><span class=\"bl\" style=\"left:94px;top:275px;font-size:13.9px;max-width:420px\">④构建新发展格局要释放内需潜力，必须充分发挥我们市场资源优势，以巨大国</span><span class=\"bl\" style=\"left:70px;top:296px;font-size:13.9px;max-width:213px\">内市场形成构建新发展格局的雄厚支撑。</span><span class=\"bl\" style=\"left:94px;top:316px;font-size:15.0px;max-width:420px\">5构建新发展格局要实行高水平对外开放，必须具备强大的国内经济循环体系和</span><span class=\"bl\" style=\"left:69px;top:337px;font-size:15.0px;max-width:445px\">稳固的基本盘，并以此形成对全球要素资源的强大吸引力、在激烈国际竞争中的强大</span><span class=\"bl\" style=\"left:69px;top:359px;font-size:13.9px;max-width:224px\">竞争力、在全球资源配置中的强大推动力。</span><span class=\"bl\" style=\"left:94px;top:379px;font-size:14.4px;max-width:340px\">6构建新发展格局必须深刻把握国内国际双循环相互促进的关系。</span><span class=\"bl b\" style=\"left:69px;top:406px;font-size:15.0px;max-width:414px\">44.4新发展阶段、贯彻新发展理念、构建新发展格局的关系（中频选择题）</span><span class=\"bl b\" style=\"left:91px;top:427px;font-size:16.1px;max-width:52px\">1.定位：</span><span class=\"bl\" style=\"left:93px;top:448px;font-size:15.6px;max-width:245px\">①进入新发展阶段明确了我国发展的历史方位。</span><span class=\"bl\" style=\"left:93px;top:470px;font-size:14.4px;max-width:281px\">②贯彻新发展理念明确了我国现代化建设的指导原则。</span><span class=\"bl\" style=\"left:92px;top:490px;font-size:17.2px;max-width:279px\">③构建新发展格局明确了我国经济现代化的路径选择</span><span class=\"bl b\" style=\"left:91px;top:509px;font-size:17.8px;max-width:65px\">2.关系：</span><span class=\"bl\" style=\"left:91px;top:532px;font-size:15.0px;max-width:345px\">①把握新展阶段是贯彻新发展理念、构建新发展格局的现实依据。</span><span class=\"bl\" style=\"left:93px;top:553px;font-size:15.6px;max-width:376px\">②贯彻新发展理念为把握新发展阶段、构建新发展格局提供了行动指南。</span><span class=\"bl\" style=\"left:93px;top:573px;font-size:15.6px;max-width:404px\">③构建新发展格局是应对新发展阶段机遇和挑战、贯彻新发展理念的战略选择。</span><span class=\"bl\" style=\"left:69px;top:608px;font-size:18.3px;max-width:99px\">经典真题回顾</span><span class=\"bl\" style=\"left:82px;top:634px;font-size:18.3px;max-width:432px\">【2022.6】发展格局是经济现代化的路径选择，是关系我国发展全局的重大战略任</span><span class=\"bl\" style=\"left:85px;top:657px;font-size:15.6px;max-width:428px\">务。立足新发展阶段，贯彻新发展理念，要致力构建国内大循环为主体，国内国</span><span class=\"bl\" style=\"left:84px;top:678px;font-size:15.6px;max-width:326px\">际双循环相互促进的新发展格局。构建新发展格局的关键在于</span><span class=\"bl\" style=\"left:84px;top:699px;font-size:13.9px;max-width:128px\">A.经济循环的畅通无阻</span><span class=\"bl\" style=\"left:84px;top:719px;font-size:15.6px;max-width:128px\">B.激发市场主体的活力</span><span class=\"bl\" style=\"left:84px;top:741px;font-size:13.9px;max-width:140px\">C.实现高水平的自立自强</span><span class=\"bl\" style=\"left:84px;top:761px;font-size:15.0px;max-width:152px\">D.产业链供应链的优化升级</span></div></div>"}],pages:[48,53]};
  D["mzt_s11"] = {id:"mzt_s11",ch:"毛中特讲义 · 第十章 “五位一体”总体布局",title:"第十章 “五位一体”总体布局",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 54 页</div><div class=\"sidebox\" style=\"left:508px;top:861px;width:195px;height:66px\"></div><span class=\"bl\" style=\"left:456px;top:57px;font-size:16.1px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:344px;top:110px;font-size:25.6px;max-width:65px\">第十章</span><span class=\"bl\" style=\"left:291px;top:160px;font-size:21.7px;max-width:181px\">“五位一体”总体布局</span><span class=\"bl\" style=\"left:52px;top:212px;font-size:16.1px;max-width:101px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:338px;top:251px;font-size:18.4px;max-width:165px\">考点45坚持习近平经济思想</span><span class=\"bl\" style=\"left:217px;top:272px;font-size:18.4px;max-width:70px\">实现经济高</span><span class=\"bl b hl\" style=\"left:338px;top:273px;font-size:15.6px;max-width:177px\">考点46深化供给侧结构性改革</span><span class=\"bl\" style=\"left:224px;top:295px;font-size:16.1px;max-width:57px\">质量发展</span><span class=\"bl b hl\" style=\"left:337px;top:292px;font-size:20.0px;max-width:332px\">考点47使市场在资源配置中起决定作用，更好发挥政府作用</span><span class=\"bl b hl\" style=\"left:338px;top:315px;font-size:15.6px;max-width:164px\">考点48建设现代化经济体系</span><span class=\"bl b hl\" style=\"left:347px;top:343px;font-size:18.4px;max-width:248px\">考点49坚持中国特色社会主义政治发展道路</span><span class=\"bl\" style=\"left:217px;top:356px;font-size:16.1px;max-width:80px\">发展社会主义</span><span class=\"bl b hl\" style=\"left:347px;top:365px;font-size:17.8px;max-width:201px\">考点50健全人民当家作主制度体系</span><span class=\"bl\" style=\"left:229px;top:377px;font-size:17.2px;max-width:56px\">民主政治</span><span class=\"bl b hl\" style=\"left:347px;top:386px;font-size:16.1px;max-width:189px\">考点51巩固和发展爱国统一战线</span><span class=\"bl\" style=\"left:93px;top:414px;font-size:18.4px;max-width:70px\">“五位一体”</span><span class=\"bl\" style=\"left:367px;top:416px;font-size:17.8px;max-width:279px\">坚持马克思主义在意识形态领域指导地位的根本制度</span><span class=\"bl b hl\" style=\"left:218px;top:428px;font-size:16.1px;max-width:97px\">考点52建设社会</span><span class=\"bl\" style=\"left:97px;top:436px;font-size:16.1px;max-width:56px\">总体布局</span><span class=\"bl\" style=\"left:367px;top:437px;font-size:17.2px;max-width:173px\">培育和践行社会主义核心价值观</span><span class=\"bl\" style=\"left:228px;top:451px;font-size:14.5px;max-width:79px\">主义文化强国</span><span class=\"bl\" style=\"left:367px;top:458px;font-size:17.2px;max-width:184px\">坚定文化自信，繁荣社会主义文化</span><span class=\"bl\" style=\"left:68px;top:475px;font-size:51.7px;max-width:147px\">微信公</span><span class=\"bl b hl\" style=\"left:218px;top:498px;font-size:15.6px;max-width:109px\">考点53加强以民生</span><span class=\"bl\" style=\"left:377px;top:497px;font-size:15.6px;max-width:139px\">在发展中保障和改善民生</span><span class=\"bl\" style=\"left:222px;top:520px;font-size:13.9px;max-width:102px\">为重点的社会建设</span><span class=\"bl\" style=\"left:378px;top:518px;font-size:15.6px;max-width:115px\">加强和创新社会治理</span><span class=\"bl\" style=\"left:79px;top:532px;font-size:51.7px;max-width:153px\">考</span><span class=\"bl\" style=\"left:217px;top:564px;font-size:17.8px;max-width:81px\">建设美丽中国</span><span class=\"bl b hl\" style=\"left:324px;top:565px;font-size:15.6px;max-width:177px\">考点54坚持人与自然和谐共生</span><span class=\"bl\" style=\"left:54px;top:625px;font-size:18.4px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:80px;top:649px;font-size:19.5px;max-width:622px\">本章主要阐述了建设中国特色社会主义“五位一体”总布局的内容。本章在本科目中属于必考内容，考生要高度重视，</span><span class=\"bl\" style=\"left:56px;top:670px;font-size:19.5px;max-width:579px\">考试形式既可能是选择题，又可能是材料分析题。在复习中要结合时政来体会“五位一体”总布局的深刻内涵。</span><span class=\"bl b hl\" style=\"left:66px;top:726px;font-size:21.7px;max-width:248px\">考点45坚持习近平经济思想☆☆☆</span><span class=\"bl\" style=\"left:662px;top:726px;font-size:15.0px;max-width:38px\">记笔记</span><span class=\"bl b\" style=\"left:56px;top:763px;font-size:16.1px;max-width:236px\">45.1习近平经济思想的形成（中频选择题）</span><span class=\"bl\" style=\"left:80px;top:783px;font-size:18.9px;max-width:423px\">党的十八大以来，以习近平同志为核心的党中央坚持观大势、谋全局、干实事，</span><span class=\"bl\" style=\"left:57px;top:805px;font-size:17.8px;max-width:447px\">紧紧围绕发展新时代中国特色社会主义经济的重大时代课题，形成一系列关于我国经</span><span class=\"bl\" style=\"left:57px;top:825px;font-size:18.4px;max-width:446px\">济发展全局的重大判断和论断，提出一系列新理念新思想新战略，推动我国经济发</span><span class=\"bl\" style=\"left:57px;top:845px;font-size:18.9px;max-width:446px\">展取得历史性成就、发生历史性变革，在理论与实践互动中形成了习近平经济思想。</span><span class=\"bl\" style=\"left:455px;top:867px;font-size:15.0px;max-width:48px\">&gt;解读1</span><span class=\"bl\" style=\"left:516px;top:867px;font-size:15.6px;max-width:103px\">火星姐姐考点解读1</span><span class=\"bl b\" style=\"left:57px;top:895px;font-size:17.8px;max-width:265px\">45.2习近平经济思想的主要内容（高频选择题）</span><span class=\"bl\" style=\"left:514px;top:889px;font-size:16.1px;max-width:191px\">理念是行动的先导。一定的发展实践都是</span><span class=\"bl\" style=\"left:515px;top:908px;font-size:15.6px;max-width:123px\">由一定的发展理念指导的。</span><span class=\"bl\" style=\"left:81px;top:915px;font-size:18.4px;max-width:320px\">1.加强党对经济工作的全面领导是我国经济发展的根本保证。</span><span class=\"bl\" style=\"left:80px;top:936px;font-size:18.4px;max-width:321px\">2.坚持以人民为中心的发展思想是我国经济发展的根本立场。</span><span class=\"bl\" style=\"left:80px;top:958px;font-size:17.2px;max-width:250px\">3.进入新发展阶段是我国经济发展的历史方位。</span><span class=\"bl\" style=\"left:81px;top:979px;font-size:16.1px;max-width:249px\">4.坚持新发展理念是我国经济发展的指导原则。</span><span class=\"bl\" style=\"left:81px;top:999px;font-size:17.2px;max-width:250px\">5.构建新发展格局是我国经济发展的路径选择。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 55 页</div><span class=\"bl\" style=\"left:90px;top:103px;font-size:14.5px;max-width:248px\">6.推动高质量发展是我国经济发展的鲜明主题。</span><span class=\"bl\" style=\"left:90px;top:124px;font-size:16.1px;max-width:421px\">7.坚持和完善社会主义基本经济制度是我国经济发展的制度基础。毫不动摇巩固</span><span class=\"bl\" style=\"left:67px;top:145px;font-size:15.6px;max-width:445px\">和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。坚持按劳分配为</span><span class=\"bl\" style=\"left:67px;top:166px;font-size:15.6px;max-width:445px\">主体、多种分配方式并存。充分发挥市场在资源配置中的决定性作用，更好发挥政府</span><span class=\"bl\" style=\"left:66px;top:187px;font-size:14.5px;max-width:213px\">作用。加快完善社会主义市场经济体制。</span><span class=\"bl\" style=\"left:89px;top:208px;font-size:15.6px;max-width:422px\">8.坚持问题导向部署实施国家重大发展战略是我国经济发展的战略举措。战略问</span><span class=\"bl\" style=\"left:66px;top:228px;font-size:16.1px;max-width:446px\">题是根本性问题。实施乡村振兴战略、区域协调发展战略、以人为核心的新型城镇化</span><span class=\"bl\" style=\"left:66px;top:249px;font-size:14.5px;max-width:39px\">战略。</span><span class=\"bl\" style=\"left:89px;top:270px;font-size:15.6px;max-width:422px\">9.坚持创新驱动发展是我国经济发展的第一动力。创新从根本上决定国家和民族</span><span class=\"bl\" style=\"left:66px;top:292px;font-size:13.9px;max-width:72px\">的前途命运。</span><span class=\"bl\" style=\"left:90px;top:312px;font-size:15.6px;max-width:325px\">10.大力发展制造业和实体经济是我国经济发展的主要着力点。</span><span class=\"bl\" style=\"left:90px;top:333px;font-size:15.6px;max-width:287px\">11.坚定不移全面扩大开放是我国经济发展的重要法宝。</span><span class=\"bl\" style=\"left:90px;top:354px;font-size:15.0px;max-width:255px\">12.统筹发展和安全是我国经济发展的重要保障。</span><span class=\"bl\" style=\"left:89px;top:375px;font-size:17.2px;max-width:422px\">13.坚持正确工作策略和方法是做好经济工作的方法论。坚持稳中求进工作总基</span><span class=\"bl\" style=\"left:65px;top:395px;font-size:16.1px;max-width:445px\">调，坚持系统观念，坚持目标导向和问题导向相结合，坚持集中精力办好自己的事，</span><span class=\"bl\" style=\"left:65px;top:416px;font-size:14.5px;max-width:143px\">坚持以钉钉子精神抓落实。</span><span class=\"bl b hl\" style=\"left:76px;top:456px;font-size:18.4px;max-width:260px\">考点46深化供给侧结构性改革☆☆☆</span><span class=\"bl b\" style=\"left:84px;top:484px;font-size:17.2px;max-width:228px\">1.深化供给侧结构性改革的必要性：</span><span class=\"bl\" style=\"left:81px;top:505px;font-size:17.2px;max-width:288px\">①实现经济高质量发展，必须坚持供给侧结构性改革。</span><span class=\"bl\" style=\"left:88px;top:526px;font-size:18.9px;max-width:320px\">②构建新发展格局，要坚持供给侧结构性改革的战略方向。</span><span class=\"bl\" style=\"left:89px;top:547px;font-size:15.6px;max-width:273px\">③要把推进供给侧结构性改革作为经济发展的主线。</span><span class=\"bl\" style=\"left:88px;top:568px;font-size:17.2px;max-width:421px\">④供给侧结构性改革，是化解我国经济发展面临困难和矛盾的重大举措，也是培</span><span class=\"bl\" style=\"left:65px;top:589px;font-size:17.2px;max-width:378px\">育增长新动力、形成先发新优势、实现创新引领发展的必然要求和选择。</span><span class=\"bl\" style=\"left:88px;top:610px;font-size:17.8px;max-width:421px\">5当前和今后一个时期，我国经济发展面临的问题，供给和需求两侧都有，但矛</span><span class=\"bl\" style=\"left:65px;top:631px;font-size:15.0px;max-width:130px\">盾的主要方面在供给侧。</span><span class=\"bl b\" style=\"left:86px;top:652px;font-size:15.6px;max-width:122px\">2.供给和需求的关系：</span><span class=\"bl\" style=\"left:87px;top:673px;font-size:17.2px;max-width:416px\">①供给和需求是市场经济内在关系的两个基本方面，是既对立又统一的辩证关系。</span><span class=\"bl\" style=\"left:87px;top:693px;font-size:15.6px;max-width:224px\">②新需求催生新供给，新供给创造新需求。</span><span class=\"bl\" style=\"left:87px;top:714px;font-size:16.1px;max-width:320px\">③供给侧管理和需求侧管理是调控宏观经济的两个基本手段。</span><span class=\"bl\" style=\"left:86px;top:736px;font-size:17.8px;max-width:422px\">④需求侧管理，重在解决总量性问题，注重短期调控，主要是通过调节税收、财</span><span class=\"bl\" style=\"left:63px;top:757px;font-size:16.1px;max-width:319px\">政支出、货币信贷等来刺激或抑制需求，进而推动经济增长。</span><span class=\"bl\" style=\"left:86px;top:777px;font-size:17.2px;max-width:421px\">5供给侧管理，重在解决结构性问题，注重激发经济增长动力，主要通过优化要</span><span class=\"bl\" style=\"left:63px;top:798px;font-size:16.1px;max-width:379px\">素配置和调整生产结构来提高供给体系质量和效率，进而推动经济增长。</span><span class=\"bl\" style=\"left:85px;top:819px;font-size:15.6px;max-width:275px\">3.推进供给侧结构性改革，关键在于理解“结构性”</span><span class=\"bl\" style=\"left:86px;top:840px;font-size:17.8px;max-width:421px\">我国经济运行面临的突出矛盾和问题，虽然有周期性、总量性因素，但根源是重</span><span class=\"bl\" style=\"left:62px;top:860px;font-size:17.2px;max-width:445px\">大结构性失衡，即实体经济结构性供需失衡、金融和实体经济失衡、房地产和实体经</span><span class=\"bl\" style=\"left:62px;top:881px;font-size:14.5px;max-width:50px\">济失衡。</span><span class=\"bl\" style=\"left:84px;top:902px;font-size:17.8px;max-width:423px\">4.推动供给侧结构性改革，重点是解放和发展社会生产力，用改革的办法推进结</span><span class=\"bl\" style=\"left:62px;top:922px;font-size:17.8px;max-width:445px\">构调整，减少无效和低端供给，扩大有效和中高端供给，提升供给体系对国内需求的</span><span class=\"bl\" style=\"left:61px;top:943px;font-size:16.1px;max-width:296px\">适配性，实现由低水平供需平衡向高水平供需平衡跃升。</span><span class=\"bl\" style=\"left:84px;top:964px;font-size:16.1px;max-width:173px\">5.供给侧结构性改革的主要任务</span><span class=\"bl\" style=\"left:85px;top:985px;font-size:17.8px;max-width:421px\">①推进增长动能转换，加快实施创新驱动发展战略。坚持创新在我国现代化建设</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1092px\"><div class=\"bxnum\">第 56 页</div><div class=\"sidebox\" style=\"left:505px;top:408px;width:197px;height:425px\"></div><span class=\"bl\" style=\"left:459px;top:59px;font-size:15.0px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:56px;top:104px;font-size:15.0px;max-width:331px\">全局中的核心地位，把科技自立自强作为国家发展的战略支撑。</span><span class=\"bl\" style=\"left:514px;top:115px;font-size:15.0px;max-width:101px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:80px;top:125px;font-size:14.5px;max-width:421px\">②深化要素市场化配置改革，实现由以价取胜向以质取胜的转变。破除无效供</span><span class=\"bl\" style=\"left:512px;top:138px;font-size:14.5px;max-width:74px\">三去一降一补：</span><span class=\"bl\" style=\"left:55px;top:146px;font-size:14.5px;max-width:446px\">给，把处置“僵尸企业”作为重要抓手，推动化解过剩产能；调整产业结构，淘汰落</span><span class=\"bl\" style=\"left:512px;top:156px;font-size:13.9px;max-width:189px\">去产能：过剩产能产业，比如钢铁和煤</span><span class=\"bl\" style=\"left:57px;top:168px;font-size:13.9px;max-width:164px\">后产能，防止低水平重复建设。</span><span class=\"bl\" style=\"left:512px;top:174px;font-size:15.0px;max-width:45px\">炭行业。</span><span class=\"bl\" style=\"left:81px;top:189px;font-size:12.2px;max-width:316px\">③加大人力资源培育力度，更加注重调动和保护人的积极性。</span><span class=\"bl\" style=\"left:512px;top:193px;font-size:13.9px;max-width:189px\">去库存：房地产库存，优化房地产市场</span><span class=\"bl\" style=\"left:80px;top:209px;font-size:13.9px;max-width:420px\">④激发各类市场主体活力，加快建设世界一流企业。毫不动摇巩固和发展公有制</span><span class=\"bl\" style=\"left:512px;top:211px;font-size:14.5px;max-width:55px\">供求关系。</span><span class=\"bl\" style=\"left:57px;top:231px;font-size:12.2px;max-width:282px\">经济，毫不动摇鼓励、支持、引导非公有制经济发展。</span><span class=\"bl\" style=\"left:512px;top:229px;font-size:13.9px;max-width:189px\">去杠杆：防范化解金融风险，有效控制</span><span class=\"bl\" style=\"left:80px;top:251px;font-size:15.0px;max-width:163px\">③持续推进“三去一降一补”。</span><span class=\"bl\" style=\"left:453px;top:252px;font-size:14.5px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:511px;top:247px;font-size:15.0px;max-width:36px\">债务。</span><span class=\"bl\" style=\"left:511px;top:266px;font-size:13.9px;max-width:191px\">降成本：通过简政放权、减税降低企业</span><span class=\"bl\" style=\"left:511px;top:283px;font-size:14.5px;max-width:55px\">体制成本。</span><span class=\"bl b hl\" style=\"left:66px;top:291px;font-size:17.8px;max-width:402px\">考点47使市场在资源配置中起决定作用、更好发挥政府作用</span><span class=\"bl\" style=\"left:512px;top:302px;font-size:13.9px;max-width:190px\">补短板：扶贫、生态、创新、增强微观</span><span class=\"bl\" style=\"left:512px;top:320px;font-size:14.5px;max-width:55px\">主体活力。</span><span class=\"bl b\" style=\"left:56px;top:343px;font-size:16.1px;max-width:309px\">47.1我们党对政府和市场关系的认识过程（中频选择题）</span><span class=\"bl b\" style=\"left:79px;top:365px;font-size:15.0px;max-width:379px\">1.党的十四大：我国经济体制改革的目标是建立社会主义市场经济体制。</span><span class=\"bl b\" style=\"left:79px;top:387px;font-size:13.9px;max-width:393px\">2.党的十八大：“更大程度更广范围发挥市场在资源配置中的基础性作用”。</span><span class=\"bl b\" style=\"left:79px;top:407px;font-size:15.0px;max-width:423px\">3.党的十八届三种全会：把市场在资源配置中的“基础性作用”修改为“决定性</span><span class=\"bl b\" style=\"left:512px;top:414px;font-size:14.5px;max-width:73px\">1.公有制经济：</span><span class=\"bl\" style=\"left:56px;top:429px;font-size:14.5px;max-width:46px\">作用”。</span><span class=\"bl\" style=\"left:512px;top:433px;font-size:13.9px;max-width:189px\">①包括：国有经济，集体经济以及混合</span><span class=\"bl b\" style=\"left:79px;top:449px;font-size:14.5px;max-width:340px\">4.党的十九大：再次强调“使市场在资源配置中起决定性作用”。</span><span class=\"bl\" style=\"left:514px;top:452px;font-size:12.2px;max-width:174px\">所有制经济中的国有成分和集体成分。</span><span class=\"bl b\" style=\"left:78px;top:469px;font-size:16.1px;max-width:423px\">5.党的十九届四中全会：明确社会主义市场经济体制为我国社会主义基本经济制</span><span class=\"bl\" style=\"left:514px;top:470px;font-size:12.2px;max-width:188px\">②地位：生产资料公有制是社会主义的</span><span class=\"bl\" style=\"left:52px;top:488px;font-size:32.8px;max-width:263px\">度之晟信公从亏：</span><span class=\"bl\" style=\"left:512px;top:486px;font-size:15.0px;max-width:190px\">根本经济特征，是社会主义经济制度的</span><span class=\"bl\" style=\"left:511px;top:505px;font-size:15.0px;max-width:36px\">基础。</span><span class=\"bl b\" style=\"left:56px;top:520px;font-size:13.9px;max-width:216px\">47.2政府与市场的关系（高频选择题）</span><span class=\"bl\" style=\"left:512px;top:524px;font-size:14.5px;max-width:190px\">③实现形式：资产或资本的组织形式和</span><span class=\"bl\" style=\"left:80px;top:539px;font-size:16.1px;max-width:422px\">1.市场决定资源配置是市场经济的一般规律、市场经济本质上就是市场决定资源</span><span class=\"bl\" style=\"left:513px;top:542px;font-size:13.9px;max-width:155px\">经营方式，比如股份制、合作制。</span><span class=\"bl\" style=\"left:55px;top:558px;font-size:20.6px;max-width:281px\">配置的经济，市场配置资源是最有效率的方式。八</span><span class=\"bl b\" style=\"left:512px;top:560px;font-size:14.5px;max-width:84px\">2.非公有制经济：</span><span class=\"bl\" style=\"left:79px;top:581px;font-size:15.6px;max-width:422px\">2.市场在资源配置中起决定性作用，并不是起全部作用。我国实行的是社会主义</span><span class=\"bl\" style=\"left:512px;top:578px;font-size:14.5px;max-width:190px\">①包括：个体经济、私营经济、外商独资</span><span class=\"bl\" style=\"left:513px;top:597px;font-size:14.5px;max-width:185px\">经济和混合所有制经济中非公有制成分。</span><span class=\"bl\" style=\"left:57px;top:603px;font-size:15.6px;max-width:437px\">市场经济体制，仍然要坚持发挥社会主义制度的优越性、发挥党和政府的积极作用。</span><span class=\"bl\" style=\"left:512px;top:615px;font-size:14.5px;max-width:191px\">②作用：稳定增长、促进创新、扩大就</span><span class=\"bl\" style=\"left:79px;top:622px;font-size:17.8px;max-width:421px\">3.政府的职责和作用主要是保持宏观经济稳定，加强和优化公共服务，保障公</span><span class=\"bl\" style=\"left:513px;top:634px;font-size:13.9px;max-width:75px\">业、增加税收。</span><span class=\"bl\" style=\"left:56px;top:644px;font-size:15.6px;max-width:445px\">平竞争，加强市场监管，维护市场秩序，推动可持续发展，促进共同富裕，弥补市</span><span class=\"bl b\" style=\"left:512px;top:652px;font-size:13.9px;max-width:94px\">3.混合所有制经济：</span><span class=\"bl\" style=\"left:56px;top:666px;font-size:16.1px;max-width:51px\">场失灵。</span><span class=\"bl\" style=\"left:512px;top:669px;font-size:14.5px;max-width:190px\">①包括：国有资本、集体资本、非公有</span><span class=\"bl\" style=\"left:80px;top:685px;font-size:16.1px;max-width:414px\">4.使市场在资源配置中起决定性作用、更好发挥政府作用，二者是有机统一的。</span><span class=\"bl\" style=\"left:513px;top:687px;font-size:15.0px;max-width:189px\">资本交叉持股、相互融合的经济。混合</span><span class=\"bl\" style=\"left:513px;top:706px;font-size:14.5px;max-width:189px\">所有制经济不属于基本制度的内容，是</span><span class=\"bl b\" style=\"left:56px;top:713px;font-size:17.2px;max-width:352px\">47.3必须坚持和完善我国社会主义基本经济制度（高频选择题）</span><span class=\"bl\" style=\"left:514px;top:725px;font-size:13.4px;max-width:125px\">基本经济制度的实现形式。</span><span class=\"bl\" style=\"left:80px;top:735px;font-size:16.1px;max-width:422px\">1.激发各类市场主体活力。毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支</span><span class=\"bl\" style=\"left:514px;top:743px;font-size:13.9px;max-width:189px\">②地位：社会主义初级阶段基本经济制</span><span class=\"bl\" style=\"left:57px;top:759px;font-size:13.9px;max-width:156px\">持、引导非公有制经济发展。</span><span class=\"bl\" style=\"left:410px;top:757px;font-size:14.5px;max-width:91px\">&gt;解读2&gt;提示1</span><span class=\"bl\" style=\"left:514px;top:762px;font-size:12.2px;max-width:94px\">度的重要实现形式。</span><span class=\"bl\" style=\"left:80px;top:778px;font-size:14.5px;max-width:237px\">2.坚持按劳分配为主体、多种分配方式并存。</span><span class=\"bl\" style=\"left:514px;top:779px;font-size:13.9px;max-width:190px\">③作用：有利于国有资本增强控制力、</span><span class=\"bl\" style=\"left:81px;top:797px;font-size:17.2px;max-width:422px\">①坚持多劳多得，着重保护劳动所得，增加劳动者特别是一线劳动者劳动报酬，</span><span class=\"bl\" style=\"left:514px;top:797px;font-size:14.5px;max-width:190px\">提高竞争力，有利于各种所有制资本取</span><span class=\"bl\" style=\"left:58px;top:821px;font-size:12.2px;max-width:189px\">提高劳动报酬在初次分配中的比重。</span><span class=\"bl\" style=\"left:515px;top:816px;font-size:13.9px;max-width:145px\">长补短、相互促进、共同发展。</span><span class=\"bl\" style=\"left:81px;top:838px;font-size:17.2px;max-width:421px\">②健全以税收、社会保障、转移支付等为主要手段的再分配调节机制。完善相关</span><span class=\"bl\" style=\"left:57px;top:861px;font-size:15.0px;max-width:307px\">制度和政策，合理调节城乡、区域、不同群体间分配关系。</span><span class=\"bl\" style=\"left:516px;top:862px;font-size:15.6px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:82px;top:880px;font-size:17.2px;max-width:421px\">③重视发挥第三次分配作用，发展慈善等社会公益事业。鼓励勤劳致富，保护</span><span class=\"bl\" style=\"left:514px;top:885px;font-size:14.5px;max-width:191px\">1.非公有制经济是社会主义性质的经济。</span><span class=\"bl\" style=\"left:58px;top:901px;font-size:17.8px;max-width:445px\">合法收入，增加低收人者收人，扩大中等收人群体，调节过高收入，清理规范隐性收</span><span class=\"bl\" style=\"left:521px;top:905px;font-size:13.4px;max-width:32px\">（×）</span><span class=\"bl\" style=\"left:58px;top:924px;font-size:13.9px;max-width:108px\">人，取缔非法收入。</span><span class=\"bl\" style=\"left:514px;top:921px;font-size:15.0px;max-width:191px\">2.非公有制经济不是社会主义性质的经</span><span class=\"bl\" style=\"left:81px;top:945px;font-size:13.9px;max-width:120px\">3.完善宏观经济治理。</span><span class=\"bl\" style=\"left:524px;top:939px;font-size:15.0px;max-width:131px\">济，公有制经济才是。（√）</span><span class=\"bl\" style=\"left:514px;top:957px;font-size:16.1px;max-width:193px\">3.非公有制经济属于社会主义经济。（×）</span><span class=\"bl\" style=\"left:80px;top:962px;font-size:18.9px;max-width:423px\">4.建设高标准市场体系。健全市场体系基础制度，坚持平等准人、公正监管、开</span><span class=\"bl\" style=\"left:514px;top:975px;font-size:15.6px;max-width:191px\">4.非公有制经济属于社会主义市场经济。</span><span class=\"bl\" style=\"left:58px;top:985px;font-size:15.6px;max-width:330px\">放有序、诚信守法，形成高效规范、公平竞争的国内统一市场。</span><span class=\"bl\" style=\"left:524px;top:995px;font-size:12.8px;max-width:30px\">(V)</span><span class=\"bl\" style=\"left:81px;top:1004px;font-size:17.2px;max-width:422px\">5.加快转变政府职能。建设职责明确、依法行政的政府治理体系。深化简政放</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1093px\"><div class=\"bxnum\">第 57 页</div><div class=\"sidebox\" style=\"left:511px;top:754px;width:195px;height:120px\"></div><span class=\"bl\" style=\"left:66px;top:104px;font-size:13.9px;max-width:318px\">权、放管结合、优化服务改革，全面实行政府权责清单制度。</span><span class=\"bl b hl\" style=\"left:76px;top:144px;font-size:18.4px;max-width:247px\">考点48建设现代化经济体系☆☆☆</span><span class=\"bl b\" style=\"left:66px;top:180px;font-size:12.2px;max-width:257px\">48.1建设现代化经济体系的意义（中频选择题）</span><span class=\"bl\" style=\"left:88px;top:200px;font-size:16.1px;max-width:423px\">1.建设现代化经济体系是我国发展的战略目标，也是转变经济发展方式、优化经</span><span class=\"bl\" style=\"left:66px;top:222px;font-size:13.9px;max-width:213px\">济结构、转换经济增长动力的迫切要求。</span><span class=\"bl\" style=\"left:89px;top:243px;font-size:13.9px;max-width:308px\">2.是开启全面建设社会主义现代化国家新征程的重大任务。</span><span class=\"bl\" style=\"left:89px;top:264px;font-size:13.9px;max-width:367px\">3.是适应我国经济已由高速增长阶段转向高质量发展阶段的必然要求。</span><span class=\"bl\" style=\"left:87px;top:284px;font-size:15.0px;max-width:423px\">4.是遵循经济发展规律、适应我国社会主要矛盾变化、保持经济持续健康发展的</span><span class=\"bl\" style=\"left:65px;top:304px;font-size:16.1px;max-width:61px\">必然要求。</span><span class=\"bl b\" style=\"left:65px;top:332px;font-size:15.0px;max-width:290px\">48.2建设现代化经济体系的科学内涵（低频选择题）</span><span class=\"bl\" style=\"left:89px;top:353px;font-size:17.3px;max-width:423px\">建设现代化经济体系，必须坚持质量第一、效益优先，推动经济发展质量变</span><span class=\"bl\" style=\"left:65px;top:374px;font-size:16.1px;max-width:445px\">革、效率变革、动力变革，提高全要素生产率。现代化经济体系主要包括以下几个</span><span class=\"bl\" style=\"left:66px;top:396px;font-size:14.5px;max-width:61px\">方面内容：</span><span class=\"bl\" style=\"left:88px;top:416px;font-size:15.0px;max-width:214px\">①建设创新引领、协同发展的产业体系。</span><span class=\"bl\" style=\"left:88px;top:436px;font-size:17.3px;max-width:214px\">②建设统一开放、竞争有序的市场体系。</span><span class=\"bl\" style=\"left:89px;top:457px;font-size:17.3px;max-width:237px\">③建设体现效率、促进公平的收入分配体系。</span><span class=\"bl\" style=\"left:86px;top:478px;font-size:17.8px;max-width:258px\">④建设彰显优势、协调联动的城乡区域发展体系</span><span class=\"bl\" style=\"left:85px;top:499px;font-size:17.3px;max-width:238px\">5建设资源节约、环境友好的绿色发展体系。</span><span class=\"bl\" style=\"left:88px;top:520px;font-size:15.0px;max-width:235px\">6建设多元平衡、安全高效的全面开放体系。</span><span class=\"bl\" style=\"left:87px;top:540px;font-size:20.0px;max-width:308px\">建设充分发挥市场作用、更好发挥政府作用的经济体制。</span><span class=\"bl b\" style=\"left:64px;top:569px;font-size:16.1px;max-width:289px\">48.3建设现代化经济体系的主要任务（高频选择题）</span><span class=\"bl\" style=\"left:87px;top:590px;font-size:16.1px;max-width:294px\">1.大力发展实体经济，筑牢现代化经济体系的坚实基础。</span><span class=\"bl\" style=\"left:87px;top:610px;font-size:17.3px;max-width:86px\">①实体经济是：</span><span class=\"bl\" style=\"left:86px;top:631px;font-size:17.3px;max-width:130px\">A.一国经济的立身之本</span><span class=\"bl\" style=\"left:86px;top:653px;font-size:15.6px;max-width:129px\">B.财富创造的根本源泉</span><span class=\"bl\" style=\"left:86px;top:674px;font-size:15.6px;max-width:129px\">C.国家强盛的重要支柱</span><span class=\"bl\" style=\"left:86px;top:694px;font-size:17.3px;max-width:164px\">D.现代化经济体系的坚实基础</span><span class=\"bl\" style=\"left:86px;top:715px;font-size:17.8px;max-width:293px\">②实体经济的关键和重点：发展先进制造业。（2020-6）</span><span class=\"bl\" style=\"left:86px;top:736px;font-size:17.8px;max-width:259px\">③构筑未来发展战略优势的重要支撑：实体经济。</span><span class=\"bl\" style=\"left:86px;top:758px;font-size:17.8px;max-width:341px\">2.加快实施创新驱动发展战略，强化现代化经济体系的战略支撑。</span><span class=\"bl\" style=\"left:460px;top:761px;font-size:15.0px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:527px;top:760px;font-size:13.9px;max-width:96px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:86px;top:777px;font-size:17.3px;max-width:156px\">①我国技术创新体系的内容：</span><span class=\"bl\" style=\"left:519px;top:782px;font-size:15.0px;max-width:164px\">我国建设创新型国家的战略目标是：</span><span class=\"bl\" style=\"left:86px;top:800px;font-size:13.9px;max-width:93px\">A.以企业为主体</span><span class=\"bl\" style=\"left:202px;top:800px;font-size:15.0px;max-width:85px\">B.市场为导向</span><span class=\"bl\" style=\"left:273px;top:799px;font-size:17.8px;max-width:129px\">C.产学研深度融合</span><span class=\"bl\" style=\"left:518px;top:801px;font-size:15.0px;max-width:152px\">到2020年进入创新型国家行列，</span><span class=\"bl\" style=\"left:86px;top:819px;font-size:17.8px;max-width:258px\">②我国实施创新驱动发展战略的方针：（2018-7）</span><span class=\"bl\" style=\"left:518px;top:819px;font-size:15.0px;max-width:150px\">到2035年路身创新型国家前列，</span><span class=\"bl\" style=\"left:86px;top:842px;font-size:14.5px;max-width:93px\">A.坚持自主创新</span><span class=\"bl\" style=\"left:202px;top:842px;font-size:14.5px;max-width:93px\">B.坚持重点跨越</span><span class=\"bl\" style=\"left:518px;top:837px;font-size:15.0px;max-width:190px\">到新中国成立100年时成为世界科技</span><span class=\"bl\" style=\"left:517px;top:855px;font-size:15.0px;max-width:35px\">强国。</span><span class=\"bl\" style=\"left:86px;top:861px;font-size:14.5px;max-width:93px\">C.坚持支撑发展</span><span class=\"bl\" style=\"left:201px;top:861px;font-size:17.3px;max-width:95px\">D.坚持引领未来</span><span class=\"bl\" style=\"left:84px;top:881px;font-size:19.5px;max-width:426px\">3.实施乡村振兴战略，夯实现代化经济体系的重要基础。（2015-23、2017-8）</span><span class=\"bl\" style=\"left:460px;top:907px;font-size:14.5px;max-width:46px\">&gt;拓展2</span><span class=\"bl\" style=\"left:520px;top:908px;font-size:13.9px;max-width:103px\">火星姐姐考点拓展2</span><span class=\"bl\" style=\"left:85px;top:923px;font-size:18.4px;max-width:422px\">①农业农村农民问题是关系国计民生的根本问题，必须始终把解决“三农”问题</span><span class=\"bl\" style=\"left:518px;top:929px;font-size:15.0px;max-width:190px\">实施乡村振兴战略，必须把确保重要农产</span><span class=\"bl\" style=\"left:62px;top:943px;font-size:16.1px;max-width:143px\">作为全党工作的重中之重。</span><span class=\"bl\" style=\"left:518px;top:948px;font-size:15.6px;max-width:190px\">品特别是粮食供给作为首要任务，把提高</span><span class=\"bl\" style=\"left:84px;top:964px;font-size:17.3px;max-width:115px\">②实施乡村振兴战略</span><span class=\"bl\" style=\"left:517px;top:966px;font-size:15.0px;max-width:191px\">农业综合生产能力放在更加突出的位置，</span><span class=\"bl\" style=\"left:85px;top:985px;font-size:15.6px;max-width:178px\">总方针：坚持农业农村优先发展。</span><span class=\"bl\" style=\"left:517px;top:984px;font-size:15.0px;max-width:191px\">把“藏粮于地、藏粮于技”真正落实到位。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 58 页</div><div class=\"sidebox\" style=\"left:506px;top:184px;width:195px;height:267px\"></div><span class=\"bl\" style=\"left:460px;top:61px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:82px;top:106px;font-size:13.9px;max-width:176px\">主线：处理好农民和土地的关系。</span><span class=\"bl\" style=\"left:81px;top:127px;font-size:15.0px;max-width:234px\">根本目的：推进农业农村现代化。（2019-8）</span><span class=\"bl\" style=\"left:82px;top:148px;font-size:13.9px;max-width:420px\">③巩固和完善农村基本经营制度，深化农村土地制度改革，完善承包地“三权”</span><span class=\"bl\" style=\"left:57px;top:169px;font-size:13.9px;max-width:444px\">分置制度。保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长30年。</span><span class=\"bl\" style=\"left:454px;top:190px;font-size:14.5px;max-width:46px\">&gt;解读1</span><span class=\"bl\" style=\"left:522px;top:190px;font-size:15.6px;max-width:95px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:81px;top:211px;font-size:13.9px;max-width:294px\">4.优化国土空间布局，推进区域协调发展和新型城镇化。</span><span class=\"bl\" style=\"left:514px;top:214px;font-size:13.9px;max-width:189px\">农村土地“三权”分置，即形成所有权、</span><span class=\"bl\" style=\"left:80px;top:232px;font-size:13.9px;max-width:156px\">（1）深入实施区域重大战略：</span><span class=\"bl\" style=\"left:512px;top:232px;font-size:14.5px;max-width:190px\">承包权、经营权三权分置，经营权流转</span><span class=\"bl\" style=\"left:82px;top:253px;font-size:13.9px;max-width:153px\">①加快推动京津冀协同发展。</span><span class=\"bl\" style=\"left:513px;top:250px;font-size:14.5px;max-width:45px\">的格局。</span><span class=\"bl\" style=\"left:513px;top:269px;font-size:13.9px;max-width:125px\">农村家庭联产承包责任制：</span><span class=\"bl\" style=\"left:82px;top:275px;font-size:12.2px;max-width:153px\">②全面推动长江经济带发展。</span><span class=\"bl\" style=\"left:513px;top:286px;font-size:14.5px;max-width:190px\">以包产到户、包干到户为主要形式；坚持</span><span class=\"bl\" style=\"left:82px;top:295px;font-size:13.9px;max-width:185px\">③积极稳妥推进粤港澳大湾区建设。</span><span class=\"bl\" style=\"left:514px;top:306px;font-size:12.2px;max-width:188px\">农村土地的集体所有权：将农民家庭承</span><span class=\"bl\" style=\"left:82px;top:316px;font-size:13.9px;max-width:165px\">④提升长三角一体化发展水平。</span><span class=\"bl\" style=\"left:514px;top:323px;font-size:14.5px;max-width:189px\">包经营的积极性和集体经济的优越性结</span><span class=\"bl\" style=\"left:82px;top:336px;font-size:14.5px;max-width:236px\">5扎实推进黄河流域生态保护和高质量发展。</span><span class=\"bl\" style=\"left:514px;top:341px;font-size:14.5px;max-width:45px\">合起来。</span><span class=\"bl\" style=\"left:80px;top:357px;font-size:15.0px;max-width:133px\">（2）区域协调发展战略：</span><span class=\"bl\" style=\"left:513px;top:359px;font-size:14.5px;max-width:190px\">改革开放以来，党在农村政策的重要基</span><span class=\"bl\" style=\"left:82px;top:380px;font-size:12.2px;max-width:130px\">①积极推进西部大开发。</span><span class=\"bl\" style=\"left:514px;top:378px;font-size:13.9px;max-width:190px\">石是：以家庭承包经营为基础、统分结</span><span class=\"bl\" style=\"left:82px;top:400px;font-size:13.9px;max-width:165px\">②振兴东北地区等老工业基地。</span><span class=\"bl\" style=\"left:514px;top:397px;font-size:12.2px;max-width:94px\">合的双层经营体制。</span><span class=\"bl\" style=\"left:513px;top:414px;font-size:15.0px;max-width:190px\">我国实现城镇化的主要任务：推进农业</span><span class=\"bl\" style=\"left:83px;top:421px;font-size:13.9px;max-width:118px\">③促进中部地区崛起。</span><span class=\"bl\" style=\"left:514px;top:432px;font-size:14.5px;max-width:85px\">转移人口市民化。</span><span class=\"bl\" style=\"left:83px;top:442px;font-size:13.9px;max-width:142px\">④鼓励东部地区率先发展。</span><span class=\"bl\" style=\"left:81px;top:461px;font-size:15.6px;max-width:320px\">5.着力发展开放型经济，提高现代化经济体系的国际竞争力。</span><span class=\"bl\" style=\"left:81px;top:481px;font-size:18.4px;max-width:423px\">要在开放的范围和层次上进一步拓展，更要在开放的思想观念、结构布局、体制</span><span class=\"bl\" style=\"left:57px;top:502px;font-size:17.8px;max-width:447px\">机制上进一步拓展。要以“一带一路”建设为重点，坚持引进来和走出去并重，形成</span><span class=\"bl\" style=\"left:57px;top:523px;font-size:18.4px;max-width:446px\">陆海内外联动、东西双向互济的开放格局。有序放宽市场准人，全面实行准人前国民</span><span class=\"bl\" style=\"left:57px;top:543px;font-size:20.0px;max-width:446px\">待遇加负面清单管理模式，继续精简负面清单，抓紧完善外资相关法律，加强知识产</span><span class=\"bl\" style=\"left:56px;top:564px;font-size:21.7px;max-width:64px\">权保护。</span><span class=\"bl\" style=\"left:82px;top:587px;font-size:15.6px;max-width:296px\">6.深化经济体制改革，完善现代化经济体系的制度保障。</span><span class=\"bl\" style=\"left:83px;top:607px;font-size:17.8px;max-width:341px\">①经济体制改革的重点：完善产权制度和要素市场化。（2018-5）</span><span class=\"bl\" style=\"left:83px;top:629px;font-size:15.6px;max-width:294px\">②经济体制改革的核心问题：处理好政府和市场的关系。</span><span class=\"bl\" style=\"left:83px;top:651px;font-size:15.0px;max-width:210px\">③全面深化改革的重点：经济体制改革</span><span class=\"bl\" style=\"left:83px;top:669px;font-size:18.9px;max-width:422px\">④措施：要完善各类国有资产管理体制，推动国有资本做强做优做大。深化国有</span><span class=\"bl\" style=\"left:60px;top:691px;font-size:17.3px;max-width:445px\">企业改革，发展混合所有制经济。支持民营企业发展，激发各类市场主体活力。深化</span><span class=\"bl\" style=\"left:60px;top:712px;font-size:17.8px;max-width:445px\">商事制度改革，全面实施市场准人负面清单制度，加快要素价格市场化改革，完善市</span><span class=\"bl\" style=\"left:59px;top:732px;font-size:18.9px;max-width:447px\">场监管体制。创新和完善宏观调控，发挥国家发展规划的战略导向作用。加快建立现</span><span class=\"bl\" style=\"left:60px;top:755px;font-size:16.1px;max-width:284px\">代财政制度，深化税收制度改革，深化金融体制改革。</span><span class=\"bl b hl\" style=\"left:70px;top:794px;font-size:20.6px;max-width:349px\">考点49 坚持中国特色社会主义政治发展道路☆☆☆</span><span class=\"bl b\" style=\"left:60px;top:829px;font-size:18.4px;max-width:347px\">49.1人民当家作主是我们党矢志不渝的奋斗目标（高频选择题）</span><span class=\"bl\" style=\"left:84px;top:852px;font-size:15.6px;max-width:259px\">1.人民当家作主是社会主义民主政治的本质特征。</span><span class=\"bl\" style=\"left:83px;top:871px;font-size:17.8px;max-width:422px\">2.我国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家，</span><span class=\"bl\" style=\"left:62px;top:895px;font-size:13.9px;max-width:131px\">国家一切权力属于人民。</span><span class=\"bl\" style=\"left:84px;top:913px;font-size:17.8px;max-width:367px\">3.中国共产党领导人民实行人民民主，就是保证和支持人民当家作主。</span><span class=\"bl b\" style=\"left:61px;top:942px;font-size:15.6px;max-width:223px\">49.2走中国特色社会主义政治发展道路</span><span class=\"bl\" style=\"left:85px;top:960px;font-size:18.9px;max-width:422px\">1.中国特色社会主义政治发展道路是近代以来中国人民长期奋斗历史逻辑、理论</span><span class=\"bl\" style=\"left:61px;top:982px;font-size:18.4px;max-width:437px\">逻辑、实践逻辑的必然结果，是坚持党的本质属性、践行党的根本宗旨的必然要求。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1094px\"><div class=\"bxnum\">第 59 页</div><div class=\"sidebox\" style=\"left:512px;top:533px;width:197px;height:303px\"></div><span class=\"bl b\" style=\"left:89px;top:106px;font-size:13.9px;max-width:177px\">2.走中国特色社会主义道路必须：</span><span class=\"bl\" style=\"left:90px;top:127px;font-size:13.9px;max-width:305px\">①必须坚持党的领导、人民当家作主、依法治国有机统一：</span><span class=\"bl\" style=\"left:89px;top:147px;font-size:13.9px;max-width:269px\">A.党的领导是人民当家作主和依法治国的根本保证</span><span class=\"bl\" style=\"left:88px;top:168px;font-size:15.0px;max-width:257px\">B.人民当家作主是社会主义民主政治的本质特征</span><span class=\"bl\" style=\"left:89px;top:190px;font-size:13.9px;max-width:245px\">C.依法治国是党领导人民治理国家的基本方式</span><span class=\"bl\" style=\"left:89px;top:210px;font-size:13.9px;max-width:257px\">D.三者统一于我国社会主义民主政治的伟大实践</span><span class=\"bl\" style=\"left:89px;top:230px;font-size:17.2px;max-width:422px\">②必须坚持正确的政治方向：我们需要借鉴国外政治文明有益成果，但绝不能放</span><span class=\"bl\" style=\"left:65px;top:251px;font-size:15.6px;max-width:132px\">弃中国政治制度的根本。</span><span class=\"bl\" style=\"left:89px;top:272px;font-size:15.6px;max-width:421px\">③必须积极稳妥推进政治体制改革：当前，走中国特色社会主义政治发展道路的</span><span class=\"bl\" style=\"left:65px;top:293px;font-size:15.0px;max-width:378px\">重点任务是深化党和国家机构改革、全面提高国家治理能力和治理水平。</span><span class=\"bl\" style=\"left:87px;top:313px;font-size:17.8px;max-width:423px\">3.事实充分证明，中国社会主义民主政治具有强大生命力，中国特色社会主义政</span><span class=\"bl\" style=\"left:65px;top:335px;font-size:16.1px;max-width:445px\">治发展道路是符合中国国情、保证人民当家作主的正确道路。坚定中国特色社会主义</span><span class=\"bl\" style=\"left:65px;top:355px;font-size:16.1px;max-width:446px\">制度自信，首先要坚定对中国特色社会主义政治制度的自信，增强走中国特色社会主</span><span class=\"bl\" style=\"left:65px;top:376px;font-size:15.6px;max-width:165px\">义政治发展道路的信心和决心。</span><span class=\"bl b hl\" style=\"left:74px;top:415px;font-size:20.0px;max-width:290px\">考点50健全人民当家作主制度体系☆☆☆</span><span class=\"bl b\" style=\"left:64px;top:452px;font-size:15.6px;max-width:234px\">50.1人民当家作主基本内涵（高频选择题）</span><span class=\"bl b\" style=\"left:86px;top:474px;font-size:15.6px;max-width:111px\">1.人民当家作主是：</span><span class=\"bl\" style=\"left:85px;top:492px;font-size:17.8px;max-width:180px\">①社会主义民主政治的本质特征：</span><span class=\"bl\" style=\"left:88px;top:512px;font-size:17.8px;max-width:191px\">②社会主义民主政治的本质和核心。</span><span class=\"bl b\" style=\"left:86px;top:534px;font-size:15.6px;max-width:162px\">2.人民当家作主的基本内涵：</span><span class=\"bl\" style=\"left:230px;top:532px;font-size:48.9px;max-width:219px\">研祝您上岸</span><span class=\"bl\" style=\"left:461px;top:537px;font-size:14.5px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:531px;top:539px;font-size:13.9px;max-width:93px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:86px;top:553px;font-size:17.2px;max-width:143px\">国家一切权力属于人民：</span><span class=\"bl\" style=\"left:520px;top:561px;font-size:15.0px;max-width:151px\">新型政党制度“新”就“新”在：</span><span class=\"bl\" style=\"left:87px;top:574px;font-size:17.8px;max-width:422px\">体现在国家根本性质（即国体）上，就是工人阶级领导的、以工农联盟为基础的</span><span class=\"bl\" style=\"left:520px;top:579px;font-size:15.6px;max-width:191px\">①有效避免了旧式政党制度代表少数人、</span><span class=\"bl\" style=\"left:64px;top:594px;font-size:15.6px;max-width:166px\">人民民主专政的社会主义国家；</span><span class=\"bl\" style=\"left:520px;top:598px;font-size:15.0px;max-width:102px\">少数利益集团的弊端。</span><span class=\"bl\" style=\"left:87px;top:615px;font-size:16.1px;max-width:421px\">体现在国家政权组织形式（即政体）上，就是人民通过各级人民代表大会行使国</span><span class=\"bl\" style=\"left:520px;top:616px;font-size:15.0px;max-width:190px\">②有效避免了一党缺乏监督或多党轮流坐</span><span class=\"bl\" style=\"left:64px;top:635px;font-size:14.5px;max-width:49px\">家权力。</span><span class=\"bl\" style=\"left:520px;top:635px;font-size:13.9px;max-width:102px\">庄、恶性竞争的弊端。</span><span class=\"bl b\" style=\"left:85px;top:654px;font-size:15.6px;max-width:168px\">3.人民当家作主制度体系包括：</span><span class=\"bl\" style=\"left:519px;top:653px;font-size:15.0px;max-width:190px\">③有效避免了旧式政党制度围于党派利</span><span class=\"bl\" style=\"left:85px;top:674px;font-size:18.3px;max-width:225px\">①一个根本政治制度：人民代表大会制度。</span><span class=\"bl\" style=\"left:519px;top:672px;font-size:14.5px;max-width:190px\">益、阶级利益、区域和集团利益决策施政</span><span class=\"bl\" style=\"left:86px;top:694px;font-size:19.5px;max-width:421px\">②三个基本政治制度：中国共产党领导的多党合作和政治协商制度、民族区域自</span><span class=\"bl\" style=\"left:520px;top:690px;font-size:13.9px;max-width:103px\">导致社会撕裂的弊端。</span><span class=\"bl\" style=\"left:519px;top:708px;font-size:13.9px;max-width:112px\">新型政党制度的优越性：</span><span class=\"bl\" style=\"left:63px;top:715px;font-size:15.6px;max-width:155px\">治制度、基层群众自治制度。</span><span class=\"bl\" style=\"left:518px;top:726px;font-size:15.0px;max-width:191px\">①既强调中国共产党的领导，也强调发扬</span><span class=\"bl\" style=\"left:86px;top:736px;font-size:15.6px;max-width:237px\">③一种特有的民主形式：社会主义协商民主。</span><span class=\"bl\" style=\"left:518px;top:746px;font-size:13.9px;max-width:74px\">社会主义民主；</span><span class=\"bl b\" style=\"left:62px;top:762px;font-size:17.8px;max-width:323px\">50.2人民代表大会制度（高频选择题）（2014-6、2015-24）</span><span class=\"bl\" style=\"left:518px;top:763px;font-size:15.0px;max-width:190px\">②不仅符合当代中国实际，而且符合中华</span><span class=\"bl\" style=\"left:85px;top:783px;font-size:17.8px;max-width:378px\">1.人民代表大会制度是我国的根本政治制度。人民代表大会制度的地位：</span><span class=\"bl\" style=\"left:519px;top:782px;font-size:13.9px;max-width:190px\">民族一贯倡导的天下为公、兼容并蓄、求</span><span class=\"bl\" style=\"left:86px;top:804px;font-size:16.1px;max-width:281px\">①保证人民当家作主的根本政治制度和最高实现形式。</span><span class=\"bl\" style=\"left:518px;top:799px;font-size:15.6px;max-width:112px\">同存异等优秀传统文化；</span><span class=\"bl\" style=\"left:518px;top:817px;font-size:15.6px;max-width:152px\">③是对人类政治文明的重大贡献。</span><span class=\"bl\" style=\"left:85px;top:824px;font-size:16.1px;max-width:343px\">②党在国家政权中充分发扬民主、贯彻群众路线的最好实现形式。</span><span class=\"bl\" style=\"left:84px;top:843px;font-size:18.3px;max-width:285px\">③符合中国国情和实际、体现中国社会主义国家性质。</span><span class=\"bl\" style=\"left:85px;top:863px;font-size:17.2px;max-width:283px\">④保证人民当家作主、保障实现中华民族的伟大复兴。</span><span class=\"bl b\" style=\"left:84px;top:883px;font-size:17.2px;max-width:215px\">2.在中国实行人民代表大会制度的原因：</span><span class=\"bl\" style=\"left:85px;top:903px;font-size:17.2px;max-width:246px\">①是中国人民在人类政治制度史上的伟大创造。</span><span class=\"bl\" style=\"left:85px;top:923px;font-size:18.3px;max-width:329px\">②是深刻总结近代以后中国政治生活惨痛教训得出的基本结论。</span><span class=\"bl\" style=\"left:85px;top:944px;font-size:17.2px;max-width:294px\">③是中国社会100多年激越变革、激荡发展的历史结果。</span><span class=\"bl\" style=\"left:84px;top:964px;font-size:17.2px;max-width:272px\">④是中国人民翻身作主、掌握自己命运的必然选择。</span><span class=\"bl\" style=\"left:83px;top:983px;font-size:18.9px;max-width:422px\">3.人民代表大会制度是坚持党的领导、人民当家作主、依法治国有机统一的根本</span><span class=\"bl\" style=\"left:58px;top:1002px;font-size:17.8px;max-width:84px\">政治制度安排。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 60 页</div><div class=\"sidebox\" style=\"left:506px;top:760px;width:197px;height:246px\"></div><span class=\"bl\" style=\"left:458px;top:58px;font-size:16.7px;max-width:244px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:78px;top:105px;font-size:17.3px;max-width:424px\">4.人民代表大会制度之所以具有强大生命力和显著优越性，关键在于它深深植根</span><span class=\"bl\" style=\"left:56px;top:129px;font-size:14.5px;max-width:71px\">于人民之中。</span><span class=\"bl b\" style=\"left:77px;top:148px;font-size:17.3px;max-width:204px\">5.如何坚持和完善人民代表大会制度：</span><span class=\"bl\" style=\"left:79px;top:169px;font-size:14.5px;max-width:284px\">①要支持和保证人民通过人民代表大会行使国家权力。</span><span class=\"bl\" style=\"left:79px;top:191px;font-size:14.0px;max-width:261px\">②发挥人大及其常委会在立法工作中的主导作用。</span><span class=\"bl\" style=\"left:80px;top:212px;font-size:14.0px;max-width:178px\">③健全人大组织制度和工作制度。</span><span class=\"bl\" style=\"left:79px;top:232px;font-size:15.1px;max-width:423px\">④支持和保证人大依法行使立法权、监督权、决定权、任免权，更好发挥人大代</span><span class=\"bl\" style=\"left:56px;top:254px;font-size:14.5px;max-width:47px\">表作用。</span><span class=\"bl\" style=\"left:79px;top:274px;font-size:14.5px;max-width:422px\">5使各级人大及其常委会成为全面担负起宪法法律赋予的各项职责的工作机关，</span><span class=\"bl\" style=\"left:56px;top:297px;font-size:12.3px;max-width:225px\">成为同人民群众保持密切联系的代表机关。</span><span class=\"bl b\" style=\"left:56px;top:323px;font-size:14.0px;max-width:351px\">50.3中国共产党领导的多党合作和政治协商制度（高频选择题）</span><span class=\"bl b\" style=\"left:79px;top:346px;font-size:12.3px;max-width:249px\">1.中国共产党领导的多党合作和政治协商制度：</span><span class=\"bl\" style=\"left:454px;top:345px;font-size:15.1px;max-width:46px\">提示1</span><span class=\"bl\" style=\"left:515px;top:345px;font-size:14.0px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:79px;top:366px;font-size:12.3px;max-width:259px\">①是我国的一项基本政治制度，是新型政党制度。</span><span class=\"bl\" style=\"left:513px;top:368px;font-size:12.3px;max-width:177px\">1.我国的多党合作就是联合执政。（×）</span><span class=\"bl\" style=\"left:80px;top:387px;font-size:14.0px;max-width:296px\">②中国共产党的领导是多党合作的首要前提和根本保证。</span><span class=\"bl\" style=\"left:512px;top:386px;font-size:14.0px;max-width:169px\">2.人民政协是我国的权力机关。（×）</span><span class=\"bl\" style=\"left:79px;top:407px;font-size:15.1px;max-width:133px\">③多党合作是核心内容。</span><span class=\"bl\" style=\"left:513px;top:405px;font-size:12.3px;max-width:190px\">3.宪法和法律是多党合作的政治基础。</span><span class=\"bl\" style=\"left:520px;top:422px;font-size:13.4px;max-width:32px\">（x）</span><span class=\"bl\" style=\"left:79px;top:428px;font-size:15.1px;max-width:273px\">④强调中国共产党的领导，强调发扬社会主义民主。</span><span class=\"bl\" style=\"left:512px;top:441px;font-size:14.0px;max-width:191px\">4.坚持中国共产党的领导是多党合作的政</span><span class=\"bl\" style=\"left:79px;top:448px;font-size:17.3px;max-width:420px\">③与各民主党派合作的基本方针是“长期共存、互相监督、肝胆相照、荣辱与共”。</span><span class=\"bl\" style=\"left:522px;top:459px;font-size:14.0px;max-width:70px\">治基础。（V）</span><span class=\"bl\" style=\"left:79px;top:469px;font-size:17.3px;max-width:418px\">这一制度的显著特征是：共产党领导、多党派合作；共产党执政、多党派参政。</span><span class=\"bl\" style=\"left:512px;top:477px;font-size:14.0px;max-width:192px\">5.中国共产党和各民主党派在政治上是领</span><span class=\"bl b\" style=\"left:78px;top:491px;font-size:15.6px;max-width:110px\">2.人民政协的性质：</span><span class=\"bl\" style=\"left:454px;top:491px;font-size:17.3px;max-width:47px\">&gt;提示2</span><span class=\"bl\" style=\"left:523px;top:495px;font-size:14.0px;max-width:118px\">导与被领导的关系。（V）</span><span class=\"bl\" style=\"left:78px;top:511px;font-size:15.1px;max-width:192px\">①是中国人民爱国统一战线的组织。</span><span class=\"bl\" style=\"left:80px;top:534px;font-size:14.0px;max-width:297px\">②是中国共产党领导的多党合作和政治协商的重要机构。</span><span class=\"bl\" style=\"left:352px;top:534px;font-size:55.8px;max-width:110px\">上</span><span class=\"bl\" style=\"left:515px;top:549px;font-size:14.0px;max-width:103px\">火星姐姐考点提示2</span><span class=\"bl\" style=\"left:80px;top:555px;font-size:14.0px;max-width:270px\">③是我国政治生活中发扬社会主义民主的重要形式。</span><span class=\"bl\" style=\"left:79px;top:576px;font-size:14.0px;max-width:189px\">④是国家治理体系的重要组成部分。</span><span class=\"bl\" style=\"left:513px;top:573px;font-size:12.3px;max-width:189px\">1.人民政协不是国家机关，不能行使国家</span><span class=\"bl\" style=\"left:522px;top:590px;font-size:13.4px;max-width:34px\">职能。</span><span class=\"bl\" style=\"left:80px;top:597px;font-size:14.0px;max-width:165px\">③是具有中国特色的制度安排。</span><span class=\"bl\" style=\"left:513px;top:609px;font-size:12.3px;max-width:189px\">2.人民政协不等于民主党派，在人民政协</span><span class=\"bl b\" style=\"left:79px;top:617px;font-size:14.0px;max-width:250px\">3.新时代加强和改进人民政协工作的总体要求：</span><span class=\"bl\" style=\"left:523px;top:626px;font-size:14.0px;max-width:179px\">的组成与活动中，不仅有民主党派，还</span><span class=\"bl\" style=\"left:79px;top:638px;font-size:14.0px;max-width:235px\">①指导思想：新时代中国特色社会主义思想。</span><span class=\"bl\" style=\"left:523px;top:646px;font-size:12.3px;max-width:131px\">有中国共产党及无党派人士。</span><span class=\"bl\" style=\"left:80px;top:659px;font-size:14.0px;max-width:213px\">②主轴：坚持和发展中国特色社会主义。</span><span class=\"bl\" style=\"left:513px;top:664px;font-size:12.3px;max-width:189px\">3.人民政协不能直接对国家事务进行决</span><span class=\"bl\" style=\"left:79px;top:680px;font-size:14.0px;max-width:259px\">③工作主线：服务实现“两个一百年”奋斗目标。</span><span class=\"bl\" style=\"left:524px;top:682px;font-size:12.3px;max-width:178px\">策，政协的提案、建议案没有法律约</span><span class=\"bl\" style=\"left:80px;top:701px;font-size:14.0px;max-width:316px\">④中心环节：加强思想政治引领、广泛凝聚共识。（2020-7）</span><span class=\"bl\" style=\"left:523px;top:700px;font-size:14.0px;max-width:175px\">束力；政协不能直接去处理行政事务。</span><span class=\"bl\" style=\"left:79px;top:722px;font-size:15.1px;max-width:144px\">③工作主题：团结和民主。</span><span class=\"bl\" style=\"left:80px;top:745px;font-size:14.0px;max-width:308px\">主要职能：政治协商、民主监督、参政议政、凝聚共识。</span><span class=\"bl\" style=\"left:455px;top:743px;font-size:15.1px;max-width:46px\">解读1</span><span class=\"bl\" style=\"left:79px;top:763px;font-size:14.5px;max-width:73px\">7工作要求：</span><span class=\"bl\" style=\"left:515px;top:766px;font-size:14.0px;max-width:104px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:79px;top:785px;font-size:14.0px;max-width:125px\">聚焦党和国家中心任务</span><span class=\"bl\" style=\"left:512px;top:788px;font-size:14.5px;max-width:191px\">政治协商：对国家大政方针和地方的重</span><span class=\"bl\" style=\"left:79px;top:806px;font-size:15.1px;max-width:138px\">围绕团结和民主两大主题</span><span class=\"bl\" style=\"left:514px;top:808px;font-size:12.3px;max-width:189px\">要举措以及经济建设、政治建设、文化</span><span class=\"bl\" style=\"left:79px;top:827px;font-size:14.5px;max-width:291px\">把协商民主贯穿政治协商、民主监督、参政议政全过程</span><span class=\"bl\" style=\"left:514px;top:826px;font-size:12.3px;max-width:189px\">建设、社会建设、生态文明建设中的重</span><span class=\"bl\" style=\"left:79px;top:847px;font-size:15.1px;max-width:315px\">重点监督党和国家重大方针政策和重要决策部署的贯彻落实</span><span class=\"bl\" style=\"left:513px;top:844px;font-size:14.0px;max-width:190px\">要问题，在决策之前和决策实施之中进</span><span class=\"bl\" style=\"left:513px;top:861px;font-size:14.5px;max-width:45px\">行协商。</span><span class=\"bl b\" style=\"left:56px;top:876px;font-size:14.0px;max-width:215px\">50.4民族区域自治制度（高频选择题）</span><span class=\"bl\" style=\"left:513px;top:880px;font-size:14.0px;max-width:191px\">民主监督：对国家宪法、法律和法规的</span><span class=\"bl b\" style=\"left:80px;top:898px;font-size:14.0px;max-width:156px\">1.民族区域自治制度的定位：</span><span class=\"bl\" style=\"left:513px;top:898px;font-size:14.5px;max-width:192px\">实施，重大方针政策、重大改革举措、</span><span class=\"bl\" style=\"left:80px;top:918px;font-size:14.0px;max-width:166px\">①是我国的一项基本政治制度。</span><span class=\"bl\" style=\"left:513px;top:915px;font-size:14.5px;max-width:191px\">重要决策部署的贯彻执行情况，涉及人</span><span class=\"bl\" style=\"left:80px;top:937px;font-size:15.6px;max-width:332px\">②是中国特色解决民族问题的正确道路的重要内容和制度保障。</span><span class=\"bl\" style=\"left:513px;top:933px;font-size:15.1px;max-width:190px\">民群众切身利益的实际问题解决落实情</span><span class=\"bl\" style=\"left:513px;top:952px;font-size:14.5px;max-width:191px\">况，国家机关及其工作人员的工作等，</span><span class=\"bl\" style=\"left:80px;top:959px;font-size:15.1px;max-width:178px\">③是党解决民族问题的基本政策。</span><span class=\"bl\" style=\"left:513px;top:970px;font-size:15.1px;max-width:192px\">通过提出意见、批评、建议的方式进行</span><span class=\"bl b\" style=\"left:79px;top:979px;font-size:16.7px;max-width:423px\">2.民族区域自治制度的内涵：在统一而不可分离的国家领导下，在各少数民族聚</span><span class=\"bl\" style=\"left:514px;top:989px;font-size:14.0px;max-width:75px\">的协商式监督。</span><span class=\"bl\" style=\"left:56px;top:999px;font-size:17.9px;max-width:341px\">居的地方设立自治机关，行使自治权，实行区域自治。（2012-8）</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1101px\"><div class=\"bxnum\">第 61 页</div><div class=\"sidebox\" style=\"left:513px;top:110px;width:196px;height:302px\"></div><span class=\"bl b\" style=\"left:86px;top:104px;font-size:18.4px;max-width:424px\">3.民族区域自治制度的核心：保障少数民族当家作主，管理本民族、本地方事务</span><span class=\"bl\" style=\"left:520px;top:116px;font-size:14.5px;max-width:50px\">（接上页）</span><span class=\"bl\" style=\"left:64px;top:126px;font-size:14.0px;max-width:104px\">的权利。（2016-8）</span><span class=\"bl\" style=\"left:520px;top:134px;font-size:15.1px;max-width:191px\">参政议政：对政治、经济、文化、社会生</span><span class=\"bl\" style=\"left:87px;top:148px;font-size:15.1px;max-width:217px\">4.坚持和完善民族区域自治制度（措施）</span><span class=\"bl\" style=\"left:463px;top:150px;font-size:15.1px;max-width:47px\">&gt;拓展1</span><span class=\"bl\" style=\"left:520px;top:153px;font-size:15.6px;max-width:191px\">活和生态环境等方面的重要问题以及人民</span><span class=\"bl\" style=\"left:88px;top:168px;font-size:15.6px;max-width:309px\">①要坚持统一与自治相结合、民族因素与区域因素相结合；</span><span class=\"bl\" style=\"left:520px;top:171px;font-size:14.5px;max-width:191px\">群众普遍关心的问题，开展调查研究，反</span><span class=\"bl\" style=\"left:88px;top:189px;font-size:15.6px;max-width:424px\">②把宪法和民族区域自治法的规定落实好，帮助民族自治地方发展经济、改善民</span><span class=\"bl\" style=\"left:520px;top:190px;font-size:14.5px;max-width:191px\">映社情民意，进行协商讨论。通过调研报</span><span class=\"bl\" style=\"left:63px;top:210px;font-size:15.6px;max-width:368px\">生，使民族区域自治制度这一理论根源越扎越深、实践根基越打越牢。</span><span class=\"bl\" style=\"left:521px;top:208px;font-size:14.5px;max-width:190px\">告、提案、建议案或其他形式，向中国共</span><span class=\"bl b\" style=\"left:86px;top:231px;font-size:15.1px;max-width:157px\">5.民族区域自治制度的作用：</span><span class=\"bl\" style=\"left:521px;top:226px;font-size:14.5px;max-width:152px\">产党和国家机关提出意见和建议。</span><span class=\"bl\" style=\"left:87px;top:253px;font-size:15.6px;max-width:297px\">既保证了国家团结统一，又实现了各民族共同当家作主。</span><span class=\"bl\" style=\"left:522px;top:262px;font-size:14.0px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:88px;top:273px;font-size:15.1px;max-width:225px\">符合我国国情，维护祖国统一、领土完整。</span><span class=\"bl b\" style=\"left:520px;top:285px;font-size:12.3px;max-width:141px\">1.处理民族问题的的基本原则：</span><span class=\"bl\" style=\"left:88px;top:294px;font-size:15.1px;max-width:331px\">加强民族平等团结，促进民族地区发展，增强中华民族凝聚力。</span><span class=\"bl\" style=\"left:530px;top:301px;font-size:15.6px;max-width:83px\">①维护祖国统一；</span><span class=\"bl b\" style=\"left:63px;top:322px;font-size:15.1px;max-width:216px\">50.5基层群众自治制度（高频选择题）</span><span class=\"bl\" style=\"left:530px;top:320px;font-size:15.6px;max-width:83px\">②反对民族分裂；</span><span class=\"bl\" style=\"left:531px;top:340px;font-size:12.3px;max-width:176px\">③坚持民族平等、民族团结、各民族共</span><span class=\"bl b\" style=\"left:88px;top:346px;font-size:12.3px;max-width:216px\">1.基层群众自治制度的定位：（2012-23）</span><span class=\"bl\" style=\"left:530px;top:358px;font-size:12.9px;max-width:42px\">同繁荣。</span><span class=\"bl\" style=\"left:88px;top:366px;font-size:14.0px;max-width:166px\">①是我国的一项基本政治制度；</span><span class=\"bl b\" style=\"left:519px;top:376px;font-size:14.0px;max-width:192px\">2.实行民族区域自治的历史依据：统一的</span><span class=\"bl\" style=\"left:86px;top:386px;font-size:17.3px;max-width:274px\">②是社会主义民主政治建设的基础和重要组成部分；</span><span class=\"bl\" style=\"left:532px;top:396px;font-size:12.3px;max-width:140px\">多民族国家的长期存在和发展。</span><span class=\"bl\" style=\"left:88px;top:408px;font-size:14.0px;max-width:224px\">③是当代中国最直接、最广泛的民主形式。</span><span class=\"bl b\" style=\"left:86px;top:430px;font-size:14.0px;max-width:424px\">2.基层群众自治制度的内涵：它是依照宪法和法律的规定，由居民（村民）选举</span><span class=\"bl\" style=\"left:64px;top:451px;font-size:14.0px;max-width:446px\">的成员组成居民（村民）委员会，实行自我管理、自我教育、自我服务、自我监督的</span><span class=\"bl\" style=\"left:63px;top:471px;font-size:15.1px;max-width:36px\">制度。</span><span class=\"bl b\" style=\"left:81px;top:493px;font-size:14.0px;max-width:430px\">3.基层民主自治体系的主要内容有：农村村民委员会、城市居民委员会、企业职</span><span class=\"bl\" style=\"left:64px;top:510px;font-size:19.6px;max-width:99px\">工代表大会。二</span><span class=\"bl b\" style=\"left:88px;top:535px;font-size:12.3px;max-width:238px\">4.完善基层民主制度，发展基层民主的措施：</span><span class=\"bl\" style=\"left:88px;top:555px;font-size:14.0px;max-width:423px\">城市的居民委员会协调会制度、听证会制度、评议会制度、居民来访制度、居委</span><span class=\"bl\" style=\"left:65px;top:576px;font-size:14.0px;max-width:446px\">会报告制度等，农村的村民委员会选举、村民会议和代表会议、村民民主管理和民主</span><span class=\"bl\" style=\"left:65px;top:598px;font-size:12.3px;max-width:353px\">监督等方式方法，充分保障基层群众享有更多、更切实的民主权利。</span><span class=\"bl b\" style=\"left:88px;top:618px;font-size:14.0px;max-width:363px\">5.一个国家民主不民主，关键在于：是不是真正做到了人民当家作主</span><span class=\"bl\" style=\"left:88px;top:639px;font-size:14.0px;max-width:309px\">①要看人民有没有投票权，更要看人民有没有广泛参与权。</span><span class=\"bl\" style=\"left:88px;top:660px;font-size:14.5px;max-width:422px\">②要看人民在选举过程中得到了什么口头许诺，更要看选举后这些承诺实现了</span><span class=\"bl\" style=\"left:64px;top:682px;font-size:13.4px;max-width:36px\">多少。</span><span class=\"bl\" style=\"left:88px;top:702px;font-size:13.4px;max-width:422px\">③要看制度和法律规定了什么样的政治程序和政治规则，更要看这些制度和法律</span><span class=\"bl\" style=\"left:64px;top:723px;font-size:14.0px;max-width:130px\">是不是真正得到了执行。</span><span class=\"bl\" style=\"left:88px;top:743px;font-size:15.6px;max-width:418px\">④要看权力运行规则和程序是否民主，更要看权力是否真正受到人民监督和制约。</span><span class=\"bl\" style=\"left:87px;top:765px;font-size:14.0px;max-width:423px\">6.我国全过程人民民主不仅有完整的制度程序，而且有完整的参与实践。我国全</span><span class=\"bl\" style=\"left:63px;top:785px;font-size:15.1px;max-width:448px\">过程人民民主实现了过程民主和成果民主、程序民主和实质民主、直接民主和间接民</span><span class=\"bl\" style=\"left:63px;top:806px;font-size:15.6px;max-width:447px\">主、人民民主和国家意志相统一，是全链条、全方位、全覆盖的民主，是最广泛、最</span><span class=\"bl\" style=\"left:64px;top:827px;font-size:15.1px;max-width:166px\">真实、最管用的社会主义民主。</span><span class=\"bl b\" style=\"left:63px;top:855px;font-size:14.5px;max-width:217px\">50.6社会主义协商民主（高频选择题）</span><span class=\"bl b\" style=\"left:86px;top:876px;font-size:15.1px;max-width:308px\">1.人民民主的真谛：有事好商量，众人的事情由众人商量。</span><span class=\"bl b\" style=\"left:86px;top:897px;font-size:15.6px;max-width:423px\">2.协商民主：是在中国共产党领导下，人民内部各方面围绕改革发展稳定重大问</span><span class=\"bl\" style=\"left:63px;top:917px;font-size:15.6px;max-width:447px\">题和涉及群众利益的实际问题，在决策之前和决策实施中，开展广泛协商，努力形成</span><span class=\"bl\" style=\"left:63px;top:939px;font-size:14.0px;max-width:118px\">共识的重要民主形式。</span><span class=\"bl b\" style=\"left:85px;top:959px;font-size:15.6px;max-width:309px\">3.社会主义协商民主是中国社会主义民主政治的特有形式：</span><span class=\"bl\" style=\"left:86px;top:980px;font-size:16.8px;max-width:424px\">①根源：社会主义协商民主具有深厚的文化基础、理论基础、实践基础、制度</span><span class=\"bl\" style=\"left:62px;top:1000px;font-size:15.1px;max-width:37px\">基础。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1101px\"><div class=\"bxnum\">第 62 页</div><span class=\"bl\" style=\"left:459px;top:59px;font-size:16.8px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:78px;top:107px;font-size:16.8px;max-width:259px\">A.它源于中华民族长期形成的优秀传统政治文化</span><span class=\"bl\" style=\"left:79px;top:129px;font-size:15.1px;max-width:223px\">B.源自近代以后中国政治发展的现实进程</span><span class=\"bl\" style=\"left:78px;top:149px;font-size:15.6px;max-width:329px\">C.源自中国共产党领导人民进行革命、建设、改革的长期实践</span><span class=\"bl\" style=\"left:78px;top:170px;font-size:16.8px;max-width:423px\">D.源自新中国成立后各党派、各团体、各民族、各阶层、各界人士在政治制度</span><span class=\"bl\" style=\"left:57px;top:193px;font-size:14.5px;max-width:77px\">上的伟大实践</span><span class=\"bl\" style=\"left:79px;top:214px;font-size:14.0px;max-width:269px\">E.源自改革开放以来中国在政治体制上的不断创新</span><span class=\"bl\" style=\"left:79px;top:233px;font-size:15.1px;max-width:422px\">②意义：协商民主适应了我国经济社会发展不同历史时期的实际需要，是中国共</span><span class=\"bl\" style=\"left:55px;top:254px;font-size:14.5px;max-width:439px\">产党和中国人民的伟大创造，是适合中国国情、具有鲜明中国特色的重要民主形式。</span><span class=\"bl\" style=\"left:78px;top:275px;font-size:14.5px;max-width:292px\">4.社会主义协商民主是中国社会主义民主政治独特优势</span><span class=\"bl\" style=\"left:80px;top:297px;font-size:14.0px;max-width:423px\">①独特优势的体现：社会主义协商民主有利于扩大公民有序政治参与，更好实现</span><span class=\"bl\" style=\"left:55px;top:317px;font-size:15.6px;max-width:119px\">人民当家作主的权利。</span><span class=\"bl\" style=\"left:80px;top:339px;font-size:14.0px;max-width:272px\">②我国协商民主建设是全方位、多层次、立体化的：</span><span class=\"bl\" style=\"left:79px;top:359px;font-size:14.0px;max-width:423px\">A.从渠道看，包含政党协商、人大协商、政府协商、政协协商、人民团体协商、</span><span class=\"bl\" style=\"left:56px;top:381px;font-size:14.0px;max-width:166px\">基层协商以及社会组织协商等；</span><span class=\"bl\" style=\"left:78px;top:401px;font-size:15.1px;max-width:424px\">B.从内容看，涵盖党和国家政治生活中的重大事项，法律法规的制定和修改，</span><span class=\"bl\" style=\"left:55px;top:422px;font-size:14.5px;max-width:447px\">经济社会发展的重要决策，涉及人民群众切身利益的实际问题，各协商渠道自身建设</span><span class=\"bl\" style=\"left:55px;top:442px;font-size:16.8px;max-width:85px\">的相关事务等；</span><span class=\"bl\" style=\"left:79px;top:464px;font-size:14.5px;max-width:424px\">C.从层级看，包括从中央到基层各个层级。通过社会主义协商民主，吸纳各党</span><span class=\"bl\" style=\"left:55px;top:484px;font-size:17.3px;max-width:447px\">派团体、社会各阶层各领域广泛参与协商，广泛接受批评和监督，充分反映各方面意</span><span class=\"bl\" style=\"left:54px;top:505px;font-size:17.3px;max-width:448px\">见建议，可以广泛达成决策和工作的最大共识，确保广大人民群众的民主权利最大限</span><span class=\"bl\" style=\"left:55px;top:526px;font-size:15.6px;max-width:215px\">度地得到实现，真正实现人民当家作主。</span><span class=\"bl\" style=\"left:78px;top:547px;font-size:16.8px;max-width:152px\">5.社会主义协商民主的作用</span><span class=\"bl\" style=\"left:79px;top:567px;font-size:17.3px;max-width:356px\">①有利于促进科学民主决策，推进国家治理体系和治理能力现代化。</span><span class=\"bl\" style=\"left:79px;top:590px;font-size:14.5px;max-width:238px\">②有利于化解矛盾冲突，促进社会和谐稳定。</span><span class=\"bl\" style=\"left:80px;top:611px;font-size:14.0px;max-width:422px\">③有利于保持党同人民群众的血肉联系，巩固和扩大党的执政基础。协商民主是</span><span class=\"bl\" style=\"left:55px;top:632px;font-size:14.5px;max-width:249px\">中国共产党的群众路线在政治领域的重要体现。</span><span class=\"bl\" style=\"left:80px;top:654px;font-size:12.3px;max-width:248px\">4有利于进一步改善党的领导方式和工作作风。</span><span class=\"bl\" style=\"left:79px;top:674px;font-size:14.0px;max-width:422px\">③有利于发挥我国政治制度优越性，增强中国特色社会主义道路自信、理论自</span><span class=\"bl\" style=\"left:56px;top:695px;font-size:14.0px;max-width:141px\">信、制度自信、文化自信。</span><span class=\"bl b hl\" style=\"left:67px;top:736px;font-size:15.6px;max-width:272px\">考点51巩固和发展爱国统一战线☆☆☆</span><span class=\"bl b\" style=\"left:56px;top:772px;font-size:14.0px;max-width:280px\">51.1爱国统一战线的内容（低频选择题）（2016-26）</span><span class=\"bl\" style=\"left:79px;top:792px;font-size:15.1px;max-width:423px\">今天的爱国统一战线是由中国共产党领导的，有各民主党派和各人民团体参加</span><span class=\"bl\" style=\"left:55px;top:814px;font-size:14.5px;max-width:61px\">的，包括：</span><span class=\"bl\" style=\"left:80px;top:835px;font-size:14.0px;max-width:125px\">①全体社会主义劳动者</span><span class=\"bl\" style=\"left:80px;top:856px;font-size:14.0px;max-width:136px\">②社会主义事业的建设者</span><span class=\"bl\" style=\"left:80px;top:876px;font-size:14.0px;max-width:136px\">③拥护社会主义的爱国者</span><span class=\"bl\" style=\"left:80px;top:897px;font-size:14.0px;max-width:278px\">④拥护祖国统一和致力于中华民族伟大复兴的爱国者</span><span class=\"bl b\" style=\"left:55px;top:925px;font-size:14.5px;max-width:285px\">51.2巩固和发展爱国统一战线的举措（中频选择题）</span><span class=\"bl\" style=\"left:79px;top:945px;font-size:15.6px;max-width:423px\">1.要坚持长期共存、互相监督、肝胆相照、荣辱与共，支持民主党派按照中国特</span><span class=\"bl\" style=\"left:57px;top:968px;font-size:14.0px;max-width:200px\">色社会主义参政党要求更好履行职能。</span><span class=\"bl\" style=\"left:79px;top:987px;font-size:15.6px;max-width:297px\">2.要深化民族团结进步教育，铸牢中华民族共同体意识。</span><span class=\"bl\" style=\"left:79px;top:1007px;font-size:17.3px;max-width:358px\">3.要全面贯彻党的宗教工作基本方针，坚持我国宗教的中国化方向。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 63 页</div><div class=\"sidebox\" style=\"left:515px;top:111px;width:197px;height:912px\"></div><span class=\"bl\" style=\"left:88px;top:104px;font-size:17.3px;max-width:355px\">①党的宗教工作的工作重点：积极引导宗教与社会主义社会相适应。</span><span class=\"bl\" style=\"left:523px;top:117px;font-size:15.6px;max-width:103px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:88px;top:125px;font-size:17.9px;max-width:422px\">②引导宗教与社会主义社会相适应的一个重要任务：支持我国宗教坚持中国化方</span><span class=\"bl\" style=\"left:522px;top:140px;font-size:15.1px;max-width:191px\">新型政商关系，是指建立在制度化、法治</span><span class=\"bl\" style=\"left:64px;top:146px;font-size:15.6px;max-width:144px\">向。坚持中国化方向是指：</span><span class=\"bl\" style=\"left:522px;top:159px;font-size:14.5px;max-width:191px\">化基础上的平等、独立、合作和互补的企</span><span class=\"bl\" style=\"left:87px;top:168px;font-size:16.8px;max-width:402px\">A.无论本土宗教还是外来宗教，都要不断适应我国社会发展，充实时代内涵</span><span class=\"bl\" style=\"left:523px;top:176px;font-size:14.5px;max-width:191px\">业与政府之间的关系，与完善的市场经济</span><span class=\"bl\" style=\"left:87px;top:189px;font-size:15.6px;max-width:342px\">B.要用社会主义核心价值观引领、用中华文化浸润我国各种宗教</span><span class=\"bl\" style=\"left:522px;top:194px;font-size:14.5px;max-width:191px\">相适应，而不是建立在非正式的、人际关</span><span class=\"bl\" style=\"left:88px;top:210px;font-size:15.6px;max-width:353px\">C.支持宗教界对宗教思想、教规教义进行符合时代进步要求的阐释</span><span class=\"bl\" style=\"left:523px;top:211px;font-size:14.5px;max-width:190px\">系基础上的，尤其是建立在官商个人利益</span><span class=\"bl\" style=\"left:88px;top:231px;font-size:15.6px;max-width:318px\">D.坚决防范西方意识形态渗透，自觉抵御极端主义思潮影响</span><span class=\"bl\" style=\"left:522px;top:229px;font-size:14.5px;max-width:192px\">基础上的政商关系。习近平总书记反复强</span><span class=\"bl\" style=\"left:522px;top:246px;font-size:14.5px;max-width:192px\">调，“官”‘商”交往要有道”，要做到</span><span class=\"bl\" style=\"left:88px;top:253px;font-size:15.1px;max-width:217px\">③党的宗教工作的基本方针：（2013-23）</span><span class=\"bl\" style=\"left:522px;top:263px;font-size:14.5px;max-width:192px\">“君子之交淡如水”，“而不要勾肩搭背、</span><span class=\"bl\" style=\"left:88px;top:273px;font-size:14.5px;max-width:200px\">A.全面贯彻党的宗教信仰自由的政策</span><span class=\"bl\" style=\"left:523px;top:282px;font-size:12.3px;max-width:189px\">不分彼此”，“不能搞成封建官僚和“红</span><span class=\"bl\" style=\"left:88px;top:294px;font-size:14.0px;max-width:115px\">B.依法管理宗教事务</span><span class=\"bl\" style=\"left:523px;top:300px;font-size:12.3px;max-width:189px\">顶商人’之间的那种关系，也不能搞成西</span><span class=\"bl\" style=\"left:88px;top:316px;font-size:14.0px;max-width:151px\">C.坚持独立自主自办的原则</span><span class=\"bl\" style=\"left:523px;top:318px;font-size:12.3px;max-width:189px\">方国家大财团和政界之间的那种关系，更</span><span class=\"bl\" style=\"left:88px;top:337px;font-size:15.1px;max-width:212px\">D.积极引导宗教与社会主义社会相适应</span><span class=\"bl\" style=\"left:523px;top:335px;font-size:12.3px;max-width:190px\">不能搞成吃吃喝喝、酒肉朋友的那种关</span><span class=\"bl\" style=\"left:523px;top:352px;font-size:14.0px;max-width:190px\">系”。“亲”“清”二字的精辟论述，是习</span><span class=\"bl\" style=\"left:88px;top:358px;font-size:14.5px;max-width:392px\">其中，前三条是重大政策和原则，第四条是根本方向和目的，是工作重点。</span><span class=\"bl\" style=\"left:522px;top:370px;font-size:12.3px;max-width:190px\">近平总书记对新型政商关系本质特征精</span><span class=\"bl\" style=\"left:87px;top:379px;font-size:14.5px;max-width:273px\">4.要牢牢把握大团结大联合的主题，做好统战工作。</span><span class=\"bl\" style=\"left:522px;top:388px;font-size:12.3px;max-width:190px\">准而生动地诠释，体现了政商之间既相处</span><span class=\"bl\" style=\"left:88px;top:400px;font-size:14.0px;max-width:191px\">①统一战线的主题：大团结大联合。</span><span class=\"bl\" style=\"left:522px;top:405px;font-size:12.3px;max-width:190px\">“亲密”又不失“分寸”的最佳状态和内</span><span class=\"bl\" style=\"left:87px;top:420px;font-size:17.3px;max-width:251px\">②统一战线的方针：坚持一致性和多样性统一。</span><span class=\"bl\" style=\"left:523px;top:423px;font-size:12.3px;max-width:189px\">在关系。“亲”，既强调政府依法尽责为</span><span class=\"bl\" style=\"left:89px;top:443px;font-size:14.0px;max-width:272px\">③统一战线工作的根本任务：争取人心、凝聚力量。</span><span class=\"bl\" style=\"left:523px;top:440px;font-size:12.3px;max-width:189px\">企业发展服务，真心实意支持经济发展，</span><span class=\"bl\" style=\"left:523px;top:457px;font-size:12.3px;max-width:189px\">领导干部坦荡真诚同企业家接触交往，帮</span><span class=\"bl\" style=\"left:88px;top:464px;font-size:14.0px;max-width:140px\">A.加强党外知识分子工作</span><span class=\"bl\" style=\"left:523px;top:475px;font-size:12.3px;max-width:190px\">助解决企业实际困难，又倡导企业积极建</span><span class=\"bl\" style=\"left:86px;top:484px;font-size:15.6px;max-width:166px\">B.做好新的社会阶层人士工作</span><span class=\"bl\" style=\"left:523px;top:493px;font-size:12.3px;max-width:189px\">言献策、释放经济活力，引导企业家爱国</span><span class=\"bl\" style=\"left:87px;top:506px;font-size:14.0px;max-width:141px\">C.构建亲清新型政商关系</span><span class=\"bl\" style=\"left:463px;top:506px;font-size:14.5px;max-width:45px\">&gt;解读1</span><span class=\"bl\" style=\"left:523px;top:511px;font-size:12.3px;max-width:189px\">敬业、回报社会。“清”，既强调领导干</span><span class=\"bl\" style=\"left:88px;top:527px;font-size:14.0px;max-width:200px\">D.广泛团结联系海外侨胞和归侨侨眷</span><span class=\"bl\" style=\"left:523px;top:528px;font-size:12.3px;max-width:189px\">部在同企业家打交道时要清白纯洁、把好</span><span class=\"bl\" style=\"left:523px;top:546px;font-size:12.3px;max-width:190px\">分寸，不能以权谋私，不能搞权钱交易，</span><span class=\"bl b hl\" style=\"left:74px;top:566px;font-size:17.9px;max-width:265px\">考点52建设社会主义文化强国☆☆</span><span class=\"bl\" style=\"left:523px;top:563px;font-size:12.3px;max-width:189px\">又要求企业家洁身自好、诚信经营，坚守</span><span class=\"bl\" style=\"left:522px;top:580px;font-size:12.3px;max-width:190px\">道德底线、守住法律红线。政商交往要</span><span class=\"bl b\" style=\"left:63px;top:602px;font-size:14.5px;max-width:404px\">52.1坚持马克思主义在意识形态领域指导地位的根本制度（低频选择题）</span><span class=\"bl\" style=\"left:522px;top:598px;font-size:12.3px;max-width:190px\">既“亲”又“清”，既不能楚河汉界，不</span><span class=\"bl\" style=\"left:523px;top:616px;font-size:12.3px;max-width:189px\">相往来，“清而不亲”；也不能勾肩搭背，</span><span class=\"bl b\" style=\"left:87px;top:625px;font-size:14.0px;max-width:424px\">1.意识形态的重要性：关乎旗帜、关乎道路、关乎国家安全，决定文化前进方向</span><span class=\"bl\" style=\"left:521px;top:631px;font-size:16.8px;max-width:66px\">“亲而不清”。</span><span class=\"bl\" style=\"left:65px;top:646px;font-size:12.9px;max-width:46px\">和道路。</span><span class=\"bl\" style=\"left:463px;top:646px;font-size:15.1px;max-width:47px\">&gt;解读2</span><span class=\"bl\" style=\"left:86px;top:666px;font-size:14.0px;max-width:425px\">2.党的十九届四中全会着眼新时代党和国家事业全局，明确把坚持马克思主义在</span><span class=\"bl\" style=\"left:523px;top:667px;font-size:14.0px;max-width:104px\">火星姐姐考点解读2</span><span class=\"bl\" style=\"left:64px;top:687px;font-size:14.5px;max-width:448px\">意识形态领域的指导地位确立为根本制度，集中体现了我们党在领导文化建设长期实</span><span class=\"bl\" style=\"left:522px;top:690px;font-size:14.0px;max-width:91px\">做好意识形态工作：</span><span class=\"bl\" style=\"left:63px;top:708px;font-size:14.5px;max-width:448px\">践中积累的成功经验和形成的方针原则，充分反映了我们党对社会主义文化建设规律</span><span class=\"bl\" style=\"left:522px;top:709px;font-size:12.3px;max-width:190px\">①党和国家指导思想在我国社会主义意识</span><span class=\"bl\" style=\"left:64px;top:730px;font-size:12.9px;max-width:60px\">的新认识。</span><span class=\"bl\" style=\"left:523px;top:726px;font-size:12.3px;max-width:189px\">形态中占据统摄地位，必须持续加强理论</span><span class=\"bl\" style=\"left:523px;top:744px;font-size:12.3px;max-width:189px\">武装工作。把坚定“四个自信”作为建设</span><span class=\"bl b\" style=\"left:86px;top:749px;font-size:14.5px;max-width:252px\">3.怎样坚持马克思主义在意识形态的领导地位：</span><span class=\"bl\" style=\"left:522px;top:760px;font-size:12.3px;max-width:190px\">社会主义意识形态的关键。把凝聚民心作</span><span class=\"bl\" style=\"left:87px;top:770px;font-size:15.1px;max-width:262px\">①把马克思主义指导地位贯穿到文化建设各方面。</span><span class=\"bl\" style=\"left:523px;top:778px;font-size:12.3px;max-width:160px\">为意识形态工作的出发点和落脚点。</span><span class=\"bl\" style=\"left:87px;top:791px;font-size:15.1px;max-width:214px\">②实施马克思主义理论研究和建设工程。</span><span class=\"bl\" style=\"left:523px;top:796px;font-size:12.3px;max-width:189px\">2做好意识形态工作，必须坚持和加强党</span><span class=\"bl\" style=\"left:87px;top:812px;font-size:15.1px;max-width:179px\">③加强和改进学校思想政治教育。</span><span class=\"bl\" style=\"left:522px;top:814px;font-size:12.3px;max-width:132px\">对意识形态工作的全面领导。</span><span class=\"bl\" style=\"left:87px;top:833px;font-size:15.1px;max-width:422px\">4落实意识形态工作责任制。坚持党管宣传、党管意识形态、党管媒体不动摇，</span><span class=\"bl\" style=\"left:522px;top:831px;font-size:13.4px;max-width:190px\">③坚持以社会主义核心价值观引领文化</span><span class=\"bl\" style=\"left:63px;top:854px;font-size:15.6px;max-width:447px\">压紧压实做好意识形态工作的政治责任、领导责任，把意识形态工作领导权牢牢掌握</span><span class=\"bl\" style=\"left:522px;top:849px;font-size:12.3px;max-width:190px\">建设制度。推动理想信念教育常态化、</span><span class=\"bl\" style=\"left:521px;top:865px;font-size:15.1px;max-width:45px\">制度化。</span><span class=\"bl\" style=\"left:63px;top:874px;font-size:16.8px;max-width:448px\">在党的手中，不断增强意识形态领域的主导权和话语权，切实维护政治安全、文化安</span><span class=\"bl\" style=\"left:521px;top:882px;font-size:15.1px;max-width:190px\">④哲学社会科学是人们认识世界、改造</span><span class=\"bl\" style=\"left:63px;top:895px;font-size:15.1px;max-width:108px\">全、意识形态安全。</span><span class=\"bl\" style=\"left:523px;top:902px;font-size:10.1px;max-width:188px\">世界的重要工具，具有鲜明的意识形态属</span><span class=\"bl\" style=\"left:522px;top:919px;font-size:12.3px;max-width:189px\">性。坚持马克思主义在我国哲学社会科学</span><span class=\"bl\" style=\"left:522px;top:935px;font-size:15.6px;max-width:84px\">领域的指导地位。</span><span class=\"bl\" style=\"left:521px;top:953px;font-size:14.5px;max-width:191px\">5新闻舆论工作处在意识形态斗争最前沿，</span><span class=\"bl\" style=\"left:522px;top:972px;font-size:12.3px;max-width:189px\">是党的一项重要工作，是治国理政、定国</span><span class=\"bl\" style=\"left:521px;top:988px;font-size:14.5px;max-width:190px\">安邦的大事。做好党的新闻舆论工作，必</span><span class=\"bl\" style=\"left:522px;top:1007px;font-size:12.3px;max-width:186px\">须把政治方向摆在第一位，坚持党性原则。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 64 页</div><span class=\"bl\" style=\"left:454px;top:61px;font-size:14.0px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:48px;top:110px;font-size:15.1px;max-width:350px\">52.2培育和践行社会主义核心价值观（中频选择题）（2019-30）</span><span class=\"bl b\" style=\"left:73px;top:132px;font-size:14.0px;max-width:132px\">1.核心价值观的重要性：</span><span class=\"bl\" style=\"left:73px;top:152px;font-size:14.0px;max-width:190px\">①是一个民族赖以维系的精神纽带。</span><span class=\"bl\" style=\"left:73px;top:174px;font-size:14.0px;max-width:189px\">②是一个国家共同的思想道德基础。</span><span class=\"bl\" style=\"left:73px;top:195px;font-size:14.0px;max-width:155px\">③是一个国家的重要稳定器。</span><span class=\"bl b\" style=\"left:72px;top:214px;font-size:15.1px;max-width:312px\">2.积极培育和践行社会主义核心价值观的优势：（2015-26）</span><span class=\"bl\" style=\"left:74px;top:236px;font-size:14.0px;max-width:284px\">①有利于巩固马克思主义在意识形态领域的指导地位。</span><span class=\"bl\" style=\"left:73px;top:256px;font-size:14.5px;max-width:284px\">②有利于巩固全党全国人民团结奋斗的共同思想基础。</span><span class=\"bl\" style=\"left:73px;top:278px;font-size:14.5px;max-width:261px\">③有利于促进人的全面发展和引领社会全面进步。</span><span class=\"bl\" style=\"left:74px;top:299px;font-size:14.0px;max-width:307px\">④有利于集聚实现中华民族伟大复兴中国梦的强大正能量。</span><span class=\"bl b\" style=\"left:72px;top:319px;font-size:15.1px;max-width:263px\">3.社会主义核心价值观的基本内容与回答的问题：</span><span class=\"bl\" style=\"left:72px;top:339px;font-size:16.7px;max-width:274px\">①建设什么样的国家一富强、民主、文明、和谐。</span><span class=\"bl\" style=\"left:73px;top:359px;font-size:18.4px;max-width:274px\">②建设什么样的社会一自由、平等、公正、法治。</span><span class=\"bl\" style=\"left:72px;top:380px;font-size:17.3px;max-width:275px\">③培育什么样的公民一爱国、敬业、诚信、友善。</span><span class=\"bl b\" style=\"left:71px;top:403px;font-size:15.6px;max-width:424px\">4.社会主义核心价值观的意义：体现了社会主义本质要求、继承了中华优秀传统</span><span class=\"bl\" style=\"left:48px;top:423px;font-size:17.9px;max-width:447px\">文化、体现了时代精神，把涉及国家、社会、公民三个层面的价值要求融为一体，是</span><span class=\"bl\" style=\"left:48px;top:444px;font-size:15.1px;max-width:143px\">当代中国精神的集中体现。</span><span class=\"bl b\" style=\"left:72px;top:464px;font-size:17.3px;max-width:203px\">5.社会主义核心价值体系的基本内容：</span><span class=\"bl\" style=\"left:213px;top:478px;font-size:51.4px;max-width:270px\">众号：</span><span class=\"bl\" style=\"left:71px;top:485px;font-size:17.3px;max-width:133px\">①马克思主义指导思想。</span><span class=\"bl\" style=\"left:73px;top:508px;font-size:14.0px;max-width:166px\">②中国特色社会主义共同理想。</span><span class=\"bl\" style=\"left:72px;top:527px;font-size:19.0px;max-width:352px\">③以爱国主义为核心的民族精神和以改革创新为核心的时代精神。</span><span class=\"bl\" style=\"left:303px;top:535px;font-size:58.6px;max-width:159px\">上</span><span class=\"bl\" style=\"left:72px;top:548px;font-size:17.3px;max-width:122px\">④社会主义荣辱观。</span><span class=\"bl b\" style=\"left:72px;top:570px;font-size:15.1px;max-width:300px\">6.社会主义核心价值观和社会主义核心价值体系的关系：</span><span class=\"bl\" style=\"left:70px;top:591px;font-size:15.1px;max-width:145px\">（1）社会主义核心价值观：</span><span class=\"bl\" style=\"left:72px;top:612px;font-size:15.6px;max-width:260px\">①是在社会主义核心价值体系基础上提炼出来的。</span><span class=\"bl\" style=\"left:72px;top:633px;font-size:15.1px;max-width:273px\">②是社会主义核心价值体系的内核凝练和集中表达。</span><span class=\"bl\" style=\"left:72px;top:654px;font-size:16.7px;max-width:297px\">③体现着社会主义核心价值体系的根本性质和基本特征。</span><span class=\"bl\" style=\"left:72px;top:675px;font-size:15.6px;max-width:296px\">④反映着社会主义核心价值体系的丰富内涵和实践要求。</span><span class=\"bl\" style=\"left:69px;top:695px;font-size:17.3px;max-width:75px\">（2）共同点：</span><span class=\"bl\" style=\"left:72px;top:717px;font-size:15.6px;max-width:225px\">①都体现了社会主义意识形态的本质要求。</span><span class=\"bl\" style=\"left:72px;top:738px;font-size:15.1px;max-width:307px\">②都体现了社会主义制度在思想和精神层面的质的规定性。</span><span class=\"bl\" style=\"left:72px;top:759px;font-size:15.1px;max-width:202px\">③都凝结着社会主义先进文化的精髓。</span><span class=\"bl\" style=\"left:72px;top:779px;font-size:16.7px;max-width:331px\">④都是中国特色社会主义道路、理论、制度和文化的价值表达。</span><span class=\"bl\" style=\"left:72px;top:802px;font-size:14.5px;max-width:260px\">③都是实现中华民族伟大复兴中国梦的价值引领。</span><span class=\"bl\" style=\"left:70px;top:822px;font-size:14.5px;max-width:369px\">（3）不同点：相比于社会主义核心价值体系，社会主义核心价值观是：</span><span class=\"bl\" style=\"left:72px;top:842px;font-size:15.6px;max-width:119px\">①更加突出核心要素。</span><span class=\"bl\" style=\"left:71px;top:863px;font-size:15.6px;max-width:120px\">②更加注重凝练表达。</span><span class=\"bl\" style=\"left:72px;top:884px;font-size:15.6px;max-width:120px\">③更加强化实践导向。</span><span class=\"bl b\" style=\"left:70px;top:905px;font-size:15.1px;max-width:226px\">7.培育和践行社会主义核心价值观的要求：</span><span class=\"bl\" style=\"left:71px;top:926px;font-size:15.1px;max-width:273px\">①要把社会主义核心价值观融入社会生活各个方面。</span><span class=\"bl\" style=\"left:72px;top:947px;font-size:14.0px;max-width:307px\">②要坚持全民行动、干部带头，从家庭做起，从娃娃抓起。</span><span class=\"bl\" style=\"left:72px;top:968px;font-size:14.5px;max-width:225px\">③必须立足中华优秀传统文化和革命文化。</span><span class=\"bl\" style=\"left:72px;top:989px;font-size:14.0px;max-width:391px\">④必须发扬中国人民在长期奋斗中培育、继承、发展起来的伟大民族精神。</span><span class=\"bl b\" style=\"left:71px;top:1010px;font-size:14.0px;max-width:418px\">8.培育和践行社会主义核心价值观的着眼点：培养担当民族复兴大任的时代新人。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 65 页</div><div class=\"sidebox\" style=\"left:465px;top:113px;width:254px;height:895px\"></div><span class=\"bl b\" style=\"left:72px;top:108px;font-size:15.6px;max-width:328px\">52.3坚定文化自信，繁荣发展社会主义文化（中频选择题）</span><span class=\"bl\" style=\"left:470px;top:111px;font-size:14.5px;max-width:47px\">&gt;拓展1</span><span class=\"bl\" style=\"left:531px;top:119px;font-size:15.6px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl b\" style=\"left:95px;top:130px;font-size:15.1px;max-width:424px\">1.文化强国的含义：一个国家具有强大的文化力量。这种力量表现为具有高度文</span><span class=\"bl\" style=\"left:530px;top:141px;font-size:15.1px;max-width:190px\">“深化中华文明探源工程”集体学习会议</span><span class=\"bl\" style=\"left:72px;top:151px;font-size:15.1px;max-width:285px\">化素养的国民、发达的文化产业、强大的文化软实力。</span><span class=\"bl\" style=\"left:531px;top:161px;font-size:12.8px;max-width:51px\">主要内容：</span><span class=\"bl b\" style=\"left:94px;top:172px;font-size:14.0px;max-width:109px\">2.文化强国的要求：</span><span class=\"bl b\" style=\"left:529px;top:179px;font-size:14.0px;max-width:191px\">1.中华文明源远流长、博大精深，是：中</span><span class=\"bl\" style=\"left:96px;top:193px;font-size:15.1px;max-width:237px\">①着力推动社会主义先进文化更加深入人心。</span><span class=\"bl\" style=\"left:541px;top:198px;font-size:12.3px;max-width:179px\">华民族独特的精神标识，是当代中国文</span><span class=\"bl\" style=\"left:96px;top:214px;font-size:15.6px;max-width:423px\">②不断开创全民族文化创造活力持续进发、社会文化生活更加丰富多彩、人民基</span><span class=\"bl\" style=\"left:541px;top:217px;font-size:12.3px;max-width:179px\">化的根基，是维系全世界华人的精神纽</span><span class=\"bl\" style=\"left:72px;top:235px;font-size:15.1px;max-width:447px\">本文化权益得到更好保障、人民思想道德素质和科学文化素质全面提高、中华文化影</span><span class=\"bl\" style=\"left:540px;top:235px;font-size:12.3px;max-width:131px\">带，是中国文化创新的宝藏。</span><span class=\"bl\" style=\"left:72px;top:256px;font-size:14.5px;max-width:285px\">响力不断增强的新局面，建设中华民族共有精神家园。</span><span class=\"bl\" style=\"left:530px;top:253px;font-size:12.3px;max-width:190px\">2.中华文明探源工程是对中华文明的起</span><span class=\"bl\" style=\"left:540px;top:271px;font-size:12.3px;max-width:179px\">源、形成、发展的历史脉络，对中华文</span><span class=\"bl\" style=\"left:95px;top:279px;font-size:12.3px;max-width:263px\">3.必须培养高度的文化自信（重要性）（2019-26）</span><span class=\"bl\" style=\"left:540px;top:289px;font-size:12.3px;max-width:180px\">明多元一体格局的形成和发展过程，对</span><span class=\"bl\" style=\"left:96px;top:299px;font-size:14.0px;max-width:422px\">①坚定文化自信，是事关国运兴衰、事关文化安全、事关民族精神独立性的大</span><span class=\"bl\" style=\"left:541px;top:307px;font-size:12.3px;max-width:178px\">中华文明的特点及其形成原因等都有了</span><span class=\"bl\" style=\"left:72px;top:319px;font-size:15.1px;max-width:37px\">问题。</span><span class=\"bl\" style=\"left:539px;top:324px;font-size:15.1px;max-width:84px\">较为清晰的认识。</span><span class=\"bl\" style=\"left:96px;top:341px;font-size:14.0px;max-width:424px\">②文化自信，是更基础、更广泛、更深厚的自信，更基本、更深沉、更持久的</span><span class=\"bl b\" style=\"left:528px;top:343px;font-size:14.5px;max-width:193px\">3.中华优秀传统文化是：中华文明的智慧</span><span class=\"bl\" style=\"left:72px;top:362px;font-size:15.1px;max-width:37px\">力量。</span><span class=\"bl\" style=\"left:541px;top:363px;font-size:12.3px;max-width:180px\">结晶和精华所在，是中华民族的根和</span><span class=\"bl\" style=\"left:96px;top:384px;font-size:12.3px;max-width:267px\">4.推动中华优秀传统文化创造性转化、创新性发展</span><span class=\"bl\" style=\"left:540px;top:379px;font-size:14.5px;max-width:180px\">魂，是我们在世界文化激荡中站稳脚跟</span><span class=\"bl\" style=\"left:541px;top:398px;font-size:12.8px;max-width:42px\">的根基。</span><span class=\"bl\" style=\"left:96px;top:405px;font-size:14.0px;max-width:143px\">中华优秀传统文化的地位：</span><span class=\"bl b\" style=\"left:530px;top:416px;font-size:14.5px;max-width:191px\">4.如何阐明中国道路的深厚文化底蕴：要</span><span class=\"bl\" style=\"left:96px;top:425px;font-size:14.0px;max-width:176px\">①是中华民族的“根”和“魂”。</span><span class=\"bl\" style=\"left:541px;top:436px;font-size:12.3px;max-width:180px\">把中华文明起源研究同中华文明特质和</span><span class=\"bl\" style=\"left:96px;top:446px;font-size:14.0px;max-width:143px\">②是最深厚的文化软实力。</span><span class=\"bl\" style=\"left:541px;top:454px;font-size:12.3px;max-width:180px\">形态等重大问题研究紧密结合起来；深</span><span class=\"bl\" style=\"left:96px;top:467px;font-size:14.0px;max-width:190px\">③是中国特色社会主义植根的沃土。</span><span class=\"bl\" style=\"left:541px;top:472px;font-size:12.3px;max-width:180px\">入研究阐释中华文明起源所昭示的中华</span><span class=\"bl\" style=\"left:99px;top:490px;font-size:12.3px;max-width:232px\">④是我们在世界文化激荡中站稳脚跟的根基。</span><span class=\"bl\" style=\"left:540px;top:490px;font-size:13.4px;max-width:180px\">民族共同体发展路向和中华民族多元</span><span class=\"bl b\" style=\"left:94px;top:509px;font-size:15.6px;max-width:426px\">5.健全人民文化权益保障制度：坚持以人民为中心的工作导向，完善文化产品创</span><span class=\"bl\" style=\"left:541px;top:508px;font-size:14.5px;max-width:180px\">一体演进格局；研究阐释中华文明讲</span><span class=\"bl\" style=\"left:73px;top:531px;font-size:14.0px;max-width:319px\">作生产传播的引导激励机制，推出更多群众喜爱的文化精品。</span><span class=\"bl\" style=\"left:541px;top:527px;font-size:13.4px;max-width:179px\">仁爱、重民本、守诚信、崇正义、尚和</span><span class=\"bl\" style=\"left:273px;top:538px;font-size:50.3px;max-width:180px\">悦您上岸</span><span class=\"bl\" style=\"left:540px;top:544px;font-size:15.1px;max-width:181px\">合、求大同的精神特质和发展形态；要</span><span class=\"bl\" style=\"left:96px;top:551px;font-size:15.1px;max-width:198px\">6.必须大力发展文化事业和文化产业</span><span class=\"bl\" style=\"left:471px;top:551px;font-size:14.5px;max-width:46px\">提示1</span><span class=\"bl\" style=\"left:540px;top:563px;font-size:14.5px;max-width:181px\">坚持守正创新，推动中华优秀传统文化</span><span class=\"bl\" style=\"left:95px;top:570px;font-size:17.9px;max-width:151px\">①发展文化事业（2013-6）</span><span class=\"bl\" style=\"left:540px;top:580px;font-size:14.5px;max-width:181px\">同社会主义社会相适应，展示中华民族</span><span class=\"bl\" style=\"left:98px;top:592px;font-size:14.0px;max-width:330px\">坚持政府主导，按照公益性、基本性、均等性、便利性的要求：</span><span class=\"bl\" style=\"left:542px;top:600px;font-size:12.3px;max-width:179px\">的独特精神标识，更好构筑中国精神、</span><span class=\"bl\" style=\"left:97px;top:614px;font-size:14.5px;max-width:261px\">加强文化基础设施建设，完善公共文化服务网络；</span><span class=\"bl\" style=\"left:541px;top:618px;font-size:14.0px;max-width:102px\">中国价值、中国力量。</span><span class=\"bl\" style=\"left:97px;top:634px;font-size:14.0px;max-width:284px\">让人民群众广泛享有免费或优惠的基本公共文化服务；</span><span class=\"bl\" style=\"left:97px;top:655px;font-size:15.1px;max-width:297px\">在满足人民群众基本文化需求的基础上，提升国民素质。</span><span class=\"bl\" style=\"left:533px;top:654px;font-size:12.3px;max-width:103px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:97px;top:677px;font-size:14.0px;max-width:145px\">②发展文化产业（2011-8）</span><span class=\"bl\" style=\"left:530px;top:676px;font-size:14.5px;max-width:191px\">1.文化事业是政府主导，不是为了盈利，</span><span class=\"bl\" style=\"left:97px;top:698px;font-size:14.0px;max-width:167px\">要按照全面协调可持续的要求；</span><span class=\"bl\" style=\"left:540px;top:694px;font-size:14.5px;max-width:114px\">而是要实现其社会效益。</span><span class=\"bl\" style=\"left:530px;top:713px;font-size:13.4px;max-width:182px\">2.文化产业是市场主导，追求经济效益。</span><span class=\"bl\" style=\"left:98px;top:720px;font-size:12.3px;max-width:142px\">推动文化产业跨越式发展；</span><span class=\"bl b\" style=\"left:529px;top:730px;font-size:15.1px;max-width:186px\">3.文化产业的本质属性是：意识形态属性。</span><span class=\"bl\" style=\"left:97px;top:738px;font-size:15.6px;max-width:423px\">在满足人民多样化精神文化需求的基础上，使之成为国民经济支柱性产业，为推</span><span class=\"bl\" style=\"left:74px;top:760px;font-size:14.0px;max-width:141px\">动科学发展提供重要支撑。</span><span class=\"bl\" style=\"left:533px;top:767px;font-size:12.3px;max-width:104px\">火星姐姐考点拓展2</span><span class=\"bl\" style=\"left:97px;top:782px;font-size:14.0px;max-width:148px\">7.必须提高国家文化软实力</span><span class=\"bl\" style=\"left:530px;top:788px;font-size:14.5px;max-width:191px\">1.加强我国国际传播能力建设的重要任</span><span class=\"bl\" style=\"left:96px;top:802px;font-size:15.1px;max-width:424px\">①内涵：文化软实力集中体现了一个国家基于文化而具有的凝聚力和生命力，以</span><span class=\"bl\" style=\"left:541px;top:807px;font-size:14.5px;max-width:181px\">务：讲好中国故事，传播好中国声音，</span><span class=\"bl\" style=\"left:75px;top:825px;font-size:12.3px;max-width:176px\">及由此而产生的吸引力和影响力。</span><span class=\"bl\" style=\"left:541px;top:825px;font-size:14.5px;max-width:143px\">展示真实、立体、全面的中国。</span><span class=\"bl\" style=\"left:99px;top:845px;font-size:12.3px;max-width:420px\">②措施：推动公共文化服务标准化、均等化，坚持政府主导、社会参与、重心下</span><span class=\"bl b\" style=\"left:530px;top:845px;font-size:12.3px;max-width:190px\">2.大外宣格局：初步构建起多主体、立体</span><span class=\"bl\" style=\"left:73px;top:865px;font-size:14.5px;max-width:447px\">移、共建共享，完善公共文化服务体系，提高基本公共文化服务的覆盖面和适用性，</span><span class=\"bl\" style=\"left:541px;top:862px;font-size:14.0px;max-width:83px\">式的大外宣格局。</span><span class=\"bl\" style=\"left:74px;top:885px;font-size:14.5px;max-width:178px\">切实保障人民群众基本文化权益。</span><span class=\"bl\" style=\"left:531px;top:881px;font-size:12.3px;max-width:190px\">3.构建具有鲜明中国特色的战略传播体</span><span class=\"bl\" style=\"left:542px;top:900px;font-size:12.3px;max-width:179px\">系，着力提高：国际传播影响力、中华</span><span class=\"bl\" style=\"left:96px;top:907px;font-size:14.0px;max-width:418px\">8.讲好中国故事是树立当代中国良好形象、提升国家文化软实力的重要战略任务。</span><span class=\"bl\" style=\"left:542px;top:918px;font-size:12.3px;max-width:179px\">文化感召力、中国形象亲和力、中国话</span><span class=\"bl\" style=\"left:98px;top:929px;font-size:12.3px;max-width:258px\">提高中华文化影响力的基本途径：讲好中国故事。</span><span class=\"bl\" style=\"left:471px;top:927px;font-size:16.8px;max-width:48px\">&gt;拓展2</span><span class=\"bl\" style=\"left:541px;top:937px;font-size:12.3px;max-width:132px\">语说服力、国际舆论引导力。</span><span class=\"bl b hl\" style=\"left:84px;top:959px;font-size:18.4px;max-width:306px\">考点53加强以民生为重点的社会建设☆☆☆</span><span class=\"bl\" style=\"left:531px;top:954px;font-size:12.3px;max-width:190px\">4.要注重把握好基调，既开放自信也谦逊</span><span class=\"bl\" style=\"left:540px;top:971px;font-size:14.5px;max-width:181px\">谦和，努力塑造可信、可爱、可敬的中</span><span class=\"bl b\" style=\"left:73px;top:994px;font-size:15.1px;max-width:247px\">53.1在发展中保障和改善民生（高频选择题）</span><span class=\"bl\" style=\"left:541px;top:990px;font-size:14.5px;max-width:42px\">国形象。</span><span class=\"bl b\" style=\"left:96px;top:1016px;font-size:14.5px;max-width:424px\">1.民生的重要性：民生是人民幸福之基、社会和谐之本。抓民生要抓住人民最关</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 66 页</div><div class=\"sidebox\" style=\"left:504px;top:438px;width:196px;height:285px\"></div><span class=\"bl\" style=\"left:457px;top:60px;font-size:15.6px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:107px;font-size:17.8px;max-width:444px\">心最直接最现实的利益问题，抓住最需要关心的人群，一件事情接着一件事情办、一</span><span class=\"bl\" style=\"left:55px;top:130px;font-size:13.9px;max-width:177px\">年接着一年干，锲而不舍向前走。</span><span class=\"bl b\" style=\"left:77px;top:151px;font-size:13.9px;max-width:133px\">2.保障民生要注意把握：</span><span class=\"bl\" style=\"left:78px;top:169px;font-size:17.8px;max-width:423px\">①要把握好发展经济与改善民生的关系。经济发展是改善民生的前提，要推动经</span><span class=\"bl\" style=\"left:54px;top:191px;font-size:15.6px;max-width:390px\">济高质量发展，为改善民生奠定更加坚实的物质基础。抓民生就是抓发展。</span><span class=\"bl\" style=\"left:78px;top:212px;font-size:15.6px;max-width:422px\">②改善民生要坚持尽力而为与量力而行的统一。要根据经济发展和财力状况逐步</span><span class=\"bl\" style=\"left:55px;top:235px;font-size:13.9px;max-width:237px\">提高人民生活水平，改善民生不能脱离国情。</span><span class=\"bl b\" style=\"left:77px;top:254px;font-size:15.1px;max-width:270px\">3.提高保障和改善民生水平的举措：（中频选择题）</span><span class=\"bl\" style=\"left:79px;top:276px;font-size:13.9px;max-width:119px\">1优先发展教育事业。</span><span class=\"bl\" style=\"left:79px;top:297px;font-size:13.9px;max-width:283px\">意义：建设教育强国是中华民族伟大复兴的基础工程。</span><span class=\"bl\" style=\"left:79px;top:318px;font-size:13.9px;max-width:422px\">措施：必须把教育事业放在优先位置。全面贯彻党的教育方针，落实立德树人根</span><span class=\"bl\" style=\"left:55px;top:338px;font-size:14.5px;max-width:445px\">本任务，发展素质教育，推进教育公平，培养德智体美劳全面发展的社会主义建设者</span><span class=\"bl\" style=\"left:56px;top:359px;font-size:14.5px;max-width:60px\">和接班人。</span><span class=\"bl\" style=\"left:78px;top:380px;font-size:15.6px;max-width:120px\">②实施就业优先战略。</span><span class=\"bl\" style=\"left:79px;top:401px;font-size:13.9px;max-width:354px\">意义：就业是人民生存的经济基础和基本保障，是最大的民生工程。</span><span class=\"bl\" style=\"left:78px;top:422px;font-size:13.9px;max-width:422px\">措施：健全有利于更充分更高质量就业的促进机制，扩大就业容量，提升就业质</span><span class=\"bl\" style=\"left:55px;top:444px;font-size:13.9px;max-width:142px\">量，缓解结构性就业矛盾。</span><span class=\"bl\" style=\"left:513px;top:444px;font-size:13.9px;max-width:102px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:78px;top:464px;font-size:15.6px;max-width:118px\">③优化收入分配结构。</span><span class=\"bl\" style=\"left:453px;top:465px;font-size:14.5px;max-width:46px\">拓展1</span><span class=\"bl b\" style=\"left:510px;top:466px;font-size:14.5px;max-width:191px\">1.合理调整收入分配关系是：实现社会公</span><span class=\"bl\" style=\"left:77px;top:484px;font-size:16.7px;max-width:425px\">意义：收人分配是民生之源，是改善民生、实现发展成果由人民共享的最重要最</span><span class=\"bl\" style=\"left:522px;top:485px;font-size:13.9px;max-width:180px\">平的重要体现，是实现共同富裕的内在</span><span class=\"bl\" style=\"left:55px;top:505px;font-size:15.6px;max-width:71px\">直接的方式。</span><span class=\"bl\" style=\"left:521px;top:503px;font-size:13.4px;max-width:35px\">要求。</span><span class=\"bl\" style=\"left:78px;top:525px;font-size:16.7px;max-width:423px\">措施：坚持按劳分配为主体、多种分配方式并存，提高劳动报酬在初次分配中的</span><span class=\"bl\" style=\"left:510px;top:520px;font-size:14.5px;max-width:191px\">2.收入分配是经济社会发展的重大问题，</span><span class=\"bl\" style=\"left:522px;top:540px;font-size:12.3px;max-width:178px\">关系人民群众切身利益，关系改革发展</span><span class=\"bl\" style=\"left:54px;top:547px;font-size:16.7px;max-width:446px\">比重，完善再分配机制。坚持居民收入增长和经济增长基本同步、劳动报酬提高和劳</span><span class=\"bl\" style=\"left:521px;top:558px;font-size:13.9px;max-width:64px\">稳定的全局。</span><span class=\"bl\" style=\"left:55px;top:568px;font-size:15.6px;max-width:445px\">动生产率提高基本同步，持续提高低收人群体收入，扩大中等收入群体，更加积极有</span><span class=\"bl\" style=\"left:512px;top:577px;font-size:12.3px;max-width:189px\">3.解决好分配不公问题，让全体人民共享</span><span class=\"bl\" style=\"left:55px;top:589px;font-size:15.6px;max-width:108px\">为地促进共同富裕。</span><span class=\"bl\" style=\"left:522px;top:595px;font-size:13.4px;max-width:180px\">改革发展的成果是维护社会公平正义、</span><span class=\"bl\" style=\"left:79px;top:611px;font-size:13.9px;max-width:196px\">4加强社会保障体系建设（2016-24）</span><span class=\"bl\" style=\"left:522px;top:614px;font-size:12.3px;max-width:179px\">促进社会和谐稳定的重要任务，是发展</span><span class=\"bl\" style=\"left:79px;top:632px;font-size:13.9px;max-width:339px\">意义：社会保障体系是民生之依。（兜底作用、社会稳定器作用）</span><span class=\"bl\" style=\"left:522px;top:632px;font-size:12.3px;max-width:141px\">中国特色社会主义的必然要求。</span><span class=\"bl\" style=\"left:78px;top:652px;font-size:13.9px;max-width:423px\">措施：要全面建成健全覆盖全民、统筹城乡、公平统一、安全规范、可持续的多</span><span class=\"bl\" style=\"left:511px;top:651px;font-size:12.3px;max-width:190px\">4.分配公平是社会公平的重要内容，也是</span><span class=\"bl\" style=\"left:56px;top:673px;font-size:13.9px;max-width:107px\">层次社会保障体系。</span><span class=\"bl\" style=\"left:523px;top:668px;font-size:12.3px;max-width:178px\">实现社会公平的重要体现。分配不公造</span><span class=\"bl\" style=\"left:523px;top:687px;font-size:12.3px;max-width:178px\">成收入差距过大，是与实现共同富裕的</span><span class=\"bl\" style=\"left:79px;top:695px;font-size:13.9px;max-width:114px\">5实施健康中国战略</span><span class=\"bl\" style=\"left:522px;top:705px;font-size:13.9px;max-width:72px\">目标相违背的。</span><span class=\"bl\" style=\"left:79px;top:716px;font-size:13.9px;max-width:271px\">意义：人民健康是民族昌盛和国家富强的重要标志。</span><span class=\"bl\" style=\"left:78px;top:737px;font-size:13.9px;max-width:422px\">措施：我们要把保障人民健康放在优先发展的战略位置，坚持预防为主的方针，</span><span class=\"bl\" style=\"left:56px;top:758px;font-size:12.3px;max-width:445px\">深人实施健康中国行动，建设体育强国，完善国民健康促进政策，织牢国家公共卫生</span><span class=\"bl\" style=\"left:56px;top:779px;font-size:13.9px;max-width:249px\">防护网，为人民提供全方位全生命期健康服务。</span><span class=\"bl b\" style=\"left:54px;top:806px;font-size:14.5px;max-width:228px\">53.2加强和创新社会治理（低频选择题）</span><span class=\"bl\" style=\"left:513px;top:813px;font-size:13.9px;max-width:105px\">火星姐姐考点拓展2</span><span class=\"bl\" style=\"left:79px;top:829px;font-size:13.9px;max-width:157px\">1.社会治理的重要性（意义）</span><span class=\"bl\" style=\"left:452px;top:828px;font-size:15.1px;max-width:47px\">&gt;拓展2</span><span class=\"bl\" style=\"left:512px;top:834px;font-size:13.9px;max-width:190px\">党的十九大明确了推进社会建设的目标要</span><span class=\"bl\" style=\"left:79px;top:847px;font-size:16.7px;max-width:319px\">①社会治理是社会建设的重大任务，是国家治理的重要领域。</span><span class=\"bl\" style=\"left:512px;top:853px;font-size:13.4px;max-width:34px\">求是：</span><span class=\"bl\" style=\"left:79px;top:869px;font-size:15.1px;max-width:367px\">②社会治理现代化是国家治理体系和治理能力现代化的题中应有之义。</span><span class=\"bl\" style=\"left:512px;top:871px;font-size:13.9px;max-width:189px\">①到2035年，我国现代社会治理格局基</span><span class=\"bl\" style=\"left:79px;top:889px;font-size:15.1px;max-width:421px\">③加强和创新社会治理是完善和发展中国特色社会主义制度、推进国家治理体系</span><span class=\"bl\" style=\"left:513px;top:890px;font-size:10.0px;max-width:161px\">本形成，社会充满活力又和谐有序。</span><span class=\"bl\" style=\"left:57px;top:911px;font-size:13.9px;max-width:165px\">和治理能力现代化的重要内容。</span><span class=\"bl\" style=\"left:513px;top:908px;font-size:12.3px;max-width:188px\">2到21世纪中叶，我国社会文明将全面</span><span class=\"bl\" style=\"left:512px;top:925px;font-size:14.5px;max-width:184px\">提升，人民将享有更加幸福安康的生活。</span><span class=\"bl\" style=\"left:79px;top:933px;font-size:12.3px;max-width:160px\">2.加强和创新社会治理的措施</span><span class=\"bl\" style=\"left:79px;top:953px;font-size:13.9px;max-width:120px\">①创新社会治理体制。</span><span class=\"bl\" style=\"left:79px;top:972px;font-size:15.1px;max-width:424px\">A.坚持完善党委领导、政府负责、民主协商、社会协同、公众参与、法治保障、</span><span class=\"bl\" style=\"left:56px;top:994px;font-size:13.9px;max-width:143px\">科技支撑的社会治理体系；</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1098px\"><div class=\"bxnum\">第 67 页</div><div class=\"sidebox\" style=\"left:514px;top:548px;width:196px;height:102px\"></div><span class=\"bl\" style=\"left:89px;top:105px;font-size:15.6px;max-width:322px\">B.完善政府治理和社会调节、居民自治良性互动的体制机制；</span><span class=\"bl\" style=\"left:89px;top:126px;font-size:15.1px;max-width:299px\">C.提高社会治理社会化、法治化、智能化、专业化水平；</span><span class=\"bl\" style=\"left:89px;top:147px;font-size:15.6px;max-width:322px\">D.推进社会治理精细化，打造共建共治共享的社会治理格局。</span><span class=\"bl\" style=\"left:89px;top:168px;font-size:17.3px;max-width:422px\">②完善正确处理新形势下人民内部矛盾有效机制。正确处理人民内部矛盾特别是</span><span class=\"bl\" style=\"left:64px;top:189px;font-size:16.7px;max-width:389px\">涉及广大人民群众切身利益的矛盾，是保持社会安定团结良好局面的关键。</span><span class=\"bl\" style=\"left:89px;top:210px;font-size:15.6px;max-width:418px\">③完善社会治安防控体系。提高社会治安水平，提高预测预警预防各类风险能力。</span><span class=\"bl\" style=\"left:89px;top:230px;font-size:17.3px;max-width:421px\">④加强社会心理服务体系建设。健全加强社会心理服务体系和疏导机制、危机干</span><span class=\"bl\" style=\"left:65px;top:252px;font-size:15.1px;max-width:191px\">预机制，重视疏导化解、柔性维稳。</span><span class=\"bl\" style=\"left:89px;top:272px;font-size:17.8px;max-width:422px\">5构建基层社会治理新格局。社区是党和政府联系、服务居民群众的“最后一公</span><span class=\"bl\" style=\"left:65px;top:294px;font-size:15.1px;max-width:272px\">里”，社会治理的重心要向基层下移落到城乡社区。</span><span class=\"bl b hl\" style=\"left:74px;top:334px;font-size:19.0px;max-width:262px\">考点54坚持人与自然和谐共生☆☆☆</span><span class=\"bl b\" style=\"left:65px;top:371px;font-size:13.9px;max-width:258px\">54.1习近平生态文明思想的意义（高频选择题）</span><span class=\"bl\" style=\"left:89px;top:392px;font-size:14.5px;max-width:423px\">习近平生态文明思想是习近平新时代中国特色社会主义思想的重要组成部分，深</span><span class=\"bl\" style=\"left:64px;top:413px;font-size:16.7px;max-width:447px\">刻回答了“为什么建设生态文明、建设什么样的生态文明、怎样建设生态文明”的重</span><span class=\"bl\" style=\"left:65px;top:434px;font-size:14.5px;max-width:446px\">大理论和实践问题，为建设美丽中国、实现中华民族永续发展提供了根本遵循和行动</span><span class=\"bl\" style=\"left:64px;top:455px;font-size:15.1px;max-width:39px\">指南。</span><span class=\"bl b\" style=\"left:64px;top:482px;font-size:17.3px;max-width:293px\">54.2习近平生态文明思想的主要内容（高频选择题）</span><span class=\"bl\" style=\"left:79px;top:504px;font-size:16.7px;max-width:280px\">1.坚持人与自然和谐共生。人与自然是生命共同体。</span><span class=\"bl\" style=\"left:89px;top:527px;font-size:12.3px;max-width:141px\">2.绿水青山就是金山银山。</span><span class=\"bl\" style=\"left:86px;top:540px;font-size:29.5px;max-width:268px\">①经济发展和生态环境保护的关系是：</span><span class=\"bl\" style=\"left:462px;top:547px;font-size:14.5px;max-width:48px\">&gt;提示1</span><span class=\"bl\" style=\"left:524px;top:554px;font-size:13.9px;max-width:103px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:88px;top:567px;font-size:13.9px;max-width:340px\">A.绿水青山既是自然财富、生态财富，又是社会财富、经济财富</span><span class=\"bl b\" style=\"left:521px;top:576px;font-size:13.9px;max-width:191px\">1.生态环境保护的成败：归根到底取决于</span><span class=\"bl\" style=\"left:89px;top:589px;font-size:13.9px;max-width:269px\">B.保护生态环境就是保护自然价值和增值自然资本</span><span class=\"bl\" style=\"left:532px;top:596px;font-size:12.3px;max-width:121px\">经济结构和经济发展方式。</span><span class=\"bl\" style=\"left:89px;top:610px;font-size:13.9px;max-width:268px\">C.保护生态环境就是保护经济社会发展潜力和后劲</span><span class=\"bl\" style=\"left:520px;top:613px;font-size:14.5px;max-width:192px\">2.生态环境问题归根到底是发展方式和生</span><span class=\"bl\" style=\"left:89px;top:631px;font-size:12.3px;max-width:256px\">D.使绿水青山持续发挥生态效益和经济社会效益</span><span class=\"bl\" style=\"left:530px;top:631px;font-size:15.6px;max-width:65px\">活方式问题。</span><span class=\"bl\" style=\"left:88px;top:651px;font-size:16.7px;max-width:50px\">②措施：</span><span class=\"bl\" style=\"left:88px;top:672px;font-size:14.5px;max-width:412px\">A.加快形成节约资源和保护环境的空间格局、产业结构、生产方式、生活方式</span><span class=\"bl\" style=\"left:88px;top:693px;font-size:14.5px;max-width:375px\">B.把经济活动、人的行为限制在自然资源和生态环境能够承受的限度内</span><span class=\"bl\" style=\"left:89px;top:714px;font-size:14.5px;max-width:222px\">C.给自然生态留下休养生息的时间和空间</span><span class=\"bl\" style=\"left:88px;top:735px;font-size:14.5px;max-width:388px\">D.加快划定并严守生态保护红线、环境质量底线、资源利用上线三条红线</span><span class=\"bl\" style=\"left:88px;top:757px;font-size:12.3px;max-width:422px\">3.良好生态环境是最普惠的民生福社。发展经济是为了民生，保护生态环境同样</span><span class=\"bl\" style=\"left:65px;top:777px;font-size:13.9px;max-width:84px\">也是为了民生。</span><span class=\"bl\" style=\"left:87px;top:797px;font-size:15.1px;max-width:423px\">4.统筹山水林田湖草沙系统治理。要深人实施山水林田湖草沙一体化生态保护</span><span class=\"bl\" style=\"left:65px;top:819px;font-size:14.5px;max-width:445px\">和修复，开展大规模国土绿化行动，加快水土流失和荒漠化石漠化综合治理，实现从</span><span class=\"bl\" style=\"left:65px;top:839px;font-size:15.6px;max-width:396px\">“沙进人退”向“绿进沙退”的根本转变，提升生态系统稳定性和可持续性。</span><span class=\"bl\" style=\"left:88px;top:862px;font-size:12.3px;max-width:226px\">5.用最严格制度最严密法治保护生态环境。</span><span class=\"bl\" style=\"left:88px;top:880px;font-size:15.6px;max-width:424px\">我国生态环境保护中存在的突出问题：体制不健全、制度不严格、法治不严密、</span><span class=\"bl\" style=\"left:64px;top:902px;font-size:13.9px;max-width:166px\">执行不到位、惩处不得力有关。</span><span class=\"bl\" style=\"left:87px;top:922px;font-size:15.6px;max-width:423px\">措施：要加快制度创新，增加制度供给，完善制度配套，强化制度执行，让制度</span><span class=\"bl\" style=\"left:64px;top:943px;font-size:15.1px;max-width:378px\">成为刚性的约束和不可触碰的高压线。严格用制度管权治吏、护蓝增绿。</span><span class=\"bl\" style=\"left:87px;top:964px;font-size:13.9px;max-width:144px\">6.共谋全球生态文明建设。</span><span class=\"bl\" style=\"left:87px;top:985px;font-size:16.7px;max-width:422px\">措施：深度参与全球环境治理，增强我国在全球环境治理体系中的话语权和影响</span><span class=\"bl\" style=\"left:64px;top:1007px;font-size:16.7px;max-width:446px\">力，积极引导国际秩序变革方向，形成世界环境保护和可持续发展的解决方案。坚持</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 68 页</div><div class=\"sidebox\" style=\"left:506px;top:200px;width:196px;height:494px\"></div><span class=\"bl\" style=\"left:458px;top:61px;font-size:15.6px;max-width:244px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:54px;top:108px;font-size:17.9px;max-width:447px\">环境友好，引导应对气候变化国际合作，推进“一带一路”建设，让生态文明的理念</span><span class=\"bl\" style=\"left:55px;top:132px;font-size:14.5px;max-width:143px\">和实践造福沿线各国人民。</span><span class=\"bl b\" style=\"left:54px;top:160px;font-size:16.8px;max-width:329px\">54.3推动绿色发展，促进人与自然和谐共生（高频选择题）</span><span class=\"bl\" style=\"left:78px;top:184px;font-size:14.0px;max-width:144px\">1.加快构建生态文明体系。</span><span class=\"bl\" style=\"left:78px;top:205px;font-size:16.8px;max-width:424px\">意义：建设生态文明是关系人民福祉、关乎中华民族永续发展的千年大计，是实</span><span class=\"bl\" style=\"left:514px;top:206px;font-size:15.6px;max-width:103px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:55px;top:229px;font-size:14.5px;max-width:203px\">现中华民族伟大复兴的重要战略任务。</span><span class=\"bl b\" style=\"left:513px;top:230px;font-size:14.0px;max-width:97px\">1.“双碳”的重要性：</span><span class=\"bl\" style=\"left:79px;top:252px;font-size:14.0px;max-width:120px\">措施：加快建立健全：</span><span class=\"bl\" style=\"left:522px;top:247px;font-size:14.5px;max-width:181px\">我国已进入新发展阶段，推进“双碳”</span><span class=\"bl\" style=\"left:523px;top:266px;font-size:14.5px;max-width:181px\">工作是破解资源环境约束突出问题、实</span><span class=\"bl\" style=\"left:79px;top:274px;font-size:14.0px;max-width:223px\">A.以生态价值观念为准则的生态文化体系</span><span class=\"bl\" style=\"left:523px;top:284px;font-size:14.5px;max-width:181px\">现可持续发展的迫切需要，是顺应技术</span><span class=\"bl\" style=\"left:79px;top:295px;font-size:14.5px;max-width:281px\">B.以产业生态化和生态产业化为主体的生态经济体系</span><span class=\"bl\" style=\"left:523px;top:303px;font-size:13.4px;max-width:180px\">进步趋势、推动经济结构转型升级的迫</span><span class=\"bl\" style=\"left:80px;top:319px;font-size:12.3px;max-width:244px\">C.以改善生态环境质量为核心的目标责任体系</span><span class=\"bl\" style=\"left:524px;top:322px;font-size:12.3px;max-width:180px\">切需要，是满足人民群众日益增长的优</span><span class=\"bl\" style=\"left:79px;top:339px;font-size:14.5px;max-width:318px\">D.以治理体系和治理能力现代化为保障的生态文明制度体系</span><span class=\"bl\" style=\"left:524px;top:341px;font-size:12.3px;max-width:180px\">美生态环境需求、促进人与自然和谐共</span><span class=\"bl\" style=\"left:79px;top:361px;font-size:14.5px;max-width:352px\">E.以生态系统良性循环和环境风险有效防控为重点的生态安全体系</span><span class=\"bl\" style=\"left:524px;top:360px;font-size:12.3px;max-width:180px\">生的迫切需要，是主动担当大国责任、</span><span class=\"bl\" style=\"left:522px;top:377px;font-size:14.5px;max-width:175px\">推动构建人类命运共同体的迫切需要。</span><span class=\"bl\" style=\"left:79px;top:385px;font-size:12.3px;max-width:249px\">2.全面推动形成绿色发展方式和绿色生活方式。</span><span class=\"bl b\" style=\"left:513px;top:396px;font-size:14.0px;max-width:171px\">2.实现“双碳”目标要处理好的关系：</span><span class=\"bl\" style=\"left:79px;top:407px;font-size:12.3px;max-width:308px\">意义：生态环境问题归根结底是发展方式和生活方式问题。</span><span class=\"bl\" style=\"left:523px;top:415px;font-size:14.0px;max-width:113px\">一是发展和减排的关系；</span><span class=\"bl\" style=\"left:78px;top:428px;font-size:15.1px;max-width:424px\">措施：加快形成绿色发展方式，调整经济结构和能源结构，培养壮大节能环保产</span><span class=\"bl\" style=\"left:523px;top:434px;font-size:12.3px;max-width:112px\">二是整体和局部的关系；</span><span class=\"bl\" style=\"left:55px;top:451px;font-size:14.5px;max-width:448px\">业、清洁生产产业、清洁能源产业，推进达标排放，扎实做好碳达峰、碳中和各项工</span><span class=\"bl\" style=\"left:524px;top:452px;font-size:12.3px;max-width:150px\">三是长远目标和短期目标的关系；</span><span class=\"bl\" style=\"left:55px;top:475px;font-size:14.0px;max-width:344px\">作。加快形成绿色生活方式，要在全社会牢固树立生态文明理念。</span><span class=\"bl\" style=\"left:453px;top:474px;font-size:14.5px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:524px;top:470px;font-size:12.3px;max-width:112px\">四是政府和市场的关系。</span><span class=\"bl b\" style=\"left:512px;top:486px;font-size:15.6px;max-width:97px\">3.“双碳”工作目标：</span><span class=\"bl\" style=\"left:79px;top:497px;font-size:14.0px;max-width:163px\">3.深入推进生态文明体制改革</span><span class=\"bl\" style=\"left:239px;top:484px;font-size:52.5px;max-width:216px\">亏：6</span><span class=\"bl\" style=\"left:453px;top:495px;font-size:17.3px;max-width:48px\">&gt;拓展2</span><span class=\"bl\" style=\"left:523px;top:506px;font-size:14.0px;max-width:106px\">2030年前实现碳达峰；</span><span class=\"bl\" style=\"left:78px;top:518px;font-size:14.5px;max-width:39px\">措施：</span><span class=\"bl\" style=\"left:522px;top:523px;font-size:15.1px;max-width:105px\">2060年前实现碳中和。</span><span class=\"bl\" style=\"left:79px;top:539px;font-size:16.8px;max-width:424px\">①实行最严格的生态环境保护制度，坚持人与自然和谐共生，坚守尊重自然、顺</span><span class=\"bl\" style=\"left:55px;top:562px;font-size:15.6px;max-width:446px\">应自然、保护自然，健全源头预防、过程控制、损害赔偿、责任追究的生态环境保护</span><span class=\"bl\" style=\"left:514px;top:559px;font-size:14.0px;max-width:104px\">火星姐姐考点拓展2</span><span class=\"bl\" style=\"left:53px;top:584px;font-size:17.3px;max-width:41px\">体系。</span><span class=\"bl\" style=\"left:514px;top:582px;font-size:14.0px;max-width:191px\">①尊重自然：人与自然相处应秉持的首要</span><span class=\"bl\" style=\"left:513px;top:601px;font-size:13.4px;max-width:35px\">态度。</span><span class=\"bl\" style=\"left:80px;top:607px;font-size:14.0px;max-width:160px\">②全面建立资源高效利用制度</span><span class=\"bl\" style=\"left:513px;top:619px;font-size:13.4px;max-width:190px\">②顺应自然：人与自然相处时应遵循的基</span><span class=\"bl\" style=\"left:80px;top:630px;font-size:14.0px;max-width:155px\">③健全生态保护和修复制度。</span><span class=\"bl\" style=\"left:514px;top:638px;font-size:12.9px;max-width:43px\">本原则。</span><span class=\"bl\" style=\"left:80px;top:652px;font-size:14.0px;max-width:428px\">④统筹山水林田湖草一体化保护和修复，加强森林、草原、河流、湖泊、湿地、</span><span class=\"bl\" style=\"left:514px;top:656px;font-size:12.3px;max-width:190px\">③保护自然：人与自然相处时应承担的重</span><span class=\"bl\" style=\"left:55px;top:674px;font-size:14.0px;max-width:120px\">海洋等自然生态保护。</span><span class=\"bl\" style=\"left:513px;top:673px;font-size:16.8px;max-width:45px\">要责任。</span><span class=\"bl\" style=\"left:79px;top:696px;font-size:14.5px;max-width:423px\">③加强对重要生态系统的保护和永续利用，构建以国家公园为主体的自然保护地</span><span class=\"bl\" style=\"left:55px;top:719px;font-size:14.0px;max-width:166px\">体系，健全国家公园保护制度。</span><span class=\"bl\" style=\"left:80px;top:743px;font-size:12.3px;max-width:165px\">6严明生态环境保护责任制度。</span><span class=\"bl\" style=\"left:80px;top:763px;font-size:14.5px;max-width:419px\">7建立生态文明建设目标评价考核制度，严格落实企业主体责任和政府监管责任。</span><span class=\"bl\" style=\"left:79px;top:785px;font-size:14.0px;max-width:424px\">4.有效防范生态环境风险。生态环境安全是国家安全的重要组成部分，是经济社</span><span class=\"bl\" style=\"left:57px;top:808px;font-size:12.3px;max-width:153px\">会持续健康发展的重要保障。</span><span class=\"bl\" style=\"left:79px;top:829px;font-size:15.1px;max-width:424px\">5.提高环境治理水平。环境治理是系统工程，提高环境治理水平，需要综合运用</span><span class=\"bl\" style=\"left:57px;top:853px;font-size:12.3px;max-width:200px\">行政、市场、法治、科技等多种手段。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 69 页</div><span class=\"bl\" style=\"left:65px;top:106px;font-size:18.4px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:66px;top:148px;font-size:19.5px;max-width:447px\">1.【2021.7】改革开放以来，我们党总结正反两方面经验，确立了公有制为主体、多</span><span class=\"bl\" style=\"left:82px;top:169px;font-size:19.5px;max-width:429px\">种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经</span><span class=\"bl\" style=\"left:82px;top:190px;font-size:17.8px;max-width:429px\">济体制等社会主义基本经济制度。在这一基本经济制度中，坚持公有制的主体地</span><span class=\"bl\" style=\"left:82px;top:212px;font-size:14.5px;max-width:67px\">位，是因为</span><span class=\"bl\" style=\"left:81px;top:233px;font-size:15.6px;max-width:270px\">A.公有制经济是社会主义市场经济的重要组成部分</span><span class=\"bl\" style=\"left:81px;top:253px;font-size:15.6px;max-width:223px\">B.公有制是我国经济社会发展的重要基础</span><span class=\"bl\" style=\"left:82px;top:275px;font-size:15.1px;max-width:268px\">C.生产资料所有制决定社会的基本性质和发展方向</span><span class=\"bl\" style=\"left:81px;top:296px;font-size:15.6px;max-width:365px\">D.由生产资料所有制决定的分配方式能使一切社会成员实现全面发展</span><span class=\"bl\" style=\"left:64px;top:331px;font-size:17.8px;max-width:447px\">2.【2022.5】共同富裕是社会主义的本质要求，是中国式现代化的重要特征。党的</span><span class=\"bl\" style=\"left:82px;top:352px;font-size:17.8px;max-width:430px\">十九届五中全会对扎实推动共同富裕作出重大战略部署，明确提出了推进共同富</span><span class=\"bl\" style=\"left:82px;top:375px;font-size:15.1px;max-width:189px\">裕的2035年远景目标。这一目标是</span><span class=\"bl\" style=\"left:81px;top:395px;font-size:15.1px;max-width:164px\">A.全体人民共同富裕基本实现</span><span class=\"bl\" style=\"left:81px;top:416px;font-size:15.1px;max-width:258px\">B.全体人民共同富裕取得更为明显的实质性进展</span><span class=\"bl\" style=\"left:82px;top:438px;font-size:13.9px;max-width:163px\">C.全体人民共同富裕全面实现</span><span class=\"bl\" style=\"left:81px;top:457px;font-size:17.3px;max-width:165px\">D.全体人民共同富裕同步实现</span><span class=\"bl\" style=\"left:64px;top:493px;font-size:17.8px;max-width:448px\">3.【2020.71人民政协作为统一战线的组织、多党合作和政治协商的机构、人民民主</span><span class=\"bl\" style=\"left:80px;top:514px;font-size:16.7px;max-width:431px\">的重要实现形式，是具有中国特色的制度安排。2019年9月20日，习近平在中央</span><span class=\"bl\" style=\"left:82px;top:536px;font-size:15.1px;max-width:429px\">政协工作会议暨庆祝中国人民政治协商会议成立70周年大会上的讲话中，提出了</span><span class=\"bl\" style=\"left:82px;top:556px;font-size:17.3px;max-width:430px\">新时代加强和改进人民政协工作的总体要求，指出新时代做好人民政协工作的中</span><span class=\"bl\" style=\"left:81px;top:578px;font-size:14.5px;max-width:55px\">心环节是</span><span class=\"bl\" style=\"left:81px;top:600px;font-size:13.9px;max-width:234px\">A.提高政治协商、民主监督、参政议政水平</span><span class=\"bl\" style=\"left:81px;top:620px;font-size:15.1px;max-width:199px\">B.加强思想政治引领，广泛凝聚共识</span><span class=\"bl\" style=\"left:81px;top:641px;font-size:13.9px;max-width:198px\">C.发挥好人民政协专门协商机构作用</span><span class=\"bl\" style=\"left:81px;top:662px;font-size:13.9px;max-width:140px\">D.强化政协委员责任担当</span><span class=\"bl\" style=\"left:64px;top:697px;font-size:15.1px;max-width:446px\">4.【2022.24】中国共产党自成立以来不断探索和发展适合中国国情的民主道路，使</span><span class=\"bl\" style=\"left:81px;top:718px;font-size:15.1px;max-width:430px\">人民民主在东方大国落地生根、繁荣发展。党的十八大以来，我们党不断深化对</span><span class=\"bl\" style=\"left:81px;top:740px;font-size:15.1px;max-width:429px\">民主政治发展规律的认识，践行以人民为中心的发展思想，积极发展全过程人民</span><span class=\"bl\" style=\"left:81px;top:760px;font-size:15.6px;max-width:127px\">民主。全过程人民民主</span><span class=\"bl\" style=\"left:81px;top:781px;font-size:15.1px;max-width:270px\">A.是完整制度程序和完整参与实践有机统一的民主</span><span class=\"bl\" style=\"left:81px;top:802px;font-size:15.1px;max-width:199px\">B.是全链条、全方位、全覆盖的民主</span><span class=\"bl\" style=\"left:81px;top:823px;font-size:15.1px;max-width:246px\">C.是最广泛、最真实、最管用的社会主义民主</span><span class=\"bl\" style=\"left:81px;top:843px;font-size:16.7px;max-width:429px\">D.实现了过程民主和成果民主、程序民主和实质民主、直接民主和间接民主、人</span><span class=\"bl\" style=\"left:95px;top:865px;font-size:13.9px;max-width:138px\">民民主和国家意志相统一</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 70 页</div><span class=\"bl\" style=\"left:451px;top:56px;font-size:18.4px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:45px;top:104px;font-size:20.1px;max-width:448px\">5.【2022.8】文化软实力集中体现了一个国家基于文化而具有的凝聚力和生命力，以</span><span class=\"bl\" style=\"left:64px;top:126px;font-size:19.0px;max-width:429px\">及由此产生的吸引力和影响力。提高国家文化软实力需要强大的国际传播能力。</span><span class=\"bl\" style=\"left:64px;top:149px;font-size:15.6px;max-width:221px\">我国加强国际传播能力建设的重要任务是</span><span class=\"bl\" style=\"left:64px;top:170px;font-size:15.6px;max-width:141px\">A.加快发展新型文化业态</span><span class=\"bl\" style=\"left:63px;top:189px;font-size:18.4px;max-width:248px\">B.推进中华传统文化创造性转化、创新性发展</span><span class=\"bl\" style=\"left:64px;top:210px;font-size:19.0px;max-width:329px\">C.推进社会主义先进文化深入人心，激发全民族文化创造活力</span><span class=\"bl\" style=\"left:64px;top:231px;font-size:18.4px;max-width:353px\">D.讲好中国故事，传播好中国声音，展现真实、立体、全面的中国</span><span class=\"bl\" style=\"left:47px;top:266px;font-size:19.0px;max-width:447px\">6.【2021.24】“十三五”时期，我国大气污染治理取得明显成效。来自生态环境部的</span><span class=\"bl\" style=\"left:64px;top:287px;font-size:19.0px;max-width:430px\">数据显示，与2015年相比，2019年细颗粒物（PM2.5）未达标地级及以上城市</span><span class=\"bl\" style=\"left:65px;top:308px;font-size:17.3px;max-width:430px\">年均浓度下降23.1%，全国337个地级及以上城市年均优良天数比例达到82%。</span><span class=\"bl\" style=\"left:64px;top:329px;font-size:18.4px;max-width:431px\">2020年1月至8月，这一比例达到86.7%，PM2.5浓度为31微克/立方米，同比</span><span class=\"bl\" style=\"left:66px;top:350px;font-size:19.0px;max-width:429px\">下降11.4%，蓝天白云的好天气正在成为常态。我国大气污染治理取得明显成效，</span><span class=\"bl\" style=\"left:66px;top:374px;font-size:14.5px;max-width:67px\">主要得益于</span><span class=\"bl\" style=\"left:65px;top:394px;font-size:16.7px;max-width:153px\">A.坚持全民共治、源头防治</span><span class=\"bl\" style=\"left:64px;top:414px;font-size:17.3px;max-width:248px\">B.把突出环境问题作为生态文明建设的着力点</span><span class=\"bl\" style=\"left:65px;top:435px;font-size:17.3px;max-width:211px\">C.构建生态廊道和生物多样性保护网络</span><span class=\"bl\" style=\"left:65px;top:456px;font-size:16.7px;max-width:249px\">D.不断完善生态环境保护制度和强化环保督察</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 71 页</div><span class=\"bl b acc\" style=\"left:352px;top:111px;font-size:25.1px;max-width:84px\">第十一章</span><span class=\"bl\" style=\"left:307px;top:160px;font-size:22.9px;max-width:181px\">“四个全面”战略布局</span><span class=\"bl\" style=\"left:67px;top:208px;font-size:20.1px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:375px;top:253px;font-size:19.0px;max-width:213px\">考点55全面建设社会主义现代化国家</span><span class=\"bl b hl\" style=\"left:375px;top:274px;font-size:19.0px;max-width:130px\">考点56全面深化改革</span><span class=\"bl\" style=\"left:205px;top:282px;font-size:17.8px;max-width:119px\">“四个全面”战略布局</span><span class=\"bl b hl\" style=\"left:374px;top:295px;font-size:18.4px;max-width:131px\">考点57全面依法治国</span><span class=\"bl b hl\" style=\"left:374px;top:316px;font-size:17.8px;max-width:131px\">考点58全面从严治党</span><span class=\"bl\" style=\"left:67px;top:364px;font-size:19.5px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:92px;top:393px;font-size:20.1px;max-width:623px\">本章主要阐述了建设中国特色社会主义“四个全面”战略布局的内容。本章在本科目中考频非常高，考生需要高度重</span><span class=\"bl\" style=\"left:67px;top:414px;font-size:20.1px;max-width:648px\">视，考试形式既可能为选择题，也可能为材料分析题。考生在复习过程中，要重点掌握我国2035年远景目标，改革开放的</span><span class=\"bl\" style=\"left:68px;top:435px;font-size:20.1px;max-width:648px\">重要性、初心和使命，全面深化改革的必要性、基本原则、根本目的、总目标、主要内容以及正确的方法论，推动全面开放</span><span class=\"bl\" style=\"left:67px;top:456px;font-size:19.5px;max-width:499px\">的必要性、要求和举措，全面依法治国的总目标、重点任务，新时代党的建设的总要求等内容。</span><span class=\"bl\" style=\"left:71px;top:480px;font-size:31.8px;max-width:386px\">微信公个号：dikv6</span><span class=\"bl b hl\" style=\"left:76px;top:508px;font-size:23.4px;max-width:314px\">考点55全面建设社会主义现代化国家☆长☆</span><span class=\"bl\" style=\"left:673px;top:515px;font-size:15.1px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:66px;top:545px;font-size:19.5px;max-width:446px\">55.1从全面建成小康社会到全面建设社会主义现代化国家（高频选择题、分析题）</span><span class=\"bl b\" style=\"left:89px;top:566px;font-size:17.8px;max-width:162px\">1.全面建成小康社会的意义：</span><span class=\"bl\" style=\"left:91px;top:588px;font-size:19.5px;max-width:423px\">全面建成小康社会是“两个一百年”奋斗目标的第一个百年奋斗目标，是党向人</span><span class=\"bl\" style=\"left:67px;top:610px;font-size:16.7px;max-width:283px\">民、向历史作出的庄严承诺，是中国人民的共同期盼。</span><span class=\"bl b\" style=\"left:89px;top:630px;font-size:17.3px;max-width:182px\">2.全面建成小康社会的底线任务：</span><span class=\"bl\" style=\"left:90px;top:651px;font-size:19.5px;max-width:423px\">全面建成小康社会，强调的不仅是“小康”，更重要、更难做到的是“全面”。</span><span class=\"bl\" style=\"left:66px;top:671px;font-size:19.5px;max-width:447px\">“小康”讲的是发展水平，“全面”讲的是发展的平衡性、协调性、可持续性。全面小</span><span class=\"bl\" style=\"left:66px;top:692px;font-size:19.5px;max-width:447px\">康，是“五位一体”全面进步的小康，要求经济、政治、文化、社会、生态文明建设</span><span class=\"bl\" style=\"left:66px;top:714px;font-size:19.0px;max-width:447px\">全面推进。全面小康，是惠及全体人民的小康，全面小康的路上，一个都不能少。全</span><span class=\"bl\" style=\"left:66px;top:735px;font-size:18.4px;max-width:447px\">面小康，是城乡区域共同发展的小康。农村特别是贫困地区，是全面小康最大的短</span><span class=\"bl\" style=\"left:65px;top:755px;font-size:19.0px;max-width:298px\">板。打赢脱贫攻坚战，是全面建成小康社会的底线任务。</span><span class=\"bl\" style=\"left:88px;top:776px;font-size:19.0px;max-width:425px\">3.脱贫攻坚取得了全面胜利，决胜全面建成小康社会取得决定性成就。经过八年</span><span class=\"bl\" style=\"left:64px;top:797px;font-size:19.0px;max-width:447px\">持续奋斗，到2020年年底，现行标准下9899万农村贫困人口全部脱贫，区域性整体</span><span class=\"bl\" style=\"left:64px;top:818px;font-size:19.5px;max-width:447px\">贫困得到解决，消除了绝对贫困，完成了全面建成小康社会最艰巨最繁重的任务，为</span><span class=\"bl\" style=\"left:64px;top:839px;font-size:19.0px;max-width:448px\">实现全面建成小康社会目标任务作出了关键性贡献、打下了坚实基础。2021年7月1</span><span class=\"bl\" style=\"left:64px;top:859px;font-size:19.5px;max-width:447px\">日，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地</span><span class=\"bl\" style=\"left:64px;top:880px;font-size:20.6px;max-width:448px\">解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个百年</span><span class=\"bl\" style=\"left:63px;top:900px;font-size:17.8px;max-width:86px\">奋斗目标迈进。</span><span class=\"bl b\" style=\"left:63px;top:928px;font-size:20.1px;max-width:389px\">55.2开启全面建设社会主义现代化国家新征程（高频选择题、分析题）</span><span class=\"bl b\" style=\"left:87px;top:950px;font-size:18.4px;max-width:238px\">1.中国式现代化与资本主义的现代化的区别：</span><span class=\"bl\" style=\"left:87px;top:971px;font-size:19.0px;max-width:404px\">①中国式现代化打破了只有遵循资本主义现代化模式才能实现现代化的神话；</span><span class=\"bl\" style=\"left:87px;top:991px;font-size:17.8px;max-width:284px\">②中国式现代化克服了资本主义现代化所固有的端；</span></div></div>"}],pages:[54,71]};
  D["mzt_s12"] = {id:"mzt_s12",ch:"毛中特讲义 · 第十一章 “四个全面”战略布局",title:"第十一章 “四个全面”战略布局",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 71 页</div><span class=\"bl b acc\" style=\"left:352px;top:111px;font-size:25.1px;max-width:84px\">第十一章</span><span class=\"bl\" style=\"left:307px;top:160px;font-size:22.9px;max-width:181px\">“四个全面”战略布局</span><span class=\"bl\" style=\"left:67px;top:208px;font-size:20.1px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:375px;top:253px;font-size:19.0px;max-width:213px\">考点55全面建设社会主义现代化国家</span><span class=\"bl b hl\" style=\"left:375px;top:274px;font-size:19.0px;max-width:130px\">考点56全面深化改革</span><span class=\"bl\" style=\"left:205px;top:282px;font-size:17.8px;max-width:119px\">“四个全面”战略布局</span><span class=\"bl b hl\" style=\"left:374px;top:295px;font-size:18.4px;max-width:131px\">考点57全面依法治国</span><span class=\"bl b hl\" style=\"left:374px;top:316px;font-size:17.8px;max-width:131px\">考点58全面从严治党</span><span class=\"bl\" style=\"left:67px;top:364px;font-size:19.5px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:92px;top:393px;font-size:20.1px;max-width:623px\">本章主要阐述了建设中国特色社会主义“四个全面”战略布局的内容。本章在本科目中考频非常高，考生需要高度重</span><span class=\"bl\" style=\"left:67px;top:414px;font-size:20.1px;max-width:648px\">视，考试形式既可能为选择题，也可能为材料分析题。考生在复习过程中，要重点掌握我国2035年远景目标，改革开放的</span><span class=\"bl\" style=\"left:68px;top:435px;font-size:20.1px;max-width:648px\">重要性、初心和使命，全面深化改革的必要性、基本原则、根本目的、总目标、主要内容以及正确的方法论，推动全面开放</span><span class=\"bl\" style=\"left:67px;top:456px;font-size:19.5px;max-width:499px\">的必要性、要求和举措，全面依法治国的总目标、重点任务，新时代党的建设的总要求等内容。</span><span class=\"bl\" style=\"left:71px;top:480px;font-size:31.8px;max-width:386px\">微信公个号：dikv6</span><span class=\"bl b hl\" style=\"left:76px;top:508px;font-size:23.4px;max-width:314px\">考点55全面建设社会主义现代化国家☆长☆</span><span class=\"bl\" style=\"left:673px;top:515px;font-size:15.1px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:66px;top:545px;font-size:19.5px;max-width:446px\">55.1从全面建成小康社会到全面建设社会主义现代化国家（高频选择题、分析题）</span><span class=\"bl b\" style=\"left:89px;top:566px;font-size:17.8px;max-width:162px\">1.全面建成小康社会的意义：</span><span class=\"bl\" style=\"left:91px;top:588px;font-size:19.5px;max-width:423px\">全面建成小康社会是“两个一百年”奋斗目标的第一个百年奋斗目标，是党向人</span><span class=\"bl\" style=\"left:67px;top:610px;font-size:16.7px;max-width:283px\">民、向历史作出的庄严承诺，是中国人民的共同期盼。</span><span class=\"bl b\" style=\"left:89px;top:630px;font-size:17.3px;max-width:182px\">2.全面建成小康社会的底线任务：</span><span class=\"bl\" style=\"left:90px;top:651px;font-size:19.5px;max-width:423px\">全面建成小康社会，强调的不仅是“小康”，更重要、更难做到的是“全面”。</span><span class=\"bl\" style=\"left:66px;top:671px;font-size:19.5px;max-width:447px\">“小康”讲的是发展水平，“全面”讲的是发展的平衡性、协调性、可持续性。全面小</span><span class=\"bl\" style=\"left:66px;top:692px;font-size:19.5px;max-width:447px\">康，是“五位一体”全面进步的小康，要求经济、政治、文化、社会、生态文明建设</span><span class=\"bl\" style=\"left:66px;top:714px;font-size:19.0px;max-width:447px\">全面推进。全面小康，是惠及全体人民的小康，全面小康的路上，一个都不能少。全</span><span class=\"bl\" style=\"left:66px;top:735px;font-size:18.4px;max-width:447px\">面小康，是城乡区域共同发展的小康。农村特别是贫困地区，是全面小康最大的短</span><span class=\"bl\" style=\"left:65px;top:755px;font-size:19.0px;max-width:298px\">板。打赢脱贫攻坚战，是全面建成小康社会的底线任务。</span><span class=\"bl\" style=\"left:88px;top:776px;font-size:19.0px;max-width:425px\">3.脱贫攻坚取得了全面胜利，决胜全面建成小康社会取得决定性成就。经过八年</span><span class=\"bl\" style=\"left:64px;top:797px;font-size:19.0px;max-width:447px\">持续奋斗，到2020年年底，现行标准下9899万农村贫困人口全部脱贫，区域性整体</span><span class=\"bl\" style=\"left:64px;top:818px;font-size:19.5px;max-width:447px\">贫困得到解决，消除了绝对贫困，完成了全面建成小康社会最艰巨最繁重的任务，为</span><span class=\"bl\" style=\"left:64px;top:839px;font-size:19.0px;max-width:448px\">实现全面建成小康社会目标任务作出了关键性贡献、打下了坚实基础。2021年7月1</span><span class=\"bl\" style=\"left:64px;top:859px;font-size:19.5px;max-width:447px\">日，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地</span><span class=\"bl\" style=\"left:64px;top:880px;font-size:20.6px;max-width:448px\">解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个百年</span><span class=\"bl\" style=\"left:63px;top:900px;font-size:17.8px;max-width:86px\">奋斗目标迈进。</span><span class=\"bl b\" style=\"left:63px;top:928px;font-size:20.1px;max-width:389px\">55.2开启全面建设社会主义现代化国家新征程（高频选择题、分析题）</span><span class=\"bl b\" style=\"left:87px;top:950px;font-size:18.4px;max-width:238px\">1.中国式现代化与资本主义的现代化的区别：</span><span class=\"bl\" style=\"left:87px;top:971px;font-size:19.0px;max-width:404px\">①中国式现代化打破了只有遵循资本主义现代化模式才能实现现代化的神话；</span><span class=\"bl\" style=\"left:87px;top:991px;font-size:17.8px;max-width:284px\">②中国式现代化克服了资本主义现代化所固有的端；</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 72 页</div><div class=\"sidebox\" style=\"left:509px;top:835px;width:195px;height:137px\"></div><span class=\"bl\" style=\"left:461px;top:61px;font-size:15.6px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:81px;top:108px;font-size:15.6px;max-width:418px\">③中国式现代化是发展中国家的现代化，开辟了后发国家走向现代化的崭新道路；</span><span class=\"bl\" style=\"left:81px;top:129px;font-size:15.6px;max-width:422px\">④中国式现代化发展是“并联式”的过程，工业化、信息化、城镇化、农业现代</span><span class=\"bl\" style=\"left:58px;top:152px;font-size:14.0px;max-width:95px\">化是叠加发展的。</span><span class=\"bl b\" style=\"left:80px;top:172px;font-size:15.1px;max-width:215px\">2.中国社会主义现代化国家的基本特征：</span><span class=\"bl\" style=\"left:82px;top:192px;font-size:15.1px;max-width:223px\">①中国的现代化是人口规模巨大的现代化。</span><span class=\"bl\" style=\"left:82px;top:213px;font-size:15.1px;max-width:422px\">②中国的现代化是全体人民共同富裕的现代化。我国的现代化是社会主义现代</span><span class=\"bl\" style=\"left:57px;top:235px;font-size:14.0px;max-width:140px\">化，共同富裕是本质要求。</span><span class=\"bl\" style=\"left:82px;top:256px;font-size:14.0px;max-width:294px\">③中国的现代化是物质文明和精神文明相协调的现代化。</span><span class=\"bl\" style=\"left:82px;top:277px;font-size:14.0px;max-width:247px\">④中国的现代化是人与自然和谐共生的现代化。</span><span class=\"bl\" style=\"left:82px;top:298px;font-size:14.0px;max-width:236px\">③中国的现代化是走和平发展道路的现代化。</span><span class=\"bl b hl\" style=\"left:68px;top:337px;font-size:17.9px;max-width:205px\">考点56全面深化改革☆☆☆</span><span class=\"bl b\" style=\"left:57px;top:373px;font-size:15.1px;max-width:307px\">56.1坚定不移推进全面深化改革（高频选择题、分析题）</span><span class=\"bl\" style=\"left:82px;top:395px;font-size:14.0px;max-width:388px\">1.改革开放是我们党的一次伟大觉醒（实行改革开放历史性决策的依据）：</span><span class=\"bl\" style=\"left:82px;top:416px;font-size:14.0px;max-width:225px\">①是基于对党和国家前途命运的深刻把握。</span><span class=\"bl\" style=\"left:82px;top:436px;font-size:15.1px;max-width:260px\">②是基于对社会主义革命和建设实践的深刻总结。</span><span class=\"bl\" style=\"left:82px;top:457px;font-size:15.1px;max-width:179px\">③是基于对时代潮流的深刻洞察。</span><span class=\"bl\" style=\"left:80px;top:478px;font-size:15.1px;max-width:238px\">④是基于对人民群众期盼和需要的深刻体悟。</span><span class=\"bl\" style=\"left:81px;top:499px;font-size:15.6px;max-width:365px\">2.改革开放是中国人民和中华民族发展史上的一次伟大革命（地位）。</span><span class=\"bl\" style=\"left:82px;top:521px;font-size:14.0px;max-width:421px\">①改革开放是决定当代中国命运的关键执择，是当代中国发展进步的活力之源，</span><span class=\"bl\" style=\"left:58px;top:542px;font-size:14.0px;max-width:445px\">是党和人民事业大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义、实现</span><span class=\"bl\" style=\"left:57px;top:561px;font-size:16.8px;max-width:171px\">中华民族伟大复兴的必由之路。</span><span class=\"bl\" style=\"left:82px;top:584px;font-size:14.0px;max-width:421px\">②改革开放是决定当代中国命运的关键一招，也是决定实现两个一百年奋斗目</span><span class=\"bl\" style=\"left:57px;top:604px;font-size:14.0px;max-width:214px\">标、实现中华民族伟大复兴的关键一招。</span><span class=\"bl\" style=\"left:82px;top:625px;font-size:14.0px;max-width:367px\">③改革开放是当代中国最鲜明的特色，也是中国共产党最鲜明的旗帜。</span><span class=\"bl\" style=\"left:82px;top:647px;font-size:14.0px;max-width:421px\">④改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌、中国共</span><span class=\"bl\" style=\"left:57px;top:668px;font-size:14.0px;max-width:72px\">产党的面貌。</span><span class=\"bl b\" style=\"left:80px;top:689px;font-size:14.0px;max-width:144px\">3.全面深化改革的必要性：</span><span class=\"bl\" style=\"left:82px;top:710px;font-size:14.0px;max-width:421px\">①顺应当今世界发展大势的必然选择。进人新时代，我国国内外环境发生了极为</span><span class=\"bl\" style=\"left:57px;top:731px;font-size:14.0px;max-width:333px\">广泛而且深刻的变化，纵观世界，变革是大势所趋、人心所向。</span><span class=\"bl\" style=\"left:82px;top:752px;font-size:14.0px;max-width:421px\">②解决中国现实问题的根本途径。随着改革进人攻坚期和深水区，遇到的阻力越</span><span class=\"bl\" style=\"left:57px;top:772px;font-size:14.5px;max-width:447px\">来越大，要破解发展中面临的难题，推动经济社会持续健康发展，必须依靠全面深化</span><span class=\"bl\" style=\"left:56px;top:793px;font-size:14.5px;max-width:39px\">改革。</span><span class=\"bl\" style=\"left:82px;top:814px;font-size:14.0px;max-width:332px\">③关系党和人民事业前途命运，关系党的执政基础和执政地位。</span><span class=\"bl b\" style=\"left:58px;top:842px;font-size:14.0px;max-width:328px\">56.2坚持全面深化改革的方向、立场和原则（中频选择题）</span><span class=\"bl\" style=\"left:456px;top:842px;font-size:14.5px;max-width:47px\">&gt;提示1</span><span class=\"bl\" style=\"left:517px;top:841px;font-size:14.0px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl b\" style=\"left:81px;top:862px;font-size:15.6px;max-width:415px\">1.方向：全面深化改革必须坚持和完善中国特色社会主义制度和国家治理体系。</span><span class=\"bl b\" style=\"left:515px;top:863px;font-size:14.5px;max-width:191px\">1.全面深化改革的根本目的：解放和发展</span><span class=\"bl\" style=\"left:82px;top:883px;font-size:15.1px;max-width:422px\">①制度优势是一个国家的最大优势，制度竞争是国家间根本的竞争，制度稳则国</span><span class=\"bl\" style=\"left:526px;top:882px;font-size:12.3px;max-width:180px\">社会生产力，促进社会公平正义，让改</span><span class=\"bl\" style=\"left:57px;top:905px;font-size:15.1px;max-width:38px\">家稳。</span><span class=\"bl\" style=\"left:526px;top:901px;font-size:12.3px;max-width:174px\">革发展成果更多更公平惠及全体人民。</span><span class=\"bl b\" style=\"left:515px;top:918px;font-size:14.0px;max-width:113px\">2.改革成效的评价标准：</span><span class=\"bl\" style=\"left:82px;top:925px;font-size:15.6px;max-width:418px\">②我国国家制度和国家治理体系具有显著优势，是坚定“四个自信”的基本依据。</span><span class=\"bl\" style=\"left:526px;top:936px;font-size:14.0px;max-width:114px\">是否促进经济社会发展；</span><span class=\"bl\" style=\"left:82px;top:946px;font-size:14.5px;max-width:423px\">③中国特色社会主义制度和国家治理体系是以马克思主义为指导、植根中国大</span><span class=\"bl\" style=\"left:526px;top:954px;font-size:14.0px;max-width:180px\">是否给人民群众带来实实在在的获得感。</span><span class=\"bl\" style=\"left:57px;top:966px;font-size:15.6px;max-width:447px\">地、具有深厚中华文化根基、深得人民拥护的制度和治理体系，是党和人民长期奋</span><span class=\"bl\" style=\"left:58px;top:987px;font-size:15.6px;max-width:447px\">斗、接力探索、历尽千辛万苦、付出巨大代价取得的根本成就，是具有强大生命力和</span><span class=\"bl\" style=\"left:58px;top:1010px;font-size:14.0px;max-width:167px\">巨大优越性的制度和治理体系。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1098px\"><div class=\"bxnum\">第 73 页</div><div class=\"sidebox\" style=\"left:512px;top:380px;width:195px;height:156px\"></div><span class=\"bl b\" style=\"left:85px;top:106px;font-size:16.7px;max-width:423px\">2.立场：全面深化改革必须始终站稳人民立场，坚持以人民为中心的改革价值取</span><span class=\"bl\" style=\"left:62px;top:126px;font-size:16.7px;max-width:447px\">向。必须坚持改革往有利于维护社会公平正义、增进人民福社方向前进。这是全面深</span><span class=\"bl\" style=\"left:62px;top:147px;font-size:16.7px;max-width:414px\">化改革的出发点和落脚点，是坚持党全心全意为人民服务根本宗旨的必然要求。</span><span class=\"bl b\" style=\"left:84px;top:169px;font-size:15.6px;max-width:424px\">3.原则：全面深化改革必须坚持党对改革的集中统一领导。党的集中统一领导是</span><span class=\"bl\" style=\"left:62px;top:189px;font-size:15.6px;max-width:355px\">保证全面深化改革乘风破浪、奋勇向前的指南针、定盘星和压舱石。</span><span class=\"bl b\" style=\"left:61px;top:217px;font-size:15.6px;max-width:427px\">56.3坚持和完善中国特色社会主义制度，推进国家治理现代化（高频选择题）</span><span class=\"bl b\" style=\"left:84px;top:239px;font-size:17.3px;max-width:422px\">1.全面深化改革的总目标：坚持和完善中国特色社会主义制度，推进国家治理体</span><span class=\"bl\" style=\"left:62px;top:260px;font-size:13.9px;max-width:118px\">系和治理能力现代化。</span><span class=\"bl b\" style=\"left:84px;top:281px;font-size:15.1px;max-width:133px\">2.全面深化改革的意义：</span><span class=\"bl\" style=\"left:86px;top:302px;font-size:14.5px;max-width:214px\">①是改革进程本身向前拓展的客观需要。</span><span class=\"bl\" style=\"left:85px;top:323px;font-size:14.5px;max-width:273px\">②是坚持和完善中国特色社会主义制度的必然要求。</span><span class=\"bl\" style=\"left:85px;top:344px;font-size:15.1px;max-width:227px\">③是实现社会主义现代化的题中应有之义。</span><span class=\"bl\" style=\"left:85px;top:365px;font-size:14.5px;max-width:260px\">④是纵观世界社会主义历史发展得出的深刻结论。</span><span class=\"bl b\" style=\"left:85px;top:388px;font-size:12.3px;max-width:214px\">3.国家治理体系和国家治理能力的关系：</span><span class=\"bl\" style=\"left:459px;top:387px;font-size:14.5px;max-width:47px\">&gt;提示1</span><span class=\"bl\" style=\"left:521px;top:386px;font-size:13.9px;max-width:102px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:86px;top:408px;font-size:13.9px;max-width:202px\">①二者是一个有机统一体，不可分割。</span><span class=\"bl\" style=\"left:519px;top:411px;font-size:12.3px;max-width:189px\">1.国家治理体系越完备，国家治理能力就</span><span class=\"bl\" style=\"left:85px;top:428px;font-size:14.5px;max-width:261px\">制度是治理的依据，制度的性质决定治理的方式；</span><span class=\"bl\" style=\"left:528px;top:429px;font-size:12.8px;max-width:60px\">一定越强x</span><span class=\"bl\" style=\"left:86px;top:450px;font-size:13.4px;max-width:248px\">治理是制度的实践，制度的实践过程就是治理。</span><span class=\"bl\" style=\"left:518px;top:448px;font-size:12.3px;max-width:189px\">2.不能把国家治理体系和国家治理能力等</span><span class=\"bl\" style=\"left:86px;top:471px;font-size:13.9px;max-width:214px\">②制度和治理两者相辅相成、相得益彰。</span><span class=\"bl\" style=\"left:529px;top:466px;font-size:12.3px;max-width:179px\">同起来，不是国家治理体系越完备，国</span><span class=\"bl\" style=\"left:529px;top:484px;font-size:12.3px;max-width:179px\">家治理能力就越强。必须把国家治理体</span><span class=\"bl\" style=\"left:82px;top:492px;font-size:13.9px;max-width:426px\">一方面，制度对于国家治理起着根本性、全局性、长期性作用。只有有了好的制</span><span class=\"bl\" style=\"left:529px;top:501px;font-size:14.5px;max-width:180px\">系和治理能力结合在一起，把两者当作</span><span class=\"bl\" style=\"left:61px;top:512px;font-size:14.5px;max-width:446px\">度，才有可能实现治理体系和治理能力的现代化。我国国家治理一切工作和活动都依</span><span class=\"bl\" style=\"left:528px;top:520px;font-size:12.3px;max-width:124px\">一个相辅相成的有机整体。</span><span class=\"bl\" style=\"left:62px;top:534px;font-size:12.3px;max-width:444px\">照中国特色社会主义制度展开，我国国家治理体系和治理能力是中国特色社会主义制</span><span class=\"bl\" style=\"left:61px;top:554px;font-size:15.1px;max-width:170px\">度及其执行能力的集中体现。</span><span class=\"bl\" style=\"left:86px;top:575px;font-size:13.9px;max-width:421px\">另一方面，没有完善的治理体系和有效的治理能力，再好的制度也难以发挥作</span><span class=\"bl\" style=\"left:62px;top:597px;font-size:12.3px;max-width:444px\">用。只有全面实现国家治理体系和治理能力现代化，才能使中国特色社会主义制度更</span><span class=\"bl\" style=\"left:62px;top:617px;font-size:13.9px;max-width:131px\">加巩固、优势充分彰显。</span><span class=\"bl\" style=\"left:83px;top:637px;font-size:14.5px;max-width:423px\">4.坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化的总</span><span class=\"bl\" style=\"left:62px;top:659px;font-size:13.4px;max-width:36px\">目标：</span><span class=\"bl\" style=\"left:86px;top:680px;font-size:13.4px;max-width:401px\">①到我们党成立一百年时，在各方面制度更加成熟更加定型上取得明显成效；</span><span class=\"bl\" style=\"left:86px;top:700px;font-size:15.1px;max-width:419px\">②到2035年，各方面制度更加完善，基本实现国家治理体系和治理能力现代化；</span><span class=\"bl\" style=\"left:84px;top:722px;font-size:14.5px;max-width:422px\">③到新中国成立一百年时，全面实现国家治理体系和治理能力现代化，使中国特</span><span class=\"bl\" style=\"left:62px;top:742px;font-size:15.1px;max-width:237px\">色社会主义制度更加巩固、优越性充分展现。</span><span class=\"bl b\" style=\"left:61px;top:770px;font-size:15.1px;max-width:180px\">56.4推动全面开放（拓展考点）</span><span class=\"bl b\" style=\"left:84px;top:791px;font-size:13.9px;max-width:167px\">1.新时代我国对外开放新形势：</span><span class=\"bl\" style=\"left:85px;top:812px;font-size:13.9px;max-width:85px\">①从国际上看：</span><span class=\"bl\" style=\"left:84px;top:833px;font-size:15.1px;max-width:308px\">经济全球化深人发展，国际经济合作与竞争格局加速演变；</span><span class=\"bl\" style=\"left:84px;top:854px;font-size:15.1px;max-width:422px\">在错综复杂的全球经济形势下抓住机遇、化解挑战，是我国对外工作面临的重要</span><span class=\"bl\" style=\"left:60px;top:874px;font-size:15.6px;max-width:40px\">任务。</span><span class=\"bl\" style=\"left:85px;top:895px;font-size:13.9px;max-width:72px\">②从国内看：</span><span class=\"bl\" style=\"left:84px;top:916px;font-size:15.1px;max-width:285px\">加快培育竞争新优势成为我国开放型经济的发展方向；</span><span class=\"bl\" style=\"left:84px;top:936px;font-size:15.6px;max-width:422px\">推动我国经济由高速增长阶段向高质量发展阶段转变，实现质量变革、效率变</span><span class=\"bl\" style=\"left:59px;top:956px;font-size:15.6px;max-width:285px\">革、动力变革，是对外开放工作必须把握的主攻方向。</span><span class=\"bl\" style=\"left:82px;top:978px;font-size:15.6px;max-width:424px\">2.要建设更高水平开放型经济新体制，实施更大范围、更宽领域、更深层次的全</span><span class=\"bl\" style=\"left:61px;top:999px;font-size:13.9px;max-width:84px\">面开放的要求：</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 74 页</div><span class=\"bl\" style=\"left:455px;top:62px;font-size:15.6px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:76px;top:109px;font-size:17.3px;max-width:417px\">①优化对外开放的空间布局，包括加快自贸试验区、自由港等对外开放高地建设。</span><span class=\"bl\" style=\"left:76px;top:129px;font-size:17.8px;max-width:422px\">②实施更宽领域的开放，就是要大幅放宽市场准入，包括在更多领域允许外资控</span><span class=\"bl\" style=\"left:52px;top:153px;font-size:13.9px;max-width:96px\">股或独资经营等。</span><span class=\"bl\" style=\"left:76px;top:171px;font-size:17.3px;max-width:421px\">③实施更深层次的开放，就是要推动贸易和投资自由化便利化，包括健全外商投</span><span class=\"bl\" style=\"left:52px;top:194px;font-size:15.1px;max-width:226px\">资准入前国民待遇加负面清单管理等制度。</span><span class=\"bl b\" style=\"left:74px;top:214px;font-size:15.6px;max-width:295px\">3.全面开放是实现国家繁荣富强的根本出路（必要性）：</span><span class=\"bl\" style=\"left:78px;top:237px;font-size:12.3px;max-width:177px\">①开放带来进步，封闭必然落后。</span><span class=\"bl\" style=\"left:77px;top:255px;font-size:15.6px;max-width:390px\">②以开放促改革、促发展，是我国现代化建设不断取得新成就的重要法宝。</span><span class=\"bl\" style=\"left:77px;top:276px;font-size:15.6px;max-width:389px\">③抓住机遇扩大开放是我们的宝贵经验，开放已成为当代中国的鲜明标识。</span><span class=\"bl\" style=\"left:78px;top:300px;font-size:12.3px;max-width:188px\">④开放是国家繁荣发展的必由之路。</span><span class=\"bl b\" style=\"left:76px;top:320px;font-size:13.9px;max-width:193px\">4.推动全面开放的举措：（2017-23）</span><span class=\"bl\" style=\"left:76px;top:340px;font-size:15.1px;max-width:422px\">①以“一带一路”建设为重点，坚持引进来和走出去并重，遵循共商共建共享原</span><span class=\"bl\" style=\"left:53px;top:361px;font-size:13.9px;max-width:401px\">则，加强创新能力开放合作，形成陆海内外联动、东西双向互济的开放格局。</span><span class=\"bl\" style=\"left:78px;top:383px;font-size:12.3px;max-width:270px\">②坚持公平开放，构建公平竞争的内外资发展环境。</span><span class=\"bl\" style=\"left:78px;top:404px;font-size:12.3px;max-width:306px\">③坚持共赢开放，推动经济全球化朝着普惠共赢方向发展。</span><span class=\"bl\" style=\"left:77px;top:423px;font-size:14.5px;max-width:355px\">④坚持包容开放，探索求同存异、包容共生的国际发展合作新途径。</span><span class=\"bl b\" style=\"left:77px;top:445px;font-size:12.3px;max-width:259px\">5.开放型世界经济的首要之义是：反对保护主义。</span><span class=\"bl b hl\" style=\"left:63px;top:485px;font-size:17.8px;max-width:211px\">考点57 全面依法治国☆★众</span><span class=\"bl b\" style=\"left:53px;top:521px;font-size:13.9px;max-width:221px\">57.1坚持习近平法治思想（高频选择题）</span><span class=\"bl\" style=\"left:77px;top:541px;font-size:15.1px;max-width:307px\">全面依法治国是中国特色社会主义的本质要求和重要保障。</span><span class=\"bl\" style=\"left:77px;top:562px;font-size:17.3px;max-width:423px\">习近平法治思想深刻回答了为什么要全面依法治国、怎样全面依法治国这个重大</span><span class=\"bl\" style=\"left:53px;top:585px;font-size:12.8px;max-width:59px\">时代课题。</span><span class=\"bl\" style=\"left:77px;top:604px;font-size:15.6px;max-width:422px\">习近平法治思想的主要内容就是“十一个坚持”。这“十一个坚持”，既是重大</span><span class=\"bl\" style=\"left:54px;top:625px;font-size:14.5px;max-width:445px\">工作部署，又是重要战略思想。其中，前3个坚持是习近平法治思想指明的政治方</span><span class=\"bl\" style=\"left:53px;top:646px;font-size:15.1px;max-width:355px\">向，集中体现全面依法治国由谁领导、为了谁依靠谁、走什么路等。</span><span class=\"bl\" style=\"left:77px;top:668px;font-size:14.5px;max-width:401px\">1.坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。</span><span class=\"bl\" style=\"left:76px;top:688px;font-size:15.1px;max-width:423px\">2.坚持以人民为中心。全面依法治国最广泛、最深厚的基础是人民，必须坚持为</span><span class=\"bl\" style=\"left:56px;top:710px;font-size:13.9px;max-width:106px\">了人民、依靠人民。</span><span class=\"bl\" style=\"left:76px;top:730px;font-size:15.1px;max-width:424px\">3.坚持中国特色社会主义法治道路。中国特色社会主义法治道路本质上是中国特</span><span class=\"bl\" style=\"left:54px;top:752px;font-size:14.5px;max-width:207px\">色社会主义道路在法治领域的具体体现</span><span class=\"bl\" style=\"left:76px;top:772px;font-size:15.1px;max-width:424px\">4.坚持依宪治国、依宪执政。党领导人民制定宪法法律，领导人民实施宪法法</span><span class=\"bl\" style=\"left:54px;top:795px;font-size:12.3px;max-width:199px\">律，党自身要在宪法法律范围内活动。</span><span class=\"bl\" style=\"left:76px;top:813px;font-size:15.1px;max-width:424px\">5.坚持在法治轨道上推进国家治理体系和治理能力现代化。法治是国家治理体系</span><span class=\"bl\" style=\"left:55px;top:836px;font-size:13.9px;max-width:131px\">和治理能力的重要依托。</span><span class=\"bl\" style=\"left:77px;top:855px;font-size:15.1px;max-width:423px\">6.坚持建设中国特色社会主义法治体系。中国特色社会主义法治体系是推进全面</span><span class=\"bl\" style=\"left:56px;top:879px;font-size:12.3px;max-width:106px\">依法治国的总抓手。</span><span class=\"bl\" style=\"left:77px;top:896px;font-size:15.6px;max-width:423px\">7.坚持依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社</span><span class=\"bl\" style=\"left:56px;top:919px;font-size:12.3px;max-width:270px\">会一体建设。法治政府建设是重点任务和主体工程。</span><span class=\"bl\" style=\"left:77px;top:938px;font-size:15.6px;max-width:424px\">8.坚持全面推进科学立法、严格执法、公正司法、全民守法。要继续推进法治领</span><span class=\"bl\" style=\"left:54px;top:959px;font-size:15.6px;max-width:447px\">域改革，解决好立法、执法、司法、守法等领域的突出矛盾和问题。公平正义是司法</span><span class=\"bl\" style=\"left:55px;top:982px;font-size:13.9px;max-width:84px\">的灵魂和生命。</span><span class=\"bl\" style=\"left:77px;top:1000px;font-size:16.7px;max-width:424px\">9.坚持统筹推进国内法治和涉外法治。要加快涉外法治工作战略布局，协调推进</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1098px\"><div class=\"bxnum\">第 75 页</div><span class=\"bl\" style=\"left:69px;top:107px;font-size:16.7px;max-width:319px\">国内治理和国际治理，更好维护国家主权、安全、发展利益。</span><span class=\"bl\" style=\"left:93px;top:128px;font-size:17.3px;max-width:422px\">10.坚持建设德才兼备的高素质法治工作队伍。要加强理想信念教育，深入开展</span><span class=\"bl\" style=\"left:68px;top:149px;font-size:17.8px;max-width:446px\">社会主义核心价值观和社会主义法治理念教育，推进法治专门队伍革命化、正规化、</span><span class=\"bl\" style=\"left:68px;top:169px;font-size:15.6px;max-width:96px\">专业化、职业化。</span><span class=\"bl\" style=\"left:92px;top:190px;font-size:18.4px;max-width:421px\">11.坚持抓住领导干部这个“关键少数”。各级领导干部要坚决贯彻落实党中央</span><span class=\"bl\" style=\"left:68px;top:212px;font-size:17.8px;max-width:446px\">关于全面依法治国的重大决策部署，带头尊崇法治、敬畏法律，了解法律、掌握法</span><span class=\"bl\" style=\"left:67px;top:233px;font-size:15.0px;max-width:178px\">律，做尊法学法守法用法的模范。</span><span class=\"bl b\" style=\"left:68px;top:261px;font-size:16.7px;max-width:265px\">57.2中国特色社会主义法治道路（中频选择题）</span><span class=\"bl\" style=\"left:91px;top:282px;font-size:15.0px;max-width:145px\">1.坚持中国共产党的领导。</span><span class=\"bl\" style=\"left:92px;top:303px;font-size:15.6px;max-width:224px\">①党的领导是社会主义法治最根本的保证。</span><span class=\"bl\" style=\"left:92px;top:323px;font-size:18.9px;max-width:421px\">②必须坚持党领导立法、保证执法、支持司法、带头守法，把依法治国同依法执</span><span class=\"bl\" style=\"left:67px;top:345px;font-size:15.6px;max-width:74px\">政统一起来。</span><span class=\"bl\" style=\"left:90px;top:367px;font-size:15.0px;max-width:226px\">2.坚持人民在全面依法治国中的主体地位。</span><span class=\"bl\" style=\"left:92px;top:387px;font-size:15.6px;max-width:325px\">1坚持中国特色社会主义法治道路的根本目的是保障人民权益</span><span class=\"bl\" style=\"left:92px;top:408px;font-size:15.0px;max-width:295px\">②坚持法治为了人民、依靠人民、造福人民、保护人民。</span><span class=\"bl\" style=\"left:91px;top:430px;font-size:13.9px;max-width:144px\">3.坚持法律面前人人平等。</span><span class=\"bl\" style=\"left:90px;top:451px;font-size:15.0px;max-width:192px\">4.坚持依法治国和以德治国相结合。</span><span class=\"bl\" style=\"left:91px;top:472px;font-size:13.9px;max-width:133px\">5.坚持从中国实际出发。</span><span class=\"bl\" style=\"left:90px;top:491px;font-size:17.8px;max-width:423px\">构建中国特色社会主义法治道路要求我们坚持从中国实际出发，突出中国特色、</span><span class=\"bl\" style=\"left:65px;top:507px;font-size:24.5px;max-width:219px\">实践特色、时代特色。</span><span class=\"bl b\" style=\"left:66px;top:540px;font-size:19.5px;max-width:292px\">57.3深化依法治国实践的重点任务口</span><span class=\"bl\" style=\"left:90px;top:562px;font-size:17.8px;max-width:423px\">全面依法治国的总目标：建设中国特色社会主义法治体系，建设社会主义法治</span><span class=\"bl\" style=\"left:66px;top:583px;font-size:15.6px;max-width:38px\">国家。</span><span class=\"bl\" style=\"left:92px;top:605px;font-size:13.9px;max-width:143px\">全面依法治国的重点任务：</span><span class=\"bl\" style=\"left:91px;top:625px;font-size:15.6px;max-width:376px\">1.推进中国特色社会主义法治体系建设（全面推进依法治国的总抓手）。</span><span class=\"bl\" style=\"left:91px;top:646px;font-size:15.0px;max-width:285px\">①要完善以宪法为核心的中国特色社会主义法律体系。</span><span class=\"bl\" style=\"left:91px;top:666px;font-size:17.8px;max-width:356px\">抓住提高立法质量这个关键，推进科学立法、民主立法、依法立法。</span><span class=\"bl\" style=\"left:91px;top:688px;font-size:15.6px;max-width:421px\">维护宪法尊严和权威，是维护国家法制统一、尊严、权威的前提，也是维护最广</span><span class=\"bl\" style=\"left:66px;top:708px;font-size:15.6px;max-width:261px\">大人民根本利益、确保国家长治久安的重要保障。</span><span class=\"bl\" style=\"left:91px;top:731px;font-size:13.9px;max-width:166px\">②要建立严密的法律监督体系。</span><span class=\"bl\" style=\"left:90px;top:751px;font-size:15.0px;max-width:297px\">建设严密的法律监督体系的重点是：规范和约束公权力。</span><span class=\"bl\" style=\"left:90px;top:771px;font-size:16.7px;max-width:423px\">努力形成科学有效的权力运行制约和监督体系，要做到有权必有责、用权受监</span><span class=\"bl\" style=\"left:66px;top:793px;font-size:13.9px;max-width:95px\">督、违法必追究。</span><span class=\"bl\" style=\"left:90px;top:813px;font-size:16.7px;max-width:422px\">加大监督力度，加强党内监督、人大监督、民主监督、行政监督、司法监督、审</span><span class=\"bl\" style=\"left:66px;top:834px;font-size:15.0px;max-width:168px\">计监督、社会监督、舆论监督。</span><span class=\"bl\" style=\"left:90px;top:855px;font-size:14.5px;max-width:167px\">③要进一步健全法治保障体系。</span><span class=\"bl\" style=\"left:90px;top:875px;font-size:16.7px;max-width:421px\">④要加强党内法规制度建设。党内法规既是管党治党的重要依据，也是建设社会</span><span class=\"bl\" style=\"left:66px;top:896px;font-size:15.0px;max-width:143px\">主义法治国家的有力保障。</span><span class=\"bl\" style=\"left:88px;top:917px;font-size:16.7px;max-width:423px\">2.必须坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政</span><span class=\"bl\" style=\"left:65px;top:937px;font-size:16.7px;max-width:131px\">府、法治社会一体建设。</span><span class=\"bl\" style=\"left:89px;top:957px;font-size:17.8px;max-width:391px\">①依法治国、依法执政、依法行政，三者本质一致、目标一致、成效相关。</span><span class=\"bl\" style=\"left:89px;top:978px;font-size:15.6px;max-width:191px\">②能不能做到依法治国，关键在于：</span><span class=\"bl\" style=\"left:88px;top:1000px;font-size:15.6px;max-width:126px\">党能不能坚持依法执政</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 76 页</div><div class=\"sidebox\" style=\"left:502px;top:485px;width:196px;height:469px\"></div><span class=\"bl\" style=\"left:455px;top:60px;font-size:15.1px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:76px;top:108px;font-size:13.9px;max-width:136px\">各级政府能不能依法行政</span><span class=\"bl\" style=\"left:75px;top:127px;font-size:17.3px;max-width:417px\">③依法执政是我们党治国理政的基本方式，依法行政是各级政府活动的基本准则。</span><span class=\"bl\" style=\"left:76px;top:150px;font-size:13.9px;max-width:225px\">④法治国家、法治政府、法治社会的关系：</span><span class=\"bl\" style=\"left:75px;top:170px;font-size:15.1px;max-width:150px\">法治国家是法治建设的目标</span><span class=\"bl\" style=\"left:75px;top:191px;font-size:15.1px;max-width:150px\">法治政府是法治国家的主体</span><span class=\"bl\" style=\"left:76px;top:213px;font-size:13.9px;max-width:150px\">法治社会是法治国家的基础</span><span class=\"bl\" style=\"left:77px;top:233px;font-size:15.1px;max-width:207px\">三者共同构成建设法治中国的三根支柱</span><span class=\"bl\" style=\"left:76px;top:253px;font-size:14.5px;max-width:397px\">5党的十九大明确要求到2035年法治国家、法治政府、法治社会基本建成。</span><span class=\"bl\" style=\"left:74px;top:274px;font-size:15.6px;max-width:321px\">3.必须坚持推进科学立法、严格执法、公正司法、全民守法。</span><span class=\"bl\" style=\"left:76px;top:295px;font-size:14.5px;max-width:415px\">新时代我国法治建设的指导方针：科学立法、严格执法、公正司法、全民守法。</span><span class=\"bl\" style=\"left:78px;top:318px;font-size:12.3px;max-width:212px\">党的领导是社会主义法治最根本的保证。</span><span class=\"bl\" style=\"left:76px;top:338px;font-size:13.9px;max-width:296px\">必须坚持党领导立法、保证执法、支持司法、带头守法。</span><span class=\"bl b hl\" style=\"left:63px;top:377px;font-size:17.8px;max-width:202px\">考点58全面从严治党☆☆☆</span><span class=\"bl b\" style=\"left:52px;top:413px;font-size:13.9px;max-width:283px\">58.1全面从严治党是伟大的自我革命（高频选择题）</span><span class=\"bl b\" style=\"left:76px;top:434px;font-size:13.9px;max-width:423px\">1.全面从严治党的必要性：打铁必须自身硬。办好中国的事情，关键在党，关键</span><span class=\"bl\" style=\"left:52px;top:454px;font-size:17.3px;max-width:179px\">在坚持党要管党、全面从严治党。</span><span class=\"bl b\" style=\"left:73px;top:476px;font-size:15.6px;max-width:110px\">2.勇于自我革命是：</span><span class=\"bl\" style=\"left:207px;top:477px;font-size:53.5px;max-width:276px\">众号：</span><span class=\"bl\" style=\"left:510px;top:491px;font-size:15.6px;max-width:103px\">火星姐姐考点解读1</span><span class=\"bl\" style=\"left:76px;top:498px;font-size:13.9px;max-width:140px\">①是我们党最鲜明的品格。</span><span class=\"bl\" style=\"left:76px;top:518px;font-size:13.9px;max-width:119px\">②我们党最大的优势。</span><span class=\"bl\" style=\"left:510px;top:514px;font-size:13.9px;max-width:190px\">2021年11月11日，习近平在党的十九届</span><span class=\"bl\" style=\"left:73px;top:535px;font-size:26.8px;max-width:322px\">③是我们党区别于其他政党最显著的标志。尔</span><span class=\"bl\" style=\"left:510px;top:533px;font-size:12.3px;max-width:189px\">六中全会第二次全体会议上的讲话中指</span><span class=\"bl\" style=\"left:510px;top:551px;font-size:12.3px;max-width:189px\">出，我们党历史这么长、规模这么大、执</span><span class=\"bl\" style=\"left:77px;top:561px;font-size:13.9px;max-width:326px\">④对我们党如何跳出治乱兴衰的历史周期率给出的第二个答案</span><span class=\"bl\" style=\"left:451px;top:561px;font-size:14.5px;max-width:45px\">&gt;解读1</span><span class=\"bl\" style=\"left:510px;top:570px;font-size:12.3px;max-width:190px\">政这么久，如何跳出冶乱兴衰的历史周期</span><span class=\"bl\" style=\"left:74px;top:580px;font-size:15.6px;max-width:424px\">3.全面从严治党以其丰富内涵诠释了自我革命的内在要求。治国必先治党，治党</span><span class=\"bl\" style=\"left:510px;top:588px;font-size:12.3px;max-width:188px\">率？毛译东同志在延安的窑洞里给出了第</span><span class=\"bl\" style=\"left:52px;top:601px;font-size:15.6px;max-width:445px\">务必从严。全面从严治党，核心是加强党的领导，基础在全面，关键在严，要害在治。</span><span class=\"bl\" style=\"left:509px;top:605px;font-size:15.1px;max-width:190px\">一个答案，这就是“只有让人民来监督政</span><span class=\"bl\" style=\"left:75px;top:624px;font-size:13.9px;max-width:424px\">4.全面从严治党，要求增强系统性、预见性、创造性、实效性，使从严治党的一</span><span class=\"bl\" style=\"left:510px;top:624px;font-size:13.9px;max-width:111px\">府，政府才不敢松邂”。</span><span class=\"bl\" style=\"left:53px;top:644px;font-size:13.9px;max-width:400px\">切努力都集中到增强党自我净化、自我完善、自我革新、自我提高能力上来。</span><span class=\"bl\" style=\"left:510px;top:643px;font-size:12.3px;max-width:188px\">经过百年奋斗特别是党的十八大以来新的</span><span class=\"bl\" style=\"left:75px;top:665px;font-size:13.9px;max-width:238px\">5.全面从严治党推进自我革命不断走向深人。</span><span class=\"bl\" style=\"left:510px;top:660px;font-size:14.5px;max-width:190px\">实践，我们党又给出了第二个答案，这就</span><span class=\"bl\" style=\"left:509px;top:679px;font-size:14.5px;max-width:63px\">是自我革命。</span><span class=\"bl\" style=\"left:75px;top:685px;font-size:15.1px;max-width:345px\">6.全面从严治党永远在路上，中国共产党的自我革命任重而道远。</span><span class=\"bl b\" style=\"left:52px;top:714px;font-size:13.9px;max-width:293px\">58.2新时代党的建设总要求（高频选择题）（2019-7）</span><span class=\"bl\" style=\"left:450px;top:714px;font-size:14.5px;max-width:46px\">&gt;拓展1</span><span class=\"bl\" style=\"left:519px;top:714px;font-size:13.9px;max-width:94px\">火星姐姐考点拓展1</span><span class=\"bl b\" style=\"left:74px;top:733px;font-size:17.8px;max-width:425px\">1.新时代党的建设的总要求：坚持和加强党的全面领导，坚持党要管党，从严</span><span class=\"bl\" style=\"left:510px;top:737px;font-size:12.3px;max-width:161px\">提出新时代党的建设总要求的原因：</span><span class=\"bl\" style=\"left:52px;top:756px;font-size:15.1px;max-width:38px\">治党。</span><span class=\"bl\" style=\"left:509px;top:755px;font-size:12.3px;max-width:190px\">1.我们党面临的执政环境是复杂的，影响</span><span class=\"bl\" style=\"left:77px;top:776px;font-size:15.6px;max-width:330px\">①以加强党的长期执政能力建设，先进性和纯洁性建设为主线。</span><span class=\"bl\" style=\"left:520px;top:773px;font-size:12.3px;max-width:179px\">党的先进性，弱化党的纯洁性的因素也</span><span class=\"bl\" style=\"left:519px;top:792px;font-size:12.3px;max-width:180px\">是复杂的，党内存在的思想不纯、组织</span><span class=\"bl\" style=\"left:77px;top:798px;font-size:13.9px;max-width:295px\">②以党的政治建设为统领，以坚定理想信念宗旨为根基。</span><span class=\"bl\" style=\"left:520px;top:811px;font-size:12.3px;max-width:179px\">不纯、作风不纯等突出问题尚未得到根</span><span class=\"bl\" style=\"left:76px;top:819px;font-size:13.9px;max-width:261px\">③以调动全党积极性、主动性、创造性为着力点。</span><span class=\"bl\" style=\"left:519px;top:828px;font-size:12.8px;max-width:44px\">本解决。</span><span class=\"bl\" style=\"left:77px;top:839px;font-size:14.5px;max-width:422px\">④以全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制</span><span class=\"bl\" style=\"left:508px;top:846px;font-size:13.9px;max-width:192px\">2.党面临的执政考验、改革开放考验、市</span><span class=\"bl\" style=\"left:53px;top:859px;font-size:15.6px;max-width:342px\">度建设贯穿其中，深人推进反腐败斗争，不断提高党的建设质量。</span><span class=\"bl\" style=\"left:520px;top:864px;font-size:12.3px;max-width:179px\">场经济考验、外部环境考验具有长期性</span><span class=\"bl\" style=\"left:76px;top:881px;font-size:14.5px;max-width:274px\">2.总要求是指导新时代党的建设的总纲领和总遵循。</span><span class=\"bl\" style=\"left:520px;top:881px;font-size:13.9px;max-width:109px\">和复杂性。（四大考验）</span><span class=\"bl\" style=\"left:76px;top:900px;font-size:17.3px;max-width:377px\">①明确新时代党的建设的目的（根本原则）：坚持和加强党的全面领导。</span><span class=\"bl\" style=\"left:509px;top:898px;font-size:15.1px;max-width:192px\">3.党面临的精神解怠危险、能力不足危</span><span class=\"bl\" style=\"left:519px;top:917px;font-size:15.1px;max-width:181px\">险、脱离群众危险、消极腐败危险具有</span><span class=\"bl\" style=\"left:77px;top:922px;font-size:15.6px;max-width:355px\">②明确新时代党的建设的根本方针：坚持党要管党，全面从严治党。</span><span class=\"bl\" style=\"left:520px;top:936px;font-size:13.9px;max-width:139px\">尖锐性和严峻性。（四种危险）</span><span class=\"bl\" style=\"left:76px;top:943px;font-size:15.6px;max-width:350px\">“全面”是基础：管党治党对象全覆盖、领域全范围，责任全担负。</span><span class=\"bl\" style=\"left:77px;top:964px;font-size:15.6px;max-width:255px\">“严”是关键：真管真严，敢管敢严，长管长严。</span><span class=\"bl\" style=\"left:77px;top:985px;font-size:14.5px;max-width:79px\">“治”是要害。</span><span class=\"bl\" style=\"left:77px;top:1005px;font-size:15.6px;max-width:422px\">③明确新时代党的建设的工作主线：加强党的长期执政能力建设、先进性和纯洁</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 77 页</div><div class=\"sidebox\" style=\"left:519px;top:297px;width:195px;height:250px\"></div><span class=\"bl\" style=\"left:68px;top:106px;font-size:14.5px;max-width:49px\">性建设。</span><span class=\"bl\" style=\"left:93px;top:126px;font-size:17.3px;max-width:421px\">④明确新时代党的建设的总体布局：以党的政治建设为统领，全面推进党的政治</span><span class=\"bl\" style=\"left:68px;top:147px;font-size:16.7px;max-width:447px\">建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进</span><span class=\"bl\" style=\"left:69px;top:169px;font-size:13.9px;max-width:74px\">反腐败斗争。</span><span class=\"bl\" style=\"left:93px;top:189px;font-size:17.3px;max-width:422px\">5明确新时代党的建设的目标：把党建设成为始终走在时代前列、人民衷心拥</span><span class=\"bl\" style=\"left:68px;top:210px;font-size:16.7px;max-width:391px\">护、勇于自我革命、经得起各种风浪考验、朝气蓬勃的马克思主义执政党。</span><span class=\"bl b\" style=\"left:68px;top:238px;font-size:15.6px;max-width:312px\">58.3把全面从严治党引1向深入（高频选择题）（2018-25）</span><span class=\"bl\" style=\"left:91px;top:259px;font-size:15.6px;max-width:423px\">1.把党的政治建设摆在首位。党的十九大首次把党的政治建设纳入党的建设总体</span><span class=\"bl\" style=\"left:68px;top:280px;font-size:15.6px;max-width:446px\">布局，并强调“以党的政治建设为统领”“把党的政治建设摆在首位”，凸显党的政</span><span class=\"bl\" style=\"left:68px;top:302px;font-size:15.1px;max-width:320px\">治建设的极端重要性，这是党的建设理论和实践的重大创新。</span><span class=\"bl\" style=\"left:465px;top:304px;font-size:14.5px;max-width:48px\">&gt;拓展1</span><span class=\"bl\" style=\"left:537px;top:303px;font-size:15.1px;max-width:92px\">火星姐姐考点拓展1</span><span class=\"bl\" style=\"left:93px;top:322px;font-size:15.6px;max-width:318px\">1旗帜鲜明讲政治是我们党作为马克思主义政党的根本要求。</span><span class=\"bl\" style=\"left:525px;top:326px;font-size:13.9px;max-width:124px\">党的政治建设的基本内容：</span><span class=\"bl\" style=\"left:93px;top:343px;font-size:15.1px;max-width:331px\">2党的政治建设是党的根本性建设，决定党的建设方向和效果。</span><span class=\"bl\" style=\"left:525px;top:343px;font-size:14.5px;max-width:191px\">①保证全党服从中央，坚持党中央权成</span><span class=\"bl\" style=\"left:92px;top:364px;font-size:15.1px;max-width:352px\">③注重抓党的政治建设是党的十八大以来全面从严治党的成功经验</span><span class=\"bl\" style=\"left:526px;top:363px;font-size:12.3px;max-width:189px\">和集中统一领导，是党的政治建设的首</span><span class=\"bl\" style=\"left:92px;top:387px;font-size:12.3px;max-width:119px\">2.加强党的思想建设。</span><span class=\"bl\" style=\"left:526px;top:382px;font-size:12.3px;max-width:44px\">要任务。</span><span class=\"bl\" style=\"left:526px;top:399px;font-size:12.3px;max-width:189px\">②要尊崇党章，严格执行新形势下党内</span><span class=\"bl\" style=\"left:93px;top:407px;font-size:13.9px;max-width:154px\">思想建设是党的基础性建设。</span><span class=\"bl\" style=\"left:526px;top:418px;font-size:12.3px;max-width:189px\">政治生活若干准则，增强党内政治生活的</span><span class=\"bl\" style=\"left:92px;top:427px;font-size:15.6px;max-width:201px\">思想建设的首要任务：坚定理想信念。</span><span class=\"bl\" style=\"left:526px;top:436px;font-size:12.3px;max-width:189px\">政治性、时代性、原则性、战斗性，自觉</span><span class=\"bl\" style=\"left:92px;top:449px;font-size:13.9px;max-width:121px\">3.加强党的组织建设。</span><span class=\"bl\" style=\"left:525px;top:453px;font-size:14.5px;max-width:177px\">抵制商品交换原则对党内生活的侵蚀。</span><span class=\"bl\" style=\"left:93px;top:470px;font-size:13.9px;max-width:399px\">包括：民主集中制建设、党的基层组织建设、干部队伍建设、党员队伍建设。</span><span class=\"bl\" style=\"left:526px;top:472px;font-size:12.3px;max-width:190px\">③完善和落实民主集中制的各项制度，</span><span class=\"bl\" style=\"left:91px;top:491px;font-size:13.9px;max-width:127px\">4.加强党的作风建设。</span><span class=\"bl\" style=\"left:209px;top:488px;font-size:39.0px;max-width:270px\">众号：</span><span class=\"bl\" style=\"left:526px;top:491px;font-size:12.3px;max-width:189px\">坚持民主基础上的集中和集中指导下的</span><span class=\"bl\" style=\"left:93px;top:512px;font-size:12.3px;max-width:128px\">党的作风就是党的形象。</span><span class=\"bl\" style=\"left:526px;top:510px;font-size:12.3px;max-width:189px\">民主相结合，既充分发扬民主，又善于</span><span class=\"bl\" style=\"left:525px;top:526px;font-size:16.7px;max-width:54px\">集中统一。</span><span class=\"bl\" style=\"left:91px;top:532px;font-size:17.3px;max-width:264px\">作风建设的核心是保持党同人民群众的血肉联系。</span><span class=\"bl\" style=\"left:92px;top:553px;font-size:15.1px;max-width:162px\">人民立场是党的根本政治立场</span><span class=\"bl\" style=\"left:93px;top:575px;font-size:12.3px;max-width:318px\">党风问题、党同人民群众联系问题是关系党生死存亡的问题。</span><span class=\"bl\" style=\"left:91px;top:595px;font-size:13.9px;max-width:85px\">5.强纪律建设。</span><span class=\"bl\" style=\"left:93px;top:616px;font-size:13.9px;max-width:225px\">加强纪律建设是全面从严治党的治本之策。</span><span class=\"bl\" style=\"left:92px;top:637px;font-size:13.9px;max-width:202px\">纪律严明是党的光荣传统和独特优势。</span><span class=\"bl\" style=\"left:92px;top:658px;font-size:15.1px;max-width:422px\">严明党的纪律，要严明政治纪律，要增强纪律教育针对性，要深化运用监督执纪</span><span class=\"bl\" style=\"left:69px;top:679px;font-size:13.9px;max-width:74px\">“四种形态”。</span><span class=\"bl\" style=\"left:91px;top:699px;font-size:14.5px;max-width:201px\">6.将制度建设贯穿党的各项建设之中。</span><span class=\"bl\" style=\"left:92px;top:720px;font-size:15.1px;max-width:414px\">制度建设是全面从严治党的重要保障，是全面从严治党的长远之策、根本之策。</span><span class=\"bl\" style=\"left:92px;top:742px;font-size:13.9px;max-width:191px\">7.巩固发展反腐败斗争压倒性胜利。</span><span class=\"bl\" style=\"left:92px;top:762px;font-size:14.5px;max-width:260px\">廉政建设和反腐败斗争，是从严治党的重中之重。</span><span class=\"bl\" style=\"left:93px;top:784px;font-size:12.3px;max-width:305px\">人民群众最痛恨腐败现象，腐败是我们党面临的最大威胁。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 78 页</div><span class=\"bl\" style=\"left:461px;top:60px;font-size:15.6px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:56px;top:108px;font-size:17.8px;max-width:102px\">■经典真题回顾</span><span class=\"bl\" style=\"left:58px;top:133px;font-size:17.8px;max-width:445px\">1.【2020.24】消除贫困，改善民生，逐步实现共同富裕，是社会主义的本质要求，</span><span class=\"bl\" style=\"left:75px;top:155px;font-size:17.3px;max-width:429px\">是我们党的重要使命，新中国成立70年来，已有7亿多人摆脱贫困，占全球减贫</span><span class=\"bl\" style=\"left:75px;top:176px;font-size:16.7px;max-width:429px\">人口的70%以上，中国是第一个完成联合国千年发展目标中减贫目标的发展中国</span><span class=\"bl\" style=\"left:75px;top:196px;font-size:17.3px;max-width:429px\">家，也是唯一个实现了经济较快增长与大规模减贫同步、综合国力增强与人民生</span><span class=\"bl\" style=\"left:75px;top:217px;font-size:17.3px;max-width:430px\">活水平提高同步这一历史性跨越的发展中国家。进人新时代，为了确保到2020年</span><span class=\"bl\" style=\"left:75px;top:238px;font-size:16.7px;max-width:429px\">现行标准下农村贫困人口实现脱贫、贫困县全部摘帽的目标，我国采取的重要举</span><span class=\"bl\" style=\"left:74px;top:261px;font-size:15.0px;max-width:34px\">措是</span><span class=\"bl\" style=\"left:75px;top:282px;font-size:15.0px;max-width:151px\">A.坚持精准扶贫、精准脱贫</span><span class=\"bl\" style=\"left:75px;top:302px;font-size:15.0px;max-width:186px\">B.强化党政一把手负总责的责任制</span><span class=\"bl\" style=\"left:76px;top:323px;font-size:13.9px;max-width:161px\">C.注重扶贫同扶志扶智相结合</span><span class=\"bl\" style=\"left:76px;top:345px;font-size:13.9px;max-width:186px\">D.重点攻克深度贫困地区脱贫任务</span><span class=\"bl\" style=\"left:59px;top:379px;font-size:14.5px;max-width:446px\">2.【2011.24】改革、发展、稳定好比现代化建设棋盘上的三招紧密关联的战略性棋</span><span class=\"bl\" style=\"left:76px;top:400px;font-size:14.5px;max-width:429px\">子，每一招棋都下好了，相互促进，就会全局皆活；如果有一招下不好，其他两</span><span class=\"bl\" style=\"left:75px;top:421px;font-size:15.0px;max-width:430px\">招也会陷入困境，就可能全局受挫。改革开放以来，党在处理改革、发展、稳定</span><span class=\"bl\" style=\"left:77px;top:443px;font-size:13.9px;max-width:196px\">关系方面积累的经验和主要原则包括</span><span class=\"bl\" style=\"left:76px;top:463px;font-size:14.5px;max-width:305px\">A.保持改革、发展、稳定在动态中的相互协调和相互促进</span><span class=\"bl\" style=\"left:75px;top:484px;font-size:13.9px;max-width:283px\">B.把实现社会稳定作为促进改革、发展的根本出发点</span><span class=\"bl\" style=\"left:75px;top:503px;font-size:17.8px;max-width:330px\">C.把改革的力度、发展的速度和社会可以承受的程度统一起来</span><span class=\"bl\" style=\"left:76px;top:525px;font-size:15.0px;max-width:365px\">D.把不断改善人民生活作为处理改革、发展、稳定关系的重要结合点</span><span class=\"bl\" style=\"left:60px;top:562px;font-size:13.9px;max-width:445px\">3.【2019.24】国家治理体系是在党领导下管理国家的制度体系，是一整套紧密相连、</span><span class=\"bl\" style=\"left:76px;top:582px;font-size:15.0px;max-width:429px\">相互协调的国家制度；国家治理能力则是运用国家制度管理社会各方面事务的能</span><span class=\"bl\" style=\"left:77px;top:604px;font-size:13.9px;max-width:149px\">力。二者的关系主要表现为</span><span class=\"bl\" style=\"left:77px;top:625px;font-size:13.9px;max-width:293px\">A.提高国家治理能力可以充分发挥国家治理体系的效能</span><span class=\"bl\" style=\"left:76px;top:646px;font-size:13.9px;max-width:233px\">B.好的国家治理体系可以提高国家治理能力</span><span class=\"bl\" style=\"left:76px;top:666px;font-size:14.5px;max-width:269px\">C.国家治理体系和治理能力是相辅相成的有机整体</span><span class=\"bl\" style=\"left:77px;top:689px;font-size:12.3px;max-width:256px\">D.国家治理体系越完备国家治理能力就一定越强</span><span class=\"bl\" style=\"left:60px;top:722px;font-size:15.0px;max-width:446px\">4.【2019.7】高度重视和不断加强党的自身建设，是中国共产党从小到大、由弱到</span><span class=\"bl\" style=\"left:76px;top:744px;font-size:15.0px;max-width:429px\">强，从挫折中奋起，在战胜困难中不断成熟的一大法宝，也是党领导的伟大事业</span><span class=\"bl\" style=\"left:77px;top:764px;font-size:14.5px;max-width:429px\">不断取得胜利的根本保证。中国特色社会主义进入新时代，党的建设的根本方针是</span><span class=\"bl\" style=\"left:77px;top:808px;font-size:13.9px;max-width:140px\">A.全面加强党的执政本领</span><span class=\"bl\" style=\"left:77px;top:828px;font-size:13.9px;max-width:174px\">B.坚持党要管党、全面从严治党</span><span class=\"bl\" style=\"left:77px;top:849px;font-size:13.9px;max-width:150px\">C.坚持解放思想、改革创新</span><span class=\"bl\" style=\"left:77px;top:869px;font-size:13.9px;max-width:139px\">D.全面推进党的政治建设</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1096px\"><div class=\"bxnum\">第 79 页</div><span class=\"bl b acc\" style=\"left:344px;top:112px;font-size:25.1px;max-width:83px\">第十二章</span><span class=\"bl\" style=\"left:244px;top:161px;font-size:23.4px;max-width:282px\">实现中华民族伟大复兴的重要保障</span><span class=\"bl\" style=\"left:60px;top:210px;font-size:19.5px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:385px;top:254px;font-size:17.3px;max-width:156px\">考点59坚持总体国家安全观</span><span class=\"bl\" style=\"left:151px;top:274px;font-size:15.6px;max-width:185px\">实现中华民族伟大复兴的重要保障</span><span class=\"bl b hl\" style=\"left:385px;top:275px;font-size:17.3px;max-width:169px\">考点60加快国防和军队现代化</span><span class=\"bl b hl\" style=\"left:385px;top:295px;font-size:18.4px;max-width:227px\">考点61坚持“一国两制”，推进祖国统一</span><span class=\"bl\" style=\"left:60px;top:346px;font-size:18.4px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:84px;top:373px;font-size:18.4px;max-width:624px\">本章主要阐述了实现中华民族伟大复兴的重要保障的相关内容。本章是本门科目中考频一般的章节，考试形式一般为选</span><span class=\"bl\" style=\"left:60px;top:395px;font-size:17.8px;max-width:647px\">择题。考生在复习过程中，要重点掌握总体国家安全观的内容，习近平强军思想的内涵、主要内容，党的十九大对全面推进</span><span class=\"bl b hl\" style=\"left:71px;top:468px;font-size:18.9px;max-width:75px\">考点59</span><span class=\"bl\" style=\"left:134px;top:470px;font-size:16.7px;max-width:184px\">坚持总体国家安全观☆☆☆</span><span class=\"bl\" style=\"left:666px;top:471px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:60px;top:505px;font-size:16.7px;max-width:278px\">59.1国家安全是安邦定国的重要基石（高频选择题</span><span class=\"bl b\" style=\"left:83px;top:525px;font-size:17.8px;max-width:145px\">1.总体国家安全观的提出：</span><span class=\"bl\" style=\"left:85px;top:546px;font-size:17.8px;max-width:422px\">①国家安全是安邦定国的重要基石，是人民幸福安康的基本要求，维护国家安全</span><span class=\"bl\" style=\"left:61px;top:568px;font-size:13.9px;max-width:165px\">是全国各族人民根本利益所在。</span><span class=\"bl\" style=\"left:84px;top:588px;font-size:17.8px;max-width:423px\">②党的十八大以来，以习近平同志为核心的党中央创新国家安全理念，统揽国家</span><span class=\"bl\" style=\"left:60px;top:609px;font-size:15.6px;max-width:446px\">安全全局，创造性提出总体国家安全观，科学回答了中国这样一个发展中的社会主义</span><span class=\"bl\" style=\"left:60px;top:630px;font-size:17.3px;max-width:446px\">大国如何维护和塑造国家安全的一系列基本问题，把我们党对国家安全的认识提升到</span><span class=\"bl\" style=\"left:60px;top:651px;font-size:17.3px;max-width:447px\">了新的高度和境界，为破解我国国家安全面临的难题、推进新时代国家安全工作提供</span><span class=\"bl\" style=\"left:60px;top:672px;font-size:14.5px;max-width:75px\">了基本遵循。</span><span class=\"bl b\" style=\"left:83px;top:692px;font-size:18.9px;max-width:381px\">2.总体国家安全观的特点：关键在“总体”，突出的是“大安全”理念。</span><span class=\"bl b\" style=\"left:83px;top:713px;font-size:16.7px;max-width:157px\">3.坚持总体国家安全的意义：</span><span class=\"bl\" style=\"left:84px;top:735px;font-size:15.0px;max-width:307px\">①适应了进行具有许多新的历史特点的伟大斗争的新要求。</span><span class=\"bl\" style=\"left:84px;top:755px;font-size:17.3px;max-width:191px\">②回应了人民对国家安全的新期待。</span><span class=\"bl\" style=\"left:83px;top:776px;font-size:16.7px;max-width:180px\">③顺应了世界发展变化的新趋势。</span><span class=\"bl b\" style=\"left:59px;top:803px;font-size:17.8px;max-width:278px\">59.2坚持走中国特色国家安全道路（高频选择题）</span><span class=\"bl b\" style=\"left:82px;top:825px;font-size:17.3px;max-width:134px\">1.总体国家安全的内容：</span><span class=\"bl\" style=\"left:83px;top:845px;font-size:17.8px;max-width:214px\">①总体国家安全观的根本是：政治安全。</span><span class=\"bl\" style=\"left:84px;top:867px;font-size:15.6px;max-width:278px\">②总体国家安全观的宗旨是：人民安全。（2019一6）</span><span class=\"bl\" style=\"left:83px;top:887px;font-size:17.3px;max-width:214px\">③总体国家安全观的基础是：经济安全。</span><span class=\"bl\" style=\"left:83px;top:907px;font-size:17.8px;max-width:284px\">④总体国家安全观的保障是：军事、文化、社会安全。</span><span class=\"bl\" style=\"left:83px;top:928px;font-size:17.3px;max-width:238px\">③总体国家安全观的依托是：促进国际安全。</span><span class=\"bl\" style=\"left:82px;top:949px;font-size:17.8px;max-width:203px\">总体国家安全观坚持国家利益至上。</span><span class=\"bl\" style=\"left:81px;top:970px;font-size:17.3px;max-width:175px\">2.如何走中国特色国家安全道路</span><span class=\"bl\" style=\"left:82px;top:990px;font-size:18.9px;max-width:422px\">①坚持统筹发展和安全两件大事。安全和发展是一体之两翼、驱动之双轮。发展</span></div></div>"}],pages:[71,79]};
  D["mzt_s13"] = {id:"mzt_s13",ch:"毛中特讲义 · 第十二章 实现中华民族伟大复兴的重要保障",title:"第十二章 实现中华民族伟大复兴的重要保障",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1096px\"><div class=\"bxnum\">第 79 页</div><span class=\"bl b acc\" style=\"left:344px;top:112px;font-size:25.1px;max-width:83px\">第十二章</span><span class=\"bl\" style=\"left:244px;top:161px;font-size:23.4px;max-width:282px\">实现中华民族伟大复兴的重要保障</span><span class=\"bl\" style=\"left:60px;top:210px;font-size:19.5px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:385px;top:254px;font-size:17.3px;max-width:156px\">考点59坚持总体国家安全观</span><span class=\"bl\" style=\"left:151px;top:274px;font-size:15.6px;max-width:185px\">实现中华民族伟大复兴的重要保障</span><span class=\"bl b hl\" style=\"left:385px;top:275px;font-size:17.3px;max-width:169px\">考点60加快国防和军队现代化</span><span class=\"bl b hl\" style=\"left:385px;top:295px;font-size:18.4px;max-width:227px\">考点61坚持“一国两制”，推进祖国统一</span><span class=\"bl\" style=\"left:60px;top:346px;font-size:18.4px;max-width:101px\">■考点考情分析</span><span class=\"bl\" style=\"left:84px;top:373px;font-size:18.4px;max-width:624px\">本章主要阐述了实现中华民族伟大复兴的重要保障的相关内容。本章是本门科目中考频一般的章节，考试形式一般为选</span><span class=\"bl\" style=\"left:60px;top:395px;font-size:17.8px;max-width:647px\">择题。考生在复习过程中，要重点掌握总体国家安全观的内容，习近平强军思想的内涵、主要内容，党的十九大对全面推进</span><span class=\"bl b hl\" style=\"left:71px;top:468px;font-size:18.9px;max-width:75px\">考点59</span><span class=\"bl\" style=\"left:134px;top:470px;font-size:16.7px;max-width:184px\">坚持总体国家安全观☆☆☆</span><span class=\"bl\" style=\"left:666px;top:471px;font-size:15.0px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:60px;top:505px;font-size:16.7px;max-width:278px\">59.1国家安全是安邦定国的重要基石（高频选择题</span><span class=\"bl b\" style=\"left:83px;top:525px;font-size:17.8px;max-width:145px\">1.总体国家安全观的提出：</span><span class=\"bl\" style=\"left:85px;top:546px;font-size:17.8px;max-width:422px\">①国家安全是安邦定国的重要基石，是人民幸福安康的基本要求，维护国家安全</span><span class=\"bl\" style=\"left:61px;top:568px;font-size:13.9px;max-width:165px\">是全国各族人民根本利益所在。</span><span class=\"bl\" style=\"left:84px;top:588px;font-size:17.8px;max-width:423px\">②党的十八大以来，以习近平同志为核心的党中央创新国家安全理念，统揽国家</span><span class=\"bl\" style=\"left:60px;top:609px;font-size:15.6px;max-width:446px\">安全全局，创造性提出总体国家安全观，科学回答了中国这样一个发展中的社会主义</span><span class=\"bl\" style=\"left:60px;top:630px;font-size:17.3px;max-width:446px\">大国如何维护和塑造国家安全的一系列基本问题，把我们党对国家安全的认识提升到</span><span class=\"bl\" style=\"left:60px;top:651px;font-size:17.3px;max-width:447px\">了新的高度和境界，为破解我国国家安全面临的难题、推进新时代国家安全工作提供</span><span class=\"bl\" style=\"left:60px;top:672px;font-size:14.5px;max-width:75px\">了基本遵循。</span><span class=\"bl b\" style=\"left:83px;top:692px;font-size:18.9px;max-width:381px\">2.总体国家安全观的特点：关键在“总体”，突出的是“大安全”理念。</span><span class=\"bl b\" style=\"left:83px;top:713px;font-size:16.7px;max-width:157px\">3.坚持总体国家安全的意义：</span><span class=\"bl\" style=\"left:84px;top:735px;font-size:15.0px;max-width:307px\">①适应了进行具有许多新的历史特点的伟大斗争的新要求。</span><span class=\"bl\" style=\"left:84px;top:755px;font-size:17.3px;max-width:191px\">②回应了人民对国家安全的新期待。</span><span class=\"bl\" style=\"left:83px;top:776px;font-size:16.7px;max-width:180px\">③顺应了世界发展变化的新趋势。</span><span class=\"bl b\" style=\"left:59px;top:803px;font-size:17.8px;max-width:278px\">59.2坚持走中国特色国家安全道路（高频选择题）</span><span class=\"bl b\" style=\"left:82px;top:825px;font-size:17.3px;max-width:134px\">1.总体国家安全的内容：</span><span class=\"bl\" style=\"left:83px;top:845px;font-size:17.8px;max-width:214px\">①总体国家安全观的根本是：政治安全。</span><span class=\"bl\" style=\"left:84px;top:867px;font-size:15.6px;max-width:278px\">②总体国家安全观的宗旨是：人民安全。（2019一6）</span><span class=\"bl\" style=\"left:83px;top:887px;font-size:17.3px;max-width:214px\">③总体国家安全观的基础是：经济安全。</span><span class=\"bl\" style=\"left:83px;top:907px;font-size:17.8px;max-width:284px\">④总体国家安全观的保障是：军事、文化、社会安全。</span><span class=\"bl\" style=\"left:83px;top:928px;font-size:17.3px;max-width:238px\">③总体国家安全观的依托是：促进国际安全。</span><span class=\"bl\" style=\"left:82px;top:949px;font-size:17.8px;max-width:203px\">总体国家安全观坚持国家利益至上。</span><span class=\"bl\" style=\"left:81px;top:970px;font-size:17.3px;max-width:175px\">2.如何走中国特色国家安全道路</span><span class=\"bl\" style=\"left:82px;top:990px;font-size:18.9px;max-width:422px\">①坚持统筹发展和安全两件大事。安全和发展是一体之两翼、驱动之双轮。发展</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 80 页</div><span class=\"bl\" style=\"left:455px;top:62px;font-size:14.5px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:51px;top:110px;font-size:14.0px;max-width:189px\">是安全的基础，安全是发展的保障。</span><span class=\"bl\" style=\"left:75px;top:131px;font-size:14.0px;max-width:283px\">②坚持人民安全、政治安全、国家利益至上有机统一。</span><span class=\"bl\" style=\"left:75px;top:151px;font-size:15.1px;max-width:422px\">③坚持维护和塑造国家安全。新时代国家安全，既要解决好大国发展进程中面临</span><span class=\"bl\" style=\"left:51px;top:171px;font-size:15.1px;max-width:414px\">的安全共性问题，更要处理好中华民族伟大复兴关键阶段面临的特殊安全问题。</span><span class=\"bl\" style=\"left:75px;top:194px;font-size:12.3px;max-width:154px\">④坚持科学统筹的根本方法。</span><span class=\"bl\" style=\"left:75px;top:214px;font-size:14.5px;max-width:422px\">5坚持党对国家安全工作的绝对领导，是做好国家安全工作的根本原则，是维护</span><span class=\"bl\" style=\"left:51px;top:235px;font-size:14.5px;max-width:447px\">国家安全和社会安定的根本保证。要求始终把国家安全置于中国特色社会主义事业全</span><span class=\"bl\" style=\"left:52px;top:257px;font-size:12.3px;max-width:307px\">局中来把握，充分调动各方面积极性，形成国家安全合力。</span><span class=\"bl b\" style=\"left:50px;top:283px;font-size:15.6px;max-width:242px\">59.3着力防范化解重大风险（中频选择题）</span><span class=\"bl\" style=\"left:75px;top:306px;font-size:12.3px;max-width:366px\">1.当前，我国正处于一个大有可为的战略机遇期，但也面临重大风险。</span><span class=\"bl\" style=\"left:76px;top:327px;font-size:12.3px;max-width:420px\">重大风险既包括国内的经济、政治、意识形态、社会风险以及来自自然界的风</span><span class=\"bl\" style=\"left:50px;top:346px;font-size:15.1px;max-width:447px\">险，也包括国际经济、政治、军事风险等，各种威胁和挑战联动效应明显，各种矛盾</span><span class=\"bl\" style=\"left:51px;top:367px;font-size:15.1px;max-width:296px\">风险挑战源、各类矛盾风险挑战点相互交织、相互作用。</span><span class=\"bl b\" style=\"left:74px;top:389px;font-size:14.0px;max-width:167px\">2.防范化解重大风险的重要性：</span><span class=\"bl\" style=\"left:75px;top:410px;font-size:15.1px;max-width:422px\">如果发生重大风险又扛不住，国家安全就可能面临重大威胁。必须坚持把防范</span><span class=\"bl\" style=\"left:51px;top:430px;font-size:15.6px;max-width:446px\">化解国家安全风险摆在突出位置，力争把可能带来重大风险的隐患发现和处置于萌</span><span class=\"bl\" style=\"left:51px;top:452px;font-size:12.8px;max-width:49px\">芽状态。</span><span class=\"bl b\" style=\"left:74px;top:474px;font-size:12.3px;max-width:143px\">3.怎样防范化解重大风险：</span><span class=\"bl\" style=\"left:74px;top:493px;font-size:15.1px;max-width:388px\">1预判风险所在是防范风险的前提，把握风险走向是谋求战略主动的关键</span><span class=\"bl\" style=\"left:74px;top:514px;font-size:15.6px;max-width:423px\">要加强战略预判和风险预警，提高风险化解能力，完善风险防控机制，建立健全</span><span class=\"bl\" style=\"left:50px;top:535px;font-size:15.1px;max-width:401px\">风险研判机制、决策风险评估机制、风险防控协同机制、风险防控责任机制</span><span class=\"bl\" style=\"left:73px;top:551px;font-size:28.5px;max-width:292px\">②坚持立足于防，又有效处置风险。个儿八</span><span class=\"bl\" style=\"left:74px;top:577px;font-size:15.1px;max-width:422px\">我们必须始终保持高度警惕。既要警惕“黑天鹅”事件，也要防范“灰犀牛”事</span><span class=\"bl\" style=\"left:50px;top:598px;font-size:15.1px;max-width:447px\">件；既要有防范风险的先手，也要有应对和化解风险挑战的高招；既要打好防范和抵</span><span class=\"bl\" style=\"left:49px;top:618px;font-size:17.3px;max-width:357px\">御风险的有准备之战，也要打好化险为夷、转危为机的战略主动战。</span><span class=\"bl b hl\" style=\"left:59px;top:658px;font-size:19.5px;max-width:262px\">考点60 加快国防和军队现代化☆☆☆</span><span class=\"bl b\" style=\"left:50px;top:694px;font-size:15.6px;max-width:122px\">60.1习近平强军思想</span><span class=\"bl\" style=\"left:73px;top:717px;font-size:14.0px;max-width:164px\">1.习近平强军思想的丰富内涵。</span><span class=\"bl\" style=\"left:74px;top:738px;font-size:14.5px;max-width:421px\">习近平强军思想深刻回答了“新时代建设一支什么样的强大人民军队，怎样建设</span><span class=\"bl\" style=\"left:50px;top:759px;font-size:14.0px;max-width:149px\">强大人民军队”的时代课题</span><span class=\"bl b\" style=\"left:73px;top:780px;font-size:14.5px;max-width:168px\">2.习近平强军思想的主要内容：</span><span class=\"bl\" style=\"left:74px;top:801px;font-size:14.5px;max-width:423px\">①强国必须强军。巩固国防和强大人民军队是新时代坚持和发展中国特色社会主</span><span class=\"bl\" style=\"left:51px;top:822px;font-size:13.4px;max-width:213px\">义、实现中华民族伟大复兴的战略支撑。</span><span class=\"bl\" style=\"left:74px;top:844px;font-size:12.3px;max-width:422px\">②党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军</span><span class=\"bl\" style=\"left:51px;top:864px;font-size:14.0px;max-width:189px\">队，必须同国家现代化进程相一致。</span><span class=\"bl\" style=\"left:74px;top:885px;font-size:14.0px;max-width:246px\">A.听党指挥是灵魂，决定军队建设的政治方向</span><span class=\"bl\" style=\"left:74px;top:905px;font-size:14.0px;max-width:339px\">B.能打胜仗是核心，反映军队的根本职能和军队建设的根本指向</span><span class=\"bl\" style=\"left:74px;top:926px;font-size:14.0px;max-width:422px\">C.作风优良是保证，关系军队的性质、宗旨、本色，是我军的鲜明特色和政治</span><span class=\"bl\" style=\"left:49px;top:946px;font-size:15.1px;max-width:32px\">优势</span><span class=\"bl\" style=\"left:74px;top:967px;font-size:14.5px;max-width:320px\">③明确党对军队绝对领导，是人民军队建军之本、强军之魂。</span><span class=\"bl\" style=\"left:75px;top:989px;font-size:12.3px;max-width:417px\">④明确军队是要准备打仗的，必须聚焦能打仗、打胜仗，创新发展军事战略指导。</span><span class=\"bl\" style=\"left:74px;top:1008px;font-size:15.1px;max-width:423px\">5明确作风优良是我军鲜明特色和政治优势，必须加强作风建设、纪律建设，坚</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 81 页</div><div class=\"sidebox\" style=\"left:521px;top:802px;width:195px;height:82px\"></div><span class=\"bl\" style=\"left:69px;top:108px;font-size:15.6px;max-width:447px\">定不移正风肃纪、反腐惩恶，大力弘扬我党我军光荣传统和优良作风，永葆人民军队</span><span class=\"bl\" style=\"left:70px;top:130px;font-size:14.0px;max-width:108px\">性质、宗旨、本色。</span><span class=\"bl\" style=\"left:94px;top:150px;font-size:16.7px;max-width:422px\">6明确推进强军事业必须坚持政治建军、改革强军、科技强军、人才强军、依法</span><span class=\"bl\" style=\"left:70px;top:172px;font-size:12.8px;max-width:37px\">治军。</span><span class=\"bl\" style=\"left:94px;top:192px;font-size:16.7px;max-width:422px\">7明确改革是强军的必由之路，必须推进军队组织形态现代化，构建中国特色现</span><span class=\"bl\" style=\"left:70px;top:213px;font-size:15.1px;max-width:272px\">代军事力量体系，完善中国特色社会主义军事制度。</span><span class=\"bl\" style=\"left:94px;top:234px;font-size:15.6px;max-width:422px\">8明确创新是引领发展的第一动力，必须坚持向科技创新要战斗力，统筹推进军</span><span class=\"bl\" style=\"left:70px;top:254px;font-size:15.6px;max-width:380px\">事理论、技术、组织、管理、文化等各方面创新，建设创新型人民军队。</span><span class=\"bl\" style=\"left:94px;top:276px;font-size:16.7px;max-width:421px\">9明确现代化军队必须构建中国特色军事法治体系，推进治军方式根本性转变，</span><span class=\"bl\" style=\"left:69px;top:297px;font-size:14.5px;max-width:179px\">提高国防和军队建设法治化水平。</span><span class=\"bl\" style=\"left:94px;top:318px;font-size:15.1px;max-width:422px\">①明确军民融合发展是兴国之举、强军之策，必须坚持发展和安全兼顾、富国和</span><span class=\"bl\" style=\"left:69px;top:340px;font-size:14.5px;max-width:448px\">强军统一，形成全要素、多领域、高效益军民融合深度发展格局，构建一体化的国家</span><span class=\"bl\" style=\"left:70px;top:361px;font-size:14.0px;max-width:96px\">战略体系和能力。</span><span class=\"bl b\" style=\"left:93px;top:382px;font-size:14.0px;max-width:144px\">4.习近平强军思想的意义：</span><span class=\"bl\" style=\"left:94px;top:403px;font-size:14.0px;max-width:422px\">①从理论上讲，是习近平新时代中国特色社会主义思想的重要组成部分（军事</span><span class=\"bl\" style=\"left:70px;top:424px;font-size:14.5px;max-width:446px\">篇），开拓了马克思主义军事理论和当代中国军事实践发展新境界，标志着党军事指</span><span class=\"bl\" style=\"left:70px;top:445px;font-size:14.0px;max-width:108px\">导理论的与时俱进。</span><span class=\"bl\" style=\"left:95px;top:465px;font-size:14.0px;max-width:422px\">②从实践上讲，指导人民军队重振政治纲纪、重塑组织形态、重整斗争格局、重</span><span class=\"bl\" style=\"left:70px;top:487px;font-size:14.0px;max-width:445px\">构建设布局、重树作风形象，在中国特色强军之路上迈出了坚定步伐，强军事业取得</span><span class=\"bl\" style=\"left:73px;top:508px;font-size:14.0px;max-width:217px\">了历史性成就，发生了历史性变革。一</span><span class=\"bl\" style=\"left:94px;top:529px;font-size:14.0px;max-width:422px\">③从未来上讲，为我军实现强军目标、迈向世界一流提供了科学指南和行动纲</span><span class=\"bl\" style=\"left:265px;top:542px;font-size:44.7px;max-width:193px\">祝您上</span><span class=\"bl\" style=\"left:70px;top:550px;font-size:14.0px;max-width:197px\">领，点亮了照耀强军征程的时代灯塔</span><span class=\"bl b\" style=\"left:71px;top:578px;font-size:12.3px;max-width:184px\">60.2实现党在新时代的强军目标</span><span class=\"bl b\" style=\"left:93px;top:599px;font-size:14.0px;max-width:144px\">1.新时代强军目标的内容：</span><span class=\"bl\" style=\"left:95px;top:620px;font-size:14.0px;max-width:422px\">习近平指出，“党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优</span><span class=\"bl\" style=\"left:71px;top:641px;font-size:14.0px;max-width:280px\">良的人民军队，把人民军队建设成为世界一流军队”。</span><span class=\"bl b\" style=\"left:94px;top:663px;font-size:12.3px;max-width:202px\">2.实现党在新时代的强军目标的意义：</span><span class=\"bl\" style=\"left:95px;top:683px;font-size:14.0px;max-width:354px\">①明确了人民军队的样子，指明了加强军队建设的聚焦点和着力点。</span><span class=\"bl\" style=\"left:95px;top:704px;font-size:12.3px;max-width:283px\">②是一项开拓性事业，是一场广泛而深刻的军事变革。</span><span class=\"bl\" style=\"left:95px;top:724px;font-size:14.0px;max-width:142px\">③要增强使命感和责任感。</span><span class=\"bl\" style=\"left:95px;top:747px;font-size:12.3px;max-width:318px\">④切实把强军目标要求贯彻到国防和军队建设各领域全过程。</span><span class=\"bl\" style=\"left:94px;top:767px;font-size:12.3px;max-width:249px\">3.听党指挥是灵魂，决定军队建设的政治方向。</span><span class=\"bl\" style=\"left:94px;top:787px;font-size:14.0px;max-width:422px\">历史告诉我们，坚持党指挥枪、建设自己的人民军队，是党在血与火的斗争中得</span><span class=\"bl\" style=\"left:70px;top:808px;font-size:14.5px;max-width:238px\">出的颠扑不破的真理。党对军队绝对领导是：</span><span class=\"bl\" style=\"left:467px;top:809px;font-size:14.5px;max-width:47px\">&gt;提示1</span><span class=\"bl\" style=\"left:530px;top:808px;font-size:12.3px;max-width:99px\">火星姐姐考点提示1</span><span class=\"bl\" style=\"left:94px;top:830px;font-size:14.5px;max-width:285px\">①军队完全区别于一切旧军队的政治特质和根本优势。</span><span class=\"bl\" style=\"left:527px;top:829px;font-size:14.5px;max-width:191px\">党对军队绝对领导的根本原则和制度：发</span><span class=\"bl\" style=\"left:95px;top:851px;font-size:14.0px;max-width:422px\">②是人民军队永远不能变的军魂、永远不能丢的命根子，任何时候任何情况下都</span><span class=\"bl\" style=\"left:528px;top:849px;font-size:12.3px;max-width:188px\">端于南昌起义，奠基于三湾改编，定型于</span><span class=\"bl\" style=\"left:528px;top:866px;font-size:14.5px;max-width:51px\">古田会议。</span><span class=\"bl\" style=\"left:70px;top:871px;font-size:14.5px;max-width:319px\">似党的旗帜为旗帜、以党的方向为方向、以党的意志为意志。</span><span class=\"bl\" style=\"left:92px;top:892px;font-size:15.1px;max-width:345px\">4.能打胜仗是核心，反映军队的根本职能和军队建设的根本指向。</span><span class=\"bl\" style=\"left:93px;top:912px;font-size:15.1px;max-width:285px\">军队强不强，关键看打仗；战场打不赢，一切等于零。</span><span class=\"bl\" style=\"left:93px;top:933px;font-size:15.6px;max-width:423px\">党和人民对军队的根本要求，是军队使命职责之所在、军队存在的根本价值之所</span><span class=\"bl\" style=\"left:69px;top:953px;font-size:15.6px;max-width:118px\">在：能打仗、打胜仗。</span><span class=\"bl\" style=\"left:92px;top:975px;font-size:15.1px;max-width:274px\">5.作风优良是保证，关系军队的性质、宗旨、本色。</span><span class=\"bl\" style=\"left:93px;top:995px;font-size:15.6px;max-width:422px\">能否保持我党我军的光荣传统和优良作风，关系军队生死存亡，关系党和国家事</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 82 页</div><span class=\"bl\" style=\"left:455px;top:60px;font-size:15.1px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:51px;top:108px;font-size:15.6px;max-width:284px\">业兴衰成败，关系社会主义红色江山会不会改变颜色。</span><span class=\"bl\" style=\"left:74px;top:129px;font-size:15.6px;max-width:261px\">6.实现强军目标，必须同国家现代化进程相一致。</span><span class=\"bl\" style=\"left:75px;top:150px;font-size:15.1px;max-width:403px\">①到2020年，国防和军队建设要基本实现机械化，信息化建设取得重大进展</span><span class=\"bl\" style=\"left:76px;top:172px;font-size:14.0px;max-width:229px\">②到2035年，基本实现国防和军队现代化。</span><span class=\"bl\" style=\"left:75px;top:192px;font-size:15.1px;max-width:290px\">③到21世纪中叶，把人民军队全面建成世界一流军队。</span><span class=\"bl b\" style=\"left:52px;top:221px;font-size:14.0px;max-width:222px\">60.3构建一体化的国家战略体系和能力</span><span class=\"bl b\" style=\"left:74px;top:241px;font-size:15.1px;max-width:251px\">1.构建一体化的国家战略体系和能力的必要性：</span><span class=\"bl\" style=\"left:75px;top:262px;font-size:15.1px;max-width:296px\">①是实现发展和安全兼顾、富国和强军统一的必然选择。</span><span class=\"bl\" style=\"left:75px;top:283px;font-size:15.1px;max-width:391px\">②富国才能强兵，强兵才能卫国，强国往往是经济和军事共同作用的结果。</span><span class=\"bl\" style=\"left:76px;top:304px;font-size:14.0px;max-width:421px\">③经济建设是国防建设的基本依托，只有国家经济实力增强了，国防建设才能有</span><span class=\"bl\" style=\"left:51px;top:325px;font-size:14.5px;max-width:61px\">更大发展。</span><span class=\"bl\" style=\"left:76px;top:346px;font-size:14.0px;max-width:422px\">④国防建设是我国现代化建设的战略任务，只有把国防建设搞上去了，经济建设</span><span class=\"bl\" style=\"left:51px;top:367px;font-size:15.1px;max-width:155px\">才能有更加坚强的安全保障。</span><span class=\"bl\" style=\"left:73px;top:387px;font-size:16.8px;max-width:424px\">2.构建一体化的国家战略体系和能力，是一个系统工程，涉及领域宽、范围广、</span><span class=\"bl\" style=\"left:51px;top:408px;font-size:15.1px;max-width:446px\">内容多。必须加强集中统一领导，努力形成统一领导、军地协调、顺畅高效的组织管</span><span class=\"bl\" style=\"left:49px;top:429px;font-size:16.8px;max-width:51px\">理体系。</span><span class=\"bl\" style=\"left:74px;top:452px;font-size:14.0px;max-width:423px\">3.军政军民团结是实现富国和强军相统一的重要政治保障，是我党我军特有的政</span><span class=\"bl\" style=\"left:50px;top:471px;font-size:15.6px;max-width:46px\">治优势。</span><span class=\"bl\" style=\"left:75px;top:479px;font-size:36.3px;max-width:406px\">微信公个号：dikv66</span><span class=\"bl b hl\" style=\"left:60px;top:509px;font-size:20.7px;max-width:334px\">考点61坚持“一国两制”，推进祖国统一女☆</span><span class=\"bl\" style=\"left:343px;top:535px;font-size:53.1px;max-width:120px\">上</span><span class=\"bl b\" style=\"left:49px;top:544px;font-size:20.1px;max-width:310px\">61.1全面准确贯彻“一国两制”的方针（高频选择题）</span><span class=\"bl b\" style=\"left:75px;top:568px;font-size:15.6px;max-width:153px\">1.“一国两制”方针的提出：</span><span class=\"bl\" style=\"left:75px;top:590px;font-size:15.6px;max-width:339px\">①提出：“一国两制”伟大构想的提出是从解决台湾问题开始的。</span><span class=\"bl\" style=\"left:76px;top:612px;font-size:14.0px;max-width:320px\">②台湾问题：是国内战争遗留下来的问题，属于中国的内政。</span><span class=\"bl\" style=\"left:75px;top:632px;font-size:15.1px;max-width:408px\">③实践：“一国两制”伟大构想在实践中首先运用于解决香港问题、澳门问题。</span><span class=\"bl\" style=\"left:75px;top:653px;font-size:14.0px;max-width:422px\">④香港问题和澳门问题：是历史上殖民主义侵略遗留下来的问题。香港特别行政</span><span class=\"bl\" style=\"left:51px;top:675px;font-size:14.0px;max-width:250px\">区事务是中国的内政，不受任何外部势力干涉。</span><span class=\"bl\" style=\"left:74px;top:696px;font-size:14.0px;max-width:422px\">2.香港、澳门回归祖国以来，“一国两制”实践取得举世公认的成功。事实证明：</span><span class=\"bl\" style=\"left:75px;top:716px;font-size:14.0px;max-width:329px\">①“一国两制”是解决历史遗留的香港、澳门问题的最佳方案。</span><span class=\"bl\" style=\"left:75px;top:738px;font-size:14.0px;max-width:353px\">②“一国两制”是香港、澳门回归后保持长期繁荣稳定的最佳制度。</span><span class=\"bl b\" style=\"left:73px;top:758px;font-size:16.8px;max-width:155px\">3.“一国两制”方针的内容：</span><span class=\"bl\" style=\"left:75px;top:777px;font-size:17.9px;max-width:109px\">①坚持一个中国是：</span><span class=\"bl\" style=\"left:75px;top:801px;font-size:14.0px;max-width:184px\">A.“和平统一、一国两制”的核心</span><span class=\"bl\" style=\"left:75px;top:822px;font-size:14.0px;max-width:222px\">B.是发展两岸关系和实现和平统一的基础</span><span class=\"bl\" style=\"left:75px;top:843px;font-size:14.0px;max-width:363px\">C.体现一个中国原则的“九二共识”明确界定了两岸关系的根本性质</span><span class=\"bl\" style=\"left:75px;top:863px;font-size:14.0px;max-width:188px\">D.是确保两岸关系和平发展的关键</span><span class=\"bl\" style=\"left:75px;top:883px;font-size:16.8px;max-width:73px\">2两制并存：</span><span class=\"bl\" style=\"left:75px;top:904px;font-size:15.1px;max-width:318px\">A.在祖国统一的前提下，国家的主体部分实行社会主义制度</span><span class=\"bl\" style=\"left:75px;top:925px;font-size:14.5px;max-width:365px\">B.同时在台湾、香港、澳门保持原有的社会制度和生活方式长期不变</span><span class=\"bl\" style=\"left:76px;top:947px;font-size:14.0px;max-width:227px\">③“一国”与“两制”的关系：（2019-25）</span><span class=\"bl\" style=\"left:74px;top:967px;font-size:15.6px;max-width:221px\">A.“一国”是实行“两制”的前提和基础</span><span class=\"bl\" style=\"left:74px;top:987px;font-size:17.3px;max-width:304px\">B.“两制”从属和派生于“一国”并统一于“一国”之内</span><span class=\"bl\" style=\"left:75px;top:1008px;font-size:17.3px;max-width:333px\">C.“一国”是根，根深才能叶茂；“一国”是本，本固才能枝荣</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 83 页</div><span class=\"bl\" style=\"left:91px;top:106px;font-size:16.8px;max-width:424px\">4.继续推动香港、澳门各项事业向前发展，必须全面准确贯彻“一国两制”</span><span class=\"bl\" style=\"left:67px;top:127px;font-size:14.5px;max-width:42px\">方针。</span><span class=\"bl\" style=\"left:91px;top:149px;font-size:16.8px;max-width:423px\">必须牢固树立“一国”意识，坚守“一国”原则，正确处理特别行政区和中央的</span><span class=\"bl\" style=\"left:68px;top:170px;font-size:15.6px;max-width:448px\">关系。任何危害国家主权安全，挑战中央权力和特别行政区基本法权威，利用香港、</span><span class=\"bl\" style=\"left:67px;top:191px;font-size:15.6px;max-width:450px\">澳门对内地进行渗透破坏的活动，都是对底线的触碰，都是绝不能允许的。（2020一26）</span><span class=\"bl\" style=\"left:90px;top:212px;font-size:15.6px;max-width:409px\">5.必须落实中央对特别行政区全面管治权，维护国家主权、安全、发展利益：</span><span class=\"bl\" style=\"left:92px;top:233px;font-size:15.6px;max-width:403px\">①中华人民共和国宪法和特别行政区基本法共同构成特别行政区的宪制基础。</span><span class=\"bl\" style=\"left:91px;top:254px;font-size:14.5px;max-width:334px\">②中央依法行使权力和特别行政区履行主体责任是有机结合的。</span><span class=\"bl\" style=\"left:91px;top:275px;font-size:15.1px;max-width:422px\">③必须把维护中央对香港、澳门特别行政区全面管治权和保障特别行政区高度自</span><span class=\"bl\" style=\"left:68px;top:296px;font-size:14.0px;max-width:108px\">治权有机结合起来。</span><span class=\"bl\" style=\"left:91px;top:318px;font-size:14.5px;max-width:344px\">6.必须始终聚焦发展这个第一要务，推动港澳融入国家发展大局。</span><span class=\"bl\" style=\"left:91px;top:339px;font-size:14.5px;max-width:423px\">发展是永恒的主题，是香港、澳门的立身之本，也是保持香港、澳门国际地位和</span><span class=\"bl\" style=\"left:67px;top:359px;font-size:14.5px;max-width:190px\">解决香港、澳门各种问题的金钥匙。</span><span class=\"bl\" style=\"left:90px;top:380px;font-size:14.5px;max-width:179px\">7.必须坚持爱国者治港治澳原则。</span><span class=\"bl b\" style=\"left:68px;top:408px;font-size:14.0px;max-width:284px\">61.2确保“一国两制”实践行稳致远（高频选择题）</span><span class=\"bl\" style=\"left:92px;top:432px;font-size:12.3px;max-width:402px\">1.为确保确保“一国两制”实践行稳致远，党和国家采取了一系列重大举措：</span><span class=\"bl\" style=\"left:91px;top:473px;font-size:14.5px;max-width:424px\">2020年通过《全国人民代表大会关于建立健全香港特别行政区维护国家安全的</span><span class=\"bl\" style=\"left:68px;top:494px;font-size:14.0px;max-width:446px\">法律制度和执行机制的决定》《中华人民共和国香港特别行政区维护国家安全法》，</span><span class=\"bl\" style=\"left:69px;top:515px;font-size:12.3px;max-width:445px\">并将其列入香港基本法附件三。香港国安法的颁布实施，为香港特别行政区行政、立</span><span class=\"bl\" style=\"left:68px;top:536px;font-size:12.3px;max-width:446px\">法、司法机关依法防范、制止和惩治危害国家安全的行为和活动提供了有力制度保</span><span class=\"bl\" style=\"left:91px;top:577px;font-size:14.5px;max-width:424px\">2021年3月，《全国人民代表大会关于完善香港特别行政区选举制度的决定》，</span><span class=\"bl\" style=\"left:68px;top:599px;font-size:12.3px;max-width:446px\">以及新修订的《中华人民共和国香港特别行政区基本法附件一香港特别行政区行政长</span><span class=\"bl\" style=\"left:68px;top:620px;font-size:14.0px;max-width:447px\">官的产生办法》和《中华人民共和国香港特别行政区基本法附件二香港特别行政区立</span><span class=\"bl\" style=\"left:67px;top:640px;font-size:14.5px;max-width:448px\">法会的产生办法和表决程序》先后通过，为全面、准确贯彻“一国两制”方针，落实</span><span class=\"bl\" style=\"left:68px;top:662px;font-size:14.0px;max-width:422px\">“爱国者治港”原则，确保香港长治久安和长期繁荣稳定提供了坚实的制度保障。</span><span class=\"bl b\" style=\"left:90px;top:682px;font-size:14.0px;max-width:110px\">2.重大举措的意义：</span><span class=\"bl\" style=\"left:93px;top:704px;font-size:12.3px;max-width:420px\">顺应了香港社会盼望良政善治、长治久安的主流民意，体现了包括香港同胞在内</span><span class=\"bl\" style=\"left:68px;top:725px;font-size:14.0px;max-width:131px\">的全国人民的共同心愿。</span><span class=\"bl b\" style=\"left:68px;top:752px;font-size:14.5px;max-width:211px\">61.3实现祖国完全统一（高频选择题）</span><span class=\"bl\" style=\"left:90px;top:773px;font-size:14.5px;max-width:424px\">1.解决台湾问题、实现祖国完全统一，是全体中华儿女共同愿望，是中华民族根</span><span class=\"bl\" style=\"left:67px;top:794px;font-size:15.6px;max-width:357px\">本利益所在，是新时代中国共产党、中国政府的三大历史任务之一。</span><span class=\"bl\" style=\"left:90px;top:815px;font-size:14.0px;max-width:424px\">2.一个中国原则是两岸关系的政治基础。世界上只有一个中国，中国主权和领土</span><span class=\"bl\" style=\"left:67px;top:836px;font-size:14.5px;max-width:448px\">完整不容分割。从中华民族整体利益把握两岸关系大局，最根本的、最核心的是维护</span><span class=\"bl\" style=\"left:67px;top:857px;font-size:14.5px;max-width:250px\">国家领土和主权完整。（2017—15、2018—8）</span><span class=\"bl\" style=\"left:89px;top:878px;font-size:14.5px;max-width:425px\">3.探索“两制”台湾方案，丰富和平统一实践。“和平统一、一国两制”是实现</span><span class=\"bl\" style=\"left:67px;top:898px;font-size:14.5px;max-width:120px\">国家统一的最佳方式。</span><span class=\"bl\" style=\"left:90px;top:919px;font-size:14.5px;max-width:424px\">4.两岸同胞是一家人，两岸的事是两岸同胞的家里事，当然也应该由家里人商量</span><span class=\"bl\" style=\"left:67px;top:940px;font-size:14.5px;max-width:41px\">着办。</span><span class=\"bl\" style=\"left:90px;top:961px;font-size:15.1px;max-width:405px\">5.在一个中国原则基础上，台湾任何政党、团体同我们的交往都不存在障碍。</span><span class=\"bl\" style=\"left:90px;top:982px;font-size:15.1px;max-width:424px\">6.以对话取代对抗、以合作取代争斗、以双赢取代零和，两岸关系才能行稳</span><span class=\"bl\" style=\"left:66px;top:1003px;font-size:13.4px;max-width:37px\">致远。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 84 页</div><span class=\"bl\" style=\"left:454px;top:60px;font-size:15.6px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:74px;top:109px;font-size:15.6px;max-width:297px\">7.台湾前途在于国家统一，台湾同胞福社系于民族复兴。</span><span class=\"bl b\" style=\"left:74px;top:129px;font-size:17.3px;max-width:422px\">8.2019年1月2日，习近平在《告台湾同胞书》发表40周年纪念会上的讲话中</span><span class=\"bl\" style=\"left:50px;top:150px;font-size:15.6px;max-width:315px\">谈到关于对推动两岸关系和平发展的五点主张：（2020一8）</span><span class=\"bl\" style=\"left:75px;top:172px;font-size:14.5px;max-width:226px\">①携手推动民族复兴，实现和平统一目标；</span><span class=\"bl\" style=\"left:76px;top:193px;font-size:15.1px;max-width:248px\">②探索“两制”台湾方案，丰富和平统一实践；</span><span class=\"bl\" style=\"left:75px;top:214px;font-size:15.6px;max-width:226px\">③坚持一个中国原则，维护和平统一前景；</span><span class=\"bl\" style=\"left:75px;top:235px;font-size:14.5px;max-width:225px\">④深化两岸融合发展，夯实和平统一基础；</span><span class=\"bl\" style=\"left:76px;top:255px;font-size:15.1px;max-width:225px\">5实现同胞心灵契合，增进和平统一认同。</span><span class=\"bl b\" style=\"left:74px;top:276px;font-size:15.6px;max-width:265px\">9.2022年8月《台湾问题与新时代中国统一事业</span><span class=\"bl\" style=\"left:76px;top:298px;font-size:14.5px;max-width:236px\">①台湾是中国的一部分不容置疑也不容改变。</span><span class=\"bl\" style=\"left:76px;top:319px;font-size:13.9px;max-width:225px\">②中国共产党坚定不移推进祖国完全统一。</span><span class=\"bl\" style=\"left:76px;top:337px;font-size:16.7px;max-width:423px\">③祖国完全统一进程不可阻挡：实现中华民族伟大复兴，是近代以来中国人民和</span><span class=\"bl\" style=\"left:52px;top:359px;font-size:15.6px;max-width:446px\">中华民族最伟大的梦想；国家发展进步引领两岸关系发展方向；“台独”分裂势力抗</span><span class=\"bl\" style=\"left:51px;top:380px;font-size:15.6px;max-width:447px\">拒统一不会得；外部势力阻碍中国完全统一必遭失败。外部势力阻碍中国完全统一</span><span class=\"bl\" style=\"left:51px;top:403px;font-size:14.5px;max-width:61px\">必遭失败。</span><span class=\"bl\" style=\"left:75px;top:422px;font-size:17.3px;max-width:423px\">④在新时代新征程上推进祖国统一：坚持“和平统一、一国两制”基本方针；努</span><span class=\"bl\" style=\"left:52px;top:443px;font-size:15.1px;max-width:446px\">力推动两岸关系和平发展、融合发展；坚决粉碎“台独”分裂和外来干涉图谋；团结</span><span class=\"bl\" style=\"left:52px;top:464px;font-size:16.7px;max-width:190px\">台湾同胞共谋民族复兴和国家统一。</span><span class=\"bl\" style=\"left:76px;top:484px;font-size:17.3px;max-width:423px\">5实现祖国和平统一的光明前景：台湾发展空间将更为广阔；台湾同胞切身利益</span><span class=\"bl\" style=\"left:51px;top:505px;font-size:17.3px;max-width:447px\">将得到充分保障；两岸同胞共享民族复兴的伟大荣光；有利于亚太地区及全世界和平</span><span class=\"bl\" style=\"left:53px;top:528px;font-size:14.5px;max-width:48px\">与发展。</span><span class=\"bl\" style=\"left:52px;top:563px;font-size:17.3px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:52px;top:589px;font-size:17.3px;max-width:447px\">1.【2019.6】党的十八大以来，为了更好适应我国国家安全面临的新形势新任务，实</span><span class=\"bl\" style=\"left:69px;top:611px;font-size:15.1px;max-width:430px\">现国家长治久安，我们党明确提出了总体国家安全观。总体国家安全观的宗旨是</span><span class=\"bl\" style=\"left:68px;top:653px;font-size:14.5px;max-width:70px\">A.政治安全</span><span class=\"bl\" style=\"left:67px;top:673px;font-size:17.8px;max-width:72px\">B.经济安全</span><span class=\"bl\" style=\"left:69px;top:696px;font-size:14.5px;max-width:69px\">C.人民安全</span><span class=\"bl\" style=\"left:69px;top:717px;font-size:13.9px;max-width:140px\">D.军事、文化、社会安全</span><span class=\"bl\" style=\"left:52px;top:750px;font-size:18.4px;max-width:447px\">2.【2018.8】解决台湾问题，实现祖国完全统一，是全体中华儿女共同愿望，是中华</span><span class=\"bl\" style=\"left:69px;top:772px;font-size:15.6px;max-width:430px\">民族根本利益所在。党的十八大以来，在以习近平同志为核心的党中央坚强领导</span><span class=\"bl\" style=\"left:71px;top:792px;font-size:15.6px;max-width:429px\">下，在两岸同胞共同努力下，两岸关系取得重要积极成果。两岸关系和平发展的</span><span class=\"bl\" style=\"left:69px;top:814px;font-size:14.5px;max-width:67px\">政治基础是</span><span class=\"bl\" style=\"left:69px;top:834px;font-size:16.7px;max-width:330px\">A.深化两岸利益融合，共创两岸互利双赢，增进两岸同胞福祉</span><span class=\"bl\" style=\"left:69px;top:857px;font-size:13.9px;max-width:127px\">B.相互尊重，求同存异</span><span class=\"bl\" style=\"left:70px;top:876px;font-size:16.7px;max-width:270px\">C.增强两岸同胞的民族认同、文化认同、国家认同</span><span class=\"bl\" style=\"left:71px;top:898px;font-size:13.9px;max-width:194px\">D.坚持“九二共识”，反对“台独”</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 85 页</div><span class=\"bl\" style=\"left:68px;top:104px;font-size:20.1px;max-width:447px\">3.【2020.26】“一国两制”是实现祖国和平统一的一项重要制度，是中国特色社会</span><span class=\"bl\" style=\"left:85px;top:126px;font-size:19.0px;max-width:431px\">主义的一个伟大创举。2019年11月，国家主席习近平在巴西利亚出席金砖国家</span><span class=\"bl\" style=\"left:84px;top:147px;font-size:18.4px;max-width:432px\">领导人第十一次会唔时，针对香港出现的街头暴力犯罪行为发表重要讲话。习近</span><span class=\"bl\" style=\"left:84px;top:167px;font-size:19.0px;max-width:432px\">平指出，香港持续发生的激进暴力犯罪行为，严重践踏法治和社会秩序，严重破</span><span class=\"bl\" style=\"left:84px;top:189px;font-size:19.0px;max-width:432px\">坏香港繁荣稳定，严重挑畔“一国两制”原则底线。止暴制乱、恢复秩序是香港</span><span class=\"bl\" style=\"left:85px;top:209px;font-size:19.5px;max-width:431px\">当前最紧迫的任务。贯彻落实“一国两制”方针，绝不能允许触碰的原则底线是</span><span class=\"bl\" style=\"left:84px;top:252px;font-size:15.6px;max-width:119px\">A.危害国家主权安全</span><span class=\"bl\" style=\"left:83px;top:272px;font-size:17.8px;max-width:165px\">B.干扰内地与香港的民间交流</span><span class=\"bl\" style=\"left:83px;top:294px;font-size:17.3px;max-width:248px\">C.挑战中央权力与香港特别行政区基本法权威</span><span class=\"bl\" style=\"left:84px;top:315px;font-size:15.1px;max-width:176px\">D.利用香港对内地进行渗透破坏</span></div></div>"}],pages:[79,85]};
  D["mzt_s14"] = {id:"mzt_s14",ch:"毛中特讲义 · 第十三章 中国特色大国外交",title:"第十三章 中国特色大国外交",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 86 页</div><span class=\"bl\" style=\"left:453px;top:57px;font-size:17.8px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b acc\" style=\"left:332px;top:113px;font-size:25.1px;max-width:84px\">第十三章</span><span class=\"bl\" style=\"left:298px;top:162px;font-size:23.4px;max-width:155px\">中国特色大国外交</span><span class=\"bl\" style=\"left:50px;top:217px;font-size:16.7px;max-width:101px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:357px;top:256px;font-size:15.6px;max-width:165px\">考点62坚持习近平外交思想</span><span class=\"bl\" style=\"left:203px;top:278px;font-size:16.7px;max-width:102px\">中国特色大国外交</span><span class=\"bl b hl\" style=\"left:355px;top:275px;font-size:18.4px;max-width:166px\">考点63坚持走和平发展道路</span><span class=\"bl b hl\" style=\"left:356px;top:297px;font-size:17.3px;max-width:189px\">考点64推动构建人类命运共同体</span><span class=\"bl\" style=\"left:50px;top:349px;font-size:20.1px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:77px;top:375px;font-size:19.0px;max-width:623px\">本章主要阐述了中国特色大国外交的相关内容。本章是本门科目中考频较高的章节，考试形式既可能为选择题，也可能</span><span class=\"bl\" style=\"left:53px;top:396px;font-size:19.0px;max-width:646px\">为材料分析题。考生在复习过程中，要重点掌握中国独立自主和平外交政策的内涵与依据、中国走和平发展道路的含义与根</span><span class=\"bl\" style=\"left:53px;top:421px;font-size:13.9px;max-width:261px\">源、推动建立新型国际关系的内涵和要求等内容。</span><span class=\"bl b hl\" style=\"left:63px;top:483px;font-size:20.1px;max-width:246px\">考点62坚持习近平外交思想☆★</span><span class=\"bl\" style=\"left:659px;top:482px;font-size:15.1px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:53px;top:520px;font-size:15.1px;max-width:257px\">62.1习近平外交思想的核心要义（中频选择题）</span><span class=\"bl\" style=\"left:77px;top:538px;font-size:18.4px;max-width:423px\">1.习近平外交思想，旗帜鲜明地回答了新时代中国应当推动建设什么样的世界、</span><span class=\"bl\" style=\"left:53px;top:560px;font-size:17.8px;max-width:446px\">构建什么样的国际关系，中国需要什么样的外交、怎样办好新时代外交等一系列重大</span><span class=\"bl\" style=\"left:53px;top:582px;font-size:17.8px;max-width:99px\">理论和实践问题。</span><span class=\"bl b\" style=\"left:77px;top:604px;font-size:13.9px;max-width:169px\">2.习近平外交思想的核心要义：</span><span class=\"bl\" style=\"left:77px;top:622px;font-size:18.4px;max-width:381px\">第一，坚持以维护党中央权威为统领加强党对对外工作的集中统一领导。</span><span class=\"bl\" style=\"left:77px;top:644px;font-size:18.4px;max-width:357px\">第二，坚持以实现中华民族伟大复兴为使命推进中国特色大国外交。</span><span class=\"bl\" style=\"left:77px;top:664px;font-size:18.4px;max-width:403px\">第三，坚持以维护世界和平、促进共同发展为宗旨推动构建人类命运共同体。</span><span class=\"bl\" style=\"left:77px;top:686px;font-size:17.8px;max-width:286px\">第四，坚持以中国特色社会主义为根本增强战略自信。</span><span class=\"bl\" style=\"left:77px;top:707px;font-size:17.3px;max-width:311px\">第五，坚持以共商共建共享为原则推动“一带一路”建设。</span><span class=\"bl\" style=\"left:77px;top:728px;font-size:17.8px;max-width:309px\">第六，坚持以相互尊重、合作共赢为基础走和平发展道路。</span><span class=\"bl\" style=\"left:78px;top:749px;font-size:17.3px;max-width:285px\">第七，坚持以深化外交布局为依托打造全球伙伴关系。</span><span class=\"bl\" style=\"left:78px;top:769px;font-size:17.8px;max-width:286px\">第八，坚持以公平正义为理念引领全球治理体系改革。</span><span class=\"bl\" style=\"left:78px;top:790px;font-size:18.4px;max-width:357px\">第九，坚持以国家核心利益为底线维护国家主权、安全、发展利益。</span><span class=\"bl\" style=\"left:78px;top:811px;font-size:18.4px;max-width:419px\">第十，坚持以外交工作优良传统和时代特征相结合为方向塑造中国外交独特风范。</span><span class=\"bl b\" style=\"left:55px;top:841px;font-size:15.1px;max-width:265px\">62.2新时代对外工作的根本遵循（中频选择题）</span><span class=\"bl\" style=\"left:79px;top:859px;font-size:19.0px;max-width:423px\">1.习近平外交思想是习近平新时代中国特色社会主义思想的重要组成部分，是马</span><span class=\"bl\" style=\"left:55px;top:880px;font-size:19.5px;max-width:447px\">克思主义基本原理同中国特色大国外交实践相结合的重大理论结晶，是以习近平同志</span><span class=\"bl\" style=\"left:56px;top:901px;font-size:19.0px;max-width:446px\">为核心的党中央治国理政思想在外交领域的集中体现，是新时代我国对外工作的根本</span><span class=\"bl\" style=\"left:56px;top:925px;font-size:14.5px;max-width:96px\">遵循和行动指南。</span><span class=\"bl\" style=\"left:79px;top:943px;font-size:17.8px;max-width:284px\">2.习近平外交思想是对新中国外交理论的继承与发展。</span><span class=\"bl\" style=\"left:79px;top:963px;font-size:19.0px;max-width:339px\">3.习近平外交思想是21世纪马克思主义在外交领域的最新成果。</span><span class=\"bl\" style=\"left:79px;top:985px;font-size:16.7px;max-width:285px\">4.习近平外交思想是对中华优秀传统文化的传承创新。</span><span class=\"bl\" style=\"left:80px;top:1006px;font-size:17.3px;max-width:285px\">5.习近平外交思想是对传统国际关系理论的扬弃超越。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1098px\"><div class=\"bxnum\">第 87 页</div><span class=\"bl\" style=\"left:90px;top:102px;font-size:19.5px;max-width:423px\">6.习近平外交思想立足世界百年未有之大变局，为破解当今世界面临的重大问</span><span class=\"bl\" style=\"left:67px;top:123px;font-size:19.5px;max-width:446px\">题、引领国际秩序和国际体系变革贡献了中国智慧、中国方案，实现了历史使命与时</span><span class=\"bl\" style=\"left:67px;top:144px;font-size:19.0px;max-width:446px\">代潮流的高度统一、民族精神与国际主义的高度统一、中国气派与世界情怀的高度统</span><span class=\"bl\" style=\"left:68px;top:165px;font-size:15.6px;max-width:177px\">一，展现出鲜明的理论创新品格。</span><span class=\"bl b hl\" style=\"left:77px;top:205px;font-size:19.0px;max-width:247px\">考点63坚持走和平发展道路☆☆☆</span><span class=\"bl b\" style=\"left:66px;top:242px;font-size:16.7px;max-width:231px\">63.1世界正处于大发展大变革大调整时期</span><span class=\"bl\" style=\"left:89px;top:263px;font-size:18.4px;max-width:422px\">冷战结束后，尤其是进人21世纪以来，国际形势发生了广泛而深刻的变化，但</span><span class=\"bl\" style=\"left:67px;top:284px;font-size:19.0px;max-width:446px\">和平与发展仍然是时代主题，和平、发展、合作、共赢成为不可阻挡的时代潮流。世</span><span class=\"bl\" style=\"left:66px;top:305px;font-size:17.8px;max-width:446px\">界多极化、经济全球化、文化多样化、社会信息化深人发展，全球治理体系和国际秩</span><span class=\"bl\" style=\"left:66px;top:326px;font-size:17.8px;max-width:446px\">序变革加速推进，各国相互联系和依存日益加深，国际力量对比更趋平衡，和平发展</span><span class=\"bl\" style=\"left:66px;top:348px;font-size:16.7px;max-width:446px\">大势不可逆转。同时，世界面临的不稳定性、不确定性突出，人类依然面临许多共同</span><span class=\"bl\" style=\"left:65px;top:369px;font-size:15.6px;max-width:297px\">挑战，推进人类和平与发展的崇高事业依然任重而道远。</span><span class=\"bl\" style=\"left:89px;top:389px;font-size:15.1px;max-width:155px\">1.世界多极化在曲折中发展。</span><span class=\"bl\" style=\"left:88px;top:410px;font-size:15.6px;max-width:133px\">2.经济全球化深入发展。</span><span class=\"bl\" style=\"left:88px;top:432px;font-size:15.1px;max-width:133px\">3.文化多样性持续推进。</span><span class=\"bl\" style=\"left:88px;top:453px;font-size:15.1px;max-width:133px\">4.社会信息化快速发展。</span><span class=\"bl\" style=\"left:87px;top:474px;font-size:15.6px;max-width:134px\">5.科学技术孕育新突破。</span><span class=\"bl b\" style=\"left:65px;top:501px;font-size:15.6px;max-width:187px\">63.2坚持独立自主和平外交政策</span><span class=\"bl b\" style=\"left:88px;top:523px;font-size:15.1px;max-width:215px\">1.中国独立自主的和平外交政策的内涵：</span><span class=\"bl\" style=\"left:88px;top:542px;font-size:19.5px;max-width:341px\">①把国家主权和安全放在第一位，坚定地维护我国的国家利益。</span><span class=\"bl\" style=\"left:88px;top:564px;font-size:18.4px;max-width:423px\">②从我国人民和世界人民的根本利益出发，对于一切国际事务，都要根据事情本</span><span class=\"bl\" style=\"left:66px;top:585px;font-size:15.1px;max-width:201px\">身的是非曲直决定自己的立场和政策。</span><span class=\"bl\" style=\"left:89px;top:607px;font-size:17.3px;max-width:421px\">③坚持各国的事务应由本国政府和人民决定，世界上的事情应由各国政府和人民</span><span class=\"bl\" style=\"left:64px;top:628px;font-size:15.1px;max-width:260px\">平等协商，反对一切形式的霸权主义和强权政治。</span><span class=\"bl\" style=\"left:88px;top:648px;font-size:15.1px;max-width:202px\">④主张和平解决国际争端和热点问题。</span><span class=\"bl\" style=\"left:87px;top:669px;font-size:15.6px;max-width:391px\">2.中国坚定不移地奉行独立自主的和平外交政策，走和平发展道路的依据：</span><span class=\"bl\" style=\"left:88px;top:690px;font-size:15.6px;max-width:284px\">①由我国的社会主义性质和在国际上的地位所决定的。</span><span class=\"bl\" style=\"left:88px;top:711px;font-size:16.7px;max-width:272px\">②是从历史、现实、未来的客观判断中得出的结论。</span><span class=\"bl\" style=\"left:87px;top:732px;font-size:16.7px;max-width:202px\">③是思想自信和实践自觉的有机统一。</span><span class=\"bl b\" style=\"left:87px;top:754px;font-size:13.9px;max-width:144px\">3.中国的外交政策及思想：</span><span class=\"bl\" style=\"left:87px;top:773px;font-size:16.7px;max-width:297px\">①我国外交政策的宗旨：维护世界和平，促进共同发展。</span><span class=\"bl\" style=\"left:87px;top:795px;font-size:15.6px;max-width:273px\">②我国对外政策的主张：和平、发展、合作、共赢。</span><span class=\"bl\" style=\"left:87px;top:815px;font-size:19.0px;max-width:392px\">③我国对外工作的基本出发点和落脚点：维护国家主权、安全、发展利益。</span><span class=\"bl\" style=\"left:86px;top:836px;font-size:19.0px;max-width:351px\">④新时代中国特色社会主义外交思想，概括起来主要有10个方面。</span><span class=\"bl b\" style=\"left:86px;top:858px;font-size:15.1px;max-width:168px\">4.中国走和平发展道路的根源：</span><span class=\"bl\" style=\"left:86px;top:878px;font-size:14.5px;max-width:166px\">①来源于中华文明的深厚渊源。</span><span class=\"bl\" style=\"left:86px;top:899px;font-size:15.6px;max-width:226px\">②来源于对实现中国发展目标条件的认知。</span><span class=\"bl\" style=\"left:86px;top:919px;font-size:15.6px;max-width:178px\">③来源于对世界发展大势的把握。</span><span class=\"bl b\" style=\"left:84px;top:940px;font-size:15.1px;max-width:168px\">5.中国走和平发展道路的含义：</span><span class=\"bl\" style=\"left:86px;top:961px;font-size:17.3px;max-width:368px\">①既积极争取和平的国际环境发展自己，又以自身发展促进世界和平。</span><span class=\"bl\" style=\"left:86px;top:982px;font-size:16.7px;max-width:344px\">②既让中国更好利用世界的机遇，又让世界更好分享中国的机遇。</span><span class=\"bl\" style=\"left:86px;top:1002px;font-size:16.7px;max-width:237px\">③促进中国和世界各国良性互动、互利共赢。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 88 页</div><span class=\"bl\" style=\"left:458px;top:62px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:54px;top:110px;font-size:13.9px;max-width:161px\">63.3推动建立新型国际关系</span><span class=\"bl b\" style=\"left:78px;top:131px;font-size:13.9px;max-width:178px\">1.推动建立新型国际关系的内涵：</span><span class=\"bl\" style=\"left:78px;top:150px;font-size:15.6px;max-width:355px\">①内容：推动建设相互尊重、公平正义、合作共赢的新型国际关系。</span><span class=\"bl\" style=\"left:77px;top:171px;font-size:17.3px;max-width:424px\">②特点：新型国际关系，“新”在合作共赢，“新”在公平正义，特别是“新”在</span><span class=\"bl\" style=\"left:55px;top:193px;font-size:16.2px;max-width:56px\">合作共赢</span><span class=\"bl\" style=\"left:78px;top:213px;font-size:15.6px;max-width:422px\">③意义：推动建设新型国际关系，是党中央立足时代发展潮流和我国根本利益作</span><span class=\"bl\" style=\"left:55px;top:235px;font-size:15.1px;max-width:294px\">出的战略选择，反映了中国人民和世界人民的共同心愿。</span><span class=\"bl b\" style=\"left:78px;top:256px;font-size:13.9px;max-width:179px\">2.推动建立新型国际关系的要求：</span><span class=\"bl\" style=\"left:79px;top:278px;font-size:12.3px;max-width:153px\">①要坚决维护国家核心利益。</span><span class=\"bl\" style=\"left:78px;top:297px;font-size:15.6px;max-width:422px\">②要在和平共处五项原则基础上发展同世界各国的友好合作。要按照大国是关</span><span class=\"bl\" style=\"left:54px;top:317px;font-size:17.3px;max-width:448px\">键、周边是首要、发展中国家是基础、多边是舞台的外交工作布局，建立新型国际</span><span class=\"bl\" style=\"left:53px;top:339px;font-size:17.3px;max-width:40px\">关系。</span><span class=\"bl\" style=\"left:79px;top:361px;font-size:13.9px;max-width:421px\">③要积极参与全球治理体系改革和建设。中国秉持共商共建共享的全球治理观，</span><span class=\"bl\" style=\"left:54px;top:381px;font-size:14.5px;max-width:446px\">倡导国际关系民主化，坚持国家不分大小、强弱、贫富一律平等，支持扩大发展中国</span><span class=\"bl\" style=\"left:56px;top:403px;font-size:13.9px;max-width:189px\">家在国际事务中的代表性和发言权。</span><span class=\"bl\" style=\"left:79px;top:424px;font-size:13.9px;max-width:261px\">④要加强涉外法律工作，完善涉外法律法规体系。</span><span class=\"bl\" style=\"left:77px;top:443px;font-size:16.2px;max-width:424px\">推动建立新型国际关系，还要把相互尊重、公平正义、合作共赢理念体现到政</span><span class=\"bl\" style=\"left:55px;top:466px;font-size:13.9px;max-width:390px\">治、经济、安全、文化等对外合作的方方面面，推动构建人类命运共同体。</span><span class=\"bl b hl\" style=\"left:66px;top:506px;font-size:17.8px;max-width:278px\">考点64推动构建人类命运共同体☆☆</span><span class=\"bl\" style=\"left:78px;top:562px;font-size:15.1px;max-width:234px\">1.提出构建人类命运共同体思想的时代背景</span><span class=\"bl\" style=\"left:77px;top:584px;font-size:13.9px;max-width:92px\">（1）从国际上看</span><span class=\"bl\" style=\"left:78px;top:604px;font-size:16.2px;max-width:424px\">①世界格局正处在加快演变进程之中，经济全球化、社会信息化极大解放和发</span><span class=\"bl\" style=\"left:54px;top:625px;font-size:17.3px;max-width:447px\">展了社会生产力，创造了前所未有的发展机遇；各国相互联系、相互依存、相互合</span><span class=\"bl\" style=\"left:56px;top:647px;font-size:13.9px;max-width:445px\">作、相互促进的程度空前加深，国际社会日益成为一个你中有我、我中有你的命运</span><span class=\"bl\" style=\"left:55px;top:667px;font-size:15.1px;max-width:49px\">共同体。</span><span class=\"bl\" style=\"left:79px;top:688px;font-size:15.1px;max-width:422px\">②世界发展面临各种问题和挑战，国际社会迫切呼唤新的全球治理理念，构建新</span><span class=\"bl\" style=\"left:56px;top:709px;font-size:14.5px;max-width:354px\">的更加公正合理的国际体系和秩序，开辟人类更加美好的发展前景。</span><span class=\"bl\" style=\"left:78px;top:731px;font-size:13.9px;max-width:92px\">（2）从国内来看</span><span class=\"bl\" style=\"left:79px;top:751px;font-size:15.6px;max-width:422px\">党的十八大以来，在新中国成立特别是改革开放以来我国发展取得重大成就的</span><span class=\"bl\" style=\"left:56px;top:771px;font-size:15.1px;max-width:446px\">基础上，党和国家事业发生历史性变革，我国发展站到了新的历史起点上，中国特色</span><span class=\"bl\" style=\"left:56px;top:793px;font-size:15.1px;max-width:446px\">社会主义进人了新时代，中国的治理理念和实践受到高度赞赏和广泛认同，国际影响</span><span class=\"bl\" style=\"left:57px;top:814px;font-size:13.9px;max-width:177px\">力、感召力、塑造力进一步提高。</span><span class=\"bl\" style=\"left:79px;top:835px;font-size:13.9px;max-width:185px\">2.构建人类命运共同体思想的内涵</span><span class=\"bl\" style=\"left:79px;top:855px;font-size:15.6px;max-width:423px\">构建人类命运共同体思想，是一个科学完整、内涵丰富、意义深远的思想体系，</span><span class=\"bl\" style=\"left:56px;top:876px;font-size:14.5px;max-width:435px\">其核心就是“建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界”。</span><span class=\"bl\" style=\"left:79px;top:895px;font-size:17.8px;max-width:423px\">①政治上，要相互尊重、平等协商，坚决摒弃冷战思维和强权政治，走对话而不</span><span class=\"bl\" style=\"left:57px;top:919px;font-size:13.9px;max-width:213px\">对抗、结伴而不结盟的国与国交往新路。</span><span class=\"bl\" style=\"left:79px;top:938px;font-size:17.3px;max-width:423px\">②安全上，要坚持以对话解决争端、以协商化解分歧，统筹应对传统和非传统安</span><span class=\"bl\" style=\"left:57px;top:961px;font-size:13.9px;max-width:189px\">全威胁，反对一切形式的恐怖主义。</span><span class=\"bl\" style=\"left:81px;top:980px;font-size:16.2px;max-width:422px\">③经济上，要同舟共济，促进贸易和投资自由化、便利化，推动经济全球化朝着</span><span class=\"bl\" style=\"left:57px;top:1003px;font-size:13.9px;max-width:260px\">更加开放、包容、普惠、平衡、共赢的方向发展。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1099px\"><div class=\"bxnum\">第 89 页</div><span class=\"bl\" style=\"left:89px;top:107px;font-size:15.6px;max-width:422px\">④文化上，要尊重世界文明多样性，以文明交流超越文明隔阁、文明互鉴超越文</span><span class=\"bl\" style=\"left:65px;top:128px;font-size:14.5px;max-width:178px\">明冲突、文明共存超越文明优越。</span><span class=\"bl\" style=\"left:89px;top:148px;font-size:16.2px;max-width:423px\">5生态上，要坚持环境友好，合作应对气候变化，保护好人类赖以生存的地球</span><span class=\"bl\" style=\"left:65px;top:171px;font-size:12.8px;max-width:36px\">家园。</span><span class=\"bl\" style=\"left:87px;top:190px;font-size:14.5px;max-width:186px\">3.构建人类命运共同体思想的意义</span><span class=\"bl\" style=\"left:88px;top:211px;font-size:15.6px;max-width:422px\">构建人类命运共同体思想顺应了历史潮流，回应了时代要求，凝聚了各国共识，</span><span class=\"bl\" style=\"left:65px;top:232px;font-size:15.1px;max-width:320px\">为人类社会实现共同发展、持续繁荣、长治久安绘制了蓝图。</span><span class=\"bl\" style=\"left:88px;top:253px;font-size:17.3px;max-width:424px\">这一思想继承和发展了新中国不同时期重大外交思想和主张，反映了中外优秀文</span><span class=\"bl\" style=\"left:64px;top:275px;font-size:15.6px;max-width:446px\">化和全人类共同价值追求，适应了新时代中国与世界关系的历史性变化，成为中国引</span><span class=\"bl\" style=\"left:65px;top:295px;font-size:15.6px;max-width:446px\">领时代潮流和人类文明进步方向的鲜明旗帜，已被多次写入联合国文件，对中国的和</span><span class=\"bl\" style=\"left:64px;top:316px;font-size:15.1px;max-width:273px\">平发展、世界的繁荣进步都具有重大和深远的意义。</span><span class=\"bl b\" style=\"left:64px;top:343px;font-size:17.9px;max-width:188px\">64.2促进“一带一路”国际合作</span><span class=\"bl\" style=\"left:88px;top:367px;font-size:14.0px;max-width:146px\">1.“一带一路”倡议的提出</span><span class=\"bl\" style=\"left:88px;top:387px;font-size:15.6px;max-width:422px\">①推进“一带一路”建设是习近平深刻思考人类前途命运及中国和世界发展大势</span><span class=\"bl\" style=\"left:64px;top:408px;font-size:15.1px;max-width:166px\">所提出的宏伟构想和中国方案。</span><span class=\"bl\" style=\"left:88px;top:429px;font-size:15.1px;max-width:424px\">②2013年9月和10月，习近平在出访中亚和东南亚国家期间，先后提出共建</span><span class=\"bl\" style=\"left:64px;top:450px;font-size:15.6px;max-width:446px\">“丝绸之路经济带”和“21世纪海上丝绸之路”的重大倡议，得到了国际社会的高度</span><span class=\"bl\" style=\"left:64px;top:470px;font-size:16.2px;max-width:96px\">关注和积极回应。</span><span class=\"bl\" style=\"left:82px;top:491px;font-size:16.2px;max-width:165px\">2.“一带一路”倡议的必要性</span><span class=\"bl\" style=\"left:86px;top:512px;font-size:17.9px;max-width:425px\">①共建“一带一路”符合国际社会的根本利益，彰显人类社会共同理想和美好</span><span class=\"bl\" style=\"left:63px;top:534px;font-size:15.1px;max-width:447px\">追求，是国际合作以及全球治理新模式的积极探索，将为世界和平发展增添新的正</span><span class=\"bl\" style=\"left:64px;top:556px;font-size:12.8px;max-width:39px\">能量。</span><span class=\"bl\" style=\"left:100px;top:552px;font-size:21.8px;max-width:132px\">大考</span><span class=\"bl\" style=\"left:88px;top:575px;font-size:15.6px;max-width:422px\">②推进“一带一路”建设既是中国扩大和深化对外开放的需要，也是加强和亚欧</span><span class=\"bl\" style=\"left:64px;top:596px;font-size:15.1px;max-width:179px\">非拉及世界各国互利合作的需要。</span><span class=\"bl\" style=\"left:86px;top:617px;font-size:14.0px;max-width:147px\">3.“一带一路”倡议的内容</span><span class=\"bl\" style=\"left:88px;top:638px;font-size:15.1px;max-width:422px\">中国政府倡议，共建“一带一路”恪守联合国宪章的宗旨和原则，坚持开放合</span><span class=\"bl\" style=\"left:64px;top:660px;font-size:14.0px;max-width:201px\">作、和谐包容、市场运作、互利共赢。</span><span class=\"bl\" style=\"left:87px;top:680px;font-size:15.6px;max-width:423px\">秉持和平合作、开放包容、互学互鉴、互利共赢的理念，全方位推进务实合作，</span><span class=\"bl\" style=\"left:63px;top:701px;font-size:15.6px;max-width:447px\">打造政治互信、经济融合、文化包容的利益共同体、命运共同体和责任共同体，以政</span><span class=\"bl\" style=\"left:64px;top:723px;font-size:15.1px;max-width:391px\">策沟通、设施联通、贸易畅通、资金融通、民心相通为主要内容加强合作。</span><span class=\"bl\" style=\"left:87px;top:744px;font-size:14.0px;max-width:147px\">4.“一带一路”倡议的要求</span><span class=\"bl\" style=\"left:86px;top:762px;font-size:18.4px;max-width:424px\">“一带一路”建设对推动构建人类命运共同体具有重要的意义作用。党的十九大</span><span class=\"bl\" style=\"left:63px;top:785px;font-size:15.6px;max-width:447px\">提出要以“一带一路”建设为重点，坚持引进来和走出去并重，遵循共商共建共享原</span><span class=\"bl\" style=\"left:63px;top:805px;font-size:16.2px;max-width:402px\">则，加强创新能力开放合作，形成陆海内外联动、东西双向互济的开放格局。</span><span class=\"bl\" style=\"left:86px;top:827px;font-size:15.6px;max-width:272px\">①要坚持引进来和走出去并重，深化双向投资合作。</span><span class=\"bl\" style=\"left:86px;top:848px;font-size:14.5px;max-width:143px\">②坚持共商共建共享原则。</span><span class=\"bl\" style=\"left:86px;top:868px;font-size:15.6px;max-width:422px\">③加强创新能力开放合作，主要是加强技术创新合作、理论创新交流互鉴、创新</span><span class=\"bl\" style=\"left:63px;top:890px;font-size:14.0px;max-width:107px\">人才资源交流合作。</span><span class=\"bl\" style=\"left:86px;top:910px;font-size:17.3px;max-width:422px\">④把“一带一路”与构建人类命运共同体更加紧密结合起来，与落实2030年可</span><span class=\"bl\" style=\"left:62px;top:930px;font-size:17.3px;max-width:447px\">持续发展议程紧密结合起来，打造国际合作新平台，增添共同发展新动力，把“一带</span><span class=\"bl\" style=\"left:61px;top:951px;font-size:15.6px;max-width:356px\">一路”建成和平之路、繁荣之路、开放之路、创新之路、文明之路。</span><span class=\"bl b\" style=\"left:62px;top:979px;font-size:15.6px;max-width:174px\">64.3共商共建人类命运共同体</span><span class=\"bl\" style=\"left:85px;top:1000px;font-size:15.6px;max-width:250px\">1.坚持和平发展道路，推动建设新型国际关系。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1100px\"><div class=\"bxnum\">第 90 页</div><span class=\"bl\" style=\"left:457px;top:61px;font-size:16.8px;max-width:243px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl\" style=\"left:77px;top:108px;font-size:17.3px;max-width:423px\">2.不断完善外交布局，打造全球伙伴关系网络。我们要扩大同世界各国的利益交</span><span class=\"bl\" style=\"left:52px;top:129px;font-size:17.3px;max-width:447px\">汇点，推进大国协调和合作，构建总体稳定、均衡发展的大国关系框架，按照亲诚惠</span><span class=\"bl\" style=\"left:53px;top:150px;font-size:17.9px;max-width:447px\">容理念和与邻为善、以邻为伴周边外交方针深化同周边国家关系，秉持正确义利观和</span><span class=\"bl\" style=\"left:53px;top:173px;font-size:15.1px;max-width:225px\">真实亲诚理念加强同发展中国家团结合作。</span><span class=\"bl\" style=\"left:76px;top:191px;font-size:17.9px;max-width:424px\">3.深度参与全球治理，积极引导国际秩序变革方向。我们将秉持共商共建共享的</span><span class=\"bl\" style=\"left:54px;top:214px;font-size:15.1px;max-width:260px\">全球治理观，积极参与全球治理体系改革和建设。</span><span class=\"bl\" style=\"left:75px;top:234px;font-size:17.3px;max-width:425px\">4.推动国际社会从伙伴关系、安全格局、经济发展、文明交流、生态建设等方</span><span class=\"bl\" style=\"left:54px;top:254px;font-size:17.3px;max-width:446px\">面为建立人类命运共同体作出努力。要坚持对话协商，建设一个持久和平的世界；要</span><span class=\"bl\" style=\"left:54px;top:275px;font-size:18.4px;max-width:447px\">坚持共建共享，建设一个普遍安全的世界；要坚持合作共赢，建设一个共同繁荣的世</span><span class=\"bl\" style=\"left:54px;top:296px;font-size:17.9px;max-width:447px\">界；要坚持交流互鉴，建设一个开放包容的世界；要坚持绿色低碳，建设一个清洁美</span><span class=\"bl\" style=\"left:54px;top:319px;font-size:14.5px;max-width:272px\">丽的世界，让人类命运共同体建设的阳光普照世界。</span><span class=\"bl\" style=\"left:53px;top:356px;font-size:15.6px;max-width:101px\">经典真题回顾</span><span class=\"bl\" style=\"left:54px;top:381px;font-size:15.6px;max-width:446px\">1.【2010.25】改革开放以来，中国成功地走上了一条与本国国情和时代特征相适应</span><span class=\"bl\" style=\"left:71px;top:402px;font-size:15.6px;max-width:430px\">的和平发展道路。坚持走和平发展道路，符合中国的历史文化传统，这是因为</span><span class=\"bl\" style=\"left:72px;top:445px;font-size:14.0px;max-width:164px\">A.中华民族是热爱和平的民族</span><span class=\"bl\" style=\"left:72px;top:467px;font-size:12.3px;max-width:185px\">B.和平与发展成为时代发展的潮流</span><span class=\"bl\" style=\"left:70px;top:505px;font-size:20.7px;max-width:367px\">D.中华文化是一种和平的文化，渴望和平始终是中国人民的精神特征</span><span class=\"bl\" style=\"left:54px;top:542px;font-size:17.3px;max-width:448px\">2.【2017.23】“一带一路”倡议提出三年来，已经有100多个国家和国际组织参与其</span><span class=\"bl\" style=\"left:71px;top:563px;font-size:17.3px;max-width:431px\">中，我国同沿线30多个国家签署共建合作协议，与20多个国家开展了国际产能</span><span class=\"bl\" style=\"left:71px;top:584px;font-size:17.3px;max-width:431px\">合作，一批有影响力的标志性项目逐步落地。截至2016年7月，我国对“一带一</span><span class=\"bl\" style=\"left:71px;top:605px;font-size:15.6px;max-width:430px\">路”相关国家的投资累计已达511亿美元，占同期对外直接投资总额的12%：与</span><span class=\"bl\" style=\"left:72px;top:626px;font-size:15.6px;max-width:430px\">沿线国家新签承包工程合同1.25万份，累计合同额2790亿美元。我国推进“一带</span><span class=\"bl\" style=\"left:72px;top:648px;font-size:15.6px;max-width:91px\">一路”建设旨在</span><span class=\"bl\" style=\"left:72px;top:670px;font-size:15.1px;max-width:140px\">A.统筹国内国际两个大局</span><span class=\"bl\" style=\"left:70px;top:690px;font-size:15.6px;max-width:141px\">B.促进沿线各国共同繁荣</span><span class=\"bl\" style=\"left:72px;top:711px;font-size:15.1px;max-width:281px\">C.打造开放、包容、均衡、普惠的区域经济合作架构</span><span class=\"bl\" style=\"left:73px;top:733px;font-size:14.0px;max-width:187px\">D.探索国际合作及全球治理新模式</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 91 页</div><span class=\"bl b acc\" style=\"left:348px;top:114px;font-size:23.4px;max-width:83px\">第十四章</span><span class=\"bl\" style=\"left:304px;top:162px;font-size:22.9px;max-width:172px\">坚持和加强党的领导</span><span class=\"bl\" style=\"left:63px;top:211px;font-size:19.5px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:364px;top:255px;font-size:17.8px;max-width:216px\">考点65实现中华民族伟大复兴关键在党</span><span class=\"bl\" style=\"left:197px;top:265px;font-size:15.6px;max-width:115px\">坚持和加强党的领导</span><span class=\"bl b hl\" style=\"left:364px;top:277px;font-size:17.8px;max-width:180px\">考点66坚持党对一切工作的领导</span><span class=\"bl\" style=\"left:63px;top:326px;font-size:18.4px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:89px;top:354px;font-size:19.0px;max-width:623px\">本章主要阐述了坚持和加强党的领导的相关内容。本章是本门科目中考频较高的章节，考试形式既可能为选择题，也可</span><span class=\"bl\" style=\"left:64px;top:375px;font-size:19.0px;max-width:605px\">能为材料分析题。考生在复习过程中，要重点掌握中国特色社会主义最本质的特征、中国共产党的历史使命等内容。</span><span class=\"bl b hl\" style=\"left:75px;top:420px;font-size:20.1px;max-width:320px\">考点65实现中华民族伟大复兴关键在党☆☆☆</span><span class=\"bl\" style=\"left:671px;top:424px;font-size:15.1px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:456px;font-size:15.6px;max-width:348px\">65.1中国共产党的领导地位是历史和人民的选择（中频选择题）</span><span class=\"bl b\" style=\"left:88px;top:478px;font-size:15.6px;max-width:121px\">1.中国共产党的性质：</span><span class=\"bl\" style=\"left:238px;top:477px;font-size:53.0px;max-width:244px\">号：</span><span class=\"bl\" style=\"left:86px;top:498px;font-size:15.6px;max-width:157px\">①是中国工人阶级的先锋队。</span><span class=\"bl\" style=\"left:88px;top:518px;font-size:17.8px;max-width:192px\">②是中国人民和中华民族的先锋队。</span><span class=\"bl\" style=\"left:87px;top:561px;font-size:15.6px;max-width:245px\">2.中国共产党的执政地位是历史和人民的选择</span><span class=\"bl\" style=\"left:64px;top:603px;font-size:15.1px;max-width:191px\">的必然，是人民拥护和选择的结果。</span><span class=\"bl b\" style=\"left:87px;top:622px;font-size:17.8px;max-width:146px\">3.坚持中国共产党的领导：</span><span class=\"bl\" style=\"left:87px;top:644px;font-size:18.4px;max-width:424px\">①历史表明，历史和人民选择中国共产党领导中华民族伟大复兴的事业是正确</span><span class=\"bl\" style=\"left:64px;top:665px;font-size:16.7px;max-width:167px\">的，必须长期坚持、永不动摇。</span><span class=\"bl\" style=\"left:87px;top:686px;font-size:18.4px;max-width:424px\">②中国共产党领导中国人民开辟的中国特色社会主义道路是正确的，必须长期坚</span><span class=\"bl\" style=\"left:63px;top:708px;font-size:14.5px;max-width:87px\">持、永不动摇。</span><span class=\"bl\" style=\"left:87px;top:728px;font-size:18.4px;max-width:424px\">③中国共产党和中国人民扎根中国大地、吸纳人类文明优秀成果、独立自主实现</span><span class=\"bl\" style=\"left:64px;top:750px;font-size:15.6px;max-width:284px\">国家发展的战略是正确的，必须长期坚持、永不动摇。</span><span class=\"bl b\" style=\"left:63px;top:777px;font-size:15.6px;max-width:290px\">65.2中国特色社会主义最本质的特征（高频选择题）</span><span class=\"bl b\" style=\"left:87px;top:798px;font-size:18.4px;max-width:298px\">1.中国特色社会主义的最本质特征：中国共产党的领导。</span><span class=\"bl\" style=\"left:86px;top:819px;font-size:17.8px;max-width:357px\">2.中国共产党的领导是中国特色社会主义最本质的特征，这一论断：</span><span class=\"bl\" style=\"left:87px;top:841px;font-size:15.6px;max-width:238px\">①这是由科学社会主义的理论逻辑所决定的。</span><span class=\"bl\" style=\"left:87px;top:861px;font-size:17.3px;max-width:321px\">②这是由中国特色社会主义产生与发展的历史逻辑所决定的。</span><span class=\"bl\" style=\"left:86px;top:881px;font-size:18.4px;max-width:322px\">③这是由中国特色社会主义迈向新征程的实践逻辑所决定的。</span><span class=\"bl b\" style=\"left:85px;top:902px;font-size:17.8px;max-width:264px\">3.党的领导是中国特色社会主义制度的最大优势：</span><span class=\"bl\" style=\"left:86px;top:923px;font-size:17.3px;max-width:216px\">①党是中国特色社会主义制度的创建者。</span><span class=\"bl\" style=\"left:86px;top:943px;font-size:18.4px;max-width:331px\">②党的领导是充分发挥中国特色社会主义制度优势的根本保障。</span><span class=\"bl\" style=\"left:86px;top:963px;font-size:19.5px;max-width:424px\">③党的自身优势是中国特色社会主义制度优势的主要来源。中国共产党作为长期</span><span class=\"bl\" style=\"left:61px;top:984px;font-size:19.5px;max-width:447px\">执政的党，以自身优势引领和锻造了中国特色社会主义的制度优势，保证了中国特色</span><span class=\"bl\" style=\"left:61px;top:1005px;font-size:17.3px;max-width:169px\">社会主义制度优势的有效发挥。</span></div></div>"}],pages:[86,91]};
  D["mzt_s15"] = {id:"mzt_s15",ch:"毛中特讲义 · 第十四章 坚持和加强党的领导",title:"第十四章 坚持和加强党的领导",book:"毛中特讲义",img:"assets/img/mzt",blocks:[{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 91 页</div><span class=\"bl b acc\" style=\"left:348px;top:114px;font-size:23.4px;max-width:83px\">第十四章</span><span class=\"bl\" style=\"left:304px;top:162px;font-size:22.9px;max-width:172px\">坚持和加强党的领导</span><span class=\"bl\" style=\"left:63px;top:211px;font-size:19.5px;max-width:102px\">■考点逻辑总览</span><span class=\"bl b hl\" style=\"left:364px;top:255px;font-size:17.8px;max-width:216px\">考点65实现中华民族伟大复兴关键在党</span><span class=\"bl\" style=\"left:197px;top:265px;font-size:15.6px;max-width:115px\">坚持和加强党的领导</span><span class=\"bl b hl\" style=\"left:364px;top:277px;font-size:17.8px;max-width:180px\">考点66坚持党对一切工作的领导</span><span class=\"bl\" style=\"left:63px;top:326px;font-size:18.4px;max-width:102px\">■考点考情分析</span><span class=\"bl\" style=\"left:89px;top:354px;font-size:19.0px;max-width:623px\">本章主要阐述了坚持和加强党的领导的相关内容。本章是本门科目中考频较高的章节，考试形式既可能为选择题，也可</span><span class=\"bl\" style=\"left:64px;top:375px;font-size:19.0px;max-width:605px\">能为材料分析题。考生在复习过程中，要重点掌握中国特色社会主义最本质的特征、中国共产党的历史使命等内容。</span><span class=\"bl b hl\" style=\"left:75px;top:420px;font-size:20.1px;max-width:320px\">考点65实现中华民族伟大复兴关键在党☆☆☆</span><span class=\"bl\" style=\"left:671px;top:424px;font-size:15.1px;max-width:39px\">记笔记</span><span class=\"bl b\" style=\"left:64px;top:456px;font-size:15.6px;max-width:348px\">65.1中国共产党的领导地位是历史和人民的选择（中频选择题）</span><span class=\"bl b\" style=\"left:88px;top:478px;font-size:15.6px;max-width:121px\">1.中国共产党的性质：</span><span class=\"bl\" style=\"left:238px;top:477px;font-size:53.0px;max-width:244px\">号：</span><span class=\"bl\" style=\"left:86px;top:498px;font-size:15.6px;max-width:157px\">①是中国工人阶级的先锋队。</span><span class=\"bl\" style=\"left:88px;top:518px;font-size:17.8px;max-width:192px\">②是中国人民和中华民族的先锋队。</span><span class=\"bl\" style=\"left:87px;top:561px;font-size:15.6px;max-width:245px\">2.中国共产党的执政地位是历史和人民的选择</span><span class=\"bl\" style=\"left:64px;top:603px;font-size:15.1px;max-width:191px\">的必然，是人民拥护和选择的结果。</span><span class=\"bl b\" style=\"left:87px;top:622px;font-size:17.8px;max-width:146px\">3.坚持中国共产党的领导：</span><span class=\"bl\" style=\"left:87px;top:644px;font-size:18.4px;max-width:424px\">①历史表明，历史和人民选择中国共产党领导中华民族伟大复兴的事业是正确</span><span class=\"bl\" style=\"left:64px;top:665px;font-size:16.7px;max-width:167px\">的，必须长期坚持、永不动摇。</span><span class=\"bl\" style=\"left:87px;top:686px;font-size:18.4px;max-width:424px\">②中国共产党领导中国人民开辟的中国特色社会主义道路是正确的，必须长期坚</span><span class=\"bl\" style=\"left:63px;top:708px;font-size:14.5px;max-width:87px\">持、永不动摇。</span><span class=\"bl\" style=\"left:87px;top:728px;font-size:18.4px;max-width:424px\">③中国共产党和中国人民扎根中国大地、吸纳人类文明优秀成果、独立自主实现</span><span class=\"bl\" style=\"left:64px;top:750px;font-size:15.6px;max-width:284px\">国家发展的战略是正确的，必须长期坚持、永不动摇。</span><span class=\"bl b\" style=\"left:63px;top:777px;font-size:15.6px;max-width:290px\">65.2中国特色社会主义最本质的特征（高频选择题）</span><span class=\"bl b\" style=\"left:87px;top:798px;font-size:18.4px;max-width:298px\">1.中国特色社会主义的最本质特征：中国共产党的领导。</span><span class=\"bl\" style=\"left:86px;top:819px;font-size:17.8px;max-width:357px\">2.中国共产党的领导是中国特色社会主义最本质的特征，这一论断：</span><span class=\"bl\" style=\"left:87px;top:841px;font-size:15.6px;max-width:238px\">①这是由科学社会主义的理论逻辑所决定的。</span><span class=\"bl\" style=\"left:87px;top:861px;font-size:17.3px;max-width:321px\">②这是由中国特色社会主义产生与发展的历史逻辑所决定的。</span><span class=\"bl\" style=\"left:86px;top:881px;font-size:18.4px;max-width:322px\">③这是由中国特色社会主义迈向新征程的实践逻辑所决定的。</span><span class=\"bl b\" style=\"left:85px;top:902px;font-size:17.8px;max-width:264px\">3.党的领导是中国特色社会主义制度的最大优势：</span><span class=\"bl\" style=\"left:86px;top:923px;font-size:17.3px;max-width:216px\">①党是中国特色社会主义制度的创建者。</span><span class=\"bl\" style=\"left:86px;top:943px;font-size:18.4px;max-width:331px\">②党的领导是充分发挥中国特色社会主义制度优势的根本保障。</span><span class=\"bl\" style=\"left:86px;top:963px;font-size:19.5px;max-width:424px\">③党的自身优势是中国特色社会主义制度优势的主要来源。中国共产党作为长期</span><span class=\"bl\" style=\"left:61px;top:984px;font-size:19.5px;max-width:447px\">执政的党，以自身优势引领和锻造了中国特色社会主义的制度优势，保证了中国特色</span><span class=\"bl\" style=\"left:61px;top:1005px;font-size:17.3px;max-width:169px\">社会主义制度优势的有效发挥。</span></div></div>"},{t:"raw",x:"<div class=\"bxwrap\"><div class=\"bxpage\" style=\"height:1097px\"><div class=\"bxnum\">第 92 页</div><span class=\"bl\" style=\"left:459px;top:61px;font-size:13.9px;max-width:242px\">毛泽东思想和中国特色社会主义理论体系概论</span><span class=\"bl b\" style=\"left:55px;top:109px;font-size:13.9px;max-width:277px\">65.3新时代中国共产党的历史使命（中频选择题）</span><span class=\"bl b\" style=\"left:79px;top:131px;font-size:12.3px;max-width:178px\">1.新时代中国共产党的历史使命：</span><span class=\"bl\" style=\"left:79px;top:149px;font-size:16.7px;max-width:423px\">新时代中国共产党的历史使命，就是统揽伟大斗争、伟大工程、伟大事业、伟大</span><span class=\"bl\" style=\"left:55px;top:170px;font-size:16.7px;max-width:448px\">梦想，在全面建成小康社会的基础上全面建成社会主义现代化强国，实现中华民族伟</span><span class=\"bl\" style=\"left:56px;top:192px;font-size:14.5px;max-width:95px\">大复兴的中国梦。</span><span class=\"bl\" style=\"left:77px;top:212px;font-size:17.3px;max-width:334px\">2.实现伟大梦想必须进行伟大斗争、推进伟大工程和伟大事业：</span><span class=\"bl\" style=\"left:80px;top:234px;font-size:15.0px;max-width:331px\">①实现伟大梦想，必须进行具有许多新的历史特点的伟大斗争。</span><span class=\"bl\" style=\"left:80px;top:254px;font-size:16.7px;max-width:295px\">②实现伟大梦想，必须深人推进党的建设新的伟大工程。</span><span class=\"bl\" style=\"left:80px;top:277px;font-size:13.9px;max-width:294px\">③实现伟大梦想，必须推进中国特色社会主义伟大事业。</span><span class=\"bl\" style=\"left:78px;top:296px;font-size:17.3px;max-width:425px\">3.伟大斗争、伟大工程、伟大事业、伟大梦想是一个紧密联系、相互贯通、相互</span><span class=\"bl\" style=\"left:55px;top:318px;font-size:15.0px;max-width:414px\">作用、有机统一的整体，统一于新时代坚持和发展中国特色社会主义伟大实践。</span><span class=\"bl\" style=\"left:81px;top:340px;font-size:13.9px;max-width:190px\">①伟大梦想是目标，指引前进方向。</span><span class=\"bl\" style=\"left:81px;top:361px;font-size:13.9px;max-width:189px\">②伟大斗争是手段，激发前进动力。</span><span class=\"bl\" style=\"left:81px;top:381px;font-size:13.9px;max-width:189px\">③伟大工程是保障，提供前进保证。</span><span class=\"bl\" style=\"left:81px;top:402px;font-size:13.9px;max-width:189px\">④伟大事业是主题，开辟前进道路。</span><span class=\"bl\" style=\"left:80px;top:422px;font-size:15.6px;max-width:290px\">“四个伟大”中，起决定性作用的是党的建设伟大工程。</span><span class=\"bl b hl\" style=\"left:66px;top:463px;font-size:18.4px;max-width:275px\">考点66坚持党对一切工作的领导☆☆☆</span><span class=\"bl\" style=\"left:217px;top:484px;font-size:36.2px;max-width:263px\">众号：diky66</span><span class=\"bl b\" style=\"left:56px;top:499px;font-size:13.9px;max-width:156px\">66.1党是最高政治领导力量</span><span class=\"bl\" style=\"left:79px;top:518px;font-size:17.8px;max-width:424px\">党是最高政治领导力量，这是马克思主义政党学说的基本原则，是对历史经验的</span><span class=\"bl\" style=\"left:55px;top:538px;font-size:20.1px;max-width:334px\">深刻总结，是推进伟大事业的根本保证。</span><span class=\"bl\" style=\"left:80px;top:559px;font-size:16.7px;max-width:422px\">①这是马克思主义政党的基本要求。无产阶级政党必须坚持党对国家政权的最高</span><span class=\"bl\" style=\"left:57px;top:581px;font-size:13.9px;max-width:248px\">领导权，这是马克思主义政党学说的基本原则。</span><span class=\"bl\" style=\"left:81px;top:600px;font-size:15.0px;max-width:296px\">②这是对党领导革命、建设和改革历史经验的深刻总结。</span><span class=\"bl\" style=\"left:81px;top:622px;font-size:13.9px;max-width:176px\">③这是推进伟大事业的根本保证。</span><span class=\"bl b\" style=\"left:56px;top:648px;font-size:15.0px;max-width:198px\">66.2确保党始终总揽全局协调各方</span><span class=\"bl\" style=\"left:81px;top:667px;font-size:17.3px;max-width:422px\">坚持党总揽全局、协调各方的领导核心地位，是党作为最高政治力量在治国理政</span><span class=\"bl\" style=\"left:57px;top:690px;font-size:14.5px;max-width:84px\">中的重要体现。</span><span class=\"bl\" style=\"left:81px;top:708px;font-size:16.7px;max-width:421px\">①确保党始终总揽全局、协调各方，必须增强政治意识、大局意识、核心意识、</span><span class=\"bl\" style=\"left:57px;top:728px;font-size:16.7px;max-width:445px\">看齐意识，自觉维护党中央权威和集中统一领导，自觉在思想上政治上行动上同党中</span><span class=\"bl\" style=\"left:57px;top:751px;font-size:13.9px;max-width:94px\">央保持高度一致。</span><span class=\"bl\" style=\"left:82px;top:769px;font-size:15.6px;max-width:389px\">②确保党始终总揽全局、协调各方，必须坚持和完善党的领导的体制机制。</span><span class=\"bl\" style=\"left:81px;top:789px;font-size:17.3px;max-width:354px\">③确保党始终总揽全局、协调各方，必须坚持党的民主集中制原则。</span><span class=\"bl b\" style=\"left:57px;top:818px;font-size:13.9px;max-width:161px\">66.3全面增强党的执政本领</span><span class=\"bl\" style=\"left:82px;top:839px;font-size:13.9px;max-width:236px\">我们党既要政治过硬，也要本领高强，需要：</span><span class=\"bl\" style=\"left:82px;top:859px;font-size:13.9px;max-width:96px\">①增强学习本领。</span><span class=\"bl\" style=\"left:82px;top:879px;font-size:13.9px;max-width:119px\">②增强政治领导本领。</span><span class=\"bl\" style=\"left:82px;top:898px;font-size:15.6px;max-width:120px\">③增强改革创新本领。</span><span class=\"bl\" style=\"left:82px;top:919px;font-size:15.6px;max-width:120px\">④增强科学发展本领。</span><span class=\"bl\" style=\"left:83px;top:940px;font-size:13.9px;max-width:118px\">③增强依法执政本领。</span><span class=\"bl\" style=\"left:82px;top:959px;font-size:15.6px;max-width:119px\">?增强群众工作本领。</span><span class=\"bl\" style=\"left:83px;top:980px;font-size:13.9px;max-width:119px\">7增强狠抓落实本领。</span><span class=\"bl\" style=\"left:83px;top:1000px;font-size:13.9px;max-width:119px\">⑧增强驾驭风险本领。</span></div></div>"}],pages:[91,92]};
  for (var k in D) window.LESSONS[k] = D[k];
})();
